window.DEEP_STORIES["rockets"] = {"slug":"rockets","title":"Rockets & Spaceflight","emoji":"🚀","tagline":"From fire arrows to footprints on the Moon — and onward to Mars","intro":"Ten, nine, eight... Have you ever wondered how a machine can fling people faster than a bullet, above the sky, and all the way to the Moon? This Deep Dive tells the whole story in 20 parts. We start a thousand years ago in China, where gunpowder fire arrows first whooshed across battlefields. We meet dreamers who were laughed at — a deaf Russian schoolteacher, a quiet American physics professor and a German student who wrote rocket books. We follow the dark wartime rockets of World War II, then the space race between the United States and the Soviet Union: Sputnik, Laika, Yuri Gagarin, and the Apollo astronauts who walked on the Moon. You will learn how rockets really work, why orbit is just falling sideways, and why space is dangerous. Then come the Space Shuttle, the International Space Station, rockets that land themselves, and robots on Mars. Strap in — liftoff!","outline":[{"n":1,"title":"Dreaming of the Sky","when":"Ancient times – 1600s"},{"n":2,"title":"Fire Arrows of China","when":"800s – 1300s"},{"n":3,"title":"Iron Rockets and the Red Glare","when":"1600s – 1800s"},{"n":4,"title":"The Dreamers: Verne and Tsiolkovsky","when":"1865 – 1935"},{"n":5,"title":"Goddard's Strange Little Rocket","when":"1899 – 1945"},{"n":6,"title":"Oberth and the Rocket Clubs","when":"1923 – 1937"},{"n":7,"title":"The V-2: A Rocket's Dark Side","when":"1937 – 1945"},{"n":8,"title":"Two Rivals, Secret Rockets","when":"1945 – 1957"},{"n":9,"title":"Beep, Beep: Sputnik and Laika","when":"1957 – 1958"},{"n":10,"title":"How Rockets Work (Part 1): Push and Fall","when":"Science explainer"},{"n":11,"title":"First Humans in Space","when":"1959 – 1965"},{"n":12,"title":"Race to the Moon","when":"1961 – 1968"},{"n":13,"title":"The Eagle Has Landed","when":"1969 – 1972"},{"n":14,"title":"How Rockets Work (Part 2): Fuel, Stages and Coming Home","when":"Science explainer"},{"n":15,"title":"Space Stations and the Space Shuttle","when":"1971 – 2011"},{"n":16,"title":"The International Space Station","when":"1998 – today"},{"n":17,"title":"Robot Explorers and the Road to Mars","when":"1962 – today"},{"n":18,"title":"Rockets That Land: The New Space Age","when":"2000 – today"},{"n":19,"title":"The Dangers and the Debates","when":"1940s – today"},{"n":20,"title":"Back to the Moon, On to Mars","when":"Today – the future"}],"people":[["Hero of Alexandria (1st century CE)","Greek engineer who described the aeolipile, a spinning steam ball showing action and reaction"],["Hasan al-Rammah (died 1294/95)","Syrian writer whose military book (around 1280) described rockets and gunpowder recipes"],["Kazimierz Siemienowicz (around 1600 – around 1651)","Polish-Lithuanian artillery expert whose 1650 book described multi-stage rockets"],["Isaac Newton (1643–1727)","English scientist whose third law of motion (1687) explains how rockets move"],["Hyder Ali (around 1720–1782) and Tipu Sultan (1751–1799)","rulers of Mysore, India, whose armies used iron-cased war rockets"],["William Congreve (1772–1828)","British inventor who developed the Congreve rocket from Mysorean designs"],["Francis Scott Key (1779–1843)","American lawyer whose poem about Fort McHenry mentions 'the rockets' red glare'"],["Jules Verne (1828–1905)","French author of 'From the Earth to the Moon' (1865), which inspired rocket pioneers"],["Konstantin Tsiolkovsky (1857–1935)","Russian schoolteacher and self-taught scientist; father of spaceflight theory and the rocket equation"],["Robert H. Goddard (1882–1945)","American physicist who launched the first liquid-fuelled rocket (1926)"],["Hermann Oberth (1894–1989)","German-speaking physicist from Transylvania; wrote 'The Rocket into Planetary Space' (1923)"],["Fritz Lang (1890–1976)","film director of 'Woman in the Moon' (1929), which popularised the countdown"],["Wernher von Braun (1912–1977)","German engineer who led V-2 development for Nazi Germany (and was an SS member), later led the US team that built the Saturn V; a hero and a controversial figure"],["Walter Dornberger (1895–1980)","German army officer in charge of the V-2 program"],["Sergei Korolev (1907–1966)","Soviet Chief Designer behind the R-7, Sputnik and Gagarin's flight; survived the Gulag; his identity was kept secret"],["Valentin Glushko (1908–1989)","Soviet rocket engine designer, Korolev's partner and later rival"],["James Van Allen (1914–2006)","American physicist whose instrument on Explorer 1 discovered Earth's radiation belts"],["Laika (around 1954–1957)","stray Moscow dog, first animal to orbit Earth; did not survive"],["Belka and Strelka","Soviet dogs who orbited Earth and returned safely in August 1960"],["Ham (1957–1983)","chimpanzee flown by the US on a Mercury suborbital flight in January 1961"],["Yuri Gagarin (1934–1968)","Soviet cosmonaut, first human in space (12 April 1961)"],["Alan Shepard (1923–1998)","first American in space (1961); later walked on the Moon on Apollo 14"],["John Glenn (1921–2016)","first American to orbit Earth (1962); flew again on the Shuttle at age 77 in 1998"],["Katherine Johnson (1918–2020)","NASA mathematician who calculated trajectories for Mercury and Apollo flights"],["Valentina Tereshkova (born 1937)","Soviet cosmonaut, first woman in space (1963)"],["Alexei Leonov (1934–2019)","Soviet cosmonaut who made the first spacewalk (1965)"],["John F. Kennedy (1917–1963)","US president who set the goal of landing on the Moon"],["Gus Grissom (1926–1967), Ed White (1930–1967), Roger Chaffee (1935–1967)","Apollo 1 crew who died in a launch-pad fire"],["Vladimir Komarov (1927–1967)","Soviet cosmonaut killed on Soyuz 1"],["Frank Borman (1928–2023), Jim Lovell (1928–2025), Bill Anders (1933–2024)","Apollo 8 crew, first humans to orbit the Moon"],["Neil Armstrong (1930–2012)","Apollo 11 commander, first person to walk on the Moon"],["Buzz Aldrin (born 1930)","Apollo 11 lunar module pilot, second person on the Moon"],["Michael Collins (1930–2021)","Apollo 11 command module pilot who orbited the Moon alone"],["Margaret Hamilton (born 1936)","MIT software engineer who led the team writing Apollo's onboard flight software"],["Gene Cernan (1934–2017)","Apollo 17 commander, last person to walk on the Moon (1972)"],["John Young (1930–2018) and Robert Crippen (born 1937)","crew of the first Space Shuttle flight (1981)"],["Sally Ride (1951–2012)","first American woman in space (1983)"],["Guion Bluford (born 1942)","first African American in space (1983)"],["Mae Jemison (born 1956)","first African American woman in space (1992)"],["Christa McAuliffe (1948–1986)","teacher chosen to fly on Challenger; died in the 1986 disaster"],["Kalpana Chawla (1962–2003)","Indian-born American astronaut who died in the Columbia disaster"],["Ilan Ramon (1954–2003)","first Israeli astronaut, died in the Columbia disaster"],["Yang Liwei (born 1965)","China's first astronaut (Shenzhou 5, 2003)"],["Elon Musk (born 1971)","founder of SpaceX (2002), which developed reusable Falcon 9 boosters and Starship"],["Jeff Bezos (born 1964)","founder of Blue Origin (2000), maker of New Shepard and New Glenn"],["Bob Behnken (born 1970) and Doug Hurley (born 1966)","first astronauts launched on Crew Dragon (2020)"],["Reid Wiseman, Victor Glover, Christina Koch, Jeremy Hansen","Artemis II crew (Koch: first woman, Glover: first Black astronaut, Hansen: first Canadian assigned to a lunar mission)"]],"glossary":[["rocket","a vehicle or engine that moves by shooting hot gas out of the back, pushing itself forward"],["thrust","the pushing force a rocket engine makes"],["Newton's third law","for every action there is an equal and opposite reaction"],["propellant","the fuel and oxidizer a rocket burns"],["oxidizer","the chemical (often liquid oxygen) that lets fuel burn where there is no air"],["liquid-fuel rocket","a rocket that pumps liquid fuel and oxidizer into an engine; can be throttled or shut off"],["solid-fuel rocket","a rocket whose fuel and oxidizer are mixed into a solid block; simple but hard to stop once lit"],["nozzle","the bell-shaped opening at the bottom of an engine that speeds up the exhaust"],["stage","a section of a rocket with its own engines and fuel that is dropped when empty"],["orbit","the curved path of an object falling around a planet so fast it keeps missing the ground"],["satellite","any object that orbits a planet; the Moon is natural, Sputnik was the first artificial one"],["escape velocity","the speed needed to break free of a planet's gravity without further push (about 11.2 km/s for Earth)"],["free fall / weightlessness","the floating feeling astronauts have because they and their spacecraft are falling together; gravity is still there"],["Kármán line","a commonly used boundary of space, 100 km above sea level"],["suborbital flight","a flight that reaches space but falls back down without completing an orbit"],["re-entry","coming back into the atmosphere, when a spacecraft must survive intense heat"],["heat shield","a protective layer that keeps a spacecraft from burning up during re-entry"],["ICBM","intercontinental ballistic missile, a rocket weapon able to reach other continents"],["gravity assist","using a planet's gravity to speed up or bend a spacecraft's path, like a slingshot"],["reusable rocket","a rocket (or part of one) that lands and flies again instead of being thrown away"]],"parts":[{"n":1,"title":"Dreaming of the Sky","when":"Ancient times – 1600s","summary":"Long before anyone built a rocket, people stared at the Moon and wished they could go there. They told stories about wings made of wax, ships blown up by whirlwinds and spirits that carried travellers through the dark. But one giant puzzle stood in the way: how do you move where there is nothing to push on?","sections":[{"heading":"A Sky Full of Questions","paragraphs":["Go outside on a clear night, far from streetlights, and look up. The Moon hangs there, bright and silent. Thousands of stars sparkle. A few brighter dots do not twinkle as much as the rest, and if you watched them for weeks you would see them slowly drift across the background of stars. Every human who has ever lived has seen this same sky, and almost every one of them has wondered what is up there and whether we could ever go and see.","For most of history, the sky was not just scenery. It was a clock, a calendar and a map. Farmers watched for certain stars to know when to plant. Sailors steered by them at night. The Moon's phases, from thin crescent to full and back again in about 29 and a half days, gave many peoples their idea of a month.","Ancient peoples filled the sky with stories. To the Greeks, the Moon was the goddess Selene, driving her silver chariot across the night. In China, a famous legend tells of Chang'e, who swallowed an elixir and floated up to live on the Moon with a jade rabbit for company. These were not science, but they show something important: people had been imagining a journey to the Moon for thousands of years before anyone knew how far away it really was.","Alongside the myths, careful watchers began to measure. In ancient Mesopotamia, in what is now Iraq, astronomers wrote down the positions of the Moon and planets on clay tablets for centuries, and learned to predict some eclipses. The Greeks called the drifting lights planetes, which means wanderers, and that is where our word planet comes from. Around 240 BCE, a scholar named Eratosthenes, working in Egypt, used shadows cast by the Sun in two different cities to estimate the size of the whole Earth, and his answer was surprisingly close to the truth.","Other Greek thinkers used eclipses and geometry to work out how far away the Moon was. The astronomer Hipparchus, in the 2nd century BCE, estimated distances of roughly 60 to 80 times the radius of the Earth. That is not far off the real average distance, which is about 60 Earth radii, or about 384,000 kilometres. Think about that: more than two thousand years ago, without telescopes, people had a rough idea of how far you would have to travel to reach the Moon. Knowing how far it is, though, is very different from knowing how to get there.","In fact, the most influential thinker of ancient Greece made the trip seem impossible in principle. Aristotle, in the 4th century BCE, taught that the world below the Moon was made of four elements, earth, water, air and fire, which naturally moved up or down. Above the Moon, he said, everything was made of a perfect fifth substance called aether, moving forever in circles. The heavens were a completely different kind of place, and ordinary things from Earth simply did not belong there. This picture of the universe, later organized in great detail by the astronomer Ptolemy in Alexandria in the 2nd century CE, was taught in schools for well over a thousand years. If the sky is made of a different kind of stuff with different rules, why would anyone even try to fly into it?"]},{"heading":"Wings of Wax: The Legend of Icarus","paragraphs":["Of all the old flying stories, one has been retold more than almost any other. It is a Greek myth, which means it is a legend, not history. Nobody thinks it really happened. But it has inspired poets, painters and inventors for more than two thousand years, and it says something true about the dream of flight.","The story goes like this. Daedalus was the most brilliant craftsman in the world. He was so clever that King Minos of Crete hired him to build the Labyrinth, a maze so tangled that nobody who entered could find the way out. Inside it lived the Minotaur, a monster that was half man and half bull. But when Daedalus fell out of favour, Minos trapped him on the island of Crete together with his young son, Icarus. The king controlled the ships and the harbours. There seemed to be no way off.","Daedalus looked up at the seabirds wheeling above the cliffs and had an idea. If the sea and the land were closed to him, the sky was not. He gathered feathers, small and large, and arranged them in rows like the pipes of a shepherd's flute. He stitched the big feathers together with thread and fixed the small ones with wax. Slowly, he curved them into two great pairs of wings, one for himself and one for his son.","Before they took off, Daedalus gave Icarus a warning. Fly the middle path, he said. Too low, and the spray from the sea will make your feathers heavy. Too high, and the heat of the Sun will melt the wax. Then they leapt into the air. At first all went well. Fishermen and shepherds below stared up, thinking the two flyers must be gods. But Icarus grew bolder and bolder. Thrilled by the feeling of flying, he climbed higher and higher towards the Sun. The wax softened, the feathers slipped away, and Icarus fell into the sea and drowned. The part of the Aegean Sea where he was said to have fallen is still called the Icarian Sea, and a nearby island is named Ikaria.","The best-known telling of this myth comes from the Roman poet Ovid, in his long poem Metamorphoses, finished around the year 8 CE. Centuries later, European artists painted the scene again and again. One famous painting, long thought to be by Pieter Bruegel the Elder, shows a peaceful landscape with a farmer ploughing and a ship sailing by, while in a corner two tiny legs splash into the water. Nobody in the picture even notices.","Of course, the science of the story is backwards. In real life, the higher you climb, the colder the air becomes, not hotter. Mountaineers on Mount Everest face freezing temperatures even though they are closer to the Sun. And human arms are far too weak to flap wings big enough to lift a person. But the myth was never meant to be an engineering manual. It is about dreaming big, about the thrill of leaving the ground, and about the danger of ignoring good advice. Every rocket engineer in this story, from medieval China to modern Florida, has had to balance daring and caution, just as Daedalus tried to teach his son."]},{"heading":"A Wooden Pigeon and a Spinning Steam Ball","paragraphs":["Did anyone in the ancient world build a machine that moved by itself? Two examples often appear in rocket history books, though neither was a rocket. The first comes from Tarentum, a Greek city in southern Italy, which today is called Taranto. Around 400 BCE, a man named Archytas lived there. He was a serious mathematician, a friend of the philosopher Plato, a respected leader of his city and an army general. According to a story, he also built a wooden model of a dove, or pigeon, that could fly.","Here is the important part: we do not have any description of this pigeon from Archytas's own time. The only ancient account comes from a Roman writer named Aulus Gellius, who lived in the 2nd century CE, around 500 years after Archytas. Gellius said he had read about it in the work of an earlier scholar, Favorinus. According to that report, the dove was balanced with weights and moved by air shut up inside it, and once it landed it could not rise again. Gellius himself seemed to think the tale was rather hard to believe. Many modern books describe the pigeon as hanging on a wire and pushed by escaping steam, but those details are guesses added much later. So the honest answer is that the pigeon is a story known only from writers who lived long after, and we cannot be sure exactly what it was or how it worked, or even whether it existed at all.","The second example is much better documented. Hero (also called Heron) of Alexandria lived in the great city of Alexandria, in Egypt, in the 1st century CE. Historians date him partly because one of his books mentions an eclipse that matches one seen in Alexandria in the year 62 CE. Hero probably taught at the Museum of Alexandria, a famous centre of learning that stood beside the great Library. His books read like lecture notes, full of mathematics, measuring and clever machines.","In one book, called the Pneumatica, which means something like 'about air and breath', Hero described more than a hundred devices worked by air, water and steam. There was a coin-operated machine that gave out a measured squirt of water when you dropped in a coin, a kind of ancient vending machine. There was a pump for spraying water onto fires, an organ played by wind, and singing mechanical birds. And there was a device we now call the aeolipile, after Aeolus, the Greek keeper of the winds.","The aeolipile worked like this. A closed metal pot of water sat over a fire. Two pipes rose up from the lid and held a hollow metal ball between them, so that the ball could turn on the pipes like a wheel on an axle. As the water boiled, steam rushed up through the pipes into the ball. Sticking out from opposite sides of the ball were two small bent tubes, shaped like the letter L and pointing in opposite directions. Steam shot out of these tubes, and as it did, the ball spun round and round, faster and faster.","Why does it spin? Because when the steam is pushed out of a tube one way, the tube, and the ball it is attached to, gets pushed the opposite way. One bent tube pushes the ball one way round, the other tube on the opposite side pushes it the same way round, and so the ball whirls. You may have seen the same thing in a spinning garden sprinkler, whose arms whirl backwards as water squirts out of them. This idea, that throwing something out one way pushes you the other way, is called action and reaction. It is exactly the principle that lifts every rocket. But nobody in Hero's time could explain it with a law of physics. That would have to wait more than 1,600 years.","Was the aeolipile a rocket? No. It was fixed in place, it did not carry its own fuel inside it and it did not go anywhere. It only spun. It was also never put to practical work. As far as we know, it remained a wonderful demonstration, the kind of thing a teacher shows to amaze students. Some historians call it the first recorded steam engine, or the first reaction engine. What it really shows is that nearly 2,000 years ago, a clever engineer had already stumbled on the push that would one day carry people to the Moon, without having any idea how big that idea really was."]},{"heading":"Lucian's Ship in a Whirlwind","paragraphs":["In the 2nd century CE, about a hundred years after Hero, a witty writer named Lucian was making people laugh all across the Roman Empire. He was born around the year 120 in Samosata, a town on the River Euphrates in what is now southeastern Turkey. His first language was probably not Greek, yet he became one of the sharpest writers in the Greek language, travelling around as a public speaker and poking fun at pompous philosophers, gossipy historians and anyone who took themselves too seriously.","His most famous joke is a book usually called A True Story, or True History. The title itself is part of the joke. In the introduction, Lucian admits that the only true thing in the whole book is that he is telling lies. He was making fun of travel writers of his day, who filled their books with wild reports of monsters and marvels from faraway lands and swore that it was all true. Lucian decided to out-exaggerate them all.","The story begins with Lucian and fifty companions setting sail westward, past the Pillars of Hercules, the rocky gateway where the Mediterranean meets the Atlantic Ocean near today's Strait of Gibraltar. For the ancient Greeks, this was the edge of the known world. A storm drives the ship across the ocean for 79 days. On the 80th day they land on a strange island where they find a river of wine and vines that are women from the waist up.","Then comes the part that makes this book famous in the history of space travel. Soon after they sail on, a mighty whirlwind spins the ship around and lifts it high into the air, far above the sea. The wind keeps pushing the sails, and after about a week of sailing through the sky, the travellers see a great shining island hanging in space. It is the Moon. Looking down, they can see the Earth far below them, with its cities, rivers and seas.","On the Moon, they are captured by soldiers riding enormous three-headed vultures and taken to the king, Endymion. (In Greek myth, Endymion was a handsome shepherd loved by the Moon goddess, so Lucian made him the Moon's ruler.) Endymion is at war with Phaethon, king of the Sun, over who gets to set up a colony on the Morning Star, which is the planet we call Venus. The armies Lucian invents are wonderfully silly: tens of thousands of vulture-riders, giant birds covered in grass with lettuce leaves for wings, soldiers riding huge fleas, and from the Sun's side, warriors on flying ants and others who hurl giant radishes. In the end the Sun's army builds a wall of clouds that blocks the sunlight from the Moon, and the Moon people have to make peace.","A True Story was meant as satire, not science, and you should not read it expecting to learn anything about real space. Lucian imagined that a ship could simply sail upward through air all the way to the Moon, because nobody yet knew that the air gets thinner and thinner and finally ends. But the book is one of the oldest surviving stories about a journey to the Moon, and a group of people from Earth meeting beings who live on other worlds. That is why many writers call it one of the earliest works of science fiction, written about 1,800 years before Star Wars. Lucian may have been joking, but he gave the world a picture that would never go away: people from Earth, looking back at their home planet from the Moon."]},{"heading":"Kepler's Dream","paragraphs":["Now jump forward about 1,400 years, to central Europe in the early 1600s. The old picture of the universe is crumbling. In 1543, the Polish astronomer Nicolaus Copernicus had published a book arguing that the Earth is not the fixed centre of everything, but a planet that spins and travels around the Sun. If Earth was a planet, then perhaps the planets were worlds, and the Moon was a place, made of rock rather than perfect aether.","One of the people who took this idea most seriously was a German astronomer named Johannes Kepler, who lived from 1571 to 1630. Kepler had poor eyesight from a childhood illness, but he was a mathematical genius. Working with the precise observations of the Danish astronomer Tycho Brahe, he discovered that planets travel around the Sun not in perfect circles but in ovals called ellipses, and that they speed up when they are closer to the Sun. In 1610, the Italian scientist Galileo Galilei published what he had seen when he pointed one of the first telescopes at the Moon: mountains, valleys and craters. The Moon was not a perfect crystal ball. It was a world.","Kepler had been thinking about the Moon since he was a student. At the University of Tübingen, in the 1590s, he had worked on a question that Copernicus's ideas raised: what would the sky look like to someone standing on the Moon? Over the years, that question grew into a strange, short book called Somnium, which is Latin for The Dream. Kepler wrote most of it around 1608 to 1609, shared a version in 1611, and kept adding to it for the rest of his life. He did not live to see it printed. It was finally published in 1634 by his son Ludwig, four years after Kepler's death.","The story is wrapped in layers like a set of nesting dolls. A narrator falls asleep while reading and dreams of a book. In that book, a boy named Duracotus grows up in Iceland with his mother, Fiolxhilde, a wise woman who sells herbs and knows secret things. Duracotus goes to Denmark to study astronomy with Tycho Brahe, just as Kepler had worked with Tycho in real life. When he comes home, his mother calls up a daemon, a kind of spirit, from a place called Levania, which is Kepler's name for the Moon.","The daemon explains how travellers can be carried to Levania, and this is where Kepler becomes surprisingly modern. The journey can only happen during a lunar eclipse, when the shadow of the Earth stretches out towards the Moon, because the daemons cannot stand sunlight. The daemon warns that weak or soft people need not apply. The take-off is so violent, it says, that it is like being blasted out by gunpowder, so travellers are given a drug to put them to sleep, and their arms and legs are carefully arranged so that the shock does not tear them apart. There is terrible cold to survive, and the air is so thin that travellers must hold damp sponges to their noses to breathe. Partway through the trip, the travellers' bodies move along towards the Moon by themselves, and near the end the daemons must slow them down so that they do not crash.","Look at the problems Kepler was worrying about: a crushing acceleration at launch, freezing cold, not enough air, and the need to brake before landing. These are real problems that every space agency has had to solve. Kepler used magic to fix some of them, but he was asking the right questions. He even seems to have imagined that the Earth's pull fades with distance until the Moon's pull takes over, decades before Isaac Newton explained gravity.","Most of the Somnium is not about the journey at all. It describes what the sky looks like from Levania. Kepler pointed out that the Moon always keeps the same side towards Earth, so for people on that side, the Earth, which he calls Volva, would hang in the same spot in the sky all the time, never rising or setting, looking far bigger than the Moon looks to us, and going through phases. People on the far side would never see the Earth at all. A day on Levania lasts about two of our weeks, and so does a night, so the ground would bake and then freeze. Kepler imagined enormous snake-like creatures with spongy skins that hide in caves from the scorching heat. The story itself is only about 30 pages long, but Kepler added 223 notes explaining the science, and the notes are several times longer than the story.","The book may also have brought real sorrow into Kepler's life. A handwritten version was passed around years before it was printed. In 1615, Kepler's own mother, Katharina, was accused of witchcraft in her home town in Germany. Kepler suspected that people had read his story about a boy whose mother summons spirits and taken it as being about his family, although historians are not sure the book played any part. Katharina was imprisoned in 1620 and threatened with torture. Kepler travelled to defend her himself, and she was finally released in 1621, dying a few months later. Because of all this, Somnium is often called the first work of science fiction that tried hard to follow real science."]},{"heading":"The Wall With No Handholds","paragraphs":["By the time Somnium was published, people had a better picture of the Moon than ever before. They knew roughly how far away it was. They had seen its mountains through telescopes. Writers had imagined trips there on wings, on ships lifted by whirlwinds, and in the arms of spirits. But nobody had the faintest idea how a real machine could get there. To see why, think about how everything that moves on Earth actually moves.","When you walk, your feet push backward on the ground, and the ground pushes you forward. A rowing boat moves because its oars push back on the water. A bird flies by pushing air down and back with its wings. Even a sailing ship needs the wind to push on its sails. Every way of travelling that anyone knew in the 1600s needed something outside the traveller to push against: earth, water or air. And a new discovery was about to show that out in space, none of these things exist.","In 1643, an Italian scientist named Evangelista Torricelli filled a long glass tube with mercury, turned it upside down into a bowl of mercury, and watched the silvery liquid sink down to a height of about 76 centimetres, leaving an empty space at the top of the tube. He explained that the column was being held up by the weight of the air pressing down on the bowl. In other words, air has weight, and we live at the bottom of an ocean of it. This was the first barometer.","A few years later, in 1648, the French thinker Blaise Pascal asked his brother-in-law, Florin Périer, to carry one of these tubes up a mountain called the Puy de Dôme in central France. As Périer climbed, the mercury in the tube sank lower and lower, because there was less air above pressing down. The ocean of air got thinner as you went up. And if it got thinner, then somewhere above it must run out completely.","Then a German inventor and mayor named Otto von Guericke built an air pump that could suck most of the air out of a container. In a famous demonstration in the 1650s, he fitted two copper half-spheres together and pumped out the air between them. Teams of horses pulling in opposite directions could not drag the halves apart, because the air pressing on the outside held them together so tightly. The experiment showed that a near-vacuum, a space with almost no air in it, was real and could be made on Earth.","Put all these discoveries together, and you get a giant problem for anyone dreaming of the Moon. The air ends a short distance above our heads. Beyond it lies an enormous emptiness, hundreds of thousands of kilometres of it, with no ground to push against, no water to row through, no air for wings or sails. Lucian's whirlwind and Daedalus's feathers would be useless out there. It was like trying to climb a cliff that has no handholds at all.","What was needed was a machine that carried its own push with it, something that could throw stuff out of its back end and be shoved forward in return, even with nothing around it. Hero's spinning steam ball had hinted at that trick, but steam needs a heavy boiler and a fire, and it is far too weak. Kepler had compared his imaginary launch to a blast of gunpowder, perhaps without realizing how close to the truth he was.","The answer would not come from steam, wax wings or magical spirits. It would come from a strange black powder that hisses, flares and roars, a powder that burns even without air from outside. It had been discovered centuries earlier, on the other side of the world, by alchemists in China who were searching for something completely different: a medicine to help people live forever."]}],"deepDive":"Historians of spaceflight love to start with Archytas and Hero, but it is worth being careful about what these devices really were. Archytas's flying dove is a classic example of a 'source problem'. The only ancient report comes from Aulus Gellius's Attic Nights, written in the 2nd century CE, who relays a claim from the scholar Favorinus about a man who had died roughly five centuries earlier. Gellius describes a wooden model balanced by weights and moved by enclosed air, and he treats the tale as hard to believe. Later retellings that mention steam, wires and pulleys are reconstructions, not evidence. Historians therefore treat the dove as an interesting legend rather than an established invention. Hero's aeolipile is on firmer ground because his own text, the Pneumatica, survives. Scholars date Hero to the 1st century CE partly because the astronomer Otto Neugebauer matched an eclipse mentioned in his Dioptra to one seen at Alexandria in 62 CE. The aeolipile is a genuine reaction device: the steam leaving its nozzles carries momentum in one direction, so the sphere gains angular momentum in the other. Engineers sometimes call it the first reaction turbine. But it differs from a rocket in two key ways: its working fluid comes from an external boiler rather than from propellant carried on board, and it produces rotation rather than travel. Its thrust is also tiny. There is a long-running debate about why the ancient world did not turn such devices into useful engines. Common explanations include plentiful slave and animal labour, the lack of strong, precisely machined metal parts, and a scholarly culture that prized theory over practical machinery, though historians warn against any single neat answer. On the literary side, critics argue about which work deserves the title 'first science fiction'. Lucian's True Story (about 160 to 180 CE) features space travel, alien life and interplanetary war, but it is openly satirical and ignores physics. Kepler's Somnium (written about 1608 to 1609, published 1634) is shorter on adventure but uses real astronomy, including Copernican motion, lunar day length and the fixed position of Earth in the lunar sky, which is why writers such as Carl Sagan and Isaac Asimov pointed to it as a founding work of science-based fiction. Both labels depend on how you define the genre.","funFact":"Kepler's Somnium is only about 30 pages of story, but he wrote 223 explanatory notes for it, and the notes are several times longer than the tale itself.","check":{"q":"Who described the aeolipile, a hollow ball that spun as steam shot out of two bent tubes?","a":"Hero of Alexandria","wrong":["Archytas of Tarentum","Johannes Kepler","Lucian of Samosata"]},"sources":[{"title":"Brief History of Rockets","publisher":"NASA Glenn Research Center","url":"https://www.grc.nasa.gov/www/k-12/TRC/Rockets/history_of_rockets.html"},{"title":"Archytas","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Archytas"},{"title":"Hipparchus","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Hipparchus"},{"title":"Heron of Alexandria (biography)","publisher":"MacTutor History of Mathematics, University of St Andrews","url":"https://mathshistory.st-andrews.ac.uk/Biographies/Heron/"},{"title":"Johannes Kepler wrote the first science fiction story","publisher":"Astronomy Magazine","url":"https://www.astronomy.com/science/johannes-kepler-wrote-the-first-science-fiction-story/"},{"title":"Kepler's Somnium","publisher":"Vatican Observatory","url":"https://www.vaticanobservatory.org/?p=173766"},{"title":"A True History by Lucian","publisher":"EBSCO Research Starters","url":"https://www.ebsco.com/research-starters/literature-and-writing/true-history-lucian"},{"title":"Lucian's True History","publisher":"Project Gutenberg","url":"https://www.gutenberg.org/ebooks/45858"}],"photos":[{"src":"img/deep/rockets/01-1.jpg","alt":"An old book engraving of Hero's aeolipile: steam from a heated pot spins a ball by puffing out of its bent pipe.","file":"Heron's Eolipile.jpg","url":"https://commons.wikimedia.org/wiki/File:Heron%27s_Eolipile.jpg","author":"Sue Clark","license":"Public domain"},{"src":"img/deep/rockets/01-2.jpg","alt":"Title page of Johannes Kepler's Somnium (\"The Dream\"), a story about the Moon printed in 1634.","file":"El Sueño o la Astronomía de la Luna.jpg","url":"https://commons.wikimedia.org/wiki/File:El_Sue%C3%B1o_o_la_Astronom%C3%ADa_de_la_Luna.jpg","author":"Johannes Kepler","license":"Public domain"},{"src":"img/deep/rockets/01-3.jpg","alt":"Landscape with the Fall of Icarus: a farmer keeps ploughing while Icarus's legs splash into the sea (bottom right).","file":"Pieter Bruegel the Elder - Landscape with the Fall of Icarus - WGA03321.jpg","url":"https://commons.wikimedia.org/wiki/File:Pieter_Bruegel_the_Elder_-_Landscape_with_the_Fall_of_Icarus_-_WGA03321.jpg","author":"Pieter Brueghel the Elder","license":"Public domain"}],"words":4375},{"n":2,"title":"Fire Arrows of China","when":"800s – 1300s","summary":"In ancient China, alchemists mixing potions to help people live forever accidentally made a powder that burst into flame. Soldiers tied tubes of this powder to arrows, and the arrows flew off by themselves. These were the first real rockets, and soon they were whooshing across battlefields and lighting up festival skies.","sections":[{"heading":"The Alchemists' Kitchen","paragraphs":["Picture a quiet mountain workshop in China more than a thousand years ago. Smoke curls from a small furnace. On the shelves are jars of strange minerals: yellow crumbs of sulfur, red lumps of a mineral called realgar, white crystals scraped from the walls of caves and old cellars. A man in robes is grinding something in a stone bowl, mixing, heating, watching and writing notes. He is not trying to invent a weapon. He is trying to make a medicine that will let people live forever.","People like him are called alchemists. In China, many alchemists followed Daoism, a tradition of thought that taught living in harmony with nature, and some of them believed that the right mixture of minerals and herbs could create an elixir of long life or even immortality. Emperors paid for this research, hoping to cheat death. For centuries, alchemists heated, boiled and blended every substance they could find. Sadly, many of their elixirs contained poisons such as mercury and arsenic, and historians think several Chinese emperors may have died from drinking them.","Three ingredients in the alchemists' jars turned out to be very special when put together. The first was saltpeter, the white crystals, which chemists today call potassium nitrate. It forms naturally where plant and animal waste rots into the soil, and in China it could be found as a crust on the ground or on cave walls. Alchemists already used it in medicines and knew it made fires flare up brightly. The second was sulfur, a yellow mineral that burns with a blue flame and a terrible smell. The third was charcoal, made by slowly baking wood with very little air until it turns into light, black, easy-to-burn lumps.","Nobody knows the name of the person who first mixed these together. But by the time of the Tang dynasty, which ruled China from 618 to 907, alchemy books were starting to describe what happened. One text dated to 808 gives a recipe of sulfur, saltpeter and a dried plant called birthwort, which would have provided the carbon that charcoal usually supplies. A little later, probably in the middle of the 9th century, a Daoist book called the Zhenyuan miaodao yaolüe, roughly 'Classified Essentials of the Mysterious Dao of the True Origin of Things', included a list of dangerous recipes that alchemists should avoid. One of them was a warning: some people had heated sulfur, realgar and saltpeter together with honey, and the mixture had burst into flame, burning their hands and faces, and even burning down the whole house.","That is the earliest clear description of something like gunpowder. Instead of a medicine for long life, the alchemists had found one of the most dangerous substances in history. The Chinese name it was given tells you where it came from: huoyao, which means 'fire medicine'. Even today, the Chinese word for gunpowder is still huoyao.","It is worth pausing on how much luck and patient work went into this. The right proportions matter enormously. Too little saltpeter and the mixture just smoulders. The ingredients must be ground very fine and mixed very thoroughly. And saltpeter collected from nature is full of other salts that spoil it, so it has to be purified. Over the next few hundred years, Chinese craftsmen would gradually learn all of these tricks, step by step, by trial and error, and sometimes by painful accident."]},{"heading":"How Fire Medicine Works","paragraphs":["Why is gunpowder so different from an ordinary fire? Think about a campfire. Wood burns only because oxygen from the air reaches it. Cover a fire with a lid or a blanket and it goes out, because it has used up the oxygen and no more can get in. A fire needs two things: a fuel, like wood, and an oxidizer, something that supplies the oxygen. Normally the oxidizer is simply the air around us.","Gunpowder carries its own oxidizer mixed right inside it. That is the job of the saltpeter. When saltpeter gets hot, it releases oxygen. The charcoal and sulfur are the fuels, and the sulfur also helps the mixture catch fire at a lower temperature and burn faster. Because the oxygen is already mixed in, tiny grain by tiny grain, gunpowder does not have to wait for air to drift in. It can burn incredibly fast, and it can even burn inside a closed tube, underwater or, as people would discover much later, in the airless emptiness of space.","When gunpowder burns, the solid powder turns very quickly into a large amount of extremely hot gas, along with smoke made of tiny solid particles. Gas takes up far more space than solid powder. Squeezed into a small space, that hot gas pushes outward hard in every direction. If the powder is sealed inside a strong container, the pressure builds until the container bursts with a bang. That is an explosion. If one end of the container is open, the gas rushes out of that end in a fierce jet. And that jet, as we will soon see, is what makes a rocket go.","Much later, in Europe, the classic recipe for gunpowder settled at roughly 75 parts saltpeter, 15 parts charcoal and 10 parts sulfur. Early Chinese mixtures often had a lot less saltpeter, around half the mixture. Those weaker powders did not explode well. Instead they fizzed, flared and spat flames, burning fiercely for a few seconds. For a weapon meant to set things on fire, or for a tube that needs to push steadily rather than blow apart, that was actually useful. The history of gunpowder weapons is partly the story of people slowly adding more and more saltpeter, and learning to purify it, until the powder became truly explosive.","So here, at last, is the answer to the great puzzle from the end of the last part. People had wondered how anything could move where there was no air to push on. Gunpowder burns without needing air from outside, and the gas it makes can push a tube forward. Nobody in medieval China was thinking about space, of course. But the key ingredient for every rocket that would ever fly, a propellant that brings its own oxidizer along, had arrived."]},{"heading":"A Book of War Secrets: the Wujing Zongyao","paragraphs":["In 960, a new dynasty, the Song, took power in China. It would rule, in one form or another, until 1279. The Song era was an age of astonishing invention. Printing with movable type was invented in this period. Magnetic compasses were being used for navigation. Huge cities bustled with markets, restaurants and theatres. But the Song empire also faced dangerous neighbours to the north and west, kingdoms of skilled horse-riding warriors. The Song government needed every advantage it could find, and it took a very close interest in the new fire medicine.","In the year 1044, scholars working for Emperor Renzong of Song finished a giant military encyclopedia called the Wujing Zongyao, which means something like 'Collection of the Most Important Military Techniques'. Its chief compilers were officials named Zeng Gongliang, Ding Du and Yang Weide, and the emperor himself wrote the preface. The book covers everything a Song general might need to know, from choosing campsites and organizing troops to building siege machines, warships and catapults.","Tucked inside are some of the earliest written recipes for gunpowder in the world. The formulas list saltpeter, sulfur and charcoal, along with other ingredients such as oils, waxes, resins and plant materials that helped the mixture stick together, burn longer or make thick smoke. Some recipes were for incendiary bombs, packages of burning powder wrapped in paper or other materials and hurled at the enemy by catapults. Others made poisonous smoke. And the book describes fire arrows, arrows carrying gunpowder that would set targets ablaze.","The original 1044 edition of the Wujing Zongyao has been lost. The oldest copy that survives today was printed in 1510, during the later Ming dynasty, so historians have to be a little careful about whether every detail and drawing matches the first version. Even so, the book shows that by the middle of the 11th century, gunpowder had moved out of the alchemist's workshop and into the official arsenals of the Chinese state, where workers produced it in large quantities.","Notice something important, though. The gunpowder in the Wujing Zongyao was mostly used for burning, not blasting or flying. The fire arrows described there were still ordinary arrows, shot from a bow, that happened to carry a burning package. The next big step would be to let the powder do the shooting itself."]},{"heading":"From Burning Arrow to Flying Arrow","paragraphs":["Here is a tricky puzzle for historians. Chinese writers used the same word, huojian, meaning 'fire arrow', for two very different things. One was an ordinary arrow, fired from a bow, carrying a little bundle of burning gunpowder near its tip. The other was a true rocket: an arrow that flew by itself, pushed along by a tube of gunpowder burning behind it. When an old document says that soldiers used fire arrows, it often does not tell us which kind. That is one reason it is so hard to say exactly when the first rocket flew.","The official history of the Song dynasty records that in 969 an officer named Feng Jisheng (sometimes written Feng Zhisheng) presented a new kind of fire arrow to the court, and that around the year 1000 another official, Tang Fu, presented more fire weapons. Some books say these were the first rockets. Many historians, however, think they were more likely improved incendiary arrows of the bow-shot kind. The British scientist and historian Joseph Needham, who spent decades studying the history of Chinese science, argued that the gunpowder recipes of the 11th century were not strong enough to push a rocket, and that true rockets probably did not appear before the 12th century.","How might the change from burning arrow to flying arrow have happened? The Smithsonian's National Air and Space Museum in Washington, DC, has a set of models that illustrate one popular theory. First came an ordinary arrow. Then came an incendiary arrow, with a tube of burning mixture tied on and pointing forward. Then, perhaps when someone noticed what happened when the gas escaped backward, came the rocket arrow, with the tube turned the other way round so that its open end faced backward. Now the jet of hot gas shot out behind, and the arrow was pushed forward, with no bow needed at all.","A rocket arrow of this kind was simple. Workers took a tube of bamboo or thick paper, packed it tightly with gunpowder, and closed off the front end. At the back they left an opening for the gas to escape, with a fuse to light it. The tube was tied to a long, thin stick, the arrow shaft, which acted like a tail. The long stick kept the rocket pointing in roughly the same direction as it flew, much like the stick on a modern firework rocket. Light the fuse, and with a hiss and a trail of sparks the arrow would leap away.","The rocket arrow works because of the principle you met in Part 1 with Hero's spinning steam ball: when the tube throws gas out of its back, the gas pushes the tube forward. Nobody in medieval China had a scientific law to describe this. They learned it by doing. And what they built was, in all the ways that matter, a genuine rocket: a vehicle carrying its own fuel and oxidizer that moves by blasting hot gas out behind it.","One clue to the rocket's birth comes not from war but from fun. In the late 12th century, Chinese writers described a firework called the dilaoshu, or 'ground rat'. It was a small tube of gunpowder that, when lit, went zooming and skittering wildly across the ground in all directions, like a frightened rat. Researchers at the Smithsonian, Frank Winter, Michael Neufeld and Kerrie Dougherty, have argued that the ground rat is the earliest device that clearly fits the definition of a true rocket, something that moves purely by its own push. There is even a famous story about one: at an imperial banquet in 1264, a ground rat firework darted towards the emperor's mother, frightening her so much that the party was stopped. These researchers suggest the rocket may have been discovered by accident, perhaps when a firework tube burst open at one end and shot away, rather than designed on purpose.","By the middle of the 1200s, the evidence becomes firm. Records describe rockets used in a Song navy exercise in 1245. From then on, rockets, or rocket arrows, appear again and again in Chinese military writing."]},{"heading":"Fire Over Kaifeng, 1232","paragraphs":["The most famous early story of fire arrows in battle comes from the city of Kaifeng, beside the Yellow River in northern China. Kaifeng had once been the glittering capital of the Song dynasty, one of the largest cities in the world. But in 1127 the Song lost northern China to the Jin dynasty, founded by the Jurchen people from the northeast, and the Song moved their capital south to Hangzhou. By the early 1230s, Kaifeng was the capital of the Jin.","Then a new power swept in from the steppes of Mongolia. The Mongols, united under Genghis Khan and then led by his son Ögedei, were the most feared army of the age, masters of fast horses and the bow. In 1232, a Mongol army whose generals included the famous commander Subutai surrounded Kaifeng. The siege that followed was one of the first in history in which gunpowder weapons played a major part.","The Jin defenders used several kinds of fire weapons. One was the zhentianlei, the 'thunder that shakes the heavens', an iron container packed with gunpowder that exploded with a roar people said could be heard many kilometres away. The defenders were said to lower these on chains down the city walls onto Mongol soldiers who were digging under the walls while sheltering beneath cowhide screens. Another weapon was the fire lance, a tube of gunpowder fixed to the end of a spear, which spat a jet of flame for a few moments, like a short-lived flamethrower, before the soldier used it as an ordinary spear.","And then there were what old accounts call 'arrows of flying fire', or 'flying fire lances'. Many rocket history books, including NASA's, describe these as the first recorded use of true rockets in war: tubes of gunpowder attached to long sticks, flying through the air and trailing fire. Historians are honestly not sure. The descriptions are short, and the words could also mean fire lances that shot out flames and sparks, or incendiary arrows fired from bows. It is entirely possible that some of the weapons at Kaifeng were rockets, but we cannot be certain. What we can say is that the Mongols were reportedly very frightened of these fire weapons, and that they made a deep impression.","The fire weapons did not save the city. The defenders held out for months, but famine and disease spread inside the walls, and in 1233 Kaifeng fell to the Mongols. The Jin dynasty itself came to an end the following year. The Mongols, however, had learned a valuable lesson. They began to recruit Chinese and Jurchen experts in gunpowder and siege warfare and to use these weapons themselves, carrying them across Asia as their empire grew."]},{"heading":"Rockets Ride West","paragraphs":["By the middle of the 1200s, the Mongol Empire stretched from Korea to the edge of Europe, the largest connected land empire the world has ever seen. Along its roads travelled merchants, diplomats, soldiers, engineers and ideas. Many historians believe this is how knowledge of gunpowder, and of rockets, spread so quickly from China to the rest of Asia and to Europe, although the exact routes are debated and written evidence is patchy.","Some of the clearest early evidence outside China comes from the Middle East. Around 1270 to 1280, a Syrian military writer named Hasan al-Rammah wrote a book about horsemanship and ingenious war devices. It contains about 107 gunpowder recipes, and 22 of them are for rockets. He also explained how to purify saltpeter using wood ashes, a crucial trick for making strong powder. His choice of words shows where the knowledge had come from: he called saltpeter 'Chinese snow' and rockets 'Chinese arrows'. Al-Rammah said he had learned much from his father and grandfathers, which suggests that gunpowder had already been known in Syria and Egypt for some time.","In Europe, the English friar and scholar Roger Bacon described a powder of saltpeter that made a loud noise and a bright flash in his work Opus Majus, written in 1267. He mentioned it being used in children's toys made in various parts of the world. Over the next century and a half, European writers described more and more rocket-like weapons. A German military engineer, Konrad Kyeser, drew several types of rockets in his book Bellifortis around 1405. An Italian engineer, Joanes de Fontana, sketched imaginative rocket-powered devices around 1420, including a rocket-driven car and a rocket torpedo meant to skim across water and set enemy ships on fire.","Meanwhile, in East Asia, rocket technology kept growing. In Korea, an official named Choe Mu-seon began producing gunpowder in the 1370s, and Korean forces built rocket weapons. By 1451, Korean engineers had created the hwacha, a wooden cart with a launching frame that could fire around a hundred rocket arrows in one terrifying volley. In China, a military manual called the Huolongjing, or 'Fire Drake Manual', from the 14th century, described all kinds of rocket weapons. One, called the 'fire dragon issuing from the water', is thought to be the earliest known two-stage rocket: a set of booster rockets carried a wooden dragon-shaped tube through the air, and when they burned out, they lit more rockets inside the dragon's mouth, which shot out towards the enemy. Ming dynasty armies also used 'wasp nest' launchers, boxes that could fire dozens of small rocket arrows at once.","These rockets were not very accurate. Many flew wildly off course, and some exploded at launch. Their real power was often in the noise, smoke and fear they caused, especially among horses. But they could be made cheaply, carried easily and fired in great numbers. Little by little, the fire arrow had become a weapon known across much of the world."]},{"heading":"Sparkles in the Sky: Fireworks","paragraphs":["Gunpowder was not only for war. From early on, it was also used to celebrate. Long before gunpowder, people in China threw lengths of green bamboo onto fires at New Year. As the air and moisture inside each section heated up, the bamboo burst with a loud crack. The noise was traditionally believed to scare away evil spirits and bad luck. Once gunpowder was known, people began packing it into bamboo or paper tubes to make a much louder, more reliable bang. These were the first firecrackers.","During the Song dynasty, fireworks became part of city life and celebrations. The playful ground rat was one kind. Others sputtered, sparkled or shot up into the air. Festival crowds watched entertainers set off displays, and fireworks were part of grand imperial celebrations, as the story of the frightened empress-mother at the 1264 banquet shows. Skilled fireworks makers became craftspeople in their own right.","Fireworks and rockets are close cousins. A skyrocket, the kind that whooshes up on a stick and bursts high above, is a tiny rocket: a tube of slow-burning powder that pushes it upward, carrying a small charge that bursts at the top. The same knowledge that went into war rockets also created beautiful displays, and fireworks makers were often among the most expert users of gunpowder anywhere.","As gunpowder spread west, so did the love of fireworks. By the time of the Renaissance, Italian cities were famous for spectacular displays, and later, kings and queens across Europe staged huge firework shows to celebrate victories, weddings and coronations. Today, when you watch a New Year or national holiday fireworks show and hear the crowd gasp, you are watching a tradition that began in China roughly a thousand years ago."]},{"heading":"The Man on the Rocket Chair: A Legend","paragraphs":["If you read about the history of rockets, sooner or later you will meet the story of Wan Hu. It is a wonderful tale, and it is told so often that many people think it is true. But it is a LEGEND, with no historical evidence behind it at all.","The story goes like this. Long ago in China, an official named Wan Hu decided to fly to the heavens. He had a sturdy chair built and fixed 47 large rockets to it, along with two big kites. On launch day, dressed in his finest robes, he sat in the chair while 47 servants, each holding a torch, rushed forward to light the fuses all at once. There was a tremendous roar and a huge cloud of smoke. When the smoke cleared, Wan Hu and his chair were gone, never to be seen again. Some say he flew to the Moon. More likely, the storytellers add, he was blown to pieces.","So where does this story come from? Not from any old Chinese book. Researchers have found no record of it in Chinese historical writing. An early forerunner of the tale appeared in the American magazine Scientific American in 1909, in which the hero was called 'Wang Tu' and the story ended with the rockets exploding. The version with the name Wan Hu and the 47 rockets was spread widely by an American author, Herbert Zim, in a 1945 book called Rockets and Jets, which gave no source for it. Joseph Needham thought the story was doubtful and might have been invented in the West. Some writers in China have since suggested a real person behind it, but no surviving evidence supports this.","The television show MythBusters tested the idea in 2004. They built a chair with rockets, using a crash-test dummy instead of a person. The result was a fiery mess, and the show concluded that such a chair would never have carried anyone very far, let alone into space. Still, the legend became so famous that in 1970 the International Astronomical Union named a crater on the far side of the Moon Wan-Hoo after him.","Why does a legend like this matter? Because it shows how easily a good story can slip into history books. Wan Hu's chair makes a great picture: a brave dreamer, a roaring blast, a mystery. But a historian's job is to ask: how do we know? Where is the evidence? For the real rockets of China, we have military books, official histories, museum reconstructions and records from many countries. For Wan Hu, we have only a story first printed in the 20th century, far from China. It is fine to enjoy it, as long as we remember it is a legend.","The real history is exciting enough. In a few hundred years, gunpowder had gone from an alchemist's accident to a weapon and a celebration known from Korea to England. Rockets would remain a common weapon for centuries, crude, loud and unpredictable. And then, in southern India, a ruler and his son would build rockets with iron casings that made them far more powerful than anything seen before."]}],"deepDive":"Two big debates surround the origins of the rocket. The first is about definitions and dates. Chinese sources use huojian ('fire arrow') both for bow-fired incendiary arrows and for self-propelled rocket arrows, so a record of 'fire arrows' in, say, 969 or 1000 does not by itself prove rockets existed. Joseph Needham, author of the monumental Science and Civilisation in China, argued that the earliest surviving gunpowder formulas, those in the Wujing Zongyao of 1044, contain too little saltpeter (around half the mixture, compared with roughly 75 percent in later European black powder) to work as an efficient propellant, and so placed true rockets no earlier than the 12th century. The first unambiguous evidence includes the 'ground rat' firework described in the late 12th century, a Song naval exercise of 1245 and the 1264 banquet incident. Smithsonian historians Frank Winter, Michael Neufeld and Kerrie Dougherty go further, suggesting the rocket was not deliberately invented at all but discovered by accident, perhaps when a firework tube vented from one end and skittered away. The 1232 'flying fire' at Kaifeng is often cited as the first battlefield use of rockets, but the Chinese term (fei huo qiang) can also be read as a fire lance, a hand-held flame-spewing tube, so many specialists treat Kaifeng as possible rather than proven. The second debate concerns how gunpowder spread. One school, represented by historians such as Tonio Andrade and Stephen Haw, sees the Mongol Empire as 'the first gunpowder empire', moving Chinese technicians and techniques across Eurasia. Others, such as Kate Raphael, point out how thin the written evidence for Mongol transmission actually is. What is not in doubt is the direction of travel: the vocabulary of Hasan al-Rammah, who called saltpeter 'Chinese snow' and rockets 'Chinese arrows', and the relatively late dates of the first Middle Eastern (about 1240 to 1280) and European (Roger Bacon, 1267) formulas all point back to China. The underlying chemistry also explains the slow pace of progress. Saltpeter must be purified, typically by dissolving it, treating it with wood ash to remove calcium and magnesium salts and recrystallizing it, before powder becomes strong and reliable. Each improvement in purification and proportion made rockets more powerful.","funFact":"A crater on the far side of the Moon is officially named Wan-Hoo after the man in the rocket-chair legend, even though there is no evidence he ever existed.","check":{"q":"What three ingredients are mixed to make gunpowder?","a":"Saltpeter, charcoal and sulfur","wrong":["Salt, flour and oil","Sand, iron and coal","Sulfur, sugar and water"]},"sources":[{"title":"Brief History of Rockets","publisher":"NASA Glenn Research Center","url":"https://www.grc.nasa.gov/www/k-12/TRC/Rockets/history_of_rockets.html"},{"title":"Model, Arrow (ordinary, incendiary and rocket arrows)","publisher":"Smithsonian National Air and Space Museum","url":"https://airandspace.si.edu/collection-objects/model-arrow/nasm_A19762057000"},{"title":"The History of Rocket Science","publisher":"Smithsonian Magazine","url":"https://www.smithsonianmag.com/innovation/the-history-of-rocket-science-4078981/"},{"title":"History of gunpowder","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_gunpowder"},{"title":"History of rockets","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/History_of_rockets"},{"title":"Wan Hu","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Wan_Hu"},{"title":"Wujing Zongyao","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Wujing_Zongyao"}],"photos":[{"src":"img/deep/rockets/02-1.jpg","alt":"Pages of the Wujing Zongyao (1044) with the earliest known written gunpowder formula, in a later printed edition.","file":"Chinese Gunpowder Formula.JPG","url":"https://commons.wikimedia.org/wiki/File:Chinese_Gunpowder_Formula.JPG","author":"PericlesofAthens","license":"Public domain"},{"src":"img/deep/rockets/02-2.jpg","alt":"The \"fire dragon issuing from the water\" from the Huolongjing: a dragon-shaped two-stage rocket that fires arrows from its mouth.","file":"Chinese Multistage Rocket.JPG","url":"https://commons.wikimedia.org/wiki/File:Chinese_Multistage_Rocket.JPG","author":"PericlesofAthens","license":"Public domain"},{"src":"img/deep/rockets/02-3.jpg","alt":"A rebuilt Korean hwacha cart loaded with rocket arrows; this style could launch about 100 arrows at once.","file":"Hwacha-Shinkigeon Style.jpg","url":"https://commons.wikimedia.org/wiki/File:Hwacha-Shinkigeon_Style.jpg","author":"Kang Byeong Kee","license":"CC BY 3.0"}],"words":4238},{"n":3,"title":"Iron Rockets and the Red Glare","when":"1600s – 1800s","summary":"In India, the armies of Mysore built rockets with strong iron tubes that could fly much further than anyone else's. The British copied them, and soon rockets were streaking across battlefields all over the world, even lighting up the sky over an American fort in a famous song. Meanwhile, a genius named Isaac Newton wrote down the simple law that explains how every rocket moves.","sections":[{"heading":"A Gunner's Book Full of Rockets","paragraphs":["By the 1600s, rockets were no longer a Chinese secret. They had spread across Asia, the Middle East and Europe, mostly as fireworks for royal parties and as noisy, unpredictable weapons. People who made them worked from experience, not from science. A good rocket maker knew which powder mixtures burned well, how tightly to pack a tube, and how long the guiding stick should be. But nobody could explain exactly why a rocket flew, and every maker guarded his own tricks.","Then, in 1650, a thick book was printed in Amsterdam with a grand Latin title: Artis Magnae Artilleriae, pars prima, which means 'The Great Art of Artillery, Part One'. Its author was Kazimierz Siemienowicz, an artillery expert born around 1600 in the Grand Duchy of Lithuania, which was then joined with the Kingdom of Poland in one large state called the Polish–Lithuanian Commonwealth. Siemienowicz had served as a senior artillery officer, and his book collected everything he knew about cannons, gunpowder and fireworks.","A big part of the book was about rockets. Siemienowicz described how to make rocket tubes, how to mix and pack the powder, and how to test them. He showed rockets launched in batteries, many at once. Most surprisingly, he drew rockets stacked on top of one another, so that when the first one burned out, the next one would light and keep pushing. That is the idea of a multi-stage rocket, the same idea that would one day carry astronauts to the Moon. He also drew rockets with triangle-shaped fins, a shape we now call a delta wing, which could keep a rocket flying straight without the usual long wooden stick.","Was he the first to think of stages? Fair credit matters here. In 1961, historians studied a manuscript written in the 1500s by Conrad Haas, an artillery officer working in Sibiu, in what is now Romania. Haas had also sketched multi-stage rockets and delta-shaped fins about a hundred years earlier. Some historians think Siemienowicz may have known of similar ideas; others think he came to them on his own. Either way, Siemienowicz's book was the one that was printed, read and copied.","And copied it was. The Great Art of Artillery was translated into French, German, Dutch and English, and for more than a century it was used as a standard handbook by artillery officers across Europe. Imagine a young officer in the 1700s, in a cold barracks room lit by a candle, turning the pages and studying the engraved pictures of rockets and fireworks. Siemienowicz's book did not launch anything into space, of course. But it showed that rockets could be studied carefully, written down, improved and taught, like any other branch of engineering.","Still, something big was missing. Siemienowicz could tell you how to build a rocket, but not why it worked. That answer would come from England, from a quiet professor at Cambridge University who never built a rocket in his life."]},{"heading":"Newton Explains the Push","paragraphs":["Isaac Newton was born in 1643 in the small village of Woolsthorpe in Lincolnshire, England. As a boy he built model windmills, water clocks and sundials. As a young man he became a professor of mathematics at Cambridge, where he worked on light, colours, mathematics and the movement of the planets. In 1687 he published a book that changed science forever. Its Latin title is Philosophiae Naturalis Principia Mathematica, which means 'Mathematical Principles of Natural Philosophy'. Most people just call it the Principia.","The book exists partly thanks to Newton's friend, the astronomer Edmond Halley, the same Halley after whom Halley's Comet is named. Halley encouraged Newton to write down his ideas and even paid for the printing himself. Near the start of the Principia, Newton set out three simple rules for how things move. We call them Newton's laws of motion.","The first law says that an object keeps doing what it is doing, sitting still or moving in a straight line at the same speed, unless a force pushes or pulls it. The second law says that a bigger force makes a bigger change in motion, and that heavy things are harder to speed up than light things. The third law is the one every rocket depends on. In a famous English translation from 1729, it reads: 'To every action there is always opposed an equal reaction.'","What does that mean in real life? It means forces always come in pairs. If you push on something, it pushes back on you just as hard, in the opposite direction. Stand on a skateboard and throw a heavy basketball forwards: you roll backwards. Fire a cannon, and the cannon jumps back, which gunners call recoil. Blow up a balloon and let it go: the air rushes out of the neck one way and the balloon zooms off the other way.","A rocket is just a very powerful, very organised version of that balloon. Inside the rocket, fuel burns and turns into a huge amount of hot gas. The gas is squeezed out through an opening at the back at enormous speed. The rocket pushes the gas backwards, and the gas pushes the rocket forwards. That forward push is called thrust. Notice something important: the rocket is not pushing against the ground or the air behind it. It pushes against its own exhaust. That is why, as later chapters will show, rockets work even better in empty space, where there is no air to get in the way.","Newton himself was not thinking about spaceships. He was explaining falling apples, swinging pendulums, ocean tides and the paths of planets around the Sun. Yet in the same book he also showed that one single force, gravity, holds the Moon in its path around the Earth. Together, his laws of motion and his law of gravity are exactly the tools that rocket engineers still use today to plan every launch and every orbit. When NASA calculated the path of the Apollo spacecraft to the Moon in the 1960s, it was doing Newton's kind of mathematics, just with faster computers.","For more than a century after 1687, though, hardly anyone connected Newton's third law with the fireworks and war rockets that were still being made by hand. The next big leap in rocket building did not come from a university at all. It came from southern India."]},{"heading":"The Iron Rockets of Mysore","paragraphs":["In the 1700s, the Kingdom of Mysore was a powerful state in the south of India. Its capital was the island fortress of Srirangapatna, which British writers of the time spelled Seringapatam. Around 1761, a talented soldier named Hyder Ali took control of the kingdom. He was a military commander who had risen from fairly humble beginnings, and he was eager to use the newest weapons he could find, from European-style cannons and muskets to rockets.","Mysore was in a dangerous spot. The British East India Company, a trading company that had its own private army, was taking over more and more of India. Between 1767 and 1799, Mysore and the Company fought four wars, now called the Anglo-Mysore Wars. In these wars, Mysore's rocket troops became famous, and feared.","What made Mysore's rockets special? Most rockets of that time, in Europe and elsewhere, had tubes made of paper, cardboard or wood. These were fine for fireworks, but they could not hold much pressure. Pack them too hard, or make the powder burn too fiercely, and the tube would burst. Mysore's rocket makers instead used tubes of hammered iron. Iron is far stronger, so the powder inside could be packed more tightly and burn at a higher pressure. Higher pressure meant faster exhaust, and faster exhaust meant a stronger push and a longer flight. Historians often describe these as the first successful iron-cased rockets.","A typical Mysore rocket tube was roughly 20 centimetres long and about 6 centimetres wide, a bit like a large tin can stretched out. It was tied to a long bamboo pole that acted like the stick on a firework rocket, keeping it pointed in roughly the right direction. The whole weapon weighed a few kilograms, and the bigger ones could fly about 2 kilometres or more. Some versions reportedly carried blades on the pole, so the rocket would slash through enemy lines as it skidded along the ground.","These rockets were not very accurate. One rocket by itself might wobble off anywhere. But a battery of hundreds of rockets fired together, screaming and trailing smoke and sparks, could frighten horses, break up lines of soldiers and set supplies on fire. Hyder Ali's army already had special companies of rocket men. His son, Tipu Sultan, expanded them much further; several accounts say that by the early 1790s Tipu's rocket troops numbered about 5,000, though numbers from that time are hard to check. A military manual written for Tipu, called the Fathul Mujahidin, even set out how rocket men should be organised in each brigade.","The rockets made a strong impression at the Battle of Pollilur on 10 September 1780, during the Second Anglo-Mysore War. There, Mysore's army defeated a large British force under Colonel William Baillie. According to accounts of the battle, a rocket or shell may have set off the British ammunition carts in a massive explosion, which helped break the British lines. Historians cannot be completely sure exactly which weapon caused the blast, but British officers came away with a healthy respect for Mysore's rockets.","Tipu Sultan, who was born in 1751 and became ruler after Hyder Ali died in 1782, was clever, well educated and interested in science and new technology. He was also a tough opponent who kept fighting the British for most of his reign. His tiger symbol appeared on his flags, his weapons and even his throne, and he was nicknamed the Tiger of Mysore."]},{"heading":"The Fall of the Tiger's Fortress","paragraphs":["In 1792, at the end of the Third Anglo-Mysore War, a British-led army reached Seringapatam. Once again, Tipu's rocket troops fired volley after volley, especially at night, when the glowing trails made them even more alarming. Tipu lost that war and had to give up about half of his kingdom, but he kept his throne and his fortress.","Seven years later, in 1799, the British came back for the Fourth Anglo-Mysore War. A large army, including thousands of Indian soldiers serving the East India Company and troops from the neighbouring state of Hyderabad, marched on Seringapatam and surrounded it. Among the British officers was a young colonel named Arthur Wellesley, who would later become famous as the Duke of Wellington. During the siege, Mysore's rockets again harassed the attackers, especially during night fighting in the groves and trenches around the fort.","On 4 May 1799, British-led troops broke through a gap blasted in the walls and stormed the city. Tipu Sultan died fighting near one of the gates. With him ended the independent Kingdom of Mysore as a great power; the British put a young member of the old royal family on the throne, under their control.","Inside the captured fortress, the British found warehouses full of weapons. Among them, according to the usual count, were about 700 rockets ready for use, around 600 launchers and some 9,000 empty rocket cases. Some of these were packed up and shipped thousands of kilometres to England, to the Royal Arsenal at Woolwich, near London, where the British army tested and stored its weapons. A few Mysore rockets survive today in museums, a reminder that one of the key steps in rocket history happened in India.","It is worth pausing on that. When people tell the story of rockets, they sometimes jump straight from ancient China to European and American scientists. But the iron rockets of Mysore were a real engineering advance, made by Indian craftsmen and soldiers. Many Indians today are proud of this history. A. P. J. Abdul Kalam, a rocket engineer who helped build India's space and missile programmes and later became President of India, often spoke of Tipu's rockets as an early chapter in his country's long story with rocketry."]},{"heading":"Congreve Copies and Improves","paragraphs":["At Woolwich, the captured rockets caught the eye of a young Englishman named William Congreve. Born on 20 May 1772, he was the son of another William Congreve, an army general who was in charge of the Royal Laboratory at Woolwich Arsenal. The younger Congreve had studied at Trinity College, Cambridge, the same college where Newton had once worked. He was full of ideas and inventions, and he was very good at persuading important people to support them.","Around 1804, Congreve began studying rockets seriously. He bought the best rockets he could find in London, took apart Indian examples, and ran test after test. His early rockets flew only a few hundred metres, much less than the Mysore weapons, so he experimented with stronger iron cases, better powder and different shapes. By 1805 he could show his rockets to the British Prime Minister, William Pitt the Younger, who agreed to fund more work.","Congreve's finished rockets came in a whole family of sizes, named by weight, like cannon balls. There were small ones of a few pounds, and huge ones of 100 pounds or more. The most common was the 32-pounder, about 14.5 kilograms. Its iron case was a bit over a metre long and about 10 centimetres wide, and it was attached to a long wooden guide stick around 4.5 metres long. These rockets could reach about 2.7 kilometres, roughly 9,000 feet. They could carry an explosive or fire-starting charge in the nose, or a load of small metal balls that burst over enemy troops.","The great advantage of rockets was that they needed no heavy cannon. A cannon that could throw a large shell weighed tonnes and needed a team of horses to pull it. A rocket was launched from a simple frame or tube, or even from the ground. A small boat could carry rocket launchers. That made rockets perfect for the British Royal Navy, which could carry them close to enemy coasts.","Congreve's rockets went into action against Napoleon's France. On 8 October 1806, British boats fired a barrage of about 2,000 rockets at the French port of Boulogne, where Napoleon had once gathered an army to invade England, and parts of the town caught fire. In 1807, during the British attack on Copenhagen in Denmark, cannons, mortars and rockets set large parts of the city ablaze. In October 1813, at the huge Battle of Leipzig in Germany, a small British Rocket Troop fought alongside Britain's allies; its commander, Captain Richard Bogue, was killed there.","Rockets were scary, but they were still wild. Their flight could be thrown off by a gust of wind, by uneven burning, or by the long stick catching on something. Some rockets even curved around and came back toward the people who had fired them. Many soldiers were not impressed. Others thought rockets were worth it for their shock value and the fires they could start. Congreve, for his part, kept improving his designs, writing books about his rocket system, and even proposing rockets for whaling and for firing rescue lines to shipwrecks."]},{"heading":"The Rockets' Red Glare","paragraphs":["Meanwhile, across the Atlantic, Britain was at war with the young United States. The War of 1812 lasted from 1812 to early 1815, and Congreve's rockets crossed the ocean with the Royal Navy. On 24 August 1814, at the Battle of Bladensburg in Maryland, British rockets screeched over the inexperienced American militia, and many of them fled. That same evening, British troops marched into Washington, D.C., and set fire to the White House and the Capitol.","Next, the British turned toward the busy port city of Baltimore. To reach it by sea, their warships had to get past Fort McHenry, a star-shaped brick fort guarding the harbour, commanded by Major George Armistead. At about 6:30 in the morning on 13 September 1814, British ships began a bombardment that went on through the day and the stormy night, about 25 hours in all.","The main weapons were bomb ships, which fired heavy exploding shells high into the air with mortars, so that they came down on the fort from above. The British fired an estimated 1,500 to 1,800 shells and rockets. A special rocket ship, HMS Erebus, launched 32-pounder Congreve rockets, whose fiery trails arced across the dark, rainy sky. The fort's own cannons could not reach most of the British ships, so the defenders mostly had to wait and endure. One American soldier later said they felt like pigeons tied by the legs to be shot at.","Watching from a ship several kilometres away was a 35-year-old American lawyer and amateur poet named Francis Scott Key. He had sailed out to the British fleet to arrange the release of a friend, Dr William Beanes, who had been taken prisoner. The British agreed to free Beanes but would not let the Americans go until the attack was over, because they had seen the British plans. So Key spent the long night on a small American truce ship, staring toward the fort, trying to see through the smoke, rain and darkness whether it had surrendered.","Every flash of a bursting shell and every streak of a rocket lit up the fort for a moment. In the morning of 14 September, as the firing stopped, the soldiers at Fort McHenry raised a huge garrison flag, about 9 by 13 metres (30 by 42 feet), sewn by the Baltimore flag maker Mary Pickersgill and her helpers. When Key saw the Stars and Stripes still flying, he knew the fort had held.","Deeply moved, Key wrote a poem about that night, first called 'Defence of Fort M'Henry'. It describes 'the rockets' red glare, the bombs bursting in air' giving 'proof through the night that our flag was still there'. The poem was soon printed and sung to the tune of a popular British song. It became known as 'The Star-Spangled Banner', and in 1931 the US Congress made it the official national anthem of the United States. The great flag itself survives and is cared for today at the Smithsonian's National Museum of American History in Washington.","There is a funny twist to the story. For all their noise and glare, the rockets did very little real damage at Fort McHenry. The fort was only lightly damaged, and only four of its defenders were killed, with about two dozen wounded. The British could not get past the fort, and their attack on Baltimore failed. So one of the most famous mentions of rockets in history celebrates a night when rockets lost the battle. Still, every time Americans sing their anthem at a baseball game or the Olympics, they are singing about Congreve's rockets, copied from the iron rockets of Mysore."]},{"heading":"Spinning Rockets and the Long Goodbye","paragraphs":["The biggest problem with Congreve rockets was that long wooden stick. It was heavy, clumsy to carry, and not very good at keeping the rocket on course. An English inventor named William Hale, born in 1797 in Colchester, thought he could do better. He noticed something that every footballer and every rifle maker knows: a spinning object flies straighter. A rifle bullet spins because of spiral grooves inside the barrel, and the spin keeps it from tumbling.","In 1844, Hale patented a stickless rocket. Instead of a guide stick, part of the rocket's exhaust escaped through angled holes and pushed against small curved vanes near the tail. This made the rocket spin rapidly as it flew, like a spinning top racing through the air. The spin evened out small wobbles and uneven burning, so the rocket flew much more accurately. Hale's rockets were among the first spin-stabilised rockets in history, and the same basic idea of using spin to steady a rocket is still used on some rockets and spacecraft today.","The United States Army was first to use Hale rockets in battle, during the Mexican–American War. In March 1847, an American rocket brigade of around 150 men fired hundreds of Hale rockets during the siege of Veracruz, the Mexican port city, which surrendered on 29 March. The British army tried Hale rockets in the Crimean War in the 1850s and officially adopted them in 1867. Austria had its own rocket corps too, and rockets were used in a number of colonial wars in Africa and Asia.","But by then, rockets were losing a race they could not win. In the middle and late 1800s, factories in Britain, Germany, France and the United States were making far better cannons. New cannons had spiral grooves inside their barrels, called rifling, which made their shells spin, just like Hale's rockets but with far more power. They loaded from the back instead of the muzzle, which was faster and safer. They were made of strong steel and could hit targets many kilometres away with impressive accuracy. Compared with these guns, black-powder rockets were weak, short-ranged and unreliable.","One by one, armies retired their rocket troops. Hale rockets lingered in British service for decades, but they were already old-fashioned by about 1900 and were officially declared obsolete in 1919. Rockets did not disappear completely, though. They found peaceful jobs. Coastguards used rockets to fire ropes out to ships stranded on rocks, so sailors could be pulled to safety; a two-stage rescue rocket designed by Edward Boxer in the 1860s was used for many years to throw lifelines to ships. Sailors used rocket flares to call for help. Whalers tried harpoon rockets. And of course, fireworks kept lighting up festivals and celebrations, just as they had in China centuries before.","By the end of the 1800s, a person could easily have concluded that the rocket's story was almost over: an old weapon replaced by better guns, kept alive mainly for rescues and parties. Yet hidden inside every rocket was the same simple principle Newton had described in 1687. A rocket does not need air, ground or anything else to push against. It carries everything it needs inside itself. A few dreamers were about to realise that this made the humble rocket perfect for a place where there is nothing to push against at all: outer space."]}],"deepDive":"Why did iron make such a difference? A rocket's push depends on how much gas it throws out each second and how fast that gas leaves the nozzle. Black powder burns faster and makes gas faster when it is under higher pressure, but a paper or wooden tube can only take a little pressure before it splits. Hammered iron let Mysore's makers pack more powder, more densely, into a smaller tube and burn it at higher pressure. Even so, black powder is a weak propellant by modern standards: its exhaust leaves at well under one kilometre per second, compared with roughly 2.5 to 4.5 kilometres per second for modern rocket engines. That is one reason no black-powder rocket could ever have reached space. Historians also debate how much Congreve truly owed to Mysore. Congreve himself acknowledged Indian rockets as a starting point, and captured rockets were sent to Woolwich after 1799, but British rocket experiments had earlier roots too, and Congreve's real achievement was turning rockets into a standardised, mass-produced weapon system with fixed sizes, launchers and drill. Another debate concerns Siemienowicz and the older manuscript of Conrad Haas, rediscovered in 1961, which shows similar multi-stage and finned rockets. Ideas often appear independently when people work on the same problems, and the line between borrowing and parallel invention can be hard to draw from surviving documents. Newton's third law, finally, is often misunderstood. The action and the reaction act on different objects: the rocket pushes the gas, the gas pushes the rocket. They do not cancel each other out, because they are not acting on the same thing. Newton's second law then tells you how much the rocket speeds up: the same push gives a light rocket a bigger change in speed than a heavy one. This is why rocket designers are obsessed with saving weight, a theme that would dominate the next 200 years of rocketry. The decline of war rockets after the 1860s is a good example of how a technology can stall: rifled, breech-loading steel guns simply did the job better until liquid fuels and precise guidance changed the equation in the 20th century.","funFact":"The famous line about 'the rockets' red glare' in the US national anthem describes a night when the rockets did very little harm: Fort McHenry survived a 25-hour bombardment with only four defenders killed.","check":{"q":"What made the war rockets of Mysore stronger and longer-ranged than most earlier rockets?","a":"Their tubes were made of iron, so the powder could burn at higher pressure","wrong":["They used liquid oxygen as fuel","They had paper tubes that were very light","They were launched from giant cannons"]},"sources":[{"title":"A Brief History of Rockets","publisher":"NASA Glenn Research Center","url":"https://www.grc.nasa.gov/www/k-12/TRC/Rockets/history_of_rockets.html"},{"title":"Newton's Third Law of Motion","publisher":"NASA Glenn Research Center","url":"https://www.grc.nasa.gov/www/k-12/BGP/newton3.html"},{"title":"Engineering of the Highest Caliber: Kazimierz Siemienowicz and the Culmination of the Military Revolution","publisher":"Studia Historiae Scientiarum","url":"https://ojs.ejournals.eu/SHS/article/view/8008"},{"title":"William Congreve","publisher":"New Mexico Museum of Space History","url":"https://nmspacemuseum.org/inductee/william-congreve/"},{"title":"William Hale's rotary rocket","publisher":"New Mexico Museum of Space History","url":"https://nmspacemuseum.org/inductee/william-hale/"},{"title":"Mysorean rockets","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mysorean_rockets"},{"title":"O Say Can You See: The Bombardment of Fort McHenry","publisher":"American Battlefield Trust","url":"https://www.battlefields.org/learn/articles/o-say-can-you-see-bombardment-fort-mchenry"},{"title":"Baltimore in the Balance","publisher":"Smithsonian National Museum of American History","url":"https://amhistory.si.edu/StarSpangledbanner/baltimore-in-the-balance.aspx"}],"photos":[{"src":"img/deep/rockets/03-1.jpg","alt":"Watercolour by Robert Home of a soldier of Tipu Sultan's Mysore army lifting an iron rocket on a long bamboo pole.","file":"Mysore rocket man, by Robert Home (watercolour).jpg","url":"https://commons.wikimedia.org/wiki/File:Mysore_rocket_man,_by_Robert_Home_(watercolour).jpg","author":"Robert Home","license":"Public domain"},{"src":"img/deep/rockets/03-2.jpg","alt":"William Congreve's own drawing of his rockets in many sizes, each fixed to a long guide stick.","file":"Congreve rockets new.png","url":"https://commons.wikimedia.org/wiki/File:Congreve_rockets_new.png","author":"Sir William Congreve, 2nd Baronet","license":"Public domain"},{"src":"img/deep/rockets/03-3.jpg","alt":"John Bower's 1814 print of British ships bombarding Fort McHenry near Baltimore, with shells arcing through the sky.","file":"John Bower - A View of the Bombardment of Fort McHenry - Google Art Project.jpg","url":"https://commons.wikimedia.org/wiki/File:John_Bower_-_A_View_of_the_Bombardment_of_Fort_McHenry_-_Google_Art_Project.jpg","author":"John Bower","license":"Public domain"}],"words":4035},{"n":4,"title":"The Dreamers: Verne and Tsiolkovsky","when":"1865 – 1935","summary":"A French writer named Jules Verne wrote an exciting story about people fired to the Moon from a giant cannon, and kids all over the world loved it. One of those kids was a Russian boy who had lost most of his hearing, taught himself science from library books, and became a village schoolteacher. He worked out, with pencil and paper, that rockets, not cannons, could carry people into space.","sections":[{"heading":"A Gun Club Aims at the Moon","paragraphs":["In 1865, a French author named Jules Verne published a novel called De la Terre à la Lune, which means 'From the Earth to the Moon'. Verne was 37 years old and already well known for adventure stories packed with real science, maps and numbers. Readers loved the way he made impossible journeys sound almost possible. This time, he aimed higher than ever: at the Moon itself.","The story begins in Baltimore, in the United States, just after the American Civil War. A group of retired weapons makers called the Baltimore Gun Club is bored, because the war is over and nobody needs their giant cannons any more. Their president, Impey Barbicane, makes an astonishing proposal: they will build the biggest cannon the world has ever seen and fire a shot all the way to the Moon.","The club raises money from people and governments around the world. They choose a site in Florida, a hill near Tampa that Verne calls Stone's Hill, because it is far enough south that the Moon passes almost straight overhead there. There they cast an enormous cannon straight down into the ground, a vertical iron tube about 270 metres (900 feet) long, and they name it the Columbiad. To watch the shot, they even build a giant telescope on a mountain in the Rocky Mountains.","Then the plan changes. A bold French adventurer named Michel Ardan arrives and announces that he wants to ride inside the projectile. Barbicane's bitter rival, Captain Nicholl, an expert in armour plate, had been about to fight a duel with him, but Ardan talks them both into joining him instead. The cannon ball becomes a hollow, cone-topped capsule with padded walls, windows, supplies and, rather charmingly, two dogs. On launch day, huge crowds gather, the Columbiad fires with a gigantic roar, and the three men shoot off into the sky. The book ends with the capsule seen through the telescope, circling the Moon, and the reader left wondering what happens next. Verne answered that in a sequel, 'Around the Moon', published in 1870, in which the travellers loop around the Moon and fall back to Earth, splashing down in the Pacific Ocean.","What made the book special was not just the adventure. Verne tried hard to get the numbers right. He worked with his cousin, a mathematics teacher, to estimate how fast the capsule would need to go to escape the Earth's gravity. The figure in the book, 12,000 yards per second, is about 11 kilometres per second, remarkably close to the real escape velocity of about 11.2 kilometres per second. For a novel written more than 90 years before the first satellite, that is impressive.","Some details also look eerily like the real Apollo missions a century later: a crew of three, a launch from Florida, a giant machine named Columbiad when Apollo 11's command module was named Columbia, a trip around the Moon and a splashdown in the Pacific. In July 1969, as Apollo 11 headed home, Neil Armstrong mentioned in a television broadcast from space that Jules Verne had written a book about a voyage to the Moon about a hundred years earlier. Some of these matches are coincidences, and some come from the simple fact that Florida really is a good place to launch from, but they show how carefully Verne thought things through."]},{"heading":"Why a Cannon Would Squash You Flat","paragraphs":["There was one huge problem with Verne's plan, and the science fans who read his book soon spotted it. A cannon gives its push all at once. The shot goes from standing still to full speed in the tiny moment it takes to travel up the barrel. To reach about 11 kilometres per second inside a barrel 270 metres long, Verne's capsule would have had to speed up at roughly 22,000 times the strength of normal gravity. Engineers say this as 22,000 g.","What does that mean for a person? When you stand still, you feel 1 g, your normal weight. On a big roller coaster you might feel 3 or 4 g for a moment, which pushes you hard into your seat. Fighter pilots in special suits can handle about 9 g for a few seconds before they risk blacking out. In 1954, an American air force doctor named John Paul Stapp rode a rocket sled that stopped so suddenly he felt about 46 g, but only for a split second, and even that was so painful that he compared the feeling in his eyes to having a tooth pulled without any painkiller. At 22,000 g, a passenger would weigh, for a moment, about as much as dozens of heavy trucks piled on top of them. Nobody could survive that. Verne's travellers would have been squashed flat at the bottom of the capsule.","Could you fix this by making the cannon longer? A longer barrel gives the shot more time to speed up gently. But the numbers quickly get silly. To keep the push down to a bearable 3 g, the barrel would need to be around 2,000 kilometres long, nearly three times the length of Florida from top to bottom. And there is a second problem: air. A capsule leaving the barrel at 11 kilometres per second at ground level would slam into the thick lower atmosphere at a speed where the air in front of it would heat up ferociously and slow it down hard. Even huge guns could not do the job.","People did try giant guns later, but only for small, sturdy, uncrewed shells. In the 1960s, a research project called HARP fired instrument-carrying shells from modified naval guns in Barbados and the United States, and one shot, fired in Arizona in 1966, went up to about 180 kilometres high. That reached space, but the shells were tough little packages that could survive thousands of g. A human, or even most delicate electronics, would not.","A rocket solves this beautifully. Instead of one giant kick, it pushes steadily, for minutes, all the way up. It starts slowly, then speeds up as it burns off fuel and gets lighter, climbing above the thickest air before it goes really fast. The huge Saturn V rocket that carried astronauts to the Moon kept the push on its crews to around 4 g at most, and the Space Shuttle was designed to keep it to about 3 g. Astronauts still feel heavy during launch, but it is uncomfortable, not deadly. In other words: a cannon throws you, a rocket carries you.","Verne could not have known all of this in 1865. But by asking the question so vividly, he got young readers thinking about it. Three of the most important rocket pioneers of the next century, the Russian Konstantin Tsiolkovsky, the American Robert Goddard and the German-speaking Hermann Oberth, all read Verne as youngsters. The first of them was only a small boy when the novel came out, but a few years later he would find it, and it would stay with him for the rest of his life."]},{"heading":"The Boy Who Could Not Hear","paragraphs":["Konstantin Eduardovich Tsiolkovsky was born on 17 September 1857 in the village of Izhevskoye, in the Ryazan region southeast of Moscow, in the Russian Empire. His father, Eduard, was a Polish-born forester who worked for the government, and his mother, Maria, came from a family of Russian and Tatar background. The family was big and not well off, and they moved several times as Eduard changed jobs.","When Konstantin was about nine or ten, he caught scarlet fever, a dangerous illness that was common in children before modern antibiotics. He survived, but the fever damaged his ears and left him very hard of hearing for the rest of his life. Today, a child with hearing loss can get hearing aids, special teachers and sign language. In the 1860s, in a small Russian town, there was little help of that kind. Konstantin found it almost impossible to follow lessons in a classroom, and other children teased him. He later recalled that his deafness made him feel cut off from people, and that it pushed him to turn inward, to his own thoughts and his own projects.","Then, when he was about 13, his mother died. It was a terribly hard time. Yet the lonely boy did not give up. He read every book he could find at home, especially on mathematics and science, and he loved to build things: little carts, toy windmills, model ships and little machines. His father noticed that his son had a real gift for invention and decided he should have a chance to learn more."]},{"heading":"Three Years in a Moscow Library","paragraphs":["In 1873, when he was 16, Konstantin travelled to Moscow, then Russia's second city, to study on his own. He could not enrol at a university, partly because of his deafness and partly because he had very little formal schooling. So he made the city's libraries his university. Day after day, he went to the Chertkov Public Library, a free library with a large collection, and read through books on physics, chemistry, astronomy, mathematics and mechanics.","His father sent him a small amount of money each month, but it was barely enough. Tsiolkovsky later remembered spending most of it on books, test tubes, chemicals and materials for experiments, and living mainly on black bread and water. He was thin and shabby, his trousers sometimes stained by acids from his experiments, and the local boys laughed at him. But in the library he found an unusual friend. One of the librarians was Nikolai Fyodorov, a strange and brilliant thinker who believed that science should one day let humanity spread out across the universe. Fyodorov helped the shy teenager choose books and guided his reading. Historians still discuss how much Fyodorov's grand ideas about humanity's future in space shaped Tsiolkovsky's later thinking.","It was during this period, or soon after, that Tsiolkovsky read Jules Verne. The idea of travelling beyond the Earth gripped him. According to a later account, by the age of about 17 he was already thinking about how a real machine could carry people into space. He tried out ideas with whatever he had: he imagined a spinning device to create artificial weight, and he puzzled over how a machine could move in empty space with nothing to push against.","After about three years, in 1876, his father called him home. Konstantin was 19, worn out and underfed, but he had given himself an extraordinary education. He continued studying at home and tutored local students. In 1879 he passed the exam to become a teacher, and in 1880 he was given a job teaching arithmetic and geometry at a school in Borovsk, a small town about 100 kilometres southwest of Moscow. That same year he married Varvara Sokolova, the daughter of the family he lodged with. They would have several children together, and the family's life was often hard and marked by sadness, including the loss of several of their children."]},{"heading":"The Schoolteacher of Kaluga","paragraphs":["Tsiolkovsky taught in Borovsk for about 12 years, from 1880 to 1892. His students remembered him as kind and enthusiastic, a teacher who showed them experiments and models instead of only making them copy from books. Because of his poor hearing, he sometimes used a home-made ear trumpet, a horn-shaped tube that funnelled sound into his ear.","In his spare hours, he wrote and experimented without stopping. In 1883 he wrote a work called 'Free Space', in which he described what life would be like in a place without weight: how objects would float, how people would move around, and how a craft could be steered by shooting out jets of gas. That last idea is exactly how small thrusters steer spacecraft today. He was only 26.","In 1892, Tsiolkovsky moved with his family to Kaluga, a larger town on the Oka River, about 160 kilometres southwest of Moscow. He would live there for the rest of his life, more than 40 years, teaching mathematics and physics at local schools. His wooden house became his workshop, laboratory and study, with models hanging from the ceiling and papers piled everywhere. Today that house is a museum, and Kaluga is also home to a big museum of space history named after him.","In Kaluga, Tsiolkovsky worked on many inventions, not only rockets. He was fascinated by airships and designed a large airship with a thin metal skin, which he hoped could carry many passengers. Around 1897, he built what is often described as one of the first wind tunnels in Russia, a box through which air could be blown past models so he could measure the forces on them. He also wrote science fiction stories to help ordinary people imagine life in space, including 'On the Moon' and 'Dreams of Earth and Sky', both from the 1890s.","In one of his writings from 1895, inspired by the newly built Eiffel Tower in Paris, he imagined a tower reaching all the way up to space, so tall that at its top objects would float. This 'space tower' is an early version of what people today call a space elevator. Nobody knows how to build one yet, but scientists still discuss the idea.","Much of the scientific world ignored him. He was a provincial schoolteacher, not a professor; he published many of his works himself, with his own small salary; and some of the experts he wrote to did not take him seriously. But he kept going, filling notebook after notebook with ideas."]},{"heading":"The Article That Started Space Science","paragraphs":["By the late 1890s, Tsiolkovsky had become convinced that the rocket, not the cannon or the balloon, was the only machine that could ever leave the Earth. A rocket carries its own fuel and its own oxygen, so it does not need air. It pushes against its own exhaust, so it can keep speeding up in empty space. And it pushes gently over a long time, so a crew inside could survive.","Around 1897, he worked out a simple but powerful formula describing how fast a rocket can go. In May 1903, he published his ideas in a Russian magazine called Nauchnoye Obozreniye, meaning 'Scientific Review'. The article's title is usually translated as 'Exploration of Outer Space by Means of Reaction Devices', or sometimes 'Exploration of World Spaces with Reaction Machines'. A reaction device simply means a machine that moves by pushing something out of its back, just as Newton's third law describes.","The formula is now called the Tsiolkovsky rocket equation, and it is still used by every space agency in the world. You do not need the mathematics to understand its big message. It says two things decide how much speed a rocket can gain. The first is how fast the exhaust gas shoots out of the back: the faster the exhaust, the more speed the rocket gets from every kilogram of fuel. The second is how much of the rocket is fuel compared with the weight of the empty rocket: the more fuel you carry compared with everything else, the faster you can go when it has all burned.","This sounds simple, but it holds a hard lesson. The speed you gain does not grow in a straight line as you add fuel. Each extra tonne of fuel also has to lift itself, so you get less and less extra speed for every tonne you add. To reach orbit, which needs a speed of roughly 8 kilometres per second, most of a rocket has to be fuel. Tsiolkovsky realised that the gunpowder of old war rockets was far too weak for this. He needed something much more powerful.","His answer was liquid fuel. He suggested burning liquid hydrogen with liquid oxygen, which together produce very fast exhaust; the reaction makes mainly water vapour. In 1903 nobody could easily make, store or pump these super-cold liquids, so it was a bold idea. But he was right: hydrogen and oxygen later powered the upper stages of the Saturn V that went to the Moon and the main engines of the Space Shuttle.","That same year, in December 1903, the Wright brothers made the first powered aeroplane flight in North Carolina, staying in the air for 12 seconds. So in the very year humans first flew a powered aeroplane a few metres above a sandy beach, a deaf schoolteacher in a small Russian town had already published the science of flying into space. At the time, hardly anyone noticed. The magazine had few readers, and the article had little impact outside Russia for many years. A second part came out in 1911 in a Russian aviation journal, with more following in 1914, and his work gradually found readers among young Russian engineers."]},{"heading":"Rocket Trains and the Cradle of Humanity","paragraphs":["Over the next three decades, Tsiolkovsky kept adding astonishing ideas. He knew that one single rocket would struggle to reach orbit, because it had to carry all its heavy empty tanks and engines all the way up. So he proposed what he called 'rocket trains', in a book published in 1929. His idea was to join several rockets together and let each one fire in turn, dropping away when its fuel ran out so the others did not have to carry its dead weight. This is the multi-stage rocket, the same idea Siemienowicz had drawn in 1650, but now backed by real calculations. Almost every rocket that reaches orbit today uses stages.","He imagined space stations orbiting the Earth, where people would live and work for long periods. He thought about airlocks, little rooms with two doors, so astronauts could go outside without letting all the air escape. He described spacesuits for working outside a spacecraft. He suggested growing plants in space greenhouses to make food and fresh oxygen, and using sunlight for power. He even described engines that could swivel to steer a rocket, much like the gimballed engines used today. In 1926 he wrote a step-by-step plan for how humanity might gradually move out into space, starting with rocket planes and ending with whole settlements around the Sun.","Life became easier for him only late in life. After the Russian Revolution of 1917, the new Soviet government took an interest in his work. Around 1920 he was granted a pension, which allowed him to stop teaching and concentrate on writing. In the 1920s and early 1930s, young Soviet rocket enthusiasts discovered his books, and he became famous in his own country, treated as a wise old pioneer. Over his life he wrote hundreds of papers, books and stories. Among the young readers he inspired were future Soviet rocket designers such as Sergei Korolev and Valentin Glushko, whose story comes later in this Deep Dive.","Tsiolkovsky never built a real rocket himself. He had no money, no laboratory and no team. His power was in his thinking, and in the way he wrote about space so that others wanted to go there. His most famous line comes from 1911 and is usually quoted in English as: 'Earth is the cradle of humanity, but one cannot live in the cradle forever.' In the Russian original he actually wrote about a planet being the cradle of the mind, or reason, but the meaning is the same. A cradle is where a baby starts life, safe and protected. But babies grow up and, one day, they leave the cradle. Tsiolkovsky believed that humanity would one day grow up and leave the Earth too.","Konstantin Tsiolkovsky died in Kaluga on 19 September 1935, two days after his 78th birthday, and was given a state funeral. He did not live to see any of his dreams come true. But just 22 years later, in October 1957, the Soviet Union launched the first artificial satellite, in the same year that marked the 100th anniversary of his birth. A large crater on the far side of the Moon now bears his name. Many people call him the father of astronautics, the science of spaceflight.","Tsiolkovsky had worked out much of the theory, but he had never fired a liquid-fuel rocket. Someone would have to actually build one, and make it fly. The first person to do that was on the other side of the world. In the autumn of 1899, in Worcester, Massachusetts, a thin and often sickly American teenager climbed a cherry tree in his back yard to trim its branches, looked up at the sky, and found himself dreaming of a machine that could fly all the way to Mars."]}],"deepDive":"The Tsiolkovsky rocket equation is usually written as delta-v = v_e × ln(m0 / mf). Here delta-v is the change in the rocket's speed, v_e is the exhaust velocity, m0 is the starting mass with all the propellant on board, mf is the final mass when the propellant is used up, and ln is the natural logarithm. The logarithm is the cruel part. If the exhaust velocity is 4.4 km/s, close to the best hydrogen–oxygen engines, and you want a delta-v of about 9.4 km/s, roughly what reaching low Earth orbit costs once you include losses to gravity and air drag, then m0/mf must be about e to the power 2.14, roughly 8.5. So about 88 percent of the rocket's starting mass has to be propellant, and the tanks, engines, structure and payload must fit in the remaining 12 percent. With kerosene and oxygen, whose exhaust is slower at roughly 3 km/s, the ratio climbs above 20 for a single stage, which is nearly impossible to build. This is why Tsiolkovsky's 'rocket trains', or stages, matter so much: throwing away empty tanks resets the equation partway up. Historians note that the equation was not entirely unique to Tsiolkovsky. A British mathematician, William Moore, had derived a related equation for rocket motion in 1813, and Robert Goddard and Hermann Oberth later reached similar results independently, partly because Tsiolkovsky's work was little known abroad. Tsiolkovsky's distinction is that he was the first to apply it systematically to spaceflight and to draw the big conclusions: liquid propellants, multiple stages, orbital stations. There is also discussion about how his work became so well known. Soviet authorities in the 1930s and later promoted him as a national hero, which helped preserve his papers but also sometimes exaggerated his priority over foreign pioneers. On Verne's cannon, the physics is simple: required acceleration equals v² divided by twice the barrel length. For 11 km/s in 270 m, that is about 220,000 m/s², or roughly 22,000 g. Space guns remain interesting only for very tough cargo, never for people.","funFact":"Tsiolkovsky published his key rocket article in 1903, the same year the Wright brothers made the first powered aeroplane flight, so the science of spaceflight was written down before anyone had flown a powered aeroplane.","check":{"q":"Why could Jules Verne's giant cannon not safely carry people to the Moon?","a":"The sudden, enormous acceleration would have crushed the passengers","wrong":["Cannons cannot fire straight upwards","The Moon was too far for any cannon shot to be seen","There was not enough gunpowder in France"]},"sources":[{"title":"Konstantin Tsiolkovsky","publisher":"European Space Agency (ESA)","url":"https://www.esa.int/Science_Exploration/Human_and_Robotic_Exploration/Exploration/Konstantin_Tsiolkovsky"},{"title":"Konstantin E. Tsiolkovsky","publisher":"New Mexico Museum of Space History","url":"https://nmspacemuseum.org/inductee/konstantin-e-tsiolkovsky/"},{"title":"A Brief History of Rockets","publisher":"NASA Glenn Research Center","url":"https://www.grc.nasa.gov/www/k-12/TRC/Rockets/history_of_rockets.html"},{"title":"From the Earth to the Moon","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/From_the_Earth_to_the_Moon"},{"title":"The Moon-Voyage by Jules Verne","publisher":"Project Gutenberg","url":"https://www.gutenberg.org/ebooks/12901"},{"title":"Konstantin Tsiolkovsky","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Konstantin_Tsiolkovsky"},{"title":"Project HARP","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Project_HARP"},{"title":"John Stapp","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/John_Stapp"}],"photos":[{"src":"img/deep/rockets/04-1.jpg","alt":"Engraving from Jules Verne's From the Earth to the Moon: the giant flag-decked Moon projectile arrives on a railway car.","file":"'From the Earth to the Moon' by Henri de Montaut 38.jpg","url":"https://commons.wikimedia.org/wiki/File:%27From_the_Earth_to_the_Moon%27_by_Henri_de_Montaut_38.jpg","author":"Henri de Montaut / François Pannemaker","license":"Public domain"},{"src":"img/deep/rockets/04-2.jpg","alt":"Konstantin Tsiolkovsky with his white beard in 1934, photographed in front of a log wall in Kaluga.","file":"Konstantin Tsiolkovsky in 1934 (by N.A.Mozhaykin).jpg","url":"https://commons.wikimedia.org/wiki/File:Konstantin_Tsiolkovsky_in_1934_(by_N.A.Mozhaykin).jpg","author":"Николай Александрович Можайкин (?-1946)","license":"Public domain"},{"src":"img/deep/rockets/04-3.jpg","alt":"Tsiolkovsky's wooden house in Kaluga, Russia, where he lived and worked; today it is a memorial museum.","file":"Kaluga Tsiolkovskogo 79 east 06.jpg","url":"https://commons.wikimedia.org/wiki/File:Kaluga_Tsiolkovskogo_79_east_06.jpg","author":"NVO","license":"CC BY-SA 3.0"}],"words":3738},{"n":5,"title":"Goddard's Strange Little Rocket","when":"1899 – 1945","summary":"A sick boy climbed a cherry tree and dreamed of flying to Mars. He grew up to be a physics professor who built the world's first rocket that burned liquid fuel. It flew for just two and a half seconds, but it started the road to the Moon.","sections":[{"heading":"A Boy in a Cherry Tree","paragraphs":["On the afternoon of 19 October 1899, a skinny 17-year-old named Robert Hutchings Goddard climbed a tall cherry tree behind the barn at his family's home in Worcester, Massachusetts. He had a saw and a hatchet, and his job was simple: cut off the dead branches. It was a quiet autumn day in New England. The leaves were turning orange, and from high up in the tree he could look out across the fields.","But Robert was not really thinking about branches. He started to imagine a machine that could leave the ground and rise up, faster and faster, all the way to the planet Mars. He pictured it whirling up from the meadow below him. When he climbed down, he wrote later, he was 'a different boy' from the one who had climbed up. From that moment on, he had a purpose for his whole life.","Robert never forgot that day. He called 19 October his 'Anniversary Day', and almost every year for the rest of his life he wrote something about it in his diary. He was a person who wrote in his diary nearly every day, and those diaries, kept from 1898 to 1945, are still stored at Clark University in Worcester. Historians can open them and read his own handwriting, which is why we know so much about how a dream grew into an invention.","Robert had been born in Worcester on 5 October 1882. He grew up as an only child (a baby brother died before his first birthday), and he was often ill. He had stomach troubles, and later he caught tuberculosis, a serious lung disease that was common at the time. Because he was so often sick, he missed whole years of school. He did not finish high school until 1904, when he was already 21, older than most of his classmates. But being stuck at home was not wasted time. He read physics books, built kites and tried little experiments, including one where he hoped to make a balloon out of thin aluminium. It did not work, but he wrote down why.","He also read science fiction. A story that thrilled him was H. G. Wells's 'The War of the Worlds', in which Martians invade Earth. It was printed in parts in a Boston newspaper in 1898, when Robert was a teenager. He also knew the novels of Jules Verne, which you met in Part 4. Those stories made space feel like a real place you might travel to, not just a pattern of lights in the night sky.","Here is something important to remember about Goddard. He did not invent the rocket. As you learned in Parts 2 and 3, rockets had already been around for many centuries, from Chinese fire arrows to the iron rockets of Mysore and the Congreve rockets of the British Navy. What Goddard did was different. He took the old idea of a rocket and asked how to make it powerful and efficient enough to climb far higher than any balloon or plane, perhaps even into space. To answer that, he needed mathematics, careful experiments and, above all, a new kind of fuel."]},{"heading":"Proving a Rocket Can Push in Empty Space","paragraphs":["In 1904, Goddard went to Worcester Polytechnic Institute, a college for engineers, where he studied general science and earned his degree in 1908. Even as a student he was thinking about space. In 1907 he wrote an article about travelling through space and sent it to a magazine, which turned it down, and the magazine Scientific American published an article of his about using gyroscopes, spinning wheels that resist being tipped over, to keep aircraft steady. That gyroscope idea would come back later in his life in a big way.","Next he moved across town to Clark University, where he earned a master's degree in 1910 and a PhD in physics in 1911. A PhD is the highest university degree, and it meant he was now Dr. Goddard. In 1912 and 1913 he worked as a research instructor at Princeton University in New Jersey. During those months he did something remarkable: in his spare time, he worked out on paper the mathematics of how a rocket could reach very high altitudes, and even reach escape velocity, the speed needed to break free from Earth's gravity completely.","Then his health collapsed. In 1913 his tuberculosis became so bad that he had to go home to rest, and for a while it seemed he might not survive. Lying in bed, he kept working in the only way he could: with ideas. In July 1914 he received his first two patents for rocket designs. A patent is an official document that says an inventor owns an idea for a number of years. One patent described a rocket fed by liquid fuel. The other described a multi-stage or 'step' rocket, where one rocket rides on top of another and the empty lower part is dropped away. Both ideas would become central to spaceflight.","Many people in those days believed something that sounds sensible but is completely wrong: that a rocket works by pushing against the air behind it, the way a swimmer pushes against water. If that were true, a rocket would be useless in space, where there is no air. Goddard knew from Isaac Newton's third law that this was false. A rocket pushes on its own exhaust gas. The hot gas is shoved out of the back, and in return the gas shoves the rocket forward. It is like standing on a skateboard and throwing a heavy ball: you roll backwards, even though you did not push against the air at all.","But knowing something in theory is not the same as proving it. In 1915 Goddard built an experiment to settle the question. He fired small rockets inside a sealed metal chamber with the air pumped out, creating something close to a vacuum, a space with almost no air. He measured how hard the rockets kicked. The result was clear: rockets produced thrust in a vacuum, and in fact they worked a little better without air getting in the way. This was one of the most important experiments in the history of spaceflight, though hardly anyone noticed at the time.","Experiments cost money, and Goddard was not rich. So he wrote to the Smithsonian Institution in Washington, D.C., a famous national museum and research organisation, describing his work. On 5 January 1917 the Smithsonian gave him 5,000 dollars from a special science fund. That was a lot of money then, and it let him keep going. During the First World War he also worked for the US Army on small rocket weapons that a soldier could fire from a tube. He demonstrated them at the Aberdeen Proving Ground in Maryland in early November 1918. The war ended only days later, so they were never used in that war."]},{"heading":"A Method of Reaching Extreme Altitudes","paragraphs":["In 1919 the Smithsonian published Goddard's report. Its title sounds very serious: 'A Method of Reaching Extreme Altitudes'. It was around 70 pages long and packed with equations, tables and descriptions of his experiments. Its main goal was practical. Weather scientists wanted to learn about the upper air, but balloons could only rise to about 30 kilometres (around 20 miles). Goddard showed, step by step, how a rocket might carry instruments much higher than that, and he calculated how big the rocket would need to be to lift each kilogram of cargo to a given height.","Near the end of the paper, Goddard added a short and daring idea. Suppose, he wrote, a rocket were sent all the way to the Moon carrying a load of flash powder, the bright powder photographers used to make a burst of light. When it struck the dark part of the Moon, the flash might be seen through a large telescope on Earth, proving the rocket had arrived. It was only a small thought experiment at the end of a long scientific report, but it was the part that newspapers seized on.","Suddenly, headlines across America were talking about the 'Moon rocket' professor from Worcester. Some articles were excited, but many treated the idea as a joke. Goddard was a shy, careful man who disliked attention, and he hated seeing his serious work turned into a cartoon.","Worst of all was an unsigned editorial in The New York Times, one of the most important newspapers in the world, on 13 January 1920. It was titled 'A Severe Strain on Credulity', which means something like 'very hard to believe'. The writer claimed that a rocket could not work in the empty space between Earth and the Moon because it would have nothing to push against. The editorial even suggested that Professor Goddard seemed to lack the basic knowledge taught every day in high schools.","Of course, it was the newspaper that was wrong. Goddard had already shown, with his vacuum experiments, that rockets work in empty space. The writer had misunderstood Newton's third law, the same law that explains how a balloon zooms around a room when you let go of it. But a famous newspaper telling millions of readers that a scientist did not understand high-school physics was painful and embarrassing. Many historians think this mockery made Goddard even more secretive and suspicious of reporters for the rest of his life.","The story has a satisfying ending, though Goddard did not live to see it. Almost 50 years later, on 17 July 1969, Apollo 11 was speeding towards the Moon with three astronauts aboard. The day after the launch, The New York Times printed a short correction. It said that further research had confirmed that a rocket can work in a vacuum as well as in the atmosphere, and it ended with the words: 'The Times regrets the error.' It may be one of the most famous late apologies in newspaper history."]},{"heading":"Why Liquid Fuel?","paragraphs":["Every rocket before Goddard's famous flight was a solid-fuel rocket. Its fuel was packed inside as a solid, usually some form of gunpowder. Solid rockets are simple and reliable, which is why fireworks still use them today. But they have big problems if you want to go to space. Gunpowder does not release very much energy for its weight. And once a solid rocket is lit, it usually burns until it is finished. You cannot turn it down, switch it off or easily control it.","Goddard became convinced that the answer was liquid fuel. He chose gasoline, the same fuel used in cars, together with liquid oxygen. Fuel cannot burn without oxygen, and in space there is no air to supply it, so a rocket has to carry its own. Oxygen is normally a gas, but if you cool it to about minus 183 degrees Celsius it turns into a pale blue liquid. As a liquid it takes up far less room, so a rocket can carry a lot of it in a small tank. The chemical that supplies the oxygen is called the oxidizer.","Liquid propellants have big advantages. A gasoline and oxygen mixture releases much more energy per kilogram than gunpowder. And because the liquids flow from tanks through pipes into the engine, an engineer can, in principle, control how fast they flow, making the engine stronger or weaker, or shutting it off. This is exactly why the giant rockets that later carried astronauts to the Moon used liquid fuel in their main stages.","But liquid fuel is also much harder to handle. Liquid oxygen is so cold that it makes metal brittle and can freeze skin instantly. It boils away constantly, so it must be loaded just before launch. The fuel and oxidizer have to be pushed into the combustion chamber at exactly the right rate, mixed and lit without blowing everything up. And the chamber where they burn becomes hot enough to melt many metals. Goddard spent years, starting around 1920, building and testing engines on test stands in his laboratory at Clark University, where he was now a physics professor. In 1923 he had an engine running on a test stand, and in 1925 a liquid-fuelled rocket in his lab lifted its own weight for the first time while held in a frame. He was ready to try a real flight."]},{"heading":"Two and a Half Seconds in Auburn","paragraphs":["Imagine a cold, grey morning on 16 March 1926 in Auburn, a small town just south of Worcester. Snow still lies in patches across a field of cabbages on a farm owned by Goddard's aunt, Effie Ward. A small group of people tramps across the frozen ground carrying an odd contraption. There is Goddard, now 43 years old; his wife Esther, whom he had married in 1924 and who acted as the project's photographer and record-keeper; and a couple of helpers from Clark University.","The rocket, later nicknamed 'Nell', looked nothing like the sleek rockets in films. It was a spindly frame of thin metal pipes, about 3 metres tall when you include the launch frame, and it weighed only about 4.6 kilograms (about 10 pounds) with its fuel loaded. Strangely, the little engine sat at the top, and the fuel tanks hung below it, connected by long thin pipes. Goddard placed the engine high up because he hoped the rocket would hang beneath it and fly straight, like a weight hanging under a hand. Engineers later learned that this does not actually make a rocket more stable, and Goddard soon moved the engine to the bottom, where it sits on almost every rocket today.","To start the rocket, an assistant used a blowtorch on a long pole to light the engine. Then everyone waited while the engine roared, building up thrust. For a moment Nell just sat there, burning and hissing, because its push was barely more than its own weight. Then, at about half past two in the afternoon, it suddenly leapt off its frame.","The flight was over almost before it began. Nell shot up, curved over, and crashed into the frozen ground. The lower part of its nozzle had burned through during the flight. That evening, Goddard wrote a short, plain entry in his diary: it rose 41 feet and went 184 feet, in 2.5 seconds. In metric units that means it climbed about 12.5 metres, about as high as a four-storey building, and landed about 56 metres away. Its average speed was roughly 90 kilometres per hour.","That does not sound very impressive, does it? But think about what it meant. For the first time ever, a rocket had flown by pumping two liquids together and burning them in a controlled engine. It was like the Wright brothers' first aeroplane flight in 1903, which lasted only 12 seconds and covered 37 metres. Neither flight was useful in itself. Both proved that something completely new was possible.","The day after, Goddard wrote to himself that it was almost magical to watch the rocket rise, with no loud noise or flame and without seeming to work any harder, as if it were simply saying it had been there long enough and would be going somewhere else, if you did not mind. Yet there were no reporters, no crowds and no newspaper stories. Goddard told the Smithsonian about the flight, but he did not announce it to the public. It would be ten years before he published a full report. The first liquid-fuelled rocket flight, one of the great moments in the history of technology, happened almost in secret in a snowy cabbage patch. Today a granite marker stands near the spot, on what is now a golf course."]},{"heading":"Too Loud for Massachusetts","paragraphs":["Goddard kept improving his rockets. On 17 July 1929, again near Auburn, he launched a larger rocket that carried scientific instruments for the first time: a small barometer to measure air pressure, a thermometer and a camera to photograph the instruments at the top of the flight. It was the first rocket ever to carry a scientific payload, the useful cargo a rocket exists to deliver.","The rocket was very loud and very bright. Neighbours who heard the roar and saw the flash thought an aeroplane had crashed and called for help. Police cars and ambulances raced to the farm, and reporters followed. Newspapers mocked him all over again, joking about how far the 'Moon rocket' had missed the Moon. Afterwards, local officials made it clear he could no longer launch rockets in the area.","But this time, the newspaper stories had a surprising effect. One person who read about Goddard was Charles Lindbergh, the most famous pilot in the world. In 1927 Lindbergh had become the first person to fly alone and nonstop across the Atlantic Ocean, from New York to Paris. He was fascinated by the future of flight, and he wanted to know whether rockets could ever be practical. On 23 November 1929 he met Goddard for the first time.","Lindbergh was impressed by the quiet professor and his careful notebooks. He used his fame to help find money for him. He spoke to Daniel Guggenheim, a very wealthy businessman whose family supported aviation research. In 1930 Guggenheim agreed to pay for Goddard's work, starting with a two-year grant, and his son Harry Guggenheim continued that support for many years afterwards. For the first time, Goddard could stop squeezing rocket experiments into his spare time and work on them full-time, with paid helpers and proper equipment.","There was one more question: where to go? Goddard needed a place with clear skies, very few people and lots of open land, where a rocket could crash without hurting anyone. He also needed a dry climate, because his tuberculosis made cold, damp New England winters hard for him. He chose Roswell, a small ranching town in the desert of New Mexico."]},{"heading":"The Desert Workshop at Roswell","paragraphs":["In July 1930, Robert and Esther Goddard moved to a house on a ranch outside Roswell, along with a small team of mechanics. Picture a workshop under the enormous New Mexico sky, with flat brown land stretching away to distant mountains. A steel launch tower about 18 metres tall was put up in the desert, and the team built rockets by hand, machining parts on lathes, welding tanks and testing engines again and again. Esther filmed and photographed launches, kept records, and became Goddard's closest partner in the work.","The biggest problem was steering. A rocket that is not guided tends to wobble, turn and veer off course. Goddard returned to his student idea: the gyroscope. A gyroscope is a fast-spinning wheel that tries to keep pointing in the same direction, like a spinning top that stays upright. In 1932 he used a gyroscope to sense when the rocket began to tilt. When it did, the gyroscope moved small metal vanes into the blast of hot gas coming out of the engine. The vanes deflected the exhaust and pushed the rocket back on course. Steering a rocket automatically like this was a crucial step towards modern guided rockets.","On 28 March 1935, one of his 'A-series' rockets, steered by a gyroscope, climbed to about 1,460 metres (4,800 feet) before flying on sideways. That same year, one of Goddard's rockets is said to have flown close to, or even past, the speed of sound, travelling at roughly 1,100 kilometres per hour (about 700 miles per hour), and another reached about 2,300 metres (7,500 feet). In 1937 one of his rockets climbed to about 2,700 metres, roughly 9,000 feet, the highest of all his flights. These were small heights compared with what came later, but they were real records for liquid-fuelled rockets.","Over the years in Roswell, Goddard and his team built and tested many series of rockets, with dozens of flights and static tests, in which the rocket is held down while the engine fires. He experimented with ideas that are still used today. He developed pumps that could force fuel into the engine at high pressure, instead of only pushing it out of the tanks with gas pressure. He worked on cooling the hot engine walls by running cold fuel around them. He tried parachutes to bring rockets back down, and he designed engines that could swivel to steer.","Many flights failed. Rockets exploded, burned through, tipped over, or rose a short way and crashed. Goddard was patient. He wrote down what went wrong, changed one thing, and tried again. In 1936 the Smithsonian published his second famous report, 'Liquid-Propellant Rocket Development', which described his flights in New Mexico and included photographs. It was much shorter than many people hoped, and it left out a great deal of detail."]},{"heading":"The Lone Genius Problem","paragraphs":["Goddard is often called 'the father of modern rocketry', and he deserves enormous credit. But to be fair to everyone in this story, we also need to look at how he worked. Goddard was a brilliant inventor, but he worked mostly alone, with a small team of helpers who built what he designed. He was very protective of his ideas. After the mockery of 1920, he distrusted reporters, and he worried that others would copy his inventions before he could patent them.","So he published very little. He rarely went to scientific meetings to share his latest results, and he turned down offers to work together with other rocket groups. Other rocket enthusiasts, such as the young members of the American Rocket Society you will meet in Part 6, learned far less from him than they hoped. And when Goddard offered his rockets to the US Army and Navy around 1940, officials were not very interested at first.","Because of this, Goddard's work influenced other rocket builders less than it could have. In Germany and the Soviet Union, other engineers were working out many of the same ideas on their own, and building large teams that shared knowledge with each other. Historians still argue about exactly how much the German rocket engineers learned from Goddard's patents and papers. What most agree on is that big teams with lots of money and shared knowledge moved faster than one brilliant inventor working in secret in the desert.","When the United States entered the Second World War, Goddard offered his skills to the government. From 1942 to 1945 he worked for the US Navy in Annapolis, Maryland, developing rocket units to help heavy aircraft take off from short runways, and engines whose power could be varied. But his health was failing. He died of throat cancer on 10 August 1945 in Baltimore, Maryland, aged 62. He was buried in Hope Cemetery in his home town of Worcester.","During his life, Goddard received 83 patents. But he had left so many notes and designs that Esther, working with the Guggenheim Foundation, spent years filing more patent applications for him. In the end he was credited with 214 patents, more than 200 in total, most of them granted after his death. In 1960 the US government paid one million dollars for the right to use his patents, because so many of his ideas, from gyroscopic steering to fuel pumps, had turned out to be part of every big rocket.","Recognition came at last. In 1959 Goddard was awarded a Congressional Gold Medal, one of America's highest civilian honours, and in May of that year NASA announced that its new space science centre in Greenbelt, Maryland, would be called the Goddard Space Flight Center. It was officially dedicated on 16 March 1961, exactly 35 years after Nell's flight. And when Buzz Aldrin travelled to the Moon in July 1969, he carried a miniature biography of Goddard with him.","Goddard had shown that liquid-fuelled rockets could fly, steer themselves and fly at around the speed of sound. But he had done it almost alone, in a quiet workshop in the desert. Meanwhile, on the other side of the Atlantic Ocean, something very different was happening. In Germany, a whole club of young rocket fans was forming, sharing their ideas, writing magazines and building rockets together in the open."]}],"deepDive":"Why was Goddard's liquid-fuel breakthrough such a big deal? The key number is exhaust velocity: how fast the gas leaves the nozzle. Tsiolkovsky's rocket equation, from Part 4, says a rocket's final speed depends on two things: how fast its exhaust shoots out, and how much of its starting mass is propellant. Black-powder rockets have slow exhaust and waste most of their chemical energy as heat and smoke. In his 1915 to 1916 experiments, Goddard showed that by burning a better powder in a strong chamber and expanding the gas through a de Laval nozzle, he could turn a much larger share of the energy into fast-moving exhaust, and his 1919 report describes this in detail. Liquid oxygen and gasoline went further still, giving more energy per kilogram than any powder of the time, and, just as importantly, liquids can be pumped. That means huge amounts of propellant can be stored in light tanks, rather than in a heavy casing that must contain the whole burning charge. Nell itself was barely able to lift itself: its engine made roughly 9 pounds of thrust, about 40 newtons, while the fuelled rocket weighed around 10 pounds, which is why it sat on its frame for some seconds while fuel burned away until thrust beat weight. Its engine-on-top layout illustrates what engineers call the pendulum rocket fallacy. It seems as if a rocket hanging below its engine should be stable like a pendulum, but because the thrust is fixed to the rocket and turns with it, the arrangement gives no real stability. Goddard soon abandoned it and turned to the true solution, active guidance with gyroscopes and vanes in the exhaust, the ancestor of the steerable engines on modern launchers. Historians debate Goddard's legacy. Supporters stress that he pioneered liquid propulsion, gyro-stabilisation, multi-stage designs, fuel pumps and regenerative cooling before almost anyone else, and that his patents were later found to cover features of big military rockets. Critics point out that his secrecy meant others reinvented much of this independently, so his practical influence on the rockets that actually reached space was smaller than his genius might suggest. Both statements can be true at once.","funFact":"The New York Times waited 49 years to correct its 1920 editorial mocking Goddard, finally printing 'The Times regrets the error' while Apollo 11 was on its way to the Moon.","check":{"q":"What did Goddard's 1926 rocket burn that made it different from all earlier rockets?","a":"Liquid fuel: gasoline and liquid oxygen","wrong":["Black gunpowder packed in an iron tube","Steam from boiling water","Hydrogen gas from a balloon"]},"sources":[{"title":"Goddard's First Liquid-Fueled Rocket Turns 100","publisher":"National Space Society","url":"https://nss.org/goddards-first-liquid-fueled-rocket-turns-100/"},{"title":"Robert Goddard","publisher":"Worcester Polytechnic Institute","url":"https://www.wpi.edu/about/robertgoddard"},{"title":"Oct. 19, 1899: Robert Goddard's 'Anniversary Day'","publisher":"Clark University","url":"https://www.clarku.edu/news/?p=14540"},{"title":"Highlights From the Life of Robert H. Goddard","publisher":"Robert H. Goddard Memorial Foundation","url":"https://goddardmemorial.org/Goddard/timeline.html"},{"title":"Robert H. Goddard","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Robert_H._Goddard"},{"title":"Goddard History","publisher":"NASA","url":"https://www.nasa.gov/goddard/history"}],"photos":[{"src":"img/deep/rockets/05-1.jpg","alt":"Robert Goddard in a heavy coat beside his first liquid-fuelled rocket and its launch frame in the snow at Auburn, 1926.","file":"Goddard and Rocket.jpg","url":"https://commons.wikimedia.org/wiki/File:Goddard_and_Rocket.jpg","author":"Esther C. Goddard","license":"Public domain"},{"src":"img/deep/rockets/05-2.jpg","alt":"Robert Goddard with one of his rockets in his workshop at Roswell, New Mexico, in October 1935.","file":"Dr Robert Goddard (GSFC 20171208 Archive e002223).jpg","url":"https://commons.wikimedia.org/wiki/File:Dr_Robert_Goddard_(GSFC_20171208_Archive_e002223).jpg","author":"NASA Goddard Space Flight Center","license":"Public domain"},{"src":"img/deep/rockets/05-3.jpg","alt":"Aerial view over the main gate of NASA's Goddard Space Flight Center in Greenbelt, Maryland, in autumn.","file":"Aerial Views of Goddard- 180- and 360-Degree Panoramas (SVS14480 - Goddard Panorama From Main Gate Still).jpg","url":"https://commons.wikimedia.org/wiki/File:Aerial_Views_of_Goddard-_180-_and_360-Degree_Panoramas_(SVS14480_-_Goddard_Panorama_From_Main_Gate_Still).jpg","author":"NASA's Scientific Visualization Studio - Cecelia Vitale-Reddy, Jefferson…","license":"Public domain"}],"words":4342},{"n":6,"title":"Oberth and the Rocket Clubs","when":"1923 – 1937","summary":"A teacher wrote a book proving rockets could reach space, and young people all over Germany got excited. They formed clubs, built little rockets in an old army yard and even helped make a space movie that invented the countdown. But soon armies wanted rockets too.","sections":[{"heading":"A Boy from Transylvania Who Knew Verne by Heart","paragraphs":["In Part 5 we met Robert Goddard, working almost alone in his workshop. Now we travel to Europe, where the rocket story became a team sport. It starts with a boy named Hermann Oberth, born on 25 June 1894 in Hermannstadt, a German-speaking town in Transylvania. Today the town is called Sibiu and lies in Romania, but at the time it was part of the Austro-Hungarian Empire. Oberth's father was a doctor, and the family expected Hermann to become one too.","When Hermann was about 11, he was given Jules Verne's novel 'From the Earth to the Moon', the story you met in Part 4 in which astronauts are fired at the Moon from a giant cannon. He read it again and again until he knew it nearly by heart. But he did not simply enjoy it. He started checking Verne's numbers. Could a cannon really fire people to the Moon? He worked out that the sudden jolt of the cannon shot would crush the passengers, and that the shell would lose much of its speed fighting through the air. A cannon would not work. But a rocket, which speeds up gradually and keeps pushing for a long time, might.","As a teenager he sketched rocket designs and did calculations in his notebooks. During the First World War he served as a soldier in the Austro-Hungarian army, and later worked in an army hospital. Even then, he kept thinking about rockets. After the war he studied physics at universities in Germany, including Munich, Göttingen and Heidelberg. He married, started a family, and set out to write a doctoral thesis, the long research project you must complete to earn a PhD, on a subject nobody else was studying: how to build a rocket that could fly into space."]},{"heading":"The Thesis Nobody Wanted","paragraphs":["Oberth's thesis was full of careful mathematics. He showed how fast a rocket would need to go to reach space, how much fuel it would need, and how its engines could be designed. He argued that the best rockets would use liquid fuels such as alcohol or hydrogen burned with liquid oxygen, and that they should be built in stages, with the empty lower part dropped off so the upper part could fly on lighter. He even calculated that human passengers could survive the strong push of a launch.","In 1922 the university turned his thesis down. Most accounts say it was the University of Heidelberg, and that the professors thought it was too fanciful, more like science fiction than real physics. Part of the problem was that no professor there really knew how to judge it, because the subject did not fit neatly into astronomy, physics or engineering. Oberth was angry and disappointed, but he did not give up. He went back to Transylvania and in 1923 successfully defended a version of his work at the university in Cluj, in Romania.","Then he did something bold. In 1923 he paid a Munich publisher to print his thesis as a small book. Its German title was 'Die Rakete zu den Planetenräumen', which means 'The Rocket into Planetary Space'. It was only about 100 pages long and was crammed with equations. It also contained a plate showing a two-stage rocket he called 'Model B', designed to carry instruments high into the atmosphere. The book argued that rockets could carry people beyond the atmosphere, that liquid fuels were the key, and that one day there could be stations in orbit around the Earth.","Around this time Oberth heard about Goddard's work in America. In 1922 he wrote to Goddard and asked for a copy of the 1919 Smithsonian paper, and Goddard sent one. This is a good example of something that happens a lot in science: two people, far apart, working on the same problem and reaching some of the same answers independently. Tsiolkovsky in Russia, Goddard in America and Oberth in Germany are sometimes called the three fathers of spaceflight, and none of them was copying the others.","The difference was what happened next. Goddard kept his work quiet. Oberth's book, by contrast, was read by curious people across the German-speaking world. Newspapers and magazines wrote about it. Writers produced popular books based on its ideas, explaining them without the hard maths. Suddenly, space travel was something people talked about in cafés and classrooms. Meanwhile, Oberth earned his living as a high-school physics and maths teacher back in Transylvania, in the town of Mediaș.","In 1929 he published a much larger version of the book, called 'Wege zur Raumschiffahrt', or 'Ways to Spaceflight'. It looked even further ahead, describing ideas such as electric rockets, which use electricity to push out a stream of charged particles. Today such engines, called ion engines, really do push spacecraft across the solar system. The book won an international prize set up by the French aviation pioneer Robert Esnault-Pelterie, and Oberth spent some of the prize money on rocket motors for young experimenters."]},{"heading":"The Society for Space Travel","paragraphs":["Oberth's book helped spark something new: a club. On 5 June 1927, in the city of Breslau (now Wrocław in Poland), a small group of enthusiasts founded the Verein für Raumschiffahrt, which means the Society for Space Travel. People usually call it the VfR. Its founders included Johannes Winkler, an engineer who became its first leader; Max Valier, an Austrian writer who gave talks about space travel; and Willy Ley, a young science writer who would later become famous in America. Oberth joined and became a kind of godfather to the group, encouraging its members and lending them his ideas.","The VfR published its own magazine, called 'Die Rakete' ('The Rocket'), from 1927 to 1929. Members wrote articles, argued about designs and dreamed out loud about stations in orbit and trips to the Moon. The club grew quickly, from a handful of people to hundreds of members, including scientists, engineers, students and ordinary fans. It is often described as the first important rocket society in the world.","In 1930 an 18-year-old student named Wernher von Braun joined. He had been born on 23 March 1912 in Wirsitz, then part of Germany and now in Poland, into a noble family. His mother gave him a telescope, and he grew up fascinated by the stars. According to a story he told later, as a boy in Berlin he strapped big fireworks to a toy wagon and sent it careering down a busy street until the police arrived. When he first tried to read Oberth's book, the equations baffled him, so he worked hard to get better at maths and physics until he could understand it. Now, as an engineering student at the Technical University in Berlin, he was eager to help build real rockets."]},{"heading":"Rocket Cars, Rocket Planes and Real Danger","paragraphs":["Not everyone interested in rockets in the late 1920s was thinking about the Moon. Some wanted a spectacular show. Max Valier, one of the VfR's founders, persuaded Fritz von Opel, a young member of the family that owned the Opel car company, that rocket-powered vehicles would make amazing publicity. The rockets themselves were solid-fuel rockets, packed with powder, made by a fireworks maker named Friedrich Wilhelm Sander.","In April 1928, a test driver drove the first Opel rocket car, the RAK.1, at the Opel factory in Rüsselsheim. It reached 100 kilometres per hour in about eight seconds. Then came the big day. On 23 May 1928, at the AVUS race track in Berlin, Fritz von Opel climbed into the RAK.2, a long, low car with stubby wings on its sides to press it down onto the track, and 24 rockets packed into its tail. About 3,000 people came to watch, including the film director Fritz Lang. With a series of roars and enormous clouds of smoke, the car shot down the track and reached about 238 kilometres per hour, around 148 miles per hour. Newspapers around the world reported it.","There were rocket-powered railway cars too, which ran on tracks. One set a speed record near Hanover in June 1928, while another was destroyed when a rocket exploded. That same month a small rocket-powered glider called the 'Ente', which means 'duck', flew at the Wasserkuppe, a famous gliding hill in central Germany. On its second flight a rocket exploded and the glider was wrecked. On 30 September 1929 Fritz von Opel himself flew a rocket plane near Frankfurt for a few kilometres before a hard landing. He walked away unhurt.","These stunts were exciting, but they did not lead directly to spaceflight, because powder rockets could not be controlled or made efficient enough. The serious experimenters already knew that liquid fuel was the way forward, as Goddard had shown in America. But liquid-fuel engines were dangerous to test, and the danger was very real.","Max Valier had moved on from powder rockets to liquid-fuelled engines, working with a company that made liquid oxygen. On 19 April 1930 he drove a rocket car with a liquid-fuelled engine. Less than a month later, on 17 May 1930, an engine he was testing on a stand in a Berlin workshop exploded, and a piece of metal struck him. He died there, aged 35. He is sometimes described as the first person to die in the age of modern rocket research. His death shocked the rocket enthusiasts, and it reminded everyone that these engines needed careful design, strong test stands and safety barriers between the engine and the people. His assistant, Arthur Rudolph, went on to build a safer version of the engine and later became an important rocket engineer himself."]},{"heading":"Woman in the Moon and the First Countdown","paragraphs":["One of the people in the crowd at the AVUS track, Fritz Lang, was one of the most famous film directors in the world. His film 'Metropolis', from 1927, had shown a gleaming city of the future. Now Lang wanted to make a film about a trip to the Moon, and he wanted the rocket to look scientifically correct. So he hired Hermann Oberth as his chief scientific adviser, with Willy Ley helping too.","The film was called 'Frau im Mond', which means 'Woman in the Moon'. It was a silent film, with written cards on the screen instead of spoken words. Oberth helped design a rocket that looked like a real spaceship of the future: a tall, sleek rocket assembled in a huge hangar, rolled out to its launch site, and launched from a pool of water with a blast. The passengers lie down on special beds to cope with the crushing force of the launch, just as Oberth's calculations said they should.","Lang added one more detail to build suspense, and it became part of real spaceflight. Before the rocket launches, the screen shows the seconds being counted backwards, one number at a time, until the word 'Now!' appears and the rocket thunders away. The film is often credited with inventing the backwards countdown that has been used for rocket launches ever since. Counting down makes sense: everyone knows exactly how much time is left before the moment of ignition, so each person can do their job at the right time.","As a publicity stunt, the film studio asked Oberth to build a real liquid-fuelled rocket and launch it on the day of the premiere. Oberth was a brilliant theorist, but he had little experience building engines, and the time was very short. He worked with a VfR member named Rudolf Nebel, but the rocket was not finished in time. The film premiered without it on 15 October 1929 at a grand cinema in Berlin called the UFA-Palast am Zoo, in front of an audience of about 2,000 people. Exhausted and disappointed, Oberth went home to Transylvania for a while.","Something good came out of the effort, though. In 1930, back in Berlin, Oberth and VfR members, including the young Wernher von Braun, tested a small liquid-fuelled engine with a cone-shaped nozzle. According to accounts of the test, it burned steadily for about a minute and a half and produced roughly 7 kilograms (about 15 pounds) of thrust. A government testing institute watched and confirmed the results in an official certificate. It was a small engine, but it proved the club could make liquid-fuelled rockets work."]},{"heading":"Rocket Airfield Berlin","paragraphs":["To test rockets, the VfR needed space where explosions and crashes would not hurt anyone. Rudolf Nebel found an unusual solution. On the northern edge of Berlin, in the district of Reinickendorf, there was an abandoned army ammunition depot, full of empty concrete bunkers with thick walls. Nebel persuaded the government to rent it to the club for almost nothing. On 27 September 1930 it opened as the Raketenflugplatz Berlin, which means 'Rocket Airfield Berlin'.","Imagine visiting on a busy weekend. Young men in overalls carry tanks of liquid oxygen, which steam and frost in the air. Others crouch behind a concrete wall with a stopwatch. A small, skinny rocket sits on a test stand. Someone shouts a warning, the engine bursts into life with a howl, and everyone watches to see whether it will burn smoothly or blow apart. Many members slept in the old buildings, and they worked for little or no pay, sometimes trading demonstrations for food or materials.","The club built a series of small rockets called Mirak, short for 'Minimumrakete', meaning 'smallest rocket', in 1930 and 1931. Some of them exploded. Then they built the Repulsor rockets, with the engine at the front and long thin fuel tanks trailing behind, a layout rather like Goddard's first rocket. In 1931 Repulsor rockets climbed hundreds of metres, and improved versions went higher than a kilometre, some floating back down on parachutes. By May 1932 the rocket airfield had seen about 85 rocket launches and around 220 engine tests.","The VfR was not the only group in Germany. Johannes Winkler, the club's first leader, worked separately in the town of Dessau. On 14 March 1931 he launched a small rocket called HW-1, which burned liquid methane and liquid oxygen. It is often described as one of the first liquid-fuelled rockets to fly in Europe, though it tipped over and flew only a short way. All over Germany, students and engineers were now experimenting. The rocket had become a craze."]},{"heading":"Rocket Clubs Around the World","paragraphs":["Germany was not the only country with rocket fans. In the Soviet Union, the vast communist country that included Russia, the ideas of Konstantin Tsiolkovsky (whom you met in Part 4) had inspired a new generation. In September 1931 an engineer named Friedrich Zander, often spelled Tsander, helped form a group in Moscow called GIRD, short for the Russian words meaning 'Group for the Study of Reactive Motion'. Zander had been born in Riga, in what is now Latvia, in 1887, and he was so eager to reach space that he often greeted friends with the slogan 'Forward to Mars!'","GIRD started in a cold basement in a building on Sadovaya-Spasskaya Street in Moscow. Money and materials were so short that members joked GIRD really stood for 'Group of Engineers Working for Nothing'. In May 1932 a young aircraft designer and glider pilot named Sergei Korolev, then 25, became its head. GIRD was divided into teams, called brigades. Zander led the engine team, while an engineer named Mikhail Tikhonravov led another team building a rocket called GIRD-09.","Sadly, Zander did not live to see a GIRD rocket fly. He fell ill and died in March 1933. A few months later, on the evening of 17 August 1933, the team took GIRD-09 to a military test range at Nakhabino, near Moscow. It was a hybrid rocket, burning liquid oxygen with a jelly-like solid fuel made from gasoline. The rocket climbed, perhaps to about 400 metres, then tipped over, because a joint in the engine leaked, and crashed into the forest. The whole flight lasted about 18 seconds. Still, it was the first Soviet rocket to fly using a liquid propellant, and the team celebrated. On 25 November 1933, Zander's own design, GIRD-X, which burned fully liquid fuels, flew too, reaching about 80 metres.","That same year, GIRD was merged with another rocket team, the Gas Dynamics Laboratory in Leningrad, to form a larger, official rocket research institute run by the military, called RNII. One young engine designer at the Leningrad lab was Valentin Glushko, who would become one of the greatest rocket engine designers in history. Korolev and Glushko would later have very difficult lives under the Soviet dictator Joseph Stalin, a story you will meet in Part 8.","In the United States, a group of science-fiction writers founded the American Interplanetary Society in New York City on 4 April 1930. Its first president was David Lasser, an editor of a science-fiction magazine. Two of the most important early members were G. Edward Pendray and his wife Leatrice, known as Lee, one of the few women in any rocket club at the time. In 1931 the Pendrays visited Berlin, watched a rocket test at the Raketenflugplatz and became friends with Willy Ley. Back home, members began building their own liquid-fuelled rockets, but they did not manage a successful flight until 1933.","In 1934 the club changed its name to the American Rocket Society, partly so that people would take it more seriously than a group dreaming about 'interplanetary' trips. Some of its members later started a company called Reaction Motors. One of its engineers, James Wyld, helped design the engine for the Bell X-1, the rocket plane in which Chuck Yeager became the first pilot to fly faster than the speed of sound in 1947. In Britain, the British Interplanetary Society was founded in Liverpool in 1933. It still exists today."]},{"heading":"The Army Comes Calling","paragraphs":["The happy days of the amateur rocket clubs did not last. To understand why, we need to go back to the end of the First World War. In 1919 Germany signed the Treaty of Versailles, the peace agreement with the countries that had defeated it. The treaty strictly limited the German army. It could have only a small number of soldiers, and it was banned from having heavy artillery, the big guns that fire shells over long distances, along with military aircraft and other weapons.","But the treaty said nothing about rockets. When it was written, rockets seemed like old-fashioned weapons, as you saw at the end of Part 3. To some officers in the German army's weapons office, this was an opening. If big guns were forbidden, perhaps long-range rockets could do the same job, and no treaty would stop them. An officer named Karl Becker, an expert on artillery, began to support rocket research. He put a younger officer, Captain Walter Dornberger, in charge of developing rockets.","Army officers began visiting the Raketenflugplatz to see what the young enthusiasts could do. In 1932, VfR members, including von Braun, demonstrated one of their rockets at an army test range at Kummersdorf, south of Berlin. Accounts say the rocket did not perform very well. But the officers were impressed by the young von Braun, who was clearly talented, hard-working and full of ideas. In late 1932 the army hired him, aged just 20, to work on rockets at Kummersdorf. The army also paid for his studies, and in 1934 he earned a PhD in physics from the University of Berlin for research on rocket engines. Because the work was secret, his thesis was kept hidden from the public for years.","The army offered something no club could: money, equipment, test stands and staff. But it came at a price. The research was now secret, and the goal was a weapon. In January 1933 Adolf Hitler and his Nazi party came to power in Germany. The new government took tight control of all rocket work and did not allow private groups to experiment freely. The VfR, already short of money, fell apart in 1933 and 1934, and the Raketenflugplatz closed. Willy Ley, who opposed the Nazis, left Germany in 1935 and moved to the United States, where he spent the rest of his life writing popular books about rockets and space.","Oberth's later life was quieter. He did not become a leader of the army's rocket program, though during the war he did some work on it. After the war he lived in West Germany, worked for a few years with von Braun in the United States in the 1950s, and in July 1969 he was invited to watch the launch of Apollo 11. He died in 1989, aged 95, having lived long enough to see the rockets he had imagined as a schoolboy carry people to the Moon.","By 1937 the army's rocket team had grown too big for Kummersdorf. It moved to a remote, wooded stretch of coast on the Baltic Sea called Peenemünde, and work began on much larger rockets. The dreamers who had wanted to go to the Moon now worked behind fences and guarded gates. Their rockets were about to become weapons in a terrible war."]}],"deepDive":"Oberth's 1923 book is remembered less for any single invention than for showing, with equations, that spaceflight was an engineering problem rather than a fantasy. He worked out the speeds a rocket needs, the importance of high exhaust velocity, and why multi-stage rockets make the impossible possible. Staging matters because of the rocket equation: if one rocket must carry its own empty tanks and engines all the way to orbit, the final speed is limited, but dropping dead weight lets the upper stages start from a high speed with a much lighter load. Oberth is also remembered for an insight now called the Oberth effect: a rocket burn gives a spacecraft more extra energy when it is already moving fast, for example when it swings close to a planet. Modern mission planners use this whenever they time engine burns at the closest point of an orbit. Historians often describe Tsiolkovsky, Goddard and Oberth, with the Frenchman Robert Esnault-Pelterie, as founders of astronautics who reached many of the same conclusions independently. Their influence differed. Tsiolkovsky's writings were little known outside Russia until the late 1920s; Goddard did most of his work quietly; Oberth's book, and the popular books it inspired, created a public movement. That movement, in turn, produced a pool of trained young engineers. Historians also debate the 'first countdown'. 'Frau im Mond' (1929) is widely credited with popularising the countdown to zero, though people have probably counted down to dramatic moments in other ways before. A darker debate concerns the clubs themselves. Some writers present the VfR as innocent dreamers corrupted by the army; others point out that several members, including von Braun, chose to accept military money because it was the only way to build big rockets, and that this choice led directly to the V-2 and its victims. The Soviet experience offers a sobering parallel: many leaders of the RNII institute were arrested in Stalin's purges of 1937 to 1938, and some were executed. In both countries, rocketry moved from amateur enthusiasm to state control within about a decade.","funFact":"The first V-2 rocket successfully launched in 1942 had the logo of Fritz Lang's film 'Woman in the Moon' painted on its base, a sign of how much the film had inspired the young engineers.","check":{"q":"Which 1929 film, advised by Hermann Oberth, is often credited with inventing the backwards countdown before a launch?","a":"Woman in the Moon (Frau im Mond), by Fritz Lang","wrong":["Metropolis","From the Earth to the Moon","The War of the Worlds"]},"sources":[{"title":"Hermann Oberth","publisher":"U.S. Centennial of Flight Commission","url":"https://centennialofflight.net/essay/SPACEFLIGHT/oberth/SP2.htm"},{"title":"Scientist of the Day: Hermann Oberth","publisher":"Linda Hall Library","url":"https://www.lindahall.org/about/news/scientist-of-the-day/hermann-oberth/"},{"title":"Early Rocket Societies","publisher":"Smithsonian National Air and Space Museum","url":"https://airandspace.si.edu/stories/editorial/early-rocket-societies"},{"title":"85 years ago: The USSR launched its first rocket using liquid propellant","publisher":"RussianSpaceWeb","url":"https://russianspaceweb.com/gird09.html"},{"title":"Group for the Study of Reactive Motion","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Group_for_the_Study_of_Reactive_Motion"},{"title":"Woman in the Moon","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Woman_in_the_Moon"},{"title":"Opel-RAK","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Opel-RAK"},{"title":"Wernher Magnus Maximilian von Braun","publisher":"Encyclopedia.com","url":"https://encyclopedia.com/science/encyclopedias-almanacs-transcripts-and-maps/wernher-magnus-maximilian-von-braun"}],"photos":[{"src":"img/deep/rockets/06-1.jpg","alt":"Hermann Oberth, the rocket pioneer from Transylvania, photographed in the 1950s.","file":"Hermann Oberth 1950s.jpg","url":"https://commons.wikimedia.org/wiki/File:Hermann_Oberth_1950s.jpg","author":"Unknown (Mondadori Publishers)","license":"Public domain"},{"src":"img/deep/rockets/06-2.jpg","alt":"A 1928 Opel RAK2 rocket car, with its stubby side wings, at the Technik Museum Speyer in Germany.","file":"Opel RAK2 vl black.jpg","url":"https://commons.wikimedia.org/wiki/File:Opel_RAK2_vl_black.jpg","author":"Stahlkocher","license":"CC BY-SA 3.0"},{"src":"img/deep/rockets/06-3.jpg","alt":"Berlin rocket club members around 1930 with a rocket; Oberth stands centre, young Wernher von Braun second from right.","file":"Wernher von Braun (6517791).jpg","url":"https://commons.wikimedia.org/wiki/File:Wernher_von_Braun_(6517791).jpg","author":"NASA Marshall Space Flight Center","license":"Public domain"}],"words":3814},{"n":7,"title":"The V-2: A Rocket's Dark Side","when":"1937 – 1945","summary":"In a secret base by the sea, German engineers built the V-2, the biggest rocket the world had ever seen. One of them even flew all the way to space. But it was built for war, it was used to attack cities, and prisoners were forced to make it, so its story is a sad and serious one.","sections":[{"heading":"A Secret Base by the Sea","paragraphs":["Imagine walking through pine woods on a quiet island on the Baltic coast of Germany in the spring of 1937. Sand dunes, reed beds, the smell of salt and resin, birds calling over the marsh. Then imagine bulldozers, railway lines, concrete test stands as tall as houses, and thousands of workers arriving. This was Peenemünde, on the northern tip of the island of Usedom, and it was about to become the most advanced rocket centre on Earth.","In the last part we met the young members of the German rocket club, the VfR, and saw how the German army became interested in rockets. Why the army? After World War I, the Treaty of Versailles had strictly limited Germany's big guns, but it said nothing about rockets, because almost nobody took rockets seriously as weapons in 1919. By the 1930s Germany was ruled by Adolf Hitler and the Nazi Party, a cruel dictatorship that was rebuilding the army and planning for war. Army officers saw rockets as a way to build a long-range weapon that no treaty had ever forbidden.","The officer in charge was Walter Dornberger, an artillery captain who had studied engineering. In 1932 he hired a brilliant 20-year-old student named Wernher von Braun, who had been one of the keenest members of the rocket club. At first the army team worked at Kummersdorf, a firing range south of Berlin, in a small walled-off area. There they built the first rockets of a series called the 'Aggregat', a dull German word that means something like 'assembly' or 'unit'. The A-1 failed. Two A-2 rockets flew from the North Sea island of Borkum in December 1934, rising about 2 kilometres. That was promising, but Kummersdorf was too small and too close to people for the much bigger rockets the army now wanted.","So the army and the German air force together chose Peenemünde, where rockets could be fired out over the empty Baltic Sea and tracked along the coast for hundreds of kilometres. The rocket group moved there in April 1937. Von Braun, only 25 years old, became technical director, which meant he led the engineers who designed the rockets. Dornberger led the whole programme for the army. Over the next few years Peenemünde grew into a town of laboratories, workshops, a power station, a liquid-oxygen factory, housing and a giant supersonic wind tunnel. By the early 1940s thousands of people worked at the army's part of the site.","It is important to say clearly what kind of place this was. Many of the engineers at Peenemünde had grown up dreaming of spaceflight, and some of them still talked about the Moon and Mars in the evenings. But they were paid by the army of a brutal government, and their job was to build a weapon. Von Braun joined the Nazi Party in 1937 and became a member of the SS, Hitler's political army, in 1940, rising to the rank of major. Historians still argue about how much he believed in Nazi ideas and how much he simply went along with them to keep his rockets funded. Either way, the dream and the weapon were tied together from the start."]},{"heading":"Building a Giant: How the A-4 Worked","paragraphs":["The army gave the Peenemünde team a clear target. It wanted a rocket that could carry about one tonne of explosives roughly 250 to 300 kilometres, much farther than any cannon could fire. And to make sure it could travel by railway and through tunnels, it had to fit the size limits of ordinary trains and roads. The design that came out of this was the A-4, the fourth rocket in the Aggregat series. Later, Nazi propaganda gave it a scarier name, as we will see.","The A-4 was enormous for its time. It stood about 14 metres tall, as high as a four-storey building, and was about 1.65 metres wide. Empty, it weighed around 4 tonnes. Fully fuelled, it weighed about 12.5 tonnes, and most of that was propellant. Its four big fins gave it the shape that many people still picture when they hear the word 'rocket'. Cartoon rockets in comics and films of the 1950s were often drawn to look like it.","It burned two liquids. The fuel was ethyl alcohol, the same kind found in drinks, mixed with about a quarter water. The water made the flame slightly cooler so the engine would not melt. The oxidizer was liquid oxygen, which has to be kept at about minus 183 degrees Celsius, so cold that frost formed all over the outside of the rocket as it waited on the launch pad. Remember Goddard's tiny rocket from 1926, which also used liquid oxygen? The A-4 was built on the same basic idea, but it was enormously bigger.","Getting tonnes of liquid into the engine fast enough was a real puzzle. Squeezing the tanks with gas pressure, as earlier small rockets did, would have needed tanks too heavy to fly. So the engineers added turbopumps, spinning fans that shoved the fuel and oxygen into the engine. The pumps were driven by a little steam turbine. The steam came from mixing hydrogen peroxide with a chemical called sodium permanganate, which made the peroxide break down into hot steam and oxygen in an instant. In other words, the rocket had a small steam engine inside it just to feed the main engine.","The main engine, developed by a team led by the engineer Walter Thiel, burned about 125 kilograms of propellant every second and produced around 25 tonnes of thrust, roughly 250 kilonewtons. It fired for a little more than a minute. In that time the rocket climbed steeply, tilted over toward its target, and reached a top speed of around 5,500 kilometres per hour, about five times the speed of sound. After the engine cut off, the rocket coasted in a great arc, rising roughly 80 to 90 kilometres high on a normal war flight, before falling back to the ground. The whole trip of about 320 kilometres took only about five minutes.","Steering was clever too. Inside the rocket, gyroscopes, spinning wheels that keep pointing the same way, sensed if the rocket started to tilt or roll. They sent signals to small rudders on the fins and, more importantly, to four vanes made of graphite that sat right in the fiery exhaust. Tilting these vanes bent the jet of hot gas, which turned the rocket. Graphite was used because it could survive the blast of gas at around 2,700 degrees Celsius for the minute or so the engine burned. A simple onboard device measured how fast the rocket was going and shut off the engine at the right moment, which decided how far it would fly."]},{"heading":"3 October 1942: 'The Spaceship Is Born'","paragraphs":["The first A-4 rockets did not go well. The first one, in June 1942, lost control and crashed into the sea only about a kilometre from the pad. The second broke apart in August. Rocket testing has always worked like this: every failure teaches something, but every failure is also expensive and sometimes dangerous.","Then, on 3 October 1942, the fourth test rocket stood on Test Stand VII at Peenemünde. It was painted in a black-and-white pattern so that cameras could see it spin, and it even carried a little painted picture on its side: a woman sitting on a crescent moon, a nod to Fritz Lang's film 'Woman in the Moon', which we met in the last part. The engine roared, the rocket rose, tipped over toward the sea and kept going. It flew about 190 kilometres down the coast and climbed to a height of about 85 kilometres, higher than anything humans had ever built. No earlier object had gone so high.","That evening Dornberger gave a speech to his team. In his memoirs, written after the war, he remembered telling them that they had shown rockets could be used for space travel, and that this day was the day 'the spaceship was born'. Then, he recalled, he reminded them that their real task was to finish a weapon as quickly as possible. That one evening sums up the whole story of the V-2: a real step toward space, and at the same time a weapon meant for war.","After this success, Hitler, who had been doubtful, became enthusiastic. In late 1942 he ordered the rocket into mass production, and the Nazi government poured money, materials and people into it. Historians have worked out that the whole V-2 programme cost Germany a huge sum, by some estimates about as much as the American atomic bomb project cost the United States, though such comparisons are rough. Some experts argue that it was a poor use of resources for Germany's war effort, because each rocket took thousands of hours of skilled work and costly materials, yet carried only about one tonne of explosives and could hit only roughly where it was aimed. The name it was given for propaganda was V-2, short for 'Vergeltungswaffe 2', which means 'Vengeance Weapon 2'. The V-1, a jet-powered flying bomb, was the first."]},{"heading":"The Hidden Price: Prisoners Under the Mountain","paragraphs":["This part of the story is hard to hear, and it is told here calmly and without gruesome details. But it must be told, because for a long time it was left out of the proud histories of spaceflight, and the people it happened to deserve to be remembered.","To build thousands of rockets quickly, the Nazi government needed workers, and by 1943 Germany was using millions of forced labourers from the countries it had invaded. Some of them were prisoners from concentration camps, the prison camps where the Nazis held, mistreated and killed people they considered enemies, including Jews, political opponents and prisoners of war. In the summer of 1943, the leaders of the V-2 programme, including Dornberger and the production manager Arthur Rudolph, agreed to use concentration-camp prisoners as workers. Hundreds of prisoners were brought to Peenemünde itself to work in the production halls, and thousands of other forced labourers, many from Eastern Europe, worked on construction in the area.","Then, on the night of 17 to 18 August 1943, British bombers attacked Peenemünde in a raid called Operation Hydra. British intelligence had learned about the rocket base from spies, captured soldiers and photographs taken by reconnaissance planes. Hundreds of bombers struck the site. Among the people killed were the engine designer Walter Thiel and his family, and also many hundreds of foreign forced labourers in a camp nearby who had no proper shelter. The raid did not stop the V-2, but it convinced the Nazi leaders that rocket production had to move somewhere bombs could not reach.","The place they chose was the Kohnstein, a hill near the town of Nordhausen in central Germany. Inside it were long tunnels that had been dug for storing fuel and chemicals. The SS took them over, and from late August 1943 prisoners were brought in to turn the tunnels into an underground factory called the Mittelwerk, meaning 'Central Works'. The prisoners' camp next to it was first called Dora and later became the main camp of a network called Mittelbau-Dora.","In the first months, the prisoners had to live inside the tunnels while they blasted rock and carried out rubble. There was hardly any daylight, little water, dust everywhere, and almost no proper beds, toilets or food. Many prisoners died from exhaustion, hunger and disease. Only in early 1944 did prisoners begin moving into a barrack camp built outside, and some still slept in the tunnels until May. Later, as rockets began rolling off the assembly lines, prisoners worked alongside German civilian technicians, doing much of the heaviest and most dangerous work. Guards punished people harshly, including for suspected sabotage, which means secretly damaging the work.","Historians estimate that about 60,000 prisoners passed through Mittelbau-Dora and its sub-camps, and that around 20,000 of them died. Not all of them worked on rockets, so experts usually say that somewhere between about 10,000 and 20,000 forced labourers died because of V-2 production. The Smithsonian's National Air and Space Museum gives a figure of at least 10,000. That leads to one of the most shocking facts in the history of rocketry: more people died building the V-2 than were killed by it as a weapon.","What did the engineers know? Von Braun visited the Mittelwerk a number of times and saw the conditions there. Historians who have studied the records, such as Michael Neufeld of the Smithsonian, have concluded that he knew about the forced labour and became increasingly involved in decisions about it, even though he was not in charge of the camp. After the war, he and many others rarely talked about it, and the full story only came out in the 1970s and 1980s. Today the site is the Mittelbau-Dora Concentration Camp Memorial, a museum and a place of mourning, where visitors can learn the names and stories of the prisoners who came from France, Poland, the Soviet Union, Belgium, Italy and many other countries."]},{"heading":"Into Space by Accident: June 1944","paragraphs":["While mass production was getting started, the test flights at Peenemünde continued, now with a new purpose. Engineers wanted to understand how the rocket behaved at very high altitudes, where the air becomes so thin that fins and air rudders no longer do anything. Normal war flights went up at an angle. But a rocket fired straight up, or nearly straight up, would rise far higher.","On 20 June 1944, a test rocket with the code name MW 18014 was launched almost vertically from Peenemünde. Its engine burned for about a minute, and then it coasted upward, slowing as gravity tugged on it, until it reached a peak height of about 175 kilometres. That is far above the Kármán line at 100 kilometres, the boundary that is often used today to mark where space begins. So, on that day, a V-2 test rocket became the first human-made object to reach outer space.","It is worth thinking about what 175 kilometres means. Passenger jets fly at about 11 kilometres. The tallest mountain, Mount Everest, is under 9 kilometres. At 175 kilometres, the sky above is black even in daytime, and Earth's curve is clearly visible. The rocket carried no camera and no person, so nobody saw that view, and the engineers did not throw a party about it. To them it was a test of controls and engines, and they cared more about the 1942 flight. Only later did people realise its importance.","The rocket did not go into orbit. To orbit the Earth, something has to travel sideways at about 28,000 kilometres per hour, which we will explore in a later part. MW 18014 was going straight up and only about a fifth of that speed, so it simply fell back down into the Baltic Sea, a few minutes after launch. It was what we now call a suborbital flight: up into space and back down again without circling the planet. Thirteen years later, a satellite called Sputnik would become the first object to stay up in orbit. But the first object to touch space at all was a German rocket built for war."]},{"heading":"Rockets Without Warning","paragraphs":["On the morning of 8 September 1944, a V-2 was launched toward Paris, which the Allies had freed from German control only a few weeks earlier. That evening, at about 6:40 pm, another V-2 fell on Staveley Road in Chiswick, in west London. Residents heard a huge double bang and saw a crater about 6 metres wide where houses had stood. Three people were killed, including a three-year-old girl named Rosemary Clarke, and many more were injured. At first the British government did not admit what it was and spoke of gas explosions, because it did not want Germany to know where its rockets were landing.","The rockets were fired from mobile launch teams hidden in woods and suburbs in the occupied Netherlands, especially around The Hague. A special trailer called a Meillerwagen lifted the rocket upright onto a small launch table. Soldiers filled it with fuel and liquid oxygen, and within a couple of hours the team could fire and drive away. Because there was no big fixed launch site, Allied planes found it very hard to find and destroy them before they fired.","What made the V-2 so frightening was that it could not be stopped. The earlier V-1 flying bomb buzzed through the sky at the speed of a fast plane, so fighter pilots could shoot it down or tip it over with their wings, and anti-aircraft guns could hit it. But the V-2 came down from the edge of space at several times the speed of sound. There was no warning siren, no time to reach a shelter. Because it travelled faster than sound, people heard the explosion first and only afterwards the roar of the rocket arriving, a strange reversal that many survivors remembered. No weapon of the time could shoot one down. The Allies' only defence was to bomb factories, railways and launch areas, and finally to capture the land the rockets were fired from.","Over the next seven months, the Germans fired somewhere around 3,000 V-2s at targets in Western Europe; the Smithsonian estimates between about 3,200 and 3,600. The two most-hit cities were London and Antwerp in Belgium. Antwerp mattered because its large port was being used to bring supplies to the Allied armies, and it received more V-2s than any other city, around 1,600. In London, a rocket struck a busy Woolworths shop in New Cross on Saturday 25 November 1944, killing more than 160 people. In Antwerp on 16 December 1944, a rocket hit the crowded Rex cinema during a film, killing more than 500 people, many of them soldiers. These were the deadliest single V-2 strikes.","Historians estimate that V-2 attacks killed about 5,000 to 9,000 people in total, most of them civilians, and injured many thousands more. The Smithsonian gives an estimate of about 5,500 killed and 6,500 badly injured; in London alone, about 2,700 people died. These are terrible numbers. Yet compared with the bombing raids of the war, which killed hundreds of thousands, the V-2 did not change the outcome of the war at all. It caused fear and grief, but it could not save Nazi Germany. The last V-2s were fired in late March 1945, as Allied armies pushed toward Germany from both sides."]},{"heading":"The War Ends and the Great Scramble Begins","paragraphs":["By early 1945, Germany was collapsing. The Soviet Red Army was advancing from the east toward Peenemünde, and in February most of the rocket team was moved south and west, away from the Soviets, to towns near the Mittelwerk such as Bleicherode. Von Braun and other leaders had already decided that if they had to surrender, they wanted to surrender to the Americans rather than the Soviets. They also knew their knowledge was valuable, perhaps their best protection.","Before leaving, the team hid about 14 tonnes of Peenemünde documents, drawings and reports in an abandoned mine, hoping to use them as a bargaining chip. In April 1945, von Braun, Dornberger and a few hundred key people moved on into the mountains of Bavaria, near the Austrian border. Von Braun had a broken arm in a plaster cast from a car accident in which his driver had fallen asleep. On 2 May 1945, his younger brother Magnus, who spoke good English, rode a bicycle down a mountain road until he met an American soldier and explained who they were. The rocket leaders surrendered, and were soon being questioned by American experts who could hardly believe how far ahead the Germans' rockets were.","Meanwhile, on 11 April 1945, American troops reached Nordhausen. In the Dora camp and in the town, they found thousands of sick and starving prisoners and the bodies of many who had died; photographs taken by American soldiers showed the world what had happened there. Inside the Kohnstein tunnels they found something else: rows of half-built V-2s and stacks of parts. The area was about to be handed over to the Soviet zone of occupation, so a special American team rushed to load railway wagons with enough parts for roughly 100 rockets and send them away before the Soviets arrived. The parts were shipped across the Atlantic to the United States. The hidden documents from the mine were also found and taken away.","The Soviets were not far behind. Their army had captured what was left of Peenemünde on 5 May 1945, and when they took control of Nordhausen in July, they began gathering every rocket part, drawing and German engineer they could find. A Soviet engineer recently freed from a prison camp, Sergei Korolev, would soon arrive in Germany to study the rocket closely. The British, too, collected V-2s and in October 1945 fired a few from northern Germany in tests called Operation Backfire, with German crews helping, so that Allied officers could see the launch process for themselves.","The war in Europe ended on 8 May 1945, and the world began to count its losses. But a new rivalry was already taking shape. The United States and the Soviet Union had been allies against Hitler, yet they distrusted each other deeply. Both had seen what the V-2 could do. Both understood that a bigger rocket, perhaps one carrying a far more powerful warhead, could one day cross an ocean in less than an hour. And so, in the ruins of Germany, the two new superpowers were racing to grab German rockets, documents and engineers, each hoping to win the next race before it had even officially begun."]}],"deepDive":"Historians judge the V-2 in two ways at once. As engineering, it was a giant leap. Before it, the biggest liquid-fuel rockets produced a few hundred kilograms of thrust; the A-4 engine produced about 25 tonnes. It brought together ideas that every later large rocket used: turbopumps, a regeneratively cooled engine (the alcohol fuel flowed around the chamber wall to cool it before being burned), gyroscopic guidance, steering by deflecting the exhaust, and a full system of test stands, wind tunnels, tracking and launch crews. Peenemünde's supersonic wind tunnel studied airflow at several times the speed of sound, which was rare in the early 1940s. After the war, rockets in the United States, the Soviet Union, Britain and France all began, directly or indirectly, with captured V-2s or V-2 experience. As a weapon, though, most historians, including Michael Neufeld of the Smithsonian's National Air and Space Museum, consider it a failure. It was very expensive, with production averaging about 75,000 Reichsmarks per rocket after costs came down, against about 100,000 at first, plus thousands of hours of work per rocket. It could only hit roughly where it was aimed: many fell kilometres from their targets, and about a quarter of launches against some targets failed or broke up in the air. Its one-tonne warhead was small compared with what a single large bomber raid could drop. The real military argument for long-range rockets only became strong later, when they were combined with nuclear weapons. The ethical debate is sharper. The V-2 is unusual among weapons because, by most estimates, more people died making it, about 10,000 to 20,000 concentration-camp prisoners and forced labourers, than were killed by it, about 5,000 to 9,000. Exact figures are uncertain because of incomplete records and because Mittelbau-Dora prisoners also worked on other projects. Debates continue over the personal responsibility of engineers such as von Braun and Arthur Rudolph, who were never put on trial for it. Rudolph left the United States in 1984 after an investigation into his role at the Mittelwerk. Many museums, including the Smithsonian, now display the V-2 with its full history, including the forced labour, instead of presenting it only as a triumph of technology.","funFact":"The first human-made object to reach space was not a satellite but a German V-2 test rocket, which climbed to about 175 kilometres on 20 June 1944 and then fell back into the Baltic Sea.","check":{"q":"Why could nobody shoot down a V-2 rocket during World War II?","a":"It came down from very high up at several times the speed of sound, too fast for any fighter or gun of the time","wrong":["It was made of a special metal that bullets could not dent","It flew so low that radar and guns could not see it","It was invisible because it was painted the colour of the sky"]},"sources":[{"title":"Missile, Surface-to-Surface, V-2 (A-4)","publisher":"Smithsonian National Air and Space Museum","url":"https://airandspace.si.edu/collection-objects/missile-surface-surface-v-2-4/nasm_A19600342000"},{"title":"Operation Paperclip at Fort Bliss: 1945-1950","publisher":"White Sands Missile Range Museum","url":"https://wsmrmuseum.com/2022/03/28/operation-paperclip-at-fort-bliss-1945-1950/"},{"title":"The 80th anniversary of the first V-2 rocket to hit London","publisher":"IanVisits","url":"https://www.ianvisits.co.uk/articles/the-80th-anniversary-of-the-first-v-2-rocket-to-hit-london-75182/"},{"title":"Sergei Korolev","publisher":"RussianSpaceWeb","url":"https://www.russianspaceweb.com/korolev.html"},{"title":"V-2 rocket","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/V-2_rocket"},{"title":"Mittelbau-Dora","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mittelbau-Dora"},{"title":"Wernher von Braun","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Wernher_von_Braun"}],"photos":[{"src":"img/deep/rockets/07-1.jpg","alt":"Workers on ladders and a tower prepare a black-and-white painted V-2 rocket for launch at Peenemünde.","file":"Bundesarchiv RH8II Bild-B0788-42 BSM, Peenemünde, Startvorbereitungen V2.jpg","url":"https://commons.wikimedia.org/wiki/File:Bundesarchiv_RH8II_Bild-B0788-42_BSM,_Peenem%C3%BCnde,_Startvorbereitungen_V2.jpg","author":"Unknown author","license":"CC BY-SA 3.0 de"},{"src":"img/deep/rockets/07-2.jpg","alt":"Cutaway drawing of a V-2 showing the warhead, alcohol and liquid-oxygen tanks, turbopump and engine, with a person for scale.","file":"Aggregat4-Schnitt-engl.jpg","url":"https://commons.wikimedia.org/wiki/File:Aggregat4-Schnitt-engl.jpg","author":"Eberhard Marx","license":"CC BY-SA 4.0"},{"src":"img/deep/rockets/07-3.jpg","alt":"Visitors read memorial panels inside a tunnel of the Mittelbau-Dora underground factory, where prisoners were forced to build V-2s.","file":"Mittelbau Dora Stollenanlage 19.jpg","url":"https://commons.wikimedia.org/wiki/File:Mittelbau_Dora_Stollenanlage_19.jpg","author":"sockenhorst","license":"CC0"}],"words":3949},{"n":8,"title":"Two Rivals, Secret Rockets","when":"1945 – 1957","summary":"After the war, America and the Soviet Union each grabbed German rockets and built their own. Fruit flies, monkeys and brave little dogs rode rockets before any person did. In secret, a Soviet engineer who had once been a prisoner built the most powerful rocket in the world.","sections":[{"heading":"Treasure Hunters in the Ruins","paragraphs":["In the summer of 1945, Germany lay in ruins. Cities were piles of broken brick, millions of people had lost their homes, and the country was split into four zones, each run by one of the winning powers: the United States, the Soviet Union, Britain and France. Moving through this wreckage were special teams of scientists and intelligence officers with lists of names and addresses. They were not looking for gold. They were looking for knowledge: jet engines, chemicals, radar and, above all, rockets.","The American effort began under the code name Operation Overcast and was soon renamed Operation Paperclip. The story usually told is that officials marked the files of the Germans they wanted with a paperclip. Its aims were simple: to use German know-how to help American weapons and science, and to stop that same know-how from going to the Soviet Union. Over the following years, about 1,600 German scientists, engineers and technicians, many with their families, were brought to the United States under Paperclip and related programmes.","The most famous group was the rocket team. Wernher von Braun, who had surrendered to American soldiers in May 1945, helped choose who should come. By February 1946, 118 German rocket specialists had arrived at Fort Bliss, an army base near El Paso, Texas, and the group soon grew to about 127. At first their life was strange and restricted. They lived in old wartime barracks in a fenced-off area, and they could only go shopping in El Paso with an American sergeant along. They played football, went bowling, watched films and learned to love Texas steaks. Their families started to arrive from Germany in December 1946.","This raised a hard question, and it is still debated today. Many of these men had worked for the Nazi regime. Some, like von Braun, had been members of the Nazi Party and the SS, and some had been involved in using forced labour at the Mittelwerk. President Harry Truman approved the programme but said that active Nazis should not be included. However, historians have shown that some officials in charge of the programme cleaned up or hid uncomfortable information in the scientists' records. Supporters argued that the United States could not afford to let the Soviet Union get all this expertise. Critics argued that people who may have shared responsibility for terrible crimes were given new careers and never faced justice. Both sides of that argument are part of the true history of spaceflight."]},{"heading":"V-2s Over the Desert","paragraphs":["Meanwhile, about 300 railway wagons full of V-2 parts, shipped across the Atlantic from the Mittelwerk, rolled into a remote stretch of New Mexico desert called White Sands. It was a perfect place for testing rockets: flat, dry, nearly empty of people, and surrounded by mountains. The US Army built a blockhouse with thick concrete walls and a launch area called Launch Complex 33. German and American engineers worked side by side, putting rockets together from the captured parts.","The first V-2 launched at White Sands, on 16 April 1946, lost one of its steering vanes and had to be shut down after 19 seconds. But soon the launches went better. Between 1946 and the early 1950s, about 67 V-2s were fired there. Instead of explosives, the nose carried scientific instruments. Scientists from universities and from the Naval Research Laboratory competed for space in the rocket's nose to measure cosmic rays, the Sun's ultraviolet light, temperatures and pressures high in the atmosphere, and how the air changes with height.","One of the most famous results came on 24 October 1946. A V-2 carried a 35-millimetre movie camera up to about 105 kilometres. The camera snapped a picture every second and a half. When the rocket fell back, the camera was smashed, but the film had been sealed inside a steel case and survived. When scientists developed it, they saw something no human had ever seen: grainy black-and-white pictures of Earth from space, with clouds, the curve of the horizon and the black sky above. Those were the first photographs ever taken from space.","Engineers also experimented with putting one rocket on top of another, the 'rocket train' idea that Tsiolkovsky had imagined decades earlier. In Project Bumper, a small American rocket called the WAC Corporal was mounted on the nose of a V-2. When the V-2 burned out, the smaller rocket lit and kept climbing. On 24 February 1949, the Bumper 5 flight reached about 400 kilometres high and a speed of more than 8,000 kilometres per hour, a record at the time. In July 1950, a Bumper became the first rocket ever launched from a new site in Florida called Cape Canaveral, which would later become one of the most famous launch sites in the world.","In 1950 the Army moved von Braun's team to Redstone Arsenal in Huntsville, Alabama. There they designed a new missile, the Redstone, which first flew in 1953. It was a direct descendant of the V-2, but American-built and more powerful. Von Braun also became a public figure, writing magazine articles and working with Walt Disney on television programmes in the 1950s that showed millions of Americans paintings and models of space stations and Moon ships. He talked about space; the Army mostly wanted missiles."]},{"heading":"The Prisoner Who Became the Chief Designer","paragraphs":["Now we cross to the other side of the world, and meet one of the most important people in the whole history of spaceflight, a man most of the world did not know existed until after he died.","Sergei Pavlovich Korolev was born in January 1907 in Zhytomyr, a city in what is now Ukraine. As a teenager he fell in love with flying, built gliders and studied engineering in Kyiv and then in Moscow. In the early 1930s he became one of the leaders of GIRD, the Moscow rocket club we met in part 6, and helped launch the GIRD-09 rocket in 1933. Then he worked at the Soviet Union's first official rocket institute, designing rocket-powered gliders and missiles.","In the late 1930s the Soviet dictator Joseph Stalin carried out the Great Purge, a time of terror when hundreds of thousands of people were arrested on false charges and many were executed. On 27 June 1938, Korolev was arrested, falsely accused of sabotage. He was sent to the Gulag, the network of Soviet prison labour camps, and spent months travelling by train and ship to the Kolyma region in the far north-east of Siberia, one of the coldest places on Earth. There he was forced to work in a gold mine. Prisoners there faced bitter cold, hunger and disease, and many did not survive. Korolev's health was badly damaged; he is said to have lost several teeth from scurvy, an illness caused by lack of vitamin C.","He was saved, in a strange way, by other prisoners. Stalin's government had set up special prison design offices, nicknamed 'sharashkas', where arrested engineers were made to keep working on aircraft and weapons. The famous aircraft designer Andrei Tupolev, himself a prisoner, asked for Korolev, and in 1940 Korolev was moved to Tupolev's prison workshop. Later he worked under another prisoner engineer, Valentin Glushko, on rocket engines to help aircraft take off. He was released in the summer of 1944, though he was only officially cleared of the false charges in 1957.","After the war, Korolev was sent to Germany as an officer to study the V-2. He was not interested in only copying it. He wanted to go much further. In 1946 he became head of a rocket department at a new research institute called NII-88 near Moscow, and in time he became the leader of his own design bureau, OKB-1. Inside the space programme everyone called him simply the 'Chief Designer'. Outside, his name was a state secret. When Soviet newspapers praised the great achievements of Soviet rockets, they never said who was behind them, and when Korolev wrote articles for the public, he used a false name, 'Professor K. Sergeyev'. His name was only revealed to the world in his obituary after he died in January 1966."]},{"heading":"The Soviets Build Their Own V-2","paragraphs":["The Americans had taken von Braun and most of the top German rocket leaders, along with the best parts. But the Soviet Union controlled Peenemünde, Nordhausen and the Mittelwerk tunnels, and many skilled German engineers and workers still lived nearby. In 1945 and 1946, Soviet engineers, including Korolev, Glushko and a young electrical engineer named Boris Chertok, set up institutes in central Germany. At first one was based in the town of Bleicherode, and later the work was gathered into larger organisations in the Nordhausen and Bleicherode area. There, Soviet and German engineers together rebuilt the V-2 from leftover parts, collected the scattered drawings and figured out how to make the rocket again.","Then, on the night of 22 October 1946, Soviet officials suddenly woke up more than 2,000 German specialists, many with their families, and put them on trains to the Soviet Union, whether they wanted to go or not. Many ended up on Gorodomlya, a small island in Lake Seliger, north-west of Moscow, where they worked under the leadership of a German engineer named Helmut Gröttrup. They proposed clever new rocket designs, but the Soviet leaders, and Korolev himself, increasingly preferred to rely on their own engineers. The Germans were gradually cut off from the important work, and by the early 1950s most were allowed to go home.","In October 1947, the Soviets launched their first rebuilt V-2s from Kapustin Yar, a new test site on the dry steppe near the Volga River. A year later came the R-1, a Soviet-made copy of the V-2 built from Soviet materials and factories. Test flights began in the autumn of 1948, and although many early rockets failed, the R-1 was soon working well enough to enter service with the Soviet army in 1950. It was not an exciting new design, but making it taught Soviet industry how to build every part of a large liquid-fuel rocket. Korolev quickly moved on to longer-range rockets, the R-2 and then the R-5, each going farther than the last.","So, by around 1950, both rivals had their own V-2 copies and teams busy improving them. In the United States, the German team was one of several groups, competing with the Army, Navy and Air Force and with companies. In the Soviet Union, Korolev's group was becoming the heart of the whole programme. Neither side knew everything the other was doing. That secrecy, and the fear that came with it, would shape the next twenty years."]},{"heading":"Bombs, Oceans and the Cold War","paragraphs":["To understand why both governments poured so much money into rockets, we have to talk about the most frightening weapon ever made. In August 1945, the United States dropped atomic bombs on the Japanese cities of Hiroshima and Nagasaki, helping to end World War II but killing well over 100,000 people. For four years, America was the only country with such bombs. Then, on 29 August 1949, the Soviet Union tested its own atomic bomb. In the early 1950s, both countries went on to build hydrogen bombs, which were hundreds of times more powerful still.","This was the start of the Cold War, a long rivalry between the United States and its allies on one side and the Soviet Union and its allies on the other. It was called 'cold' because the two superpowers never fought each other directly in a full war. Instead, they competed in almost everything: weapons, spying, sport, science and, before long, space. Each side was afraid that the other might attack first.","At first, the only way to deliver a nuclear bomb across the world was by a large bomber plane. Bombers were slow, taking many hours to fly between continents, and they could be spotted by radar and shot down. A rocket was different. A rocket big enough to throw a bomb thousands of kilometres would fly up through space and down onto its target in about half an hour, and nothing could stop it. Such a weapon is called an intercontinental ballistic missile, or ICBM. 'Ballistic' means that after its engines stop, it simply falls along a curved path, like a thrown ball. It needed a range of thousands of kilometres, at least ten times farther than the V-2 could fly.","For the Soviet Union, the ICBM mattered even more than for the United States. America had air bases in Europe and Asia close to the Soviet Union, so American bombers could reach Soviet cities fairly easily. Soviet bombers, however, would have had to fly all the way across the Arctic or the oceans to reach America. A rocket that could cross the world was the Soviets' way of catching up. That is why, in the early 1950s, the Soviet government gave Korolev the go-ahead to build a gigantic rocket. Early Soviet hydrogen bombs were also very heavy, so the missile had to lift a warhead of around 5 tonnes, which forced Korolev to design something far larger than anyone had built. That giant size would turn out to be very important for space."]},{"heading":"Flies, Monkeys and Dogs Go First","paragraphs":["Before any human could ride a rocket, scientists wanted to know: can a living creature survive the shaking of launch, the crushing push of acceleration, the weightlessness of free fall and the radiation high above the atmosphere? No one knew. So the first passengers were animals.","The very first animals sent into space and brought back alive were tiny fruit flies. On 20 February 1947, American scientists put them, along with some corn seeds, into a capsule called Blossom on the nose of a V-2 at White Sands. Fruit flies were chosen because scientists already knew a lot about their genes, so they could check whether radiation had harmed them. The rocket reached about 109 kilometres in just over three minutes. Then the Blossom capsule was thrown off, its parachute opened, and when it was found in the desert, the flies were still alive.","Next came monkeys. Several rhesus monkeys, all named Albert, rode V-2s from White Sands. On 14 June 1949, Albert II reached about 134 kilometres, making him the first monkey, and the first mammal, in space. Sadly, his parachute failed and he died when the capsule hit the ground. Several of the early animal flights ended like this, which is part of why these experiments still make many people uncomfortable today. Scientists of the time argued they were the only safe way to learn whether space was survivable before risking a human life.","The Soviet Union chose dogs. Soviet scientists picked small stray dogs from the streets of Moscow, believing that dogs who had survived cold winters and hunger would be tough and calm. They chose dogs that weighed about 6 to 7 kilograms so they would fit in small cabins, and mostly female dogs, partly because a special suit for collecting waste worked better for them. Light-coloured dogs were preferred because they showed up better on the cameras that filmed them. The dogs were trained for weeks: sitting quietly in small boxes, wearing their suits and getting used to loud noise and vibration.","In the summer of 1951, two dogs named Dezik and Tsygan, whose name means 'Gypsy', rode a modified R-1 rocket to an altitude of about 100 kilometres. Their cabin came back down by parachute, and both dogs were found alive and well. They were the first dogs to make a suborbital flight. Tsygan never flew again; a senior Soviet scientist, Anatoli Blagonravov, took her home as a pet. Dezik was less lucky and died on a later flight with another dog named Lisa when the parachute failed. Over the 1950s, dozens of dogs made rocket flights, many of them more than once. Their brave little journeys helped engineers design the cabins, parachutes and life-support systems that would later keep human cosmonauts alive."]},{"heading":"The Semyorka: A Bundle of Five Rockets","paragraphs":["Korolev's giant missile was called the R-7, and its engineers nicknamed it 'Semyorka', which means 'little seven' or 'number seven' in Russian. It was unlike anything built before.","The problem was simple to state and very hard to solve: no single rocket engine of the time was strong enough to lift such a heavy missile. Korolev's answer was to bundle rockets together. In the middle stood a long central core. Strapped around it were four tapered boosters, which made the rocket look a little like a bunch of carrots or a fat skirt at the bottom. The engines came from Valentin Glushko's design bureau. Each of the five parts had one engine with four combustion chambers and nozzles, so at liftoff the R-7 fired 20 main nozzles at once, plus smaller steering engines. It burned kerosene with liquid oxygen. Fully fuelled, it weighed about 280 tonnes, more than 20 times as much as a V-2, and it stood about 31 metres tall.","There was another clever trick. In the 1950s, nobody was sure that a large liquid-fuel engine could be safely started high up in the thin air after the rocket had already been flying. So Korolev's team lit all the engines, the core and all four boosters, on the ground at the same time. After about two minutes, the four empty boosters fell away and the core kept burning. This meant the R-7 was really a two-stage rocket, but with both stages running at liftoff. The rocket did not stand on its tail on the launch pad; it hung from strong metal arms over a huge pit, so the flames could pour down into a deep trench. As it rose, the arms swung back like the petals of an opening flower.","To launch it, the Soviets built a new secret base on the flat, empty steppe of Kazakhstan, near a railway stop called Tyuratam. Construction started in 1955, in a place of blazing summers, freezing winters and dust storms. Today this site is known as the Baikonur Cosmodrome, and it is still in use.","The first R-7 launch, on 15 May 1957, ended when a fire in one booster made the rocket break up. The next attempts also failed. Then, on 21 August 1957, an R-7 roared off its pad and flew about 6,000 kilometres across the Soviet Union, landing its dummy warhead in the target area on the Kamchatka Peninsula in the far east. The warhead broke apart as it came back into the thick air, a problem engineers would still need to fix. But the rocket itself had worked. It was the world's first successful flight of an ICBM. On 27 August, the Soviet news agency TASS announced to the world that the Soviet Union had a 'super-long-distance' multistage ballistic missile. Many people in the West were not sure whether to believe it. The American Atlas ICBM had not yet made a successful flight.","There is one more amazing fact about the R-7. Its basic design, a core with four strap-on boosters and engines all lit at liftoff, is still flying today as the Soyuz rocket, which has launched cosmonauts, astronauts and countless satellites. The R-7 family has flown more often than any other family of rockets in history. A rocket designed in the 1950s to carry a nuclear bomb ended up becoming one of humanity's most reliable spaceships."]},{"heading":"A Year for Science, and a Race Nobody Announced","paragraphs":["While the military raced in secret, scientists around the world were planning something peaceful. They called it the International Geophysical Year, or IGY, and it ran from 1 July 1957 to 31 December 1958, about 18 months. Scientists from 67 countries agreed to study the Earth together: the oceans, the weather, earthquakes, the poles, the Sun's effects on our atmosphere and the glowing northern and southern lights. Research stations were set up in Antarctica, and ships and balloons gathered data all over the world.","In 1954, the scientists organising the IGY suggested that countries should try to launch an artificial satellite during it, a small object circling the Earth to measure conditions in space. The United States took up the challenge. On 29 July 1955, the White House announced that America would launch 'small earth-circling satellites' as part of the IGY. President Dwight Eisenhower and his advisers also had a quieter reason. They wanted to establish the principle of 'freedom of space', the idea that a satellite flying over another country was not breaking into its airspace. This would make it legal, later, to use spy satellites to watch the Soviet Union.","Only a few days later, in early August 1955, at a scientific meeting in Copenhagen, the Soviet scientist Leonid Sedov announced that the Soviet Union would launch a satellite too. Few people in the West paid much attention.","The Americans now had to decide whose rocket to use. Von Braun's team offered a plan called Project Orbiter, using a Redstone missile with small extra rocket stages on top. Instead, a committee chose a new rocket called Vanguard, designed by the Naval Research Laboratory. Part of the reason was that Vanguard was a scientific rocket, not a military missile, so it fitted the peaceful image the United States wanted, and it would not disturb the Army's missile work. Project Vanguard officially began in September 1955. Its planned satellite was tiny, about the size of a grapefruit and weighing less than 2 kilograms in its first version.","But Vanguard was a brand-new rocket that had to be designed from scratch, and that took time. Meanwhile, von Braun's team in Huntsville was testing a souped-up Redstone called the Jupiter-C. On 20 September 1956 it flew more than 1,000 kilometres high. Its top stage was not a real rocket, but a dummy filled with inert material, and many people have wondered since whether the team could have reached orbit if they had been allowed to try. Historians still argue about it.","By the autumn of 1957, the IGY had begun, Vanguard was still not ready, and the Soviets had a working giant rocket that had just flown across Siberia. Korolev, who had been dreaming of space since his GIRD days, had persuaded his government to let him use an R-7 to launch a simple satellite. In the CIA and the Pentagon, some officials suspected something might happen soon. But most Americans had no idea. Then, on the night of 4 October 1957, radio operators around the world picked up a strange new signal from the sky: beep... beep... beep. It was coming from space, and the whole world was about to be surprised."]}],"deepDive":"Historians often describe the period from 1945 to 1957 as one in which captured German technology gave both superpowers a head start, but in very different ways. The United States got most of the senior German engineers, including von Braun, and about 100 rockets' worth of parts. Yet for years the American rocket effort was split among the Army, Navy and Air Force, each with its own projects, and missiles had low priority until the early 1950s, partly because long-range bombers already seemed good enough. The Soviet Union got fewer top Germans but put its own engineers, led by Korolev, Glushko and others, firmly in charge, and used the Germans mostly as a source of knowledge before sending them home. Soviet leaders, lacking bases near America, also had a stronger reason to fund ICBMs early. A key technical turning point came with the hydrogen bomb. In 1954, an American committee led by the mathematician John von Neumann concluded that thermonuclear warheads would soon be light and powerful enough that an ICBM could carry one and did not need to hit its target precisely. This made the Atlas missile a top national priority. The Soviets, whose early warheads were heavier, built the R-7 to carry about 5 tonnes, which is why it was so large, and why it could later lift satellites and crewed spacecraft. Its first stage and boosters together produced roughly 400 tonnes of thrust at liftoff. The R-7's flight on 21 August 1957 is usually called the first successful ICBM test, although its warhead disintegrated on re-entry; heat shields for warheads took further work in both countries. Another debate is moral. Operation Paperclip brought scientists into the United States despite official rules against admitting active Nazis, and historians and writers such as Michael Neufeld and Annie Jacobsen have shown how records were sometimes softened. Supporters stress the Cold War context; critics point to the forced labourers who died at the Mittelwerk. Animal flights raise their own ethical questions. Today, researchers still debate how much the space race was driven by science and how much by weapons; in this period the honest answer is that rockets were built mainly as weapons, with science and exploration riding along, sometimes literally, in their nose cones.","funFact":"The first photographs of Earth taken from space were shot on 24 October 1946 by a movie camera riding a captured V-2 from New Mexico; the camera was smashed on landing, but the film survived inside a steel case.","check":{"q":"What were the first animals sent into space and recovered alive, in February 1947?","a":"Fruit flies","wrong":["A rhesus monkey named Albert","A stray dog named Laika","A chimpanzee named Ham"]},"sources":[{"title":"Operation Paperclip at Fort Bliss: 1945-1950","publisher":"White Sands Missile Range Museum","url":"https://wsmrmuseum.com/2022/03/28/operation-paperclip-at-fort-bliss-1945-1950/"},{"title":"What Was Operation Paperclip?","publisher":"History.com","url":"https://www.history.com/articles/what-was-operation-paperclip"},{"title":"Sergei P. Korolev","publisher":"NASA History","url":"https://www.nasa.gov/history/sputnik/korolev.html"},{"title":"Sergei Korolev","publisher":"RussianSpaceWeb","url":"https://www.russianspaceweb.com/korolev.html"},{"title":"R-7 intercontinental ballistic missile","publisher":"RussianSpaceWeb","url":"https://www.russianspaceweb.com/r7.html"},{"title":"A Brief History of Animals in Space","publisher":"NASA History","url":"https://www.nasa.gov/history/a-brief-history-of-animals-in-space/"},{"title":"International Geophysical Year: US satellite announcement","publisher":"NASA History","url":"https://www.nasa.gov/history/sputnik/usannounce.html"},{"title":"Missile, Surface-to-Surface, V-2 (A-4)","publisher":"Smithsonian National Air and Space Museum","url":"https://airandspace.si.edu/collection-objects/missile-surface-surface-v-2-4/nasm_A19600342000"}],"photos":[{"src":"img/deep/rockets/08-1.jpg","alt":"Bumper 8, a captured German V-2 with a small upper stage, lifts off from Cape Canaveral in July 1950.","file":"Bumper8 launch-GPN-2000-000613.jpg","url":"https://commons.wikimedia.org/wiki/File:Bumper8_launch-GPN-2000-000613.jpg","author":"NASA/U.S. Army","license":"Public domain"},{"src":"img/deep/rockets/08-2.jpg","alt":"Sergei Korolev, the Soviet Chief Designer, holding one of the little dogs trained for rocket flights.","file":"Sergey Korolev with dog.jpg","url":"https://commons.wikimedia.org/wiki/File:Sergey_Korolev_with_dog.jpg","author":"Музей космонавтики / Главархив Москвы","license":"CC BY 4.0"},{"src":"img/deep/rockets/08-3.jpg","alt":"A full-size R-7 family rocket on display in Moscow, showing the central core and the strap-on boosters around it.","file":"Semyorka Rocket R7 by Sergei Korolyov in VDNH Ostankino RAF0540.jpg","url":"https://commons.wikimedia.org/wiki/File:Semyorka_Rocket_R7_by_Sergei_Korolyov_in_VDNH_Ostankino_RAF0540.jpg","author":"Sergei Arssenev","license":"CC BY-SA 4.0"}],"words":4099},{"n":9,"title":"Beep, Beep: Sputnik and Laika","when":"1957 – 1958","summary":"In 1957 a shiny metal ball called Sputnik zoomed around the Earth, beeping on the radio, and the whole world listened. A brave little dog named Laika rode the next Soviet satellite. Then the Americans raced to launch their own satellite and started a brand-new space agency called NASA.","sections":[{"heading":"A Ball That Changed the World","paragraphs":["Imagine standing on a flat, windy plain in Kazakhstan on the night of 4 October 1957. In the darkness ahead stands Sergei Korolev's giant R-7 rocket, the same rocket that had made its first successful flight as a missile only about six weeks earlier. Its frosty sides steam as super-cold liquid oxygen boils off. Engineers in a concrete bunker watch through periscopes. Then the engines roar to life, the night turns as bright as day, and the rocket climbs on a pillar of flame.","The launch site was near a railway stop called Tyuratam. The Soviet government, which loved secrets, told the world the rockets flew from Baikonur, the name of a small mining town hundreds of kilometres away, to confuse anyone trying to find the base. The name stuck, and today the place is still known as the Baikonur Cosmodrome, the oldest spaceport on Earth.","About five minutes after liftoff, the rocket's engines shut down and a small object separated from its nose. It was a polished metal ball only about 58 centimetres across, a bit bigger than a beach ball, with four long, thin antennas sweeping back from it like the whiskers of a cat. It weighed 83.6 kilograms, about as much as a grown man. Its name was Sputnik, a Russian word that means something like 'fellow traveller' or 'companion'. Today we call it Sputnik 1, because more followed.","Inside the ball there was not much: silver-zinc batteries, two small radio transmitters, a fan to keep things cool, and sensors for temperature and pressure. The transmitters sent out short pulses of radio sound, about a third of a second long, on two frequencies, 20.005 and 40.002 megahertz. On a radio speaker they sounded like a steady 'beep... beep... beep...'. That simple sound proved Sputnik was really up there.","And it was. Sputnik followed an oval-shaped orbit that swooped as low as about 215 kilometres above the ground and climbed as high as about 940 kilometres. It went all the way around the planet roughly every 96 minutes, at a speed of about 29,000 kilometres per hour. In the time it takes to watch a long movie, it crossed oceans, deserts and both of the world's rival superpowers.","Sputnik was actually a backup plan. Korolev's team had been building a big, heavy scientific satellite, packed with instruments, for a worldwide science project called the International Geophysical Year. But that satellite was running late, and Korolev was worried the Americans might launch first. So he got permission to build what his engineers called the 'simplest satellite' (PS-1 for short) in just a few weeks. It turned out that simple was enough to make history.","Sputnik 1 was the first artificial satellite, the first human-made object to orbit the Earth. (It was not the first human-made object to reach space; a German V-2 test rocket had shot up past 100 kilometres in 1944 and fallen back down. The difference is that Sputnik stayed up, going around and around.) Its batteries ran out on 26 October 1957, after about three weeks, and the beeping stopped. The silent ball kept circling until drag from the thin upper air slowly pulled it down. It burned up as it fell back into the atmosphere on 4 January 1958, after about three months and well over a thousand trips around the world."]},{"heading":"The Whole World Listens","paragraphs":["News of Sputnik raced around the planet almost as fast as Sputnik itself. The Soviet news agency TASS announced the launch, and within hours radio stations were playing the beeping sound for their listeners. In the United States, millions of people heard the eerie 'beep-beep' on the evening news. It was the first time ordinary people could hear something that came from space and was made by humans.","At that very moment, a group of scientists from many countries were gathered at a party at the Soviet embassy in Washington, DC, at the end of a week of meetings about the International Geophysical Year. A New York Times reporter named Walter Sullivan was called to the telephone and told the news. He whispered it to the American scientist Lloyd Berkner, who tapped a glass, asked for quiet, and announced that a Soviet satellite was circling the Earth. He then congratulated the Soviet scientists in the room. Imagine the gasps and the clinking of glasses.","Amateur radio fans, often called 'hams', became part of the story. All over the world, people with radio sets in their garages and attics tuned to 20 and 40 megahertz and listened for the beeps. Because Sputnik's signal grew louder as it approached and fainter as it moved away, and its pitch shifted slightly as it passed (the same effect that makes a racing car's 'neeeee-owww' change tone), listeners could even help work out its path. Scientists at universities used these tricks to track the satellite precisely.","Many people also wanted to see Sputnik. Through the Smithsonian Astrophysical Observatory, volunteer teams called Operation Moonwatch had been set up in towns around the world to spot satellites with small telescopes. Now they had something real to watch. Here is a surprising twist: the small, shiny Sputnik ball was hard to see with the naked eye. The bright 'star' that many people saw sliding across the evening sky was usually the R-7 rocket's huge central stage, which had also reached orbit and was much bigger. It tumbled along nearby, catching the sunlight, until it fell back to Earth in early December.","In the Soviet Union, the newspaper Pravda first printed only a short report about the launch. When the leaders saw how amazed the rest of the world was, they realised what a huge propaganda victory they had won, and Sputnik became a national celebration. Soviet leader Nikita Khrushchev began boasting that his country's science and rockets were the best on Earth.","In the United States, the mood was very different. Many Americans were shocked, and some were frightened. The United States thought of itself as the world's leader in technology, with its cars, televisions, refrigerators and jet planes. Now its great rival had beaten it into space. A NASA historian, Roger Launius, has written that Sputnik had a 'Pearl Harbor' effect on American public opinion, meaning it felt like a sudden surprise attack, even though it was harmless. Senator Lyndon B. Johnson, who later became president, remembered looking up at the night sky in Texas and feeling that, as he put it, 'Now, somehow, in some new way, the sky seemed almost alien.'","This wave of worry became known as the 'Sputnik crisis'. The fear was not really about a beeping ball. It was about the rocket that carried it. If the Soviets had a rocket powerful enough to throw an 84-kilogram satellite into orbit, it could surely throw a nuclear bomb across the ocean to an American city. Sputnik showed that the R-7 was a working intercontinental ballistic missile, an ICBM, and there was no way to stop one."]},{"heading":"Laika, the Little Barker","paragraphs":["Khrushchev was delighted with Sputnik, and he wanted another space spectacular quickly, in time for the 40th anniversary of the Russian Revolution on 7 November 1957. That left Korolev's exhausted team less than a month. They decided to send up something even more astonishing than a beeping ball: a living animal.","Soviet scientists had already been sending dogs on short up-and-down rocket flights since 1951, so they knew dogs well. They chose small female dogs from the streets of Moscow. Stray dogs, they reasoned, were already used to surviving cold winters and hunger, so they might cope better with harsh conditions. Females were picked partly because the special suit and waste-collecting equipment were easier to design for them.","One of the dogs was a quiet, calm mixed-breed of about three years old, weighing only about 5 kilograms, part husky or terrier perhaps. Her first name was Kudryavka, meaning 'Little Curly'. But after she barked on a radio broadcast, she became known as Laika, which means 'barker' in Russian, and that is the name history remembers. Two other dogs, Albina and Mushka, trained alongside her as backups and helpers.","Training was tough. To get the dogs used to the tiny cabin, they were kept in smaller and smaller cages for days at a time. They were spun in centrifuges, big machines that whirl round to copy the heavy push of a rocket launch, and placed in machines that imitated the noise and shaking of liftoff. They learned to eat a special jelly-like food and to wear a harness and sensors that measured their heartbeat, breathing and blood pressure. One of the doctors, Vladimir Yazdovsky, later said he took Laika home to play with his children shortly before the flight, because he wanted to do something nice for her.","Sputnik 2 launched on 3 November 1957, less than a month after Sputnik 1. It was far bigger: about 508 kilograms, six times heavier than the first satellite. Inside a cone-shaped body sat instruments to study the Sun's radiation and cosmic rays, and a padded, pressurised cabin, just big enough for Laika to stand, sit or lie down. It had an air-freshening system, a supply of food and water, and a radio system that sent her heartbeat and breathing back to Earth.","Laika became the first animal to orbit the Earth. Her heart raced during the noisy launch, then slowly calmed down when she reached weightlessness. Scientists on the ground could see from her signals that a living creature could survive the launch and the strange floating feeling of orbit, at least for a while. That was important news for anyone hoping to send people one day."]},{"heading":"A One-Way Trip","paragraphs":["Here is the sad part of Laika's story, and it is important to tell it honestly. Sputnik 2 was never designed to come back. In 1957 nobody yet knew how to bring a spacecraft safely back through the fiery heat of re-entry, and there was no time to invent a way in less than a month. Everyone who built the spacecraft knew from the start that Laika would not return.","For many years the Soviet government said that Laika had lived for several days in orbit and had died peacefully, perhaps when her oxygen ran low or by a planned dose of food. That was not true. In 2002, at a space conference in Houston, Texas, a Russian scientist who had worked on the mission, Dimitri Malashenkov, explained what really happened. Part of the rocket had not separated properly, and the cooling system could not cope. The cabin grew hotter and hotter. Laika died from overheating and stress within a few hours, probably five to seven hours after launch, on only her fourth trip or so around the Earth.","Even in 1957, without knowing all of this, many people were upset. Animal-welfare groups in Britain and other countries protested about sending a dog into space with no way home. Newspapers nicknamed her 'Muttnik'. Some of the Soviet scientists themselves felt sorry too. Years later, in 1998, Oleg Gazenko, one of the scientists who trained the space dogs, said that the more time passed, the more sorry he felt, and that they had not learned enough from the mission to justify the death of the dog.","Sputnik 2 kept circling the Earth for about five months, about 2,570 orbits, until it fell back and burned up in the atmosphere on 14 April 1958. Laika's body burned up with it, high above the Earth.","Laika is still remembered. She appeared on stamps and posters in many countries. In 2008, a small statue of her standing on top of a rocket was unveiled in Moscow, near the military research institute where she was trained. Her flight taught scientists that a living body could survive launch and weightlessness, and it made engineers determined that the next animals, and later the first humans, would come home safely. Just under three years later, two other Soviet space dogs, Belka and Strelka, would do exactly that, as you will see in Part 11."]},{"heading":"Flopnik: America's Fiery Flop","paragraphs":["So where was the American satellite? The United States had announced back in 1955 that it would launch a small scientific satellite during the International Geophysical Year. The job went to the US Navy's Naval Research Laboratory and a new rocket called Vanguard. The government chose Vanguard partly because it was not based on a weapon, so the satellite would look like peaceful science rather than a military threat.","The trouble was that Vanguard was brand new, and building a new rocket from scratch takes time. Meanwhile, the US Army had a team led by Wernher von Braun, the German engineer brought to America after World War II, who had a powerful missile called the Redstone, a descendant of the V-2. Von Braun believed his team could launch a satellite quickly, but for a long time they were told to stay out of the satellite business. Some historians think the Army could have reached orbit before Sputnik if it had been allowed to try, though that will always remain a 'what if'.","After Sputnik, the pressure on Vanguard was enormous. On 6 December 1957, at Cape Canaveral in Florida, the rocket called Vanguard TV-3 stood ready to carry a tiny test satellite, a metal ball only about 15 centimetres (6 inches) across that weighed about 1.4 kilograms (3 pounds). It was meant to be a test flight, but newspapers and television crews treated it as America's answer to Sputnik. Cameras were pointing at the pad, and the countdown was broadcast to the nation.","At ignition, the engine roared, and the rocket rose... about 1.2 metres (4 feet). Then it lost thrust, sank back onto the launch pad and exploded in a huge ball of orange fire and black smoke. It was all over in a couple of seconds. The little satellite was thrown clear and landed nearby, where, according to the famous story, it lay in the scrub still beeping. It was too damaged to fly again and today it is displayed at the Smithsonian's National Air and Space Museum in Washington.","The newspapers were merciless. They called the failed rocket 'Flopnik', 'Kaputnik' and 'Stayputnik'. Around the world, people laughed, and Americans felt even more embarrassed. It showed that launching a satellite was very hard, and that having several different military teams working separately was not a good way to win a space race.","Vanguard's engineers did not give up. After another failure in February 1958, a Vanguard rocket finally put a grapefruit-sized satellite, Vanguard 1, into orbit on 17 March 1958. Khrushchev made fun of its small size, but Vanguard 1 was the first satellite powered by solar cells, and it was placed in such a high orbit that it is still up there today. It is the oldest human-made object still circling the Earth."]},{"heading":"Explorer 1 and the Hidden Radiation Belts","paragraphs":["Even before the Vanguard explosion, the US government had finally given von Braun's Army team the go-ahead to try for orbit. They had a rocket ready: the Jupiter-C, a stretched Redstone missile with extra stages on top. For the satellite launch it was called Juno I. Its first stage burned liquid fuel. On top sat a spinning 'tub' holding a cluster of 11 small solid-fuel rockets, then a ring of 3 more, and finally 1 on its own, carrying the satellite. Spinning the tub, like spinning a football when you throw it, kept the little stages pointing straight as they fired.","The satellite itself was built by the Jet Propulsion Laboratory (JPL) in Pasadena, California, led by William Pickering. It was a slim tube about 2 metres long and only about 15 centimetres wide, weighing about 14 kilograms (roughly 30 pounds). The front part held the science instruments, designed by physicist James Van Allen of the State University of Iowa. They included a cosmic-ray detector (a kind of Geiger counter, which clicks when tiny, fast-moving particles pass through it), temperature sensors, and a microphone to listen for hits from tiny space dust called micrometeorites.","The satellite was named Explorer 1, and it launched from Cape Canaveral at 10:48 pm Eastern time on 31 January 1958. It worked. The United States had its first satellite, less than four months after Sputnik. In the middle of the night, at a press conference in Washington, Pickering, Van Allen and von Braun held a full-size model of Explorer 1 high above their heads for the photographers. That photo, three grinning men lifting a satellite into the air like a trophy, became one of the most famous pictures of the early space age.","Explorer 1's orbit was a stretched oval, swinging from about 360 kilometres up to about 2,500 kilometres up, and it took around 115 minutes per lap. As it flew, Van Allen's detector sent back something puzzling. At lower heights it counted cosmic rays as expected. But at the highest parts of the orbit, the count sometimes dropped to zero. Had space suddenly gone empty?","Van Allen and his team came up with a clever explanation. The detector wasn't seeing too few particles; it was being swamped by far too many, so many that the counter jammed, a bit like a person so dazzled by bright light that they can't see anything. They realised Earth must be surrounded by zones filled with electrically charged particles, mostly from the Sun, trapped by our planet's magnetic field. Later satellites, beginning with Explorer 3 in March 1958, confirmed it. These two giant, doughnut-shaped zones circling the Earth are called the Van Allen radiation belts, after him.","This was the first major scientific discovery of the space age, and it mattered a lot. Spacecraft and astronauts need protection when they pass through the belts, and later Moon missions planned their paths to cross them quickly. Explorer 1 kept sending signals until its batteries died on 23 May 1958. It stayed in orbit, silent, for twelve more years, finally burning up in the atmosphere on 31 March 1970 after more than 58,000 orbits."]},{"heading":"NASA Is Born, and Schools Change","paragraphs":["After Sputnik, American leaders decided they needed to organise their space efforts better. In November 1957 President Dwight D. Eisenhower appointed James Killian, president of the Massachusetts Institute of Technology, as his first special adviser for science and technology. In February 1958 the government created a new defence research office called ARPA (the Advanced Research Projects Agency), which, years later, also helped build ARPANET, an early ancestor of the internet.","Eisenhower wanted peaceful space exploration and science to be run by a civilian agency, not by the army, navy or air force. His advisers suggested building it around an older organisation called NACA, the National Advisory Committee for Aeronautics, which had been researching aircraft since 1915 in big laboratories with wind tunnels. Congress agreed and passed the National Aeronautics and Space Act, which Eisenhower signed on 29 July 1958. The new agency's job was to 'plan, direct, and conduct aeronautical and space activities'.","That agency was NASA, the National Aeronautics and Space Administration. It officially began work on 1 October 1958, less than a year after Sputnik. On its first day it took over NACA's three research centres and about 8,000 employees. Its first leader was T. Keith Glennan. Soon NASA also took over JPL and, in 1960, von Braun's rocket team in Huntsville, Alabama. Within its first weeks, NASA approved Project Mercury, its plan to put an American astronaut into orbit.","Sputnik changed classrooms too. Many Americans worried that Soviet schools were training more scientists and engineers than American schools. In September 1958 Congress passed the National Defense Education Act, which gave money for student loans, scholarships for advanced study, and better teaching of science, mathematics and foreign languages. Schools bought new lab equipment, and new science textbooks and courses were written by university scientists. Children who were in school in those years are sometimes called the 'Sputnik generation', and many of them grew up to become the engineers who built the Moon rockets.","In the Soviet Union, the launches kept coming too. On 15 May 1958, Sputnik 3, the big scientific laboratory that had been delayed, finally reached orbit. It weighed about 1,327 kilograms, more than fifteen times as heavy as Sputnik 1, and carried a dozen instruments. The space race was well and truly on. Both sides had satellites in orbit, both had sent up instruments, and one side had sent up a living animal.","Every one of these steps led to an obvious next question. Satellites could go up. A dog had reached orbit and her body had survived the launch. If a dog could go to orbit, when would a human being ride a rocket into space and come home again? And which country would get there first?"]}],"deepDive":"Historians now see the 'Sputnik crisis' as partly a crisis of perception. President Eisenhower was less alarmed than the public, partly because secret U-2 spy-plane flights had shown him that the Soviet missile force was smaller than people feared. He was also quietly pleased about one thing: Sputnik had flown over dozens of countries, including the United States, and nobody had objected. That set an important precedent, sometimes called 'freedom of space' — the idea that satellites may pass over any nation. Eisenhower's government wanted exactly that rule, because it was secretly developing spy satellites (the Corona program, which returned its first photographs in 1960). Because he could not reveal what he knew, Eisenhower looked complacent, and critics such as Senator John F. Kennedy later campaigned on a supposed 'missile gap'. In reality the United States had more long-range nuclear weapons than the Soviet Union in those years; the gap, where it existed, ran the other way.\n\nOn the Soviet side, historians such as Asif Siddiqi have shown how improvised the early triumphs were. Khrushchev at first saw the satellite as a minor sideshow to the R-7 missile program; only the world's reaction made Sputnik a political prize, after which he pushed Korolev for ever bigger 'firsts' on short deadlines. Sputnik 2 was designed and built in about four weeks, which helps explain why its thermal control failed. The R-7 itself was a poor weapon — it took many hours to fuel with liquid oxygen and needed huge, easily spotted launch pads — but it was a superb space launcher, and its descendants still fly as Soyuz rockets.\n\nThe physics of Sputnik's orbit also taught scientists something. By tracking how quickly the satellites' orbits shrank, researchers measured the density of the upper atmosphere far more accurately than before, finding it denser than many had expected. Small wobbles in satellite orbits soon revealed that the Earth is slightly flattened and very slightly pear-shaped — early 'satellite geodesy', the ancestor of today's GPS-based mapping. Vanguard 1's long-lived orbit was especially useful for this work.","funFact":"Vanguard 1, launched in March 1958, stopped transmitting in 1964 but is still orbiting the Earth today, making it the oldest human-made object in space.","check":{"q":"What did James Van Allen's instrument on Explorer 1 help discover?","a":"Belts of charged particles trapped around Earth by its magnetic field (the Van Allen radiation belts)","wrong":["Water ice on the Moon","A hole in the ozone layer","The first planet beyond our Solar System"]},"sources":[{"title":"Sputnik and the Origins of the Space Age","publisher":"NASA History Office (Roger D. Launius)","url":"https://www.nasa.gov/history/sputnik/sputorig.html"},{"title":"60 Years Ago, the Space Age Began","publisher":"NASA","url":"https://www.nasa.gov/history/60-years-ago-the-space-age-began"},{"title":"60 Years Ago: Vanguard Fails to Reach Orbit","publisher":"NASA","url":"https://www.nasa.gov/feature/60-years-ago-vanguard-fails-to-reach-orbit"},{"title":"Explorer 1","publisher":"NASA Science","url":"https://science.nasa.gov/mission/explorer-1"},{"title":"Explorer 1","publisher":"NASA Jet Propulsion Laboratory","url":"https://www.jpl.nasa.gov/missions/explorer-1"},{"title":"60 years ago: Sputnik 1 and the dawn of space","publisher":"FAI (World Air Sports Federation)","url":"https://www-2025.fai.org/news/60-years-ago-sputnik-1-and-dawn-space"},{"title":"Sputnik 1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sputnik_1"},{"title":"Laika","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Laika"}],"photos":[{"src":"img/deep/rockets/09-1.jpg","alt":"A replica of Sputnik 1, the shiny metal ball with four long antennas, at the National Air and Space Museum.","file":"Sputnik asm.jpg","url":"https://commons.wikimedia.org/wiki/File:Sputnik_asm.jpg","author":"NSSDC, NASA","license":"Public domain"},{"src":"img/deep/rockets/09-2.jpg","alt":"Laika the dog in 1957, shortly before her flight on Sputnik 2.","file":"Laika in 1957.jpg","url":"https://commons.wikimedia.org/wiki/File:Laika_in_1957.jpg","author":"Музей космонавтики / Главархив Москвы","license":"CC BY 4.0"},{"src":"img/deep/rockets/09-3.jpg","alt":"William Pickering, James Van Allen and Wernher von Braun hold up a model of Explorer 1 after its launch in 1958.","file":"Explorer1 people.jpg","url":"https://commons.wikimedia.org/wiki/File:Explorer1_people.jpg","author":"NASA","license":"Public domain"}],"words":3786},{"n":10,"title":"How Rockets Work (Part 1): Push and Fall","when":"Science explainer","summary":"A rocket flies by throwing hot gas out of its back, just like a balloon zooms around when you let it go. To stay in space, a spaceship has to go sideways so fast that it keeps falling around the Earth without ever hitting it. Astronauts float because they are falling too, not because gravity has switched off.","sections":[{"heading":"Push Me, Push You","paragraphs":["Blow up a balloon, pinch the end, and then let go. Whoosh! It zigzags wildly around the room, squealing, until it flops to the floor. Congratulations: you have just launched a rocket. Every rocket ever built, from a Chinese fire arrow to the giant Saturn V, works on exactly the same idea as that runaway balloon.","The idea was explained by Isaac Newton in 1687, in his famous book the Principia. It is his third law of motion, and it is usually said like this: for every action, there is an equal and opposite reaction. In plainer words, forces always come in pairs. Whenever one thing pushes on a second thing, the second thing pushes back on the first, just as hard, in the opposite direction.","In the balloon, the stretchy rubber squeezes the air inside. The air rushes out through the open neck. As the balloon pushes the air backwards out of the hole, the air pushes the balloon forwards. Action: air shoved out the back. Reaction: balloon shoved forward. The two forces are equal in size but point opposite ways, and they act on different things, one on the air and one on the balloon. That is the secret of the whole law.","Here is another experiment you can imagine, but please only try it carefully with a grown-up. Stand on a skateboard holding a heavy ball, such as a basketball or, even better, a medicine ball. Throw the ball hard straight ahead. What happens to you? You roll backwards! You pushed the ball forwards, so the ball pushed you backwards. The heavier the ball and the harder you throw it, the faster you roll away.","There is even a simple rule for how fast. Suppose you and your skateboard together have a mass of 40 kilograms, and you throw a 4-kilogram medicine ball forward at 5 metres per second. You are 10 times heavier than the ball, so you will roll backwards 10 times more slowly: about half a metre per second. Scientists describe this with a quantity called momentum, which is mass multiplied by speed. The ball's momentum forward exactly balances your momentum backward.","You have probably felt the third law many times without noticing. When a garden hose is turned on full and you drop it, the nozzle wriggles and whips about like a snake, because the water shooting out pushes the hose back the other way. Firefighters must brace themselves and often hold big hoses in teams, because the kick from a fire hose is strong enough to knock a person over. When you swim, you push water backwards with your hands and feet, and the water pushes you forwards. When you jump off a small boat onto a dock, the boat scoots away behind you.","A rocket engine is simply a machine that throws stuff backwards very hard and very fast. Instead of a medicine ball, it throws an enormous stream of hot gas, made by burning fuel. A big rocket engine can blast out tonnes of gas every second, at speeds of around 2 to 4.5 kilometres per second, many times faster than a jet airliner flies. All that gas rushing backwards gives the rocket a giant push forwards. That push is called thrust."]},{"heading":"Rockets Don't Need Air to Push On","paragraphs":["Now for one of the most famous mistakes in the history of science. In 1920, the New York Times printed an article that made fun of the rocket scientist Robert Goddard. The writer claimed that a rocket could never work in the emptiness of space, because there would be nothing for it to push against. As you read in Part 5, the newspaper finally printed a correction in July 1969, while Apollo 11 was on its way to the Moon.","Why was the newspaper wrong? Think about the skateboarder again. Did the skateboarder roll backwards because the ball pushed on the air? No. The skateboarder rolled backwards because of the push between the hand and the ball. The air had nothing to do with it. You could do the same trick on a frictionless floor inside a giant vacuum chamber and it would still work.","A rocket is the same. It does not push on the air outside; it pushes on its own exhaust. Inside the engine's combustion chamber, burning propellant makes extremely hot, high-pressure gas. That gas presses outwards in every direction, on the sides of the chamber, on the top, everywhere. But at the bottom there is an opening, the nozzle, where the gas can escape. Because the gas presses on the top of the chamber but has a hole to escape at the bottom, the pushes do not balance, and the rocket is shoved upwards. The gas rushing out the back is the 'thrown ball'.","In fact, rockets work better in space than in the air. Down near the ground, the atmosphere presses against the exhaust as it leaves the nozzle, getting in the way a little, like trying to blow a powerful puff of air into a strong headwind. In the vacuum of space there is no air pressing back, so the exhaust escapes more freely and the engine gives more thrust. The F-1 engines of the Saturn V, for example, produced about 15 percent more thrust in a vacuum than at sea level. Engineers even build engines with extra-long nozzles that are designed only for use high up or in space, where they work best.","So the next time someone tells you that rockets push off the air, you can explain kindly that it is the other way around. Air is not a help to rockets; it is a nuisance. It slows them down with drag and squashes their exhaust. The perfect place for a rocket is the empty sky above the sky."]},{"heading":"Bring Your Own Oxygen","paragraphs":["To make hot gas, a rocket burns fuel. But burning needs more than fuel. Think of a campfire: you need wood (the fuel), heat to get it started, and oxygen from the air. Put a glass jar over a candle and the flame soon goes out, because it has used up the oxygen inside. Fire needs oxygen, or something that does oxygen's job.","On Earth, oxygen is everywhere, making up about 21 percent of the air we breathe. Cars, aeroplanes and campfires simply take what they need from the air around them. But in space there is no air at all, and so there is no oxygen. A rocket that relied on the air to burn its fuel would go out like a candle under a jar as soon as it climbed above the atmosphere.","The solution is to take your own. A rocket carries both a fuel and an oxidizer, a chemical that supplies the oxygen (or does the same job) so that the fuel can burn anywhere, even in the empty vacuum of space. Together, the fuel and the oxidizer are called the propellant. Many big rockets use liquid oxygen, which is oxygen gas cooled down to about minus 183 degrees Celsius until it becomes a pale blue liquid. That is why rockets on the launch pad are often covered in frost and puffing white clouds: their tanks are full of oxygen colder than anything in a home freezer.","The oxidizer is often heavier than the fuel. In an engine that burns kerosene (a fuel similar to jet fuel) with liquid oxygen, roughly 2.5 kilograms of oxygen are used for every kilogram of kerosene. In an engine that burns liquid hydrogen with liquid oxygen, it is about 6 kilograms of oxygen for every kilogram of hydrogen. So most of the weight in a rocket's tanks is not fuel at all, but oxygen. Solid rockets carry their oxidizer too, mixed into the solid fuel. The gunpowder in the very first Chinese rockets contained saltpeter, which supplied oxygen in exactly this way.","This is the big difference between a rocket and a jet engine. A jet engine on an airliner sucks in huge amounts of air at the front, squeezes it, mixes it with fuel, burns it, and blasts it out of the back. It throws air backwards to push itself forward, so it also uses Newton's third law. But it needs the air, both for oxygen and as the stuff it throws. That makes jets very efficient for flying through the atmosphere, because they do not need to carry heavy oxidizer, but it also means they cannot fly into space. As you go higher, the air gets thinner and thinner, until a jet engine simply cannot breathe. Even the highest-flying jet planes, such as the American SR-71 Blackbird spy plane, cruised at only about 25 kilometres up, and brief record-breaking 'zoom climbs' went only a little higher. A rocket carries everything it needs inside itself, so it can keep going all the way to space and beyond."]},{"heading":"The Great Tug-of-War: Thrust Against Weight","paragraphs":["Picture a rocket standing on the launch pad. Two forces are fighting over it. Gravity pulls it down; that pull is the rocket's weight. When the engines light, thrust pushes it up. It is like a tug-of-war, and the rocket only lifts off when thrust wins, when the upward push is bigger than the downward pull of its weight.","Scientists measure forces in units called newtons, named after you-know-who. On Earth, every kilogram of mass weighs about 9.8 newtons. So a 1-kilogram bag of sugar presses down with a force of about 10 newtons, and a 30-kilogram child weighs about 300 newtons. To lift off, a rocket must push down on its exhaust with more newtons of thrust than its own weight.","Let's try it with the most famous rocket of all, the Saturn V that carried astronauts to the Moon. Fully fuelled, it had a mass of about 2,900 tonnes, which means a weight of roughly 28 million newtons. Its five first-stage F-1 engines together produced about 34 million newtons of thrust at liftoff. Thrust beat weight, but not by a huge margin: thrust was only about 1.2 times the weight. The difference, about 6 million newtons, was all that was left to actually speed the rocket up.","That is why giant rockets seem to rise so slowly at first, almost lazily, as if they are being gently lifted by a crane. The Saturn V took about 12 seconds just to climb past its own launch tower, even though its engines were roaring with enough power to shake the ground kilometres away. If thrust had been less than weight, the rocket would simply have sat there burning fuel and going nowhere, and if they were exactly equal, it would have hovered.","But here is a wonderful thing: the rocket gets lighter every second. Those five F-1 engines together gulped about 13 tonnes of propellant every second. As the tanks drain, the weight drops, while the thrust stays the same or even grows as the air thins. So the rocket speeds up faster and faster. By the time a rocket's first stage burns out, the astronauts are being pressed into their seats with a force of about four times their normal weight. A 70-kilogram astronaut feels as if they weigh 280 kilograms!","This is also why rocket engineers are obsessed with saving weight. Every extra kilogram of metal, wiring or cargo needs extra propellant to lift it, and that propellant has weight too, which needs even more propellant. It is a bit like a snowball rolling downhill. Engineers fight this problem with clever tricks, such as dropping empty parts of the rocket on the way up, which you will explore in Part 14."]},{"heading":"Orbit: Falling Sideways Forever","paragraphs":["Here is a riddle. If you throw a ball as hard as you can, it lands on the ground. If a rocket goes up 400 kilometres and stops, it falls straight back down too. So how does a satellite stay up for years without engines? The answer is amazing: it doesn't stay up. It is falling all the time. It just keeps missing the Earth.","Isaac Newton explained this with a famous thought experiment, an experiment you do in your imagination. Picture a cannon on top of an impossibly tall mountain, poking up above the air so nothing slows the cannonball down. Fire the cannonball sideways, gently, and it curves down and lands near the foot of the mountain. Fire it faster, and it flies further before it lands. Faster still, and it lands on the other side of the world.","Now fire it so fast that, as it falls, the curved surface of the Earth drops away beneath it at the same rate. The cannonball is still falling, pulled down by gravity every moment, but it never gets any closer to the ground. It falls all the way around the planet and comes back to the mountain from behind. (Duck!) That is an orbit. An orbit is simply falling around a planet while going sideways fast enough to keep missing it.","How fast is fast enough? There's a neat coincidence that gives the answer. Any falling object drops about 5 metres in its first second of falling. And because the Earth is round, its surface curves downward by about 5 metres over a distance of about 8 kilometres. So if you could travel sideways at about 8 kilometres every second, then in each second you would fall about 5 metres, but the ground would also have curved away by about 5 metres. You would stay at the same height, falling forever.","The precise number for a low orbit, a few hundred kilometres up, is about 7.8 kilometres per second. That is around 28,000 kilometres per hour, about 23 times the speed of sound at sea level and about eight times faster than a speeding rifle bullet. At that speed you could cross the Atlantic Ocean in about 12 minutes. The International Space Station, at about 400 kilometres up, goes all the way around the Earth in about an hour and a half, so the astronauts on board see roughly 16 sunrises and 16 sunsets every day.","This shows something that surprises many people: the hard part of getting into orbit is not going up, it's going sideways. Reaching a height of 100 kilometres takes only a fraction of the energy needed for orbit. That's why rockets climb straight up only for the first part of their flight, to get out of the thickest air, and then gradually tip over until they are flying almost level with the ground, building up that enormous sideways speed. Without it, anything that climbs into space falls straight back down. Such up-and-down hops are called suborbital flights.","The orbit also has to be high enough. Even at 200 kilometres, there are still a few traces of air, which gently drag on a satellite, slowing it down until it spirals back into the atmosphere, just as happened to Sputnik. Higher up, there is less drag, and orbits last longer. Further out, gravity is also weaker, so satellites need less speed to stay in orbit and they take longer to go around. Weather and TV satellites about 36,000 kilometres up take exactly one day per orbit, so they seem to hover above the same spot on Earth. The Moon, our natural satellite, about 384,000 kilometres away, is falling around us too, at only about 1 kilometre per second, taking about 27 days per lap.","What if you go even faster? Push past about 11.2 kilometres per second near the Earth's surface, about 40,000 kilometres per hour, and you have reached escape velocity. At that speed (ignoring air resistance), you are going so fast that Earth's gravity can never pull you all the way back. Your path stretches out and never closes, and you sail away from the Earth. Probes heading to Mars, Jupiter and beyond have to reach roughly this speed."]},{"heading":"Where Does Space Begin?","paragraphs":["If you drive straight up a mountain road, the air gets thinner. If you could keep driving straight up into the sky, at what point would you say, 'Now I'm in space'? Surprisingly, there's no sharp edge. The atmosphere doesn't end like the surface of a swimming pool. It just fades away, getting thinner and thinner the higher you go.","Here are some heights to give you an idea. About half of all the air in the atmosphere lies below about 5.5 kilometres. The top of Mount Everest is about 8.8 kilometres up, where climbers usually need bottled oxygen. Airliners cruise at about 10 to 12 kilometres. Weather balloons drift up to around 30 to 40 kilometres. By 100 kilometres up, the air is so thin that it is less than a millionth as dense as at sea level, and the sky above looks black even in daytime.","The most common boundary used is the Kármán line, 100 kilometres above sea level. It is named after Theodore von Kármán, a Hungarian-born American engineer who helped start the Jet Propulsion Laboratory. He worked out that at around this height, the air becomes so thin that a plane would have to fly as fast as orbital speed just to get enough lift from its wings, so wings stop being useful and you might as well be a spacecraft. His calculations actually gave a height somewhat lower than 100 kilometres; 100 was chosen partly because it is a nice round number. The world air sports federation (FAI), which keeps records for flying, uses 100 kilometres.","However, not everyone agrees. The US Air Force and NASA have used a lower boundary of 50 miles, about 80 kilometres, and have awarded astronaut wings to pilots who flew above it. In 2018 the astronomer and spaceflight historian Jonathan McDowell published a study arguing that around 80 kilometres actually makes more scientific sense, because satellites in elliptical orbits can briefly dip that low and survive. This debate matters to real people: some tourist spacecraft fly a little above 80 kilometres but below 100, so whether their passengers 'went to space' depends on which line you pick.","There is no official international law that says exactly where a country's airspace ends and outer space begins. And there is no physical wall in the sky. Even the International Space Station, at about 400 kilometres up, flies through a very faint wisp of atmosphere that slowly drags it down, so it needs a push from rocket engines every now and then to stay in orbit. Space doesn't begin at a line; it creeps up on you."]},{"heading":"Floating Is Falling","paragraphs":["You have surely seen videos of astronauts floating around the International Space Station, doing somersaults in mid-air and chasing blobs of water that wobble like jelly. Many people say they are in 'zero gravity'. But that is not true. At the Space Station's height, about 400 kilometres up, Earth's gravity is still about 90 percent as strong as it is on the ground. If you could build a tower 400 kilometres tall and stand on top of it, you would feel nearly as heavy as you do now.","So why do astronauts float? Because they are falling. Remember Newton's cannonball: the Space Station is in orbit, falling around the Earth all the time. The astronauts inside are falling too, at exactly the same rate, along with their food, their pens and their toothbrushes. Since everything is falling together, nothing presses on anything else. The floor doesn't push up on their feet, so they feel weightless. Scientists call this state free fall.","You can get a tiny taste of it on Earth. Have you ever been in a lift (an elevator) that suddenly starts going down fast, and felt your stomach float for a moment? Or ridden a roller coaster over the top of a hill and felt yourself lift out of your seat? Or jumped off a diving board? For that short moment, you were in free fall, and you felt lighter. If you were standing on bathroom scales in a falling lift, the scales would fall with you and read zero, even though gravity hadn't gone anywhere.","NASA uses this trick to train astronauts. A specially equipped aeroplane flies up in a steep climb and then over the top in a curved arc, like a ball thrown through the air. For around 20 to 25 seconds on each arc, everyone inside floats. Because the ride can make people feel sick, this plane earned the nickname the 'Vomit Comet'. An astronaut in orbit is simply on a 'Vomit Comet' ride that never ends, because the Earth's surface keeps curving away.","Scientists often use the word microgravity for life in orbit, because tiny forces remain, such as the gentle drag of thin air on the station and the little pushes when astronauts move around. Living in free fall has surprising effects. Without weight pressing down, fluids in the body shift up towards the head, giving astronauts puffy faces and 'bird legs'. Candle flames burn as round, blue balls, because hot air no longer rises. And bones and muscles start to weaken because they don't have to hold the body up, which is why astronauts must exercise every day, as you'll discover in Part 16.","So now you know the two big secrets of spaceflight. First, a rocket flies by pushing its own exhaust backwards, and it works even better in empty space. Second, getting to orbit means going sideways so fast that you fall around the world forever. Knowing the science is one thing. But in the early 1960s, nobody knew whether a human body could survive being blasted off on top of a burning rocket, falling around the Earth, and plunging home again. Strapping a person on top of a rocket was the next giant gamble."]}],"deepDive":"Newton's third law becomes a precise tool once you add momentum. A rocket's thrust is roughly the mass of exhaust leaving each second multiplied by the exhaust's speed, plus a pressure term: the difference between the gas pressure at the nozzle exit and the surrounding air pressure, multiplied by the exit area. At sea level that pressure term is reduced or even negative, which is exactly why engines produce more thrust in a vacuum. Engineers compare engines with 'specific impulse', which is essentially effective exhaust speed: kerosene–oxygen engines reach roughly 3 km/s in vacuum, hydrogen–oxygen engines about 4.4 km/s.\n\nOrbital speed comes from setting gravity's pull equal to the force needed to keep something moving in a circle. For a circular orbit, v = √(GM/r), where GM for Earth is about 398,600 km³/s² and r is the distance from Earth's centre. At the ISS (r ≈ 6,770 km) this gives about 7.67 km/s and a period of about 92 minutes. Escape velocity is √2 times the circular speed at the same distance, which gives about 11.2 km/s at Earth's surface. Gravity at the ISS's height is (6,371/6,771)² ≈ 0.89 of surface gravity — hence 'about 90 percent'.\n\nIn practice a rocket needs a total change in speed ('delta-v') of roughly 9.3–10 km/s to reach low orbit, not just 7.8 km/s. The extra goes to 'gravity losses' (fighting gravity while climbing, worst when thrust-to-weight is low), drag losses and steering losses. Launching eastward helps, because Earth's rotation already carries a launch site at the equator east at about 0.46 km/s; that is one reason spaceports such as Kourou in French Guiana sit close to the equator and why Florida's Cape Canaveral launches over the Atlantic to the east.\n\nThe edge-of-space debate is real science, not just record-keeping. The 100 km figure was popularised after von Kármán's work in the 1950s; von Kármán's own figure was about 84 km, and the writer Andrew Haley, who gave the 'Kármán line' its name, based it on that number. Jonathan McDowell's 2018 paper in Acta Astronautica showed that satellites on elliptical orbits can pass below 100 km and survive for several orbits, and suggested that a boundary near 80 km fits the physics better. Legally, the Outer Space Treaty (1967) never defines where space begins.","funFact":"At the International Space Station's height, Earth's gravity is still about 90 percent as strong as on the ground — astronauts float only because they and the station are falling around the Earth together.","check":{"q":"Why do astronauts on the International Space Station float?","a":"Because they and the station are in free fall together around the Earth; gravity is still there","wrong":["Because there is no gravity in space","Because the station is above the air, and air is what causes weight","Because the station's engines push them up"]},"sources":[{"title":"Newton's Cannon","publisher":"Smithsonian National Air and Space Museum (How Things Fly)","url":"https://howthingsfly.si.edu/media/newtons-cannon"},{"title":"Basics of Space Flight: Gravity and Mechanics (Chapter 3)","publisher":"NASA Science","url":"https://science.nasa.gov/learn/basics-of-space-flight/chapter3-4"},{"title":"Practical Rocketry","publisher":"NASA Glenn Research Center","url":"https://www.grc.nasa.gov/www/K-12/rocket/TRCRocket/practical_rocketry.html"},{"title":"Newton's Laws of Motion","publisher":"NASA Glenn Research Center (Beginner's Guide to Aeronautics)","url":"https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/newtons-laws-of-motion/"},{"title":"The Kármán Line: Where does space begin?","publisher":"Astronomy magazine","url":"https://www.astronomy.com/space-exploration/the-karman-line-where-does-space-begin/"},{"title":"Kármán line","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/K%C3%A1rm%C3%A1n_line"},{"title":"Reduced-gravity aircraft","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Reduced-gravity_aircraft"}],"photos":[{"src":"img/deep/rockets/10-1.jpg","alt":"Newton's cannonball drawing: shots from mountain top V land farther away the faster they go, until one circles the Earth.","file":"Newton's cannonball cropped.png","url":"https://commons.wikimedia.org/wiki/File:Newton%27s_cannonball_cropped.png","author":"Isaac Newton","license":"Public domain"},{"src":"img/deep/rockets/10-2.jpg","alt":"Astronaut Cady Coleman and her flutes float in free fall inside the Space Station's cupola in 2011.","file":"Catherine Coleman with flutes floating in space.jpg","url":"https://commons.wikimedia.org/wiki/File:Catherine_Coleman_with_flutes_floating_in_space.jpg","author":"NASA","license":"Public domain"},{"src":"img/deep/rockets/10-3.jpg","alt":"Seen from the Space Station, Earth's thin blue air fades into black space, with the Moon behind it.","file":"Top of Atmosphere.jpg","url":"https://commons.wikimedia.org/wiki/File:Top_of_Atmosphere.jpg","author":"NASA Earth Observatory","license":"Public domain"}],"words":3978},{"n":11,"title":"First Humans in Space","when":"1959 – 1965","summary":"First, two brave dogs and a chimpanzee showed that living things could ride a rocket and come home. Then, in 1961, a young pilot called Yuri Gagarin shouted 'Let's go!' and became the first person ever to fly around the Earth. Soon after came the first American astronauts, the first woman in space, and a cosmonaut who floated outside his spaceship on a rope.","sections":[{"heading":"Test Pilots with Fur","paragraphs":["By 1960 rockets could reach orbit, but nobody knew for sure what would happen to a living body up there. Could a person swallow without gravity pulling food down? Would the heart beat normally? Would the brain get confused and the person faint? Doctors on both sides of the Cold War had worried guesses but no answers. So before any human climbed aboard, animals went first.","Remember Laika from the last chapters: she reached orbit in 1957, but her spacecraft was never built to come back. The next big step was to send animals into orbit AND bring them home safely. The Soviet Union tried this with a new spaceship called Vostok, the very same design that would later carry a human. The first attempt, in July 1960, ended badly when the rocket failed shortly after launch and the two dogs on board were killed. The engineers fixed the problem and tried again.","On 19 August 1960 a rocket lifted off from the Baikonur launch site in Kazakhstan carrying two small, light-coloured dogs named Belka ('Whitey') and Strelka ('Little Arrow'). They were not alone. The capsule was a tiny zoo: dozens of mice, two rats, insects and even plants rode along so scientists could study how different kinds of life coped with spaceflight. A television camera pointed at the dogs, so the controllers could actually watch them float in their harnesses.","The film showed something worrying. During the fourth trip around the Earth, one dog became sick and seemed very uncomfortable. That small detail mattered enormously: it was one reason Soviet planners decided to keep the first human flight short, in case people also felt ill. About 25 hours after launch, on 20 August 1960, the capsule came back through the atmosphere and the dogs landed safely. Belka and Strelka were the first animals to go into orbit and return alive. They became celebrities, appearing on stamps, postcards and toys. Later Strelka had puppies, and one of them, named Pushinka ('Fluffy'), was sent as a friendly gift from the Soviet leader to the family of the American president, John F. Kennedy, in the middle of the Cold War.","The Americans used a different animal. Because chimpanzees are our close relatives, US scientists believed they would be a good stand-in for a human pilot. A young chimp named Ham had been trained for months to pull levers when a light flashed; if he did it right, he got a banana pellet. On 31 January 1961 Ham rode a Mercury capsule on top of a Redstone rocket from Cape Canaveral in Florida. This was not an orbital flight but a suborbital one: a giant arc up into space and back down into the ocean, like a ball thrown extremely high.","Ham's flight was rough. The rocket flew faster and farther than planned, and his capsule came down about 210 km (130 miles) beyond the target point. The cabin also lost air pressure, but Ham was sealed inside his own pressurized couch and was fine. Most importantly, he kept pulling his levers correctly while weightless, showing that a pilot could think and work in space. After about 16 and a half minutes he splashed into the Atlantic, and a helicopter picked him up. Ham later lived at the National Zoo in Washington, D.C., and at a zoo in North Carolina, and died in 1983 at about 25 years old."]},{"heading":"The Boy from Klushino","paragraphs":["Yuri Alekseyevich Gagarin was born on 9 March 1934 in the village of Klushino, west of Moscow. His father was a carpenter and his mother worked on the village's collective farm. When Yuri was seven, the Second World War reached his village and it was occupied by the German army. His family was pushed out of their house and lived for a time in a dugout, a hole in the ground with a roof. It was a hard, frightened childhood, and when the war ended he went back to school hungry for a better life.","As a teenager Gagarin trained as a foundry worker, learning to pour hot metal into moulds, and then studied at a technical college in the city of Saratov on the Volga River. There he joined a local flying club and discovered that he loved being in the air. The air force noticed him. He trained as a military pilot, graduated in 1957 (the year of Sputnik) and flew jet fighters in the far north of Russia, near the Arctic Circle, where winter nights last for weeks.","In 1959 Soviet doctors secretly began searching the air force for possible 'cosmonauts', a Russian word meaning 'sailors of the universe'. They wanted young, healthy pilots who were calm under stress, and they also wanted SMALL ones, because the Vostok cabin was cramped. Gagarin was only about 1.57 m (5 ft 2 in) tall. In 1960 he became one of 20 men chosen for training. They spun in centrifuges (machines that whirl you around to imitate the heavy push of launch), sat for days in silent, sealed rooms, jumped with parachutes and studied the spacecraft.","Gagarin was quick, cheerful and friendly, with a famous wide smile. Sergei Korolev, the secret Chief Designer you met in earlier chapters, liked him a great deal. In the end two men were the leading candidates: Gagarin and Gherman Titov. A few days before launch, Gagarin was picked for the first flight, with Titov as his backup, ready to take his place if he fell ill.","The Vostok spacecraft he would ride was simple but clever. The crew part was a metal ball about 2.3 m wide, covered in a heat shield on all sides. Because it was a ball, it did not need to point in a particular direction when it came back through the air; its heavy bottom made it swing into the right position, like a weighted toy that always stands back up. Below the ball was an equipment section with the retrorocket (a braking rocket) and supplies. Inside, the cosmonaut sat on an ejection seat, a seat with its own small rockets that could shoot him out of the craft. The whole flight was designed to be controlled automatically from the ground, because no one knew whether a human could think clearly in weightlessness. Gagarin could take over by hand in an emergency, but the controls were locked with a secret code inside a sealed envelope."]},{"heading":"Poyekhali! 108 Minutes Around the World","paragraphs":["Early on the morning of 12 April 1961, Gagarin and Titov were woken, given breakfast and helped into their orange pressure suits. A bus drove them to the launch pad, where the tall R-7 rocket stood steaming in the cold spring air, its tanks full of kerosene and super-cold liquid oxygen. Gagarin rode a lift to the top, climbed into the Vostok ball and was strapped in. Korolev, who had hardly slept with worry, talked to him over the radio.","At 9:07 in the morning, Moscow time (06:07 UTC), the engines roared. As the rocket rose, Gagarin called out a cheerful word that became famous around the world: 'Poyekhali!', which means 'Let's go!' or 'Off we go!' Within minutes the strap-on boosters fell away, the core stage burned out, and the upper stage pushed him the rest of the way into orbit. He was now travelling at about 27,400 km/h, falling around the Earth just as Newton's cannonball does in the thought experiment from Part 10.","Gagarin became the first human to see the Earth from space. He reported the bright blue band of the atmosphere at the edge of the planet, the shadows of clouds and the dark sky. He ate and drank a little to show it was possible, tried writing notes in his logbook, and kept describing everything into his radio. He felt fine. Weightlessness, which doctors had feared, turned out to be strange but bearable.","His single lap around the planet took him across Siberia, the Pacific Ocean, the tip of South America and the South Atlantic. Over Africa the retrorocket fired to slow him down so he would fall back into the air. Then something went wrong. The equipment section was supposed to separate cleanly from the ball, but a bundle of cables kept the two pieces joined, and the spacecraft began to tumble. For several minutes Gagarin was spun around as he plunged into the atmosphere, until the heat burned through the cables and the ball broke free. He stayed calm and reported that things were all right.","Now came the part that was kept secret for years. Vostok's ball was too heavy to land gently on a parachute with a person inside; it would hit the ground very hard. So the plan had always been for the cosmonaut to leave it. At about 7 km above the ground the hatch blew off and Gagarin was shot out on his ejection seat. He then separated from the seat and floated down under his own parachute, while the empty capsule came down separately on its own parachute nearby.","He landed in a field near the city of Engels, in the Saratov region, not far from where he had learned to fly. A farm woman and her granddaughter saw a man in a bright orange suit and a white helmet walking towards them, and they were frightened. Gagarin reportedly called out that he was a friend, a Soviet citizen, and that he needed a telephone to call Moscow. From launch to landing the flight lasted about 108 minutes (later studies suggest the true figure may have been a minute or two less).","Why the secret? At the time, the rules of the Fédération Aéronautique Internationale (FAI), the organization that certifies flying records, said a pilot had to land inside his aircraft for a record to count. Soviet officials worried that the flight would not be accepted, and they also wanted the Vostok to look perfect. So for years they told the world Gagarin had landed in his capsule. Some early Soviet descriptions accidentally hinted at the truth, but the government did not officially admit the ejection until 1971. The FAI accepted the record anyway and later changed its rules, because the important thing was that a human had launched, orbited and returned safely."]},{"heading":"A Hero Overnight","paragraphs":["Gagarin left Moscow that morning as a senior lieutenant whom almost nobody had heard of. While he was still in orbit, he was promoted to major, and Soviet radio announced the flight to the world. Within hours his name and smiling face were on front pages from Tokyo to Buenos Aires. Two days later a huge crowd filled Red Square in Moscow to welcome him. In the following years he toured dozens of countries.","Gagarin himself never flew in space again. The Soviet leaders thought he was too precious a national hero to risk. He trained other cosmonauts, studied engineering and kept trying to get back onto the flight list. On 27 March 1968, he and an instructor, Vladimir Seryogin, were killed when their MiG-15 training jet crashed during a routine flight. He was only 34. Investigations have offered several possible causes, and historians still discuss them, but no single explanation has been fully proven."]},{"heading":"America's Mercury Seven and Shepard's Hop","paragraphs":["The United States had started its own human spaceflight programme, called Project Mercury, in 1958. Mercury was the messenger of the gods in Roman myths, a speedy name for a speedy craft. On 9 April 1959 NASA introduced its first astronauts to the public at a crowded press conference in Washington. There were seven, all military test pilots: Scott Carpenter, Gordon Cooper, John Glenn, Gus Grissom, Wally Schirra, Alan Shepard and Deke Slayton. They became known as the Mercury Seven, and almost overnight they were as famous as film stars.","On 5 May 1961, just over three weeks after Gagarin, Alan Shepard lay on his back in a capsule he had named Freedom 7, perched on a Redstone rocket at Cape Canaveral. The launch had already been postponed by bad weather, and that morning the countdown kept stopping for small problems. Shepard waited in the capsule for hours. Getting impatient, he is reported to have told the controllers to fix their little problem and 'light this candle'.","When the Redstone finally fired, it pushed him upwards with a force of about six times his normal weight. The flight was suborbital: he rose to about 187 km, well above the 100 km line many people use as the edge of space, and then curved back down. During about five minutes of weightlessness he became the first person to steer a spacecraft by hand, using a control stick to turn the capsule, and he looked out through a small periscope at the coast of Florida. On the way down the force pressing him into his couch reached about 11 times his weight for a few seconds.","Just over 15 minutes after launch, Freedom 7 splashed into the Atlantic about 487 km from the launch pad. A helicopter lifted Shepard and his capsule to the aircraft carrier USS Lake Champlain. His flight was much shorter than Gagarin's, and he never went into orbit, but millions of Americans had watched it live on television, and he became the first American in space. Ten years later, in 1971, Shepard would walk on the Moon with Apollo 14.","A second suborbital flight followed on 21 July 1961, when Gus Grissom flew Liberty Bell 7. After splashdown the hatch blew open too early, water poured in, and Grissom had to swim for his life while the capsule sank. He was rescued, but the capsule lay on the bottom of the Atlantic until it was found and raised in 1999."]},{"heading":"Glenn, Friendship 7 and the Woman Who Checked the Numbers","paragraphs":["A suborbital hop was not enough. To match Gagarin, an American needed to go all the way around the world, and the Redstone was not powerful enough. NASA switched to the much larger Atlas rocket, which was originally built as an intercontinental missile. The astronaut chosen was John Glenn, a Marine Corps pilot from Ohio who had flown in two wars and set a speed record by flying across the United States in under three and a half hours.","Before Glenn's flight, NASA had begun using electronic computers, such as the IBM 7090, to work out the path, or trajectory, of the capsule: exactly when to fire the retrorockets and where it would come down in the ocean. Computers were new, room-sized and sometimes made mistakes, and many people did not yet trust them. Glenn asked for the computer's numbers to be checked by a human expert. According to Katherine Johnson's own memory of it, he said to 'get the girl to check the numbers', and that if she said the numbers were good, he was ready to go.","'The girl' was Katherine Johnson, then about 43 and one of the best mathematicians at NASA's Langley Research Center in Hampton, Virginia. Born in 1918 in White Sulphur Springs, West Virginia, she had been so quick at maths that she started high school at about ten. In 1953 she joined a group of Black women mathematicians at Langley known as 'computers', a job title in the days when a computer was a person who computed. At that time the American South was segregated: Black and white workers were kept apart in offices, cafeterias and even bathrooms. Johnson still earned the trust of the engineers by asking sharp questions and being right. She had already calculated the trajectory for Shepard's flight in 1961.","To check Glenn's orbit, Johnson worked through the same long equations by hand, using a desk calculating machine and pages of figures. The writer Margot Lee Shetterly, whose book 'Hidden Figures' made Johnson famous, says the work took about a day and a half. Her answers matched the computer's. Johnson later worked on the paths for the Apollo missions to the Moon, and in 2015 President Barack Obama gave her the Presidential Medal of Freedom, the highest award for an American civilian. She died in 2020 at the age of 101.","After many delays for weather and equipment, Glenn launched in his capsule Friendship 7 on 20 February 1962. As the Atlas ignited, fellow astronaut Scott Carpenter said over the radio, 'Godspeed, John Glenn.' Glenn circled the Earth three times. He saw four sunsets and sunrises in less than five hours and reported a mystery: glowing specks floating around his capsule like fireflies. Later astronauts worked out that they were bits of frost flaking off the spacecraft and lit by the Sun.","Then came a scare. A signal on the ground suggested that Friendship 7's heat shield might have come loose. If it had, Glenn would burn up on re-entry. Mission controllers told him to keep the retrorocket pack, which was strapped over the heat shield, instead of throwing it away as planned, hoping its straps would hold the shield in place. As he dropped into the atmosphere, Glenn saw chunks of the burning pack fly past his window. It was frightening, but he came through safely. The signal turned out to be a faulty sensor; the shield had been fine all along.","Glenn splashed down in the Atlantic 4 hours, 55 minutes and 23 seconds after launch. He was the first American to orbit the Earth, and he was given a huge ticker-tape parade in New York City. He later became a United States senator, and in 1998, at the age of 77, he flew into space again on the Space Shuttle. His capsule, Friendship 7, is now on display at the Smithsonian's National Air and Space Museum in Washington, D.C."]},{"heading":"The Seagull: Valentina Tereshkova","paragraphs":["In 1962 the Soviet Union quietly began training a group of women as cosmonauts. They were not chosen from pilots, because there were few women military pilots at the time. Instead the selectors looked for experienced parachutists, since a Vostok pilot had to eject and land by parachute. Five women were picked from hundreds of applicants.","One of them was Valentina Tereshkova, born on 6 March 1937 in a small village near the city of Yaroslavl, north-east of Moscow. Her father, a tractor driver, was killed in war when she was a toddler. She left school at about 16 to work, first in a tyre factory and then in a textile mill, weaving cloth, while studying in the evenings. In her spare time she joined a local flying club and made many parachute jumps. That hobby changed her life.","On 16 June 1963 Tereshkova launched aboard Vostok 6 and became the first woman in space. She was 26. Her radio call sign was 'Chaika', which means 'Seagull', and her words 'Ya Chaika' ('I am Seagull') became famous. Another cosmonaut, Valery Bykovsky, was already in orbit in Vostok 5, and the two spacecraft flew at the same time, with the pilots talking to each other by radio.","Tereshkova's flight was not a quick hop. She spent nearly three days in space, 2 days and almost 23 hours, and went around the Earth 48 times. That was more time in space than all the American Mercury astronauts had spent added together up to then. She took photographs of the horizon, which scientists used to study the layers of the atmosphere, and kept a logbook. She later said the flight was tiring and uncomfortable at times, which is not surprising: she was strapped into a cabin the size of a small cupboard for three days.","On 19 June, like every Vostok pilot, she ejected and landed by parachute. Tereshkova was made a Hero of the Soviet Union and became a famous public figure, an engineer and later a politician. She never flew in space again, and no other woman went into space for 19 years, until the Soviet cosmonaut Svetlana Savitskaya in 1982. Tereshkova is still the only woman ever to have flown a space mission completely alone."]},{"heading":"Leonov Steps Outside","paragraphs":["By 1965 people had spent days in space, but always sealed inside a capsule. To build stations or land on the Moon, someone would one day have to go outside and work. The Soviets wanted to try it first. Their spaceship, Voskhod 2, was an adapted Vostok with a clever addition: an inflatable tube called an airlock, named Volga, attached to the side. An airlock is a small room with two doors, so a person can leave a spacecraft without letting all the air out of the cabin. Once in orbit, the tube would blow up like a long balloon. The cosmonaut would climb in, close the inner door, let the air out of the tube, open the outer door and float into space.","The crew were commander Pavel Belyayev and Alexei Leonov, born in 1934 in a village in Siberia. Leonov was a fighter pilot and also a talented artist who loved to draw and paint. They launched on 18 March 1965. On their first orbit Leonov wriggled into the airlock and, at the end of a tether about 5 m long, pushed himself out of the hatch. He was the first human to float freely in space. Below him, he later said, he could see the Black Sea and the curve of the Earth. A camera filmed him tumbling slowly at the end of his line, high above the clouds.","Then came a dangerous problem. In the vacuum, Leonov's spacesuit swelled up like an overfilled balloon. The air pressure inside it pushed outward with nothing outside to push back, so the suit grew stiff and his hands and feet pulled back inside the gloves and boots. He could not reach the camera switch on his thigh, and, much worse, he could not fit back through the narrow airlock opening.","Leonov thought fast. Without asking ground control, he opened a valve and let some of the air out of his suit, lowering the pressure to below the safe limit. This was risky, because a sudden drop in pressure can cause the bends, a painful sickness divers can get. But it worked: the suit softened, and he pulled himself into the airlock head first instead of feet first as planned. Then he had to turn himself around inside the tight tube to close the hatch. By the time he got back into the cabin he was soaked in sweat and his heart was racing. He had been outside the spacecraft for about 12 minutes.","Voskhod 2's troubles were not over. The automatic landing system failed, so the crew had to steer and fire the retrorocket by hand, later than planned. They came down hundreds of kilometres off course, in a deep, snowy forest in the Ural Mountains near the city of Perm. Rescuers could see the capsule from a helicopter but could not land among the trees. The two cosmonauts spent a freezing night in the forest. Rescuers on skis reached them the next day, and after a second night in a log cabin, everyone skied out to a waiting helicopter.","Leonov's spacewalk was a world first, and it showed that people could leave their spacecraft, but it also showed how hard working outside would be. Less than three months later, in June 1965, the American astronaut Ed White made the first US spacewalk, and both countries kept learning how to design better suits. Leonov later flew again in 1975, and his paintings and drawings of space, including sketches he made in orbit, are among the first artworks made by someone who had actually been there.","Even so, the Soviet Union seemed to keep winning every first: first satellite, first man, first woman, first spacewalk. American leaders decided they needed a goal so huge that both countries would have to start almost from scratch. Just six weeks after Gagarin's flight, and only 20 days after Alan Shepard's 15-minute hop, President John F. Kennedy stood before the United States Congress on 25 May 1961 and made an astonishing promise. The country, he said, should commit itself to landing a man on the Moon and returning him safely to the Earth before the decade was out. At that moment, the total American experience of human spaceflight was about 15 minutes."]}],"deepDive":"Who really 'won' the early human spaceflight race depends on what you count, and historians still debate it. On paper the Soviet Union took nearly every early first, largely because Korolev's R-7 was far more powerful than any American rocket of the time. It could lift a Vostok of about 4.7 tonnes into orbit, while the Mercury capsule had to be kept well under 2 tonnes so the Atlas could carry it. Soviet secrecy also hid failures and shortcuts. Vostok had no backup retrorocket; instead, its orbit was chosen low enough that air drag would have brought it down within about ten days if the braking rocket failed, which is why it carried food and water for even longer than that. The cosmonauts ejected because the capsule's landing was too hard to survive inside, a fact hidden for a decade partly because of the FAI rule that a pilot had to land with his craft. Gagarin's flight time is itself a small puzzle: the official figure is 108 minutes, but later analyses of the timeline suggest about 106. Mercury took a different path. Its capsule was designed for a water landing with the pilot aboard, and its engineers added more manual control after the astronauts, all test pilots, insisted on being pilots and not passengers. Shepard's suborbital flight is sometimes dismissed, but it reached about 187 km, comfortably above the Kármán line, so it was a genuine spaceflight, just not an orbital one. Another debate concerns credit. For decades the women and Black mathematicians at Langley, such as Katherine Johnson, Dorothy Vaughan and Mary Jackson, were left out of the popular story; the 2016 book and film 'Hidden Figures' brought their work to wide attention, although the film simplified and moved some events for drama. Similarly, the Soviet female cosmonaut group was disbanded in 1969 without any of the others flying, and some historians argue Tereshkova's flight was partly a propaganda move rather than the start of real equality. Finally, the physical risks were real: Glenn's heat-shield alarm, Grissom's sinking capsule, Gagarin's tumbling re-entry and Leonov's ballooning suit all show how thin the margins were in these first years.","funFact":"Valentina Tereshkova's three-day flight in 1963 lasted longer than all six crewed Mercury flights put together.","check":{"q":"How did Yuri Gagarin get back to the ground at the end of his Vostok 1 flight?","a":"He ejected from the capsule and landed by his own parachute","wrong":["He stayed inside the capsule and splashed down in the ocean","A helicopter caught the capsule in mid-air","He glided the spacecraft down to a runway like a plane"]},"sources":[{"title":"April 1961: First Human Entered Space","publisher":"NASA","url":"https://www.nasa.gov/image-article/april-1961-first-human-entered-space/"},{"title":"Vostok 1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Vostok_1"},{"title":"Capsule, Mercury, Friendship 7, John Glenn","publisher":"Smithsonian National Air and Space Museum","url":"https://airandspace.si.edu/collection-objects/capsule-mercury-friendship-7-john-glenn/nasm_A19670176000"},{"title":"NASA mathematician Katherine Johnson, celebrated in 'Hidden Figures,' dies at age 101","publisher":"PBS NewsHour","url":"https://www.pbs.org/newshour/science/nasa-mathematician-katherine-johnson-celebrated-in-hidden-figures-dies-at-age-101"},{"title":"Mercury-Redstone 3","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mercury-Redstone_3"},{"title":"Vostok 6","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Vostok_6"},{"title":"Voskhod 2","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Voskhod_2"},{"title":"Korabl-Sputnik 2 (Sputnik 5)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Sputnik_5"}],"photos":[{"src":"img/deep/rockets/11-1.jpg","alt":"Yuri Gagarin, the first human in space, photographed in uniform during his visit to Finland in 1961.","file":"Yuri Gagarin (1961) - Restoration.jpg","url":"https://commons.wikimedia.org/wiki/File:Yuri_Gagarin_(1961)_-_Restoration.jpg","author":"Arto Jousi / /Suomen valokuvataiteen museo / Alma Media / Uuden Suomen…","license":"Public domain"},{"src":"img/deep/rockets/11-2.jpg","alt":"John Glenn's Mercury capsule Friendship 7, on display at the Smithsonian's National Air and Space Museum.","file":"Mercury, MA-6, Friendship 7 - Seitenansicht.jpg","url":"https://commons.wikimedia.org/wiki/File:Mercury,_MA-6,_Friendship_7_-_Seitenansicht.jpg","author":"Smithsonian Institut","license":"CC0"},{"src":"img/deep/rockets/11-3.jpg","alt":"Valentina Tereshkova, the first woman in space, in her Soviet Air Force uniform with her medals.","file":"RIAN archive 612748 Valentina Tereshkova.jpg","url":"https://commons.wikimedia.org/wiki/File:RIAN_archive_612748_Valentina_Tereshkova.jpg","author":"Alexander Mokletsov / Александр Моклецов","license":"CC BY-SA 3.0"}],"words":4361},{"n":12,"title":"Race to the Moon","when":"1961 – 1968","summary":"A president promised that Americans would walk on the Moon within ten years, even though nobody yet knew how. Robot probes crashed into the Moon, photographed its hidden side and landed on it, while astronauts practised meeting and joining spaceships in orbit. There were sad accidents too, but by Christmas 1968 three astronauts were circling the Moon and taking a famous photo of our blue Earth rising over it.","sections":[{"heading":"A Promise Nobody Knew How to Keep","paragraphs":["In the spring of 1961 the young American president, John F. Kennedy, was having a bad few weeks. On 12 April Yuri Gagarin had orbited the Earth. A few days later, an American-backed invasion of Cuba at the Bay of Pigs had failed badly. Kennedy asked his vice-president, Lyndon Johnson, to find out whether there was any space goal where the United States had a real chance of beating the Soviet Union. The experts' answer was surprising: probably not a space station, and probably not orbiting more people, because the Soviets' powerful R-7 rocket gave them a head start. But a landing on the Moon was so hard that both countries would need brand-new giant rockets. In that race, the Americans might win.","On 25 May 1961 Kennedy stood in front of the United States Congress and asked for a huge amount of money. 'I believe that this nation should commit itself to achieving the goal, before this decade is out, of landing a man on the Moon and returning him safely to the Earth,' he said. Remember that at that moment the only American who had been to space was Alan Shepard, for about 15 minutes. NASA did not have a rocket big enough, a spacecraft able to land on the Moon, a spacesuit for walking there, or even a plan for how to do it. Polls showed that many Americans thought it was a waste of money.","Kennedy made his case again on 12 September 1962, on a hot day in the football stadium of Rice University in Houston, Texas, near where NASA was building its new centre to control spaceflights. About 40,000 people listened. 'We choose to go to the Moon,' he said, and repeated it, explaining that the country would do it and other things 'not because they are easy, but because they are hard'. He described a rocket taller than a football field is long, built of metals not yet invented, that would have to survive heat about half that of the surface of the Sun on its way home. He even made a joke about the local college football rivalry, asking why Rice played Texas, a much bigger and stronger team.","The speech, written largely with his speechwriter Ted Sorensen, became one of the most famous ever given about science and exploration. Kennedy did not live to see the goal reached. He was assassinated in Dallas on 22 November 1963. Soon afterwards NASA's launch site in Florida was named the John F. Kennedy Space Center, and the country kept working towards his deadline as a kind of memorial."]},{"heading":"Robots Go First","paragraphs":["Before people could land on the Moon, someone had to answer some very basic questions. What did the surface look like close up? Were there safe flat places to land? And was the ground solid at all? Some scientists, most famously the astronomer Thomas Gold, worried that the Moon might be covered in deep, fluffy dust that would swallow a landing spaceship like quicksand. The only way to find out was to send robots.","The Soviet Union struck first again. In September 1959 its probe Luna 2 slammed into the Moon, becoming the first human-made object to reach another world. It was not a gentle arrival: the probe hit at more than 3 km per second, near the region called Mare Imbrium, the Sea of Showers. It carried small metal badges with the Soviet coat of arms, which were scattered on impact.","Just a month later, Luna 3 did something even more amazing. The Moon always keeps the same face turned towards Earth, so no human had ever seen its far side. Luna 3 swung around behind the Moon in October 1959 and took pictures on photographic film. Then, inside the probe, the film was developed, dried and scanned, and the images were sent back by radio, line by line, like a slow fax. The pictures were blurry and grainy, but they showed for the first time that the far side looks different: it has very few of the big dark plains, the lunar 'seas', that make the 'face' of the Man in the Moon.","The United States had a rough start. The first six of its Ranger probes, designed to photograph the Moon as they dived into it, all failed in one way or another. Then, in July 1964, Ranger 7 worked perfectly, sending back more than 4,000 sharp pictures in its last minutes before crashing. The final photos showed craters only about a metre wide.","The next big question, the dust, was answered on 3 February 1966, when the Soviet Luna 9 made the first soft landing on the Moon, in the Ocean of Storms. It was protected by inflatable airbags, bounced several times, and then opened four metal petals like a flower to stand upright. Its camera sent back the first pictures ever taken on the surface of another world, showing rocks and a horizon about 1.4 km away. Astronomers at the Jodrell Bank radio telescope in England picked up the signal, recognized that it used the same format newspapers used to send photos, and a British newspaper decoded and printed the pictures before the Soviets released them. Most importantly, Luna 9 had not sunk. The ground could hold a spacecraft.","Four months later, on 2 June 1966, the American Surveyor 1 made a soft landing too, using braking rockets and three legs, much as a crewed lander would. It sent back more than 10,000 pictures. Meanwhile, five American Lunar Orbiter probes, in 1966 and 1967, photographed almost the whole Moon from orbit so that NASA could pick safe, smooth landing sites for astronauts."]},{"heading":"Gemini: Practice in Pairs","paragraphs":["Getting to the Moon would need skills nobody had yet. How do you fly two spacecraft close together in orbit and join them? Can people live in a tiny cabin for a week or more, the time a Moon trip would take? Can an astronaut do useful work outside in a spacesuit? NASA needed a training programme, and it built one between Mercury and Apollo. Because its capsule carried two astronauts side by side, it was named Gemini, the Latin word for twins and the name of a constellation.","The reason meeting in orbit mattered so much was NASA's plan for the Moon, chosen in 1962 and pushed hard by a Langley engineer named John Houbolt. Instead of landing one enormous spaceship on the Moon, Apollo would send two craft joined together. A command ship would stay circling the Moon while a small, light lander took two astronauts down to the surface. Afterwards the top half of the lander would blast off and meet the command ship in lunar orbit. This idea, called lunar orbit rendezvous, saved so much weight that a single giant rocket could do the job. But it only worked if astronauts could reliably find and dock with another spacecraft, far from home. If it failed, the moonwalkers would be stranded. Gemini would test it.","The first crewed Gemini flight, Gemini 3, launched on 23 March 1965 with Gus Grissom and John Young. It lasted under five hours, but it did something no earlier American capsule could: the astronauts fired thrusters to change the shape and height of their orbit, actually steering their spacecraft from one path around the Earth to another. That skill would be essential for chasing another spacecraft. The flight is also remembered for a joke. Young had secretly carried a corned beef sandwich aboard and offered Grissom a bite. Crumbs floating around a cabin full of electronics could be dangerous, and some members of Congress were not amused, so later crews ate only approved space food: bite-sized cubes, freeze-dried meals that had to be mixed with water, and drinks squeezed from pouches.","Ten crewed Gemini flights launched in 1965 and 1966, each on a Titan II rocket, another former missile. In June 1965, on Gemini 4, Ed White made the first American spacewalk. He floated outside for over 20 minutes, pushing himself around with a small hand-held gas gun, and enjoyed it so much that he did not want to come back in, later calling it the saddest moment of his life. In August, Gemini 5 stayed up for about eight days, long enough for a round trip to the Moon.","Then came the most daring test. In December 1965 Frank Borman and Jim Lovell launched on Gemini 7 for a marathon: nearly 14 days crammed into a cabin about the size of the front seat of a small car. While they were up there, a second capsule, Gemini 6A with Wally Schirra and Tom Stafford, was meant to chase and meet them. Its first launch attempt, on 12 December, ended with a fright when the engines lit and then shut down after about one and a half seconds. The rocket stayed on the pad, and Schirra, judging correctly that it was not going to fall or explode, decided not to pull the ejection handle. Three days later, on 15 December, Gemini 6A flew perfectly.","Within about six hours Schirra had steered his capsule to Gemini 7. The two spacecraft flew together for hours, at times as close as about 30 centimetres, travelling around the Earth at about 28,000 km/h. The astronauts could see each other's faces through the windows. Schirra held up a sign for Gemini 7 to read, and before coming home the 6A crew surprised Mission Control by playing 'Jingle Bells' on a tiny harmonica and some bells they had smuggled aboard. Gemini had shown that a rendezvous in space was possible."]},{"heading":"Armstrong's Wild Spin","paragraphs":["Meeting another spacecraft was one thing; actually locking onto it was the next step. For this, NASA launched an uncrewed target rocket called an Agena, with a docking collar on its nose. On 16 March 1966, Gemini 8, flown by Neil Armstrong and David Scott, caught up with its Agena and gently slid its nose into the collar. It was the first time two spacecraft had ever docked in orbit.","About half an hour later, the joined spacecraft began to roll for no obvious reason. The astronauts undocked, thinking the Agena was the problem, but the spinning got much worse. One of Gemini's own small steering thrusters had become stuck on, probably because of an electrical fault, and was firing nonstop. Soon the capsule was whirling at nearly one full turn every second. Armstrong and Scott's vision began to blur, and there was a real danger they would black out.","Armstrong kept his head. He switched off the main steering thrusters and used a separate set meant for re-entry to slowly stop the spin. It worked, but using that fuel meant the mission rules required an immediate return. Gemini 8 came down in the western Pacific after only about 10 hours and 41 minutes, instead of the three days planned. NASA's managers noticed how calmly Armstrong had handled a life-threatening emergency, and that reputation would matter three years later.","The last flight, Gemini 12 in November 1966, solved the spacewalking problem. Earlier spacewalkers had become exhausted and overheated, because without something to brace against, every twist of a wrench spins your own body the other way. Buzz Aldrin had trained underwater, where floating is a little like weightlessness, and the spacecraft was given handholds and foot restraints. Taking regular rests, Aldrin worked outside for a total of about five and a half hours. By the end of Gemini, NASA knew how to rendezvous, dock, spend two weeks in space and work outside. Now it needed the Moon ship itself."]},{"heading":"Fire on Pad 34","paragraphs":["The first Apollo flight with a crew was planned for early 1967. Its astronauts were Gus Grissom, a veteran of Mercury and Gemini; Ed White, America's first spacewalker; and Roger Chaffee, a young Navy pilot preparing for his first flight. On 27 January 1967 they were strapped into their command module on top of an unfuelled Saturn IB rocket at Launch Complex 34 at Cape Kennedy, for what was called a 'plugs-out' test: a full rehearsal of the countdown with the spacecraft running on its own power. Because there was no fuel in the rocket, the test was not considered dangerous.","The cabin was filled with pure oxygen at slightly more than normal air pressure, as had been done in earlier spacecraft. In pure oxygen, things that normally burn slowly, such as nylon netting and Velcro patches, burn extremely fast. At about 6:31 in the evening, a spark, most likely from damaged wiring, started a fire. It spread through the cabin in seconds. The hatch was a heavy door that opened inwards and needed several steps to open, and the rising pressure of the hot gases held it shut. Ground crews rushed to help through smoke and heat, but within moments it was too late. All three astronauts died.","The whole country mourned, and some people asked whether the Moon goal should be abandoned. Instead, NASA and its contractors examined every part of the spacecraft. The command module was redesigned: a new hatch that could swing outwards in a few seconds, fireproof cloth for spacesuits, self-extinguishing materials, better-protected wiring, and a cabin atmosphere on the launch pad of 60 per cent oxygen and 40 per cent nitrogen instead of pure oxygen. Crewed Apollo flights were delayed by about 20 months. Many engineers later said the tragedy made the spacecraft far safer, and that Apollo might not have succeeded without those changes. The mission was renamed Apollo 1 in the crew's honour."]},{"heading":"Trouble on the Other Side","paragraphs":["The Soviet Union was racing too, but in secret, and it was having troubles of its own. On 14 January 1966 Sergei Korolev, the Chief Designer who had led Sputnik and Gagarin's flight, died during an operation, aged 59. Only after his death did the Soviet government reveal his name to the public. His team lost its strongest leader just as it faced its hardest job. Korolev's long rivalry with the top engine designer, Valentin Glushko, had also left his Moon rocket, the N1, with a difficult design: its first stage needed 30 engines firing together.","The Soviets also had a new spacecraft, Soyuz, meaning 'union'. On 23 April 1967 cosmonaut Vladimir Komarov launched on the first crewed Soyuz flight. Almost at once things went wrong: one of the two solar panels, which made electricity from sunlight, failed to unfold, leaving the ship short of power, and other systems began to fail. A second Soyuz, which was meant to launch the next day and meet him, was cancelled. Controllers brought Komarov home early. During the descent on 24 April, the main parachute did not come out and the reserve parachute tangled. The capsule hit the ground hard and Komarov was killed. He was the first person to die during a space mission. His backup for the flight had been Yuri Gagarin.","Soyuz flights stopped for about 18 months while the spacecraft was improved, and the design that came out of those fixes has flown, in updated versions, ever since. Meanwhile, the Soviets prepared a smaller project: a crew flight looping around the Moon without landing. In September 1968 an uncrewed version, Zond 5, flew around the Moon and back carrying two tortoises, along with fruit-fly eggs, plants and other tiny living things. The tortoises splashed down in the Indian Ocean and survived, becoming the first living things to travel around the Moon and come home. To American planners, it looked as if cosmonauts might be next."]},{"heading":"Apollo 8: Christmas at the Moon","paragraphs":["In October 1968 Apollo 7, with Wally Schirra, Donn Eisele and Walter Cunningham, tested the redesigned command module in Earth orbit for 11 days and sent the first live television broadcasts from an American spacecraft. It worked well. But the lunar module, the lander, was badly behind schedule. In the summer of 1968 a NASA manager named George Low suggested a bold idea: instead of waiting, send the next crew all the way to the Moon, to orbit it without a lander. The giant Saturn V had flown only twice, both times without people, and the second flight had had problems. Even so, NASA agreed. Some of the reasons were technical, and some were worry about what the Soviets might do next.","On 21 December 1968 Frank Borman, Jim Lovell and Bill Anders became the first people to ride a Saturn V. A few hours later, a burn of the third stage pushed them out of Earth orbit at about 39,000 km/h. They were the first humans ever to leave the neighbourhood of Earth, and the first to see the whole planet as a round ball hanging in space. The trip took about three days. On 24 December, as Apollo 8 swung behind the Moon, its radio signal was cut off by the Moon itself. Behind the Moon, the crew fired their engine to slow down and slip into orbit. If the burn had failed, they would have swung around and back towards Earth. Mission Control waited in nervous silence until, right on time, Lovell's voice came back. They were in lunar orbit.","For about 20 hours, Apollo 8 circled the Moon ten times, roughly 110 km above its grey, cratered surface. The astronauts were the first people to see the far side with their own eyes. They photographed possible landing sites. Then, on the fourth orbit, the spacecraft turned, and the crew suddenly saw the blue and white Earth rising above the Moon's horizon. Anders grabbed a camera loaded with colour film and took the picture now called 'Earthrise'. It showed our whole planet small and beautiful against black space, above a lifeless grey landscape. Many people say it changed how humans think about Earth, and it is often credited with helping to inspire the first Earth Day in 1970.","That night, Christmas Eve, the crew made a television broadcast from lunar orbit. Taking turns, they read the opening verses of the Book of Genesis from the Bible, about the creation of the heavens and the Earth. Borman ended by wishing a merry Christmas and God bless 'all of you on the good Earth'. It was one of the most-watched broadcasts in history up to that time. On Christmas Day the engine fired again behind the Moon to send them home, and when the signal returned, Lovell announced, 'Please be informed, there is a Santa Claus.' Apollo 8 splashed down in the Pacific Ocean on 27 December 1968, and the three astronauts were named Time magazine's Men of the Year."]},{"heading":"The 400,000 People Behind the Astronauts","paragraphs":["It is easy to think of the space race as a story about a few famous astronauts. In fact, at its peak, the Apollo programme involved roughly 400,000 people across the United States, along with more than 20,000 companies and universities. Only a small fraction worked for NASA directly. Most were employed by contractors: Boeing built the first stage of the Saturn V; North American Aviation built the second stage and the command module; Douglas built the third stage; Rocketdyne made the engines; and Grumman, on Long Island in New York, built the lunar module.","The work ranged from enormous to tiny. Welders joined fuel tanks big enough to hold swimming pools. At the Massachusetts Institute of Technology, engineers and programmers designed the guidance computer and its software. Factory workers, many of them women, wove the computer's permanent memory by hand, threading thin copper wires through or around tiny magnetic rings; each choice stored a one or a zero. Seamstresses at a company in Delaware stitched the moonwalkers' spacesuits from many layers of fabric, so precisely that a single badly placed stitch could mean a leak. Radio engineers ran giant dish antennas in California, Spain and Australia so that a spacecraft could always be heard as the Earth turned. Thousands of mathematicians, like Katherine Johnson, worked out trajectories.","The cost was enormous too. Apollo cost about 25 billion dollars at the time, roughly 257 billion dollars in 2020 money, and in the mid-1960s NASA received around 4 per cent of the whole US government budget. Many people argued, then and now, that the money should have been spent on problems on Earth. Supporters answered that the effort trained a generation of engineers and pushed forward computers, materials and electronics.","By early 1969, two more flights had tested the lunar module, first in Earth orbit and then in a full dress rehearsal near the Moon, coming within about 15 km of the surface. Everything was ready. In July 1969, at Launch Complex 39A in Florida, a white Saturn V rocket more than 110 m tall stood steaming in the summer heat, its tanks being filled with fuel, waiting for three astronauts and the most famous journey in history."]}],"deepDive":"How do you get to the Moon? In 1961 NASA argued over three plans. 'Direct ascent' meant building one colossal rocket, sometimes called Nova, to fly a whole spaceship to the Moon, land it tail-first, and fly it home. 'Earth orbit rendezvous', at first preferred by Wernher von Braun's team, meant launching two or more large rockets and assembling the Moon ship in Earth orbit. 'Lunar orbit rendezvous' (LOR), championed by John Houbolt of Langley, used one Saturn V and two spacecraft: only a small, light lander would go down to the surface, and only its upper half would come back up. Because every kilogram landed on the Moon must be carried there, slowed down and lifted off again, the savings snowballed. Houbolt wrote to NASA leaders that he felt like 'a voice in the wilderness', but by mid-1962 NASA chose LOR, and Gemini's rendezvous flights were designed to prove it. On the Soviet side, historians argue about why the USSR lost the Moon race even though it led early on. Reasons often given include: the government did not officially commit to a Moon landing until 1964, three years after Kennedy; money and effort were split between rival design bureaus led by Korolev, Vladimir Chelomei and others; Korolev and Glushko disagreed about engines, so the N1 was built around 30 smaller engines instead of a few giant ones; there was no big test stand to fire the whole first stage on the ground before flight; and Korolev's death in 1966 removed the leader who held everything together. Another debate concerns risk. Apollo 8 was a huge gamble: the Saturn V had flown only twice, and a failure of the engine behind the Moon could have stranded the crew. NASA leaders estimated the risks carefully, but they also felt time pressure from Kennedy's deadline and from Soviet Zond flights. Finally, the cost: in today's money Apollo is often estimated at around 250 billion dollars or more, and opinion polls through the 1960s showed many Americans did not think it was worth it, even though the Moon landings are now remembered as a national triumph.","funFact":"According to the Smithsonian, the first musical instruments played in space were a tiny harmonica and a handful of small bells, used by the Gemini 6A crew to play 'Jingle Bells' in December 1965. Those instruments are now in the Smithsonian's collection.","check":{"q":"Who took the famous 'Earthrise' photograph from lunar orbit on Apollo 8?","a":"Bill Anders","wrong":["Neil Armstrong","John Glenn","Alexei Leonov"]},"sources":[{"title":"We choose to go to the Moon","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/We_choose_to_go_to_the_Moon"},{"title":"Luna 9","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Luna_9"},{"title":"Project Gemini","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Project_Gemini"},{"title":"Gemini 8","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Gemini_8"},{"title":"Apollo 1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apollo_1"},{"title":"Soyuz 1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Soyuz_1"},{"title":"Apollo 8","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apollo_8"},{"title":"Project Apollo","publisher":"The Planetary Society","url":"https://www.planetary.org/explore/space-topics/space-missions/apollo.html"}],"photos":[{"src":"img/deep/rockets/12-1.jpg","alt":"President John F. Kennedy at the lectern in the Rice University stadium, Houston, during his Moon speech, September 1962.","file":"Kennedy at Rice University - GPN-2000-001618.jpg","url":"https://commons.wikimedia.org/wiki/File:Kennedy_at_Rice_University_-_GPN-2000-001618.jpg","author":"NASA","license":"Public domain"},{"src":"img/deep/rockets/12-2.jpg","alt":"The Gemini 7 spacecraft above Earth, photographed from Gemini 6A during the first space rendezvous, December 1965.","file":"Gemini 6 Views Gemini 7.jpg","url":"https://commons.wikimedia.org/wiki/File:Gemini_6_Views_Gemini_7.jpg","author":"NASA","license":"Public domain"},{"src":"img/deep/rockets/12-3.jpg","alt":"Earthrise: our planet rising over the Moon's horizon, photographed by Bill Anders on Apollo 8, 24 December 1968.","file":"NASA-Apollo8-Dec24-Earthrise.jpg","url":"https://commons.wikimedia.org/wiki/File:NASA-Apollo8-Dec24-Earthrise.jpg","author":"NASA/Bill Anders","license":"Public domain"}],"words":3790},{"n":13,"title":"The Eagle Has Landed","when":"1969 – 1972","summary":"In July 1969 a giant rocket called the Saturn V carried three astronauts to the Moon, and Neil Armstrong took the first step onto its dusty ground. Twelve people walked on the Moon in all, one crew survived an explosion on the way there, and the astronauts brought home boxes full of Moon rocks.","sections":[{"heading":"A Skyscraper Made of Fuel","paragraphs":["Imagine standing on a beach in Florida before dawn on 16 July 1969. About five kilometres away, lit up by searchlights, stands the tallest, heaviest and most powerful machine that had ever flown: the Saturn V rocket. It is about 110 metres (363 feet) tall, taller than the Statue of Liberty on its pedestal and almost as tall as a 36-storey building. Around a million people have crowded onto beaches, roads and riverbanks to watch. Some have camped in their cars for days.","The Saturn V was designed by Wernher von Braun's team at NASA's Marshall Space Flight Center in Huntsville, Alabama, and built by several big companies working together: Boeing made the first stage, North American Aviation the second, and Douglas Aircraft the third. Fully loaded, the whole rocket weighed about 2,900 tonnes, roughly as much as 400 African elephants. Almost all of that weight was propellant, the fuel and oxidizer the rocket would burn in the next few minutes.","The rocket was really three rockets stacked on top of each other, called stages. The bottom stage, the S-IC, was about 42 metres tall and 10 metres wide. At its base sat five F-1 engines, each as tall as a giraffe and as heavy as a big truck. Together they burned kerosene and liquid oxygen and pushed with a force of about 34 million newtons, or about 7.5 million pounds of thrust. The second stage, the S-II, had five smaller J-2 engines burning super-cold liquid hydrogen and liquid oxygen. The third stage, the S-IVB, had a single J-2 engine that could be switched off and lit again later, which was vital for the trip to the Moon.","On top of all this sat the part that actually mattered to the astronauts: the Apollo spacecraft. There was a cone-shaped command module, where the three astronauts sat; a cylinder-shaped service module behind it, with an engine, fuel, oxygen tanks and electricity-making fuel cells; and, folded up inside a protective shell, the spidery lunar module that would land on the Moon. At the very tip stood a launch escape tower, a small rocket that could yank the command module away if anything went badly wrong on the launch pad.","The numbers tell a striking story. Out of roughly 2,900 tonnes on the pad, only the small command module, about 3.9 metres wide at its base, would come home. Everything else would be dropped into the ocean, left in orbit, sent around the Sun or left on the Moon. A Moon trip was a bit like building a whole skyscraper just so that one tiny room on top could travel to the Moon and back.","The first Saturn V had flown without a crew in November 1967 on the Apollo 4 test. Apollo 8 had already used one to carry Frank Borman, Jim Lovell and Bill Anders around the Moon. Now, in July 1969, Saturn V number six was ready for the real thing."]},{"heading":"Three Men and a Plan","paragraphs":["The crew of Apollo 11 were three test pilots, all born in 1930. The commander was Neil Armstrong, a calm engineer from Ohio who had flown the X-15 rocket plane and who had already saved Gemini 8 when a jammed thruster sent it spinning in 1966. The lunar module pilot was Edwin \"Buzz\" Aldrin, a former fighter pilot with a doctorate from MIT; his university research had been about how spacecraft can meet up in orbit, which is exactly what Apollo had to do. The command module pilot was Michael Collins, a witty Air Force pilot who had made two spacewalks on Gemini 10.","They named their two spacecraft carefully. The command module was called Columbia, after the poetic name for America and after the giant cannon-launched capsule \"Columbiad\" in Jules Verne's 1865 novel. The lunar module was called Eagle, after the American national bird. Their mission patch showed an eagle landing on the Moon with an olive branch in its claws, a symbol of peace. The crew decided to leave their names off the patch, because they wanted it to represent everyone who had worked on Apollo.","The plan had many steps, and every one had to work. The Saturn V would put them in orbit around Earth. The third stage would then fire again to send them on a three-day coast to the Moon. Collins would turn Columbia around, dock with Eagle and pull it out of its shell. Near the Moon, the service module's engine would slow them down so that the Moon's gravity could capture them into orbit. Then Armstrong and Aldrin would crawl into Eagle, separate, and fly down to the surface while Collins waited above.","After their moonwalk, the top half of Eagle, called the ascent stage, would blast off, using the bottom half as a launch pad, and meet Columbia again in lunar orbit. The three astronauts would ride home in Columbia, drop off the service module just before reaching Earth, and splash down in the Pacific Ocean. If any of these steps failed, the astronauts might not come back. US President Richard Nixon even had a speech prepared, written by his speechwriter William Safire, to read in case Armstrong and Aldrin were stranded on the Moon. Happily, it was never needed."]},{"heading":"Liftoff and Three Days to the Moon","paragraphs":["At 9:32 in the morning, Florida time (13:32 UTC), on 16 July 1969, the five F-1 engines roared to life on Launch Complex 39A at the Kennedy Space Center. For a few seconds, huge clamps held the rocket down while the engines built up full power. Then they let go. Because the rocket was so heavy, it rose slowly at first, taking about 10 seconds just to climb past the tower. Spectators said they felt the sound as much as heard it; it shook their chests and rattled windows kilometres away.","Inside the command module, the astronauts were pressed back into their couches as the rocket shook and rattled. About two and a half minutes after launch, the first stage had burned through its fuel and was dropped, falling into the Atlantic Ocean. The second stage took over for about six minutes, then the third stage fired to push them into an orbit about 190 kilometres above Earth. In just under 12 minutes, they had gone from standing still to about 28,000 km/h.","After about one and a half orbits, while the crew double-checked everything, the third stage fired again for about six minutes. This burn, called translunar injection, raised their speed to about 39,000 km/h, fast enough to coast all the way to the Moon. Collins then performed the tricky docking with Eagle and pulled it free. The empty third stage was sent off on a path that took it past the Moon and into orbit around the Sun.","The coast to the Moon took about three days. The astronauts ate freeze-dried food, sent television pictures home, and slept in sleeping bags. To keep one side of the spacecraft from baking in the sunshine while the other froze, they slowly rotated the whole ship, a trick nicknamed the \"barbecue roll\". On 19 July they passed behind the Moon, out of radio contact with Earth, and fired the service module's engine to slow down and enter lunar orbit. Flight controllers in Houston waited nervously until Apollo 11 came around the other side and its radio signal returned."]},{"heading":"Twelve Minutes of Alarms, Boulders and Fuel","paragraphs":["On 20 July 1969, Armstrong and Aldrin floated through the tunnel into Eagle and undocked. Collins, alone in Columbia, looked the lander over to check that its legs had unfolded properly. \"You cats take it easy on the lunar surface,\" he radioed. Then Eagle fired its descent engine and began the most dangerous part of the whole trip: a powered descent of about 12 minutes from roughly 15 kilometres up all the way to the ground.","Eagle's brain was the Apollo Guidance Computer. By today's standards it was tiny: it had about 4 kilobytes of erasable memory and about 72 kilobytes of fixed memory, far less than a cheap pocket calculator today. Its programs were literally woven by hand into a kind of rope of wires and tiny magnetic rings, a method called core rope memory. Yet this computer was steering a spacecraft down to another world.","The software was written at the MIT Instrumentation Laboratory in Cambridge, Massachusetts. Margaret Hamilton led the team that wrote the onboard flight software for both the command module and the lunar module. She is often credited with helping to popularise the term \"software engineering\", because she wanted people to treat writing programs as seriously as building bridges. Her team designed the software so that if the computer had too much to do, it would drop the less important jobs and keep running the most important ones, like steering and the engine.","About five minutes into the descent, an alarm light lit up and Armstrong called out, \"Program alarm... It's a 1202.\" The astronauts had never seen this code in training. In Houston, a 26-year-old guidance officer named Steve Bales and his support engineer Jack Garman had to decide in seconds whether to abort. Garman knew from earlier testing that a 1202 meant the computer was being asked to do more jobs than it had time for, and that it was sensibly shedding the unimportant ones. As long as the alarms did not come constantly, the landing was safe. Bales called \"Go!\", and the capsule communicator, astronaut Charlie Duke, told the crew, \"We're go on that alarm.\" More 1202 and 1201 alarms followed, and each time Houston said go. Part of the cause turned out to be the radar meant for meeting Columbia later, which, because of an electrical mismatch, kept interrupting the computer. Thanks to Hamilton's team's design, the computer kept flying the ship.","Then came a second problem. Because of tiny errors in their path, Eagle was coming down several kilometres past the planned spot. When Armstrong looked out of his small triangular window, he saw that the computer was heading for a crater about the size of a football field, surrounded by boulders, some of them two or three metres across. Landing there could tip Eagle over. Armstrong took partial manual control and, a few hundred feet above the ground, flew forward like a helicopter, searching for a smooth, flat place.","That used up fuel. In Houston, controllers began counting down. At \"60 seconds\", Eagle was still a few dozen metres up. At \"30 seconds\", the room went silent. Aldrin read out height and speed numbers to Armstrong while the engine kicked up a sheet of grey dust that made the ground hard to see. Then Aldrin called, \"Contact light,\" meaning a probe under one of the footpads had touched the surface. The engine shut down. Armstrong said: \"Houston, Tranquility Base here. The Eagle has landed.\"","Charlie Duke, so relieved he stumbled over the words, replied: \"Roger, Twan... Tranquility, we copy you on the ground. You got a bunch of guys about to turn blue. We're breathing again. Thanks a lot.\" The time was 20:17 UTC on 20 July 1969. Later analysis showed that the fuel was not quite as low as the warning lights suggested, because sloshing in the tanks had fooled the fuel sensor, but it was still a very close call. Eagle had landed in the Sea of Tranquility, a flat plain of old lava, several kilometres from its target."]},{"heading":"One Small Step","paragraphs":["The original plan had included a rest period after landing, but nobody felt like sleeping. Armstrong and Aldrin spent several hours checking Eagle and putting on their backpacks, gloves and helmets, a slow job in the cramped cabin. Aldrin, privately, took a quiet moment for Communion. Then they let the air out of the cabin and Armstrong squeezed backwards through the hatch onto a small porch and down a ladder.","On the way down, he pulled a handle that opened a storage bay holding a black-and-white television camera, so that people on Earth could watch. The pictures were picked up by big radio dishes, including the Goldstone station in California and the Honeysuckle Creek and Parkes dishes in Australia, and sent around the world. At 02:56 UTC on 21 July, which was still the evening of 20 July in the Americas, Armstrong stepped off the footpad onto the Moon. He said: \"That's one small step for man, one giant leap for mankind.\" He later explained that he meant to say \"one small step for a man\", and that the little word \"a\" may have been lost in the radio static or simply not spoken. Either way, the meaning was clear to everyone.","About 600 million people, roughly one in every six humans alive at the time, are thought to have watched or listened. Families gathered around televisions in living rooms, schools, shop windows and town squares. Many people who saw it remember exactly where they were for the rest of their lives.","Aldrin joined Armstrong about 19 minutes later. He looked around and described the view as \"magnificent desolation\". The Moon's gravity is only about one-sixth of Earth's, so the astronauts, even in suits and backpacks that would have weighed more than 80 kilograms on Earth, could bounce along in kangaroo hops. The fine grey soil, called regolith, was powdery and stuck to everything, and their boots left crisp prints. Since there is no wind or rain on the Moon, many of those footprints are probably still there today, unless disturbed by tiny meteorite impacts or the blast from Eagle's take-off.","The two men worked hard for about two and a half hours. They planted an American flag, kept stiff by a horizontal rod along its top because there is no air to make it fly. They set up a seismometer to detect moonquakes, a sheet of foil to catch particles blowing from the Sun, and a laser retroreflector: a panel of special mirrors that bounces light straight back to where it came from. Scientists on Earth still fire lasers at it today to measure the distance to the Moon to within a few centimetres, which shows that the Moon is slowly drifting away from Earth by about 3.8 centimetres a year. They also took a telephone call from President Nixon, and collected about 21.5 kilograms of rocks and soil.","On one of Eagle's legs they left a metal plaque that reads: \"Here men from the planet Earth first set foot upon the Moon, July 1969, A.D. We came in peace for all mankind.\" They also left a small silicon disc carrying goodwill messages from leaders of more than 70 countries, and medals honouring Yuri Gagarin and Vladimir Komarov as well as the Apollo 1 astronauts.","Meanwhile, high above, Michael Collins circled the Moon alone in Columbia. Each time he passed behind the Moon he lost radio contact with everyone, and for about 48 minutes of every two-hour orbit he was more cut off from other humans than almost anyone in history. He wrote later that he did not feel lonely, but rather awareness, anticipation, satisfaction and confidence, almost exultation. After about 21 and a half hours on the surface, Eagle's ascent stage blasted off, met Columbia, and the three astronauts headed home. They splashed down in the Pacific on 24 July 1969 and were picked up by the aircraft carrier USS Hornet. Because no one was sure whether the Moon carried germs, they were kept in quarantine for about three weeks. No Moon germs were ever found."]},{"heading":"Houston, We've Had a Problem","paragraphs":["Just four months after Apollo 11, Apollo 12 showed the first landing was no lucky fluke. Less than a minute after launch in November 1969, the Saturn V was struck by lightning twice, knocking out power and sending warning lights flashing. A young flight controller, John Aaron, remembered a strange pattern he had once seen in testing and told the crew to flip an obscure switch called \"SCE to AUX\". It worked, and the mission carried on. Pete Conrad and Alan Bean then made a pinpoint landing in the Ocean of Storms, walking over to Surveyor 3, a robot lander that had arrived two and a half years earlier, and bringing pieces of it home so scientists could study how materials age on the Moon.","The next mission is famous for not landing at all. Apollo 13 launched on 11 April 1970 with Jim Lovell, Jack Swigert and Fred Haise aboard. About 56 hours into the flight, more than 300,000 kilometres from Earth, the crew heard a loud bang. One of the two oxygen tanks in the service module had exploded, and the other soon began leaking. A damaged wire inside the tank, left over from a mistake during ground testing, had sparked and set fire to the insulation inside.","Swigert radioed, \"Okay, Houston, we've had a problem here.\" When Houston asked him to repeat, Lovell said, \"Houston, we've had a problem.\" (Films and posters often change this to \"we have a problem\", but those were not the real words.) Those oxygen tanks fed the fuel cells that made the command module's electricity and water, and the oxygen the crew breathed. Within a couple of hours, the command module, Odyssey, was dying.","The crew's lifeline was the lunar module, Aquarius. It had its own batteries, oxygen and engine, and it was still attached. The astronauts shut down Odyssey to save its batteries for the return to Earth, and crowded into Aquarius, which was built to keep two men alive for about two days, not three men for four. It became a lifeboat. Aquarius's descent engine was fired to put them on a path that swung around the Moon and back towards Earth, and fired again later to speed up the trip.","Then the air started to go bad. People breathe out carbon dioxide, which must be removed or it becomes dangerous. Aquarius's carbon-dioxide filters, called lithium hydroxide canisters, were filling up. Odyssey had plenty of spare canisters, but they were square, while Aquarius's holders were round. Engineers in Houston gathered exactly the items the astronauts had on board, such as plastic bags, cardboard covers from the flight plan, a spacesuit hose and lots of grey duct tape, and invented a way to fit the square canisters into the round system. They read the instructions up by radio, the crew built the contraption, and it worked.","To save power, almost everything was turned off. The cabin fell to a few degrees above freezing, water droplets formed on the walls, and the crew got very little sleep. Haise came down with a fever. Near Earth, they let go of the damaged service module and saw for the first time that a whole side panel had been blown off. Then they powered up the cold command module, hoping it would wake up, and released Aquarius. On 17 April 1970, Odyssey splashed down safely in the Pacific. It became known as a \"successful failure\": they had not reached the Moon, but teamwork and quick thinking had brought everyone home."]},{"heading":"Twelve Moonwalkers and a Moon Car","paragraphs":["After a careful investigation and a redesign of the oxygen tanks, Apollo flights resumed. Apollo 14, in February 1971, landed in the hilly Fra Mauro region, where Apollo 13 had been meant to go. Its commander was Alan Shepard, the first American in space ten years earlier, who at 47 became the oldest person to walk on the Moon. He also smuggled a golf club head onto the mission and hit two golf balls in the low gravity.","The last three missions were longer and more scientific. They carried the Lunar Roving Vehicle, an electric Moon car that folded up like a camping chair to fit on the side of the lunar module. It ran on batteries, had wire-mesh tyres because rubber ones could not survive the Moon's heat and cold, and could travel at about the speed of a fast bicycle on Earth. Its range let astronauts explore kilometres from their lander instead of a few hundred metres.","Apollo 15 (July–August 1971) landed near a long winding valley called Hadley Rille at the foot of the Apennine mountains. Dave Scott and Jim Irwin drove the first rover and found a piece of very old white rock that reporters nicknamed the \"Genesis Rock\", because it came from the Moon's early crust, at least 4 billion years old. Scott also dropped a hammer and a falcon feather side by side to show that, with no air, they hit the ground at the same moment, just as Galileo had predicted. Apollo 16 (April 1972) took John Young and Charlie Duke to the Descartes highlands. Duke left a photo of his family on the ground.","Apollo 17, in December 1972, was the last. Gene Cernan and Harrison Schmitt, a geologist and the only professional scientist to walk on the Moon, explored a valley called Taurus-Littrow for three long moonwalks, while Ronald Evans orbited above. When a rover fender broke off and dust sprayed everywhere, they fixed it by taping together spare maps. Schmitt found surprising orange soil, which turned out to be made of tiny glass beads from ancient volcanic fountains. On the way to the Moon, the crew took one of the most famous photographs ever, the \"Blue Marble\", showing the whole round Earth lit by the Sun.","On 14 December 1972, Cernan was the last to climb back into the lander. Before he did, he said that they were leaving as they came and, God willing, would return, \"with peace and hope for all mankind\". He traced his daughter's initials in the dust. Nobody has stood on the Moon since.","Altogether, twelve men walked on the Moon: Neil Armstrong, Buzz Aldrin, Pete Conrad, Alan Bean, Alan Shepard, Edgar Mitchell, Dave Scott, Jim Irwin, John Young, Charlie Duke, Gene Cernan and Harrison Schmitt. They brought back about 382 kilograms (842 pounds) of rocks, pebbles, soil and core samples, split into more than 2,000 separate samples. Scientists around the world are still studying them; some sealed samples were opened for the first time only in the 2020s using modern instruments. These rocks helped show that the Moon probably formed from debris after a huge collision between the young Earth and a Mars-sized body, an idea known as the giant-impact hypothesis.","The Moon landings are among the best-proven events in history. The rocks are unlike anything found on Earth, the laser mirrors are still used, spacecraft orbiting the Moon have photographed the landing sites with their rovers and footpaths, and the Soviet Union, America's rival, tracked the missions itself and never disputed them."]},{"heading":"Meanwhile in the Soviet Union","paragraphs":["What happened to the Soviet Moon program? The USSR had secretly been trying to land a cosmonaut too. Its Moon rocket was the N1, a giant cone about 105 metres tall. Because the Soviets had not built engines as big as the F-1, its first stage used 30 smaller engines working together. Controlling so many engines at once was extremely hard, and there was little money or time for full ground tests of the whole first stage. Sergei Korolev, the Chief Designer, had died in 1966, and his successor, Vasily Mishin, struggled with delays and disagreements between designers.","The N1 was launched four times, without a crew, and failed all four times: in February 1969, July 1969, June 1971 and November 1972. The second launch, on 3 July 1969, only two weeks before Apollo 11, fell back onto its launch pad and exploded, wrecking the pad. It is often described as one of the biggest non-nuclear explosions ever caused by people. The Soviet government kept the failures secret, and the Moon-landing program was cancelled in 1974. For many years the Soviets said they had never been racing to land people on the Moon at all.","Instead, the Soviet Union sent clever robots. While Armstrong and Aldrin were on the Moon, a Soviet probe called Luna 15 was orbiting nearby, trying to grab a soil sample before the Americans got home. It crashed into the Moon on 21 July 1969. But in September 1970, Luna 16 landed in the Sea of Fertility, drilled into the ground, and sent back about 100 grams of soil in a small capsule, the first time a robot had brought samples back from another world. Two more Luna missions returned samples later.","In November 1970, Luna 17 delivered Lunokhod 1, the first remote-controlled rover to drive on another world. It looked like a bathtub on eight wheels with a lid that opened like a clam to expose solar panels. A team of drivers on Earth steered it using television pictures that arrived several seconds late. Lunokhod 1 worked for about ten months and travelled about 10 kilometres, sending back thousands of pictures and testing the soil. Today its laser reflector is still used by scientists, just like the ones left by Apollo.","So by the end of 1972 both rivals had reached the Moon in very different ways: one with twelve human explorers, the other with skilful robots. Yet after Apollo 17, the giant Saturn Vs were retired. The final one launched in 1973 carrying not astronauts to the Moon but America's first space station. That raised the big question every space fan was asking: after the Moon, what next? The answer would be a home in orbit, and a spaceship that could fly again and again."]}],"deepDive":"Historians and engineers still argue about how close Apollo 11 came to an abort. The 1202 and 1201 alarms were 'executive overflow' warnings: the Apollo Guidance Computer's real-time scheduler had run out of slots for new jobs. A major contributor was the rendezvous radar, whose electronics, because of a power-supply mismatch, sent a stream of unneeded interrupts, eating roughly 13 percent of the computer's time during descent, when the landing job already needed most of the rest. Because the software, written by Margaret Hamilton's team at MIT under a design approach later called priority scheduling, restarted and kept only the high-priority tasks (guidance, engine control, displays), the landing could continue. Had the alarms come continuously, the computer could have stopped updating the guidance, and the controllers' rule was to abort in that case. Fuel is the other debate. At touchdown the crew believed about 20 to 25 seconds of hover time remained before the 'bingo' call, when they would have had to land within 20 seconds or abort. Later analysis showed propellant sloshing had triggered the low-level sensor early, so the real margin was larger, perhaps closer to 50 seconds; the Science Museum notes that when Armstrong asked about fuel late in the descent, Aldrin answered 'eight percent'. Apollo 13 is a case study in engineering failure chains: a thermostat switch rated for 28 volts was never upgraded when the ground power supply changed to 65 volts, and a long heating procedure after a ground-test fault welded it shut, cooking the wire insulation. On the Soviet side, the N1's failures are often blamed on its 30-engine first stage, controlled by a system called KORD that could shut down engines in opposing pairs; without full static firing tests of the stage, problems such as vibration, pipe ruptures and fires were discovered only in flight. Apollo's cost, about 25 billion dollars at the time (well over 200 billion in today's money), remains part of the debate about whether its achievements, and its 382 kilograms of samples, justified the expense.","funFact":"Because there is no wind on the Moon, the footprints left by the Apollo astronauts could last for millions of years, slowly worn down only by tiny meteorite impacts.","check":{"q":"During Apollo 13, which spacecraft did the astronauts use as a 'lifeboat' after the oxygen tank exploded?","a":"The lunar module Aquarius","wrong":["The Saturn V's third stage","A Soviet Soyuz capsule","The command module Columbia"]},"sources":[{"title":"Moon Landing 1969","publisher":"History.com","url":"https://www.history.com/articles/moon-landing-1969"},{"title":"Apollo 11 Moon landing: the most difficult moments","publisher":"Science Museum (London)","url":"https://blog.sciencemuseum.org.uk/apollo-11-moon-landing-the-most-difficult-moments/"},{"title":"Apollo 13","publisher":"Smithsonian National Air and Space Museum","url":"https://airandspace.si.edu/explore/stories/apollo-missions/apollo-13"},{"title":"Apollo 17","publisher":"Smithsonian National Air and Space Museum","url":"https://airandspace.si.edu/explore/stories/apollo-missions/apollo-17"},{"title":"The Apollo Missions","publisher":"Smithsonian National Air and Space Museum","url":"https://airandspace.si.edu/explore/stories/apollo-missions"},{"title":"Scene at MIT: Margaret Hamilton's Apollo code","publisher":"MIT News","url":"https://news.mit.edu/2016/scene-at-mit-margaret-hamilton-apollo-code-0817"},{"title":"N1 Moon rocket","publisher":"RussianSpaceWeb (Anatoly Zak)","url":"https://www.russianspaceweb.com/n1.html"},{"title":"Apollo 11","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apollo_11"}],"photos":[{"src":"img/deep/rockets/13-1.jpg","alt":"Buzz Aldrin standing on the Moon during Apollo 11; Neil Armstrong and the lunar module are reflected in his visor.","file":"Aldrin Apollo 11 original.jpg","url":"https://commons.wikimedia.org/wiki/File:Aldrin_Apollo_11_original.jpg","author":"Neil Armstrong","license":"Public domain"},{"src":"img/deep/rockets/13-2.jpg","alt":"The Saturn V rocket carrying Apollo 11 lifts off from Launch Complex 39A, 16 July 1969.","file":"Apollo 11 Launch - GPN-2000-000630.jpg","url":"https://commons.wikimedia.org/wiki/File:Apollo_11_Launch_-_GPN-2000-000630.jpg","author":"NASA","license":"Public domain"},{"src":"img/deep/rockets/13-3.jpg","alt":"The Lunar Roving Vehicle parked on the Moon during Apollo 15, with mountains in the background.","file":"Apollo15LunarRover.jpg","url":"https://commons.wikimedia.org/wiki/File:Apollo15LunarRover.jpg","author":"NASA/Dave Scott; cropped by User:Bubba73","license":"Public domain"}],"words":4539},{"n":14,"title":"How Rockets Work (Part 2): Fuel, Stages and Coming Home","when":"Science explainer","summary":"A big rocket is mostly fuel, packed into tanks and burned in engines with giant bell-shaped nozzles. Rockets drop their empty parts as they climb so they get lighter, and steer by tilting their engines. Coming home, a capsule plunges through air so squashed and hot that it needs a special shield that slowly burns away.","sections":[{"heading":"Two Kinds of Rocket Food","paragraphs":["In Part 10 we learned the big idea: a rocket moves by throwing hot gas out of its back, and Newton's third law pushes the rocket the other way. Now let's open up a rocket and see how engineers actually make that happen, and how they get astronauts home again afterwards.","Every rocket burns propellant, which means two things together: a fuel, and an oxidizer that lets the fuel burn. On Earth, a campfire takes its oxygen from the air. A rocket cannot do that high in the sky or in space, so it carries its own. There are two main ways to pack this \"rocket food\": as a solid or as liquids.","A solid-fuel rocket is the older kind. The fuel and oxidizer are mixed together into a rubbery or crumbly block, packed inside a strong tube. Fireworks and the Chinese fire arrows from Part 2 were tiny solid rockets using gunpowder. Modern solid rockets use better recipes, often a powdered oxidizer called ammonium perchlorate, powdered aluminium as fuel, and a rubbery binder that holds it all together, a bit like a giant pencil eraser. The Space Shuttle's two white side boosters were solid rockets, each about 45 metres tall, and so are many military missiles and the boosters strapped to rockets like NASA's Space Launch System.","Solid rockets have big advantages. They are fairly simple, with few moving parts. They can sit ready for years. And they can push enormously hard for their size. But they have one big problem: once you light one, you generally cannot turn it off or turn it down. It burns until it is empty, a bit like a match. Engineers shape a hollow channel down the middle of the block, sometimes star-shaped, to control how fast the burning surface grows, which is a clever way to plan the thrust in advance.","A liquid-fuel rocket keeps its fuel and oxidizer in separate tanks as liquids and pumps them into the engine, where they meet and burn. Robert Goddard's little 1926 rocket was the first of these. Liquid rockets are more complicated, with pipes, valves and pumps, but they have a superpower: you can throttle them up and down, switch them off, and sometimes restart them. That control is why almost every crewed spacecraft has relied on liquid engines.","There are several favourite liquid combinations. Kerosene, a refined fuel similar to jet fuel (rocket engineers use a very pure version called RP-1), burned with liquid oxygen, powered the five F-1 engines of the Saturn V's first stage and powers the SpaceX Falcon 9 today. It is dense, so the tanks can be smaller, and it is easy to store. Liquid hydrogen burned with liquid oxygen gives the fastest exhaust of any common chemical pair, so it squeezes the most push out of every kilogram, which is why the Saturn V's upper stages and the Space Shuttle's main engines used it. But hydrogen has to be chilled to about minus 253 degrees Celsius to stay liquid, and it is so light and fluffy that it needs huge tanks; the Shuttle's big orange external tank was mostly filled with hydrogen. Liquid oxygen itself must be kept below about minus 183 degrees Celsius, which is why rockets on the pad often have frost on their sides and clouds of vapour drifting off them.","A third kind, called hypergolic propellants, catch fire the instant they touch each other, with no spark needed. They are poisonous and must be handled with great care, but they are very reliable. The Apollo service module engine and both engines of the lunar module used them, because an engine that had to fire to get astronauts off the Moon or out of lunar orbit could not be allowed to fail to light.","So which is better? It depends on the job. Engineers often mix the two. The Space Shuttle lit its two solid boosters and its three liquid-hydrogen main engines together: the solids gave a huge shove for the first two minutes, then dropped away, while the more efficient liquid engines kept going all the way to orbit. Small satellites are often nudged around by tiny liquid thrusters, while missiles that must be ready in seconds usually use solids. A good rocket designer chooses the right food for each part of the trip."]},{"heading":"Inside the Engine","paragraphs":["Let's take a tour of a liquid-fuel engine, using the mighty F-1 as our example. It stood about 5.6 metres tall, weighed about 8.4 tonnes, and on its own produced about 6,770 kilonewtons of thrust, roughly 1.5 million pounds. It first flew on 9 November 1967 on the uncrewed Apollo 4 mission, and it remains the most powerful single-chamber liquid-fuel rocket engine ever flown. Some Russian engines make more thrust, but they do it by sharing their pumps between four combustion chambers.","The first big part is the turbopump. The tanks hold the propellants, but the engine needs them pushed in at enormous pressure and speed. So each F-1 had a turbine, spun by a small burner of its own, connected to two pumps. That turbine produced about 55,000 horsepower, roughly as much as dozens of race cars, and the pumps shoved in roughly 2.5 tonnes of kerosene and liquid oxygen every second. At that rate, an F-1 could have emptied a backyard swimming pool in well under a minute.","The propellants then rush into the combustion chamber, where they spray through an injector plate full of tiny holes, mix and burn. The temperature inside reaches about 3,000 degrees Celsius, hot enough to melt most metals. To stop the engine from melting itself, engineers use a trick called regenerative cooling: cold fuel is first sent through dozens of thin tubes that form the walls of the chamber and nozzle, soaking up heat before it is burned. The F-1's walls were built from hundreds of these tubes brazed together.","Early F-1 engines had a frightening problem called combustion instability: the burning gases sloshed and vibrated so violently that the engine could tear itself apart in a fraction of a second. Engineers tested it by setting off small bombs inside running engines to see if the shaking would calm down. After years of work and many redesigns of the injector plate, with baffles added to break up the waves, the F-1 became stable and safe.","Finally, there is the nozzle, the giant bell shape at the bottom. You might think the bell is just a funnel, but it does something clever. The hot gas first squeezes through a narrow neck called the throat, where it reaches the speed of sound. Then the nozzle widens out. For gas moving faster than sound, a widening passage makes it speed up even more, as the gas expands and cools. This type of nozzle is named after the Swedish engineer Gustaf de Laval, who designed it for steam turbines in the 1880s. By the time the exhaust leaves the bell, it is moving at roughly 2.5 to 4.5 kilometres per second, many times faster than a rifle bullet. The faster the exhaust, the harder it pushes the rocket.","Nozzle size depends on where the engine works. Near the ground, air pressure pushes back on the exhaust, so first-stage nozzles are fairly short. In the near-vacuum of space, a much bigger bell can stretch the gas further and get more push, which is why upper-stage engines often have enormous, thin nozzles that look almost too big for them."]},{"heading":"The Fuel Problem","paragraphs":["Here is the strangest thing about rockets: they are mostly fuel. A fully loaded Saturn V weighed about 2,900 tonnes, and roughly 90 percent of that was propellant. The metal tanks, engines, computers, spacecraft and astronauts together made up only a small slice. A Falcon 9 today is similar. In fact, a big rocket is a bit like an egg: a thin shell wrapped around a huge amount of liquid. Some rockets have tank walls so thin that they need to be pressurised, like a balloon, to keep from crumpling under their own weight.","Why so much fuel? Remember Konstantin Tsiolkovsky and his rocket equation from Part 4. The idea is simple to say: the speed a rocket can reach depends on two things, how fast its exhaust shoots out, and how much of the rocket is fuel compared with what is left when the fuel is gone. Engineers call the second number the mass ratio: the full rocket's mass divided by its empty mass.","The catch is that the speed grows only slowly as you add fuel, following a mathematical curve called a logarithm. Every extra bit of fuel also has to lift itself and all the fuel still waiting above it. Doubling the fuel does not double the speed. To go from orbit speed to Moon speed, or to reach orbit at all, you need a staggering amount of propellant.","Let's put in some numbers. To get into low Earth orbit, a rocket must reach about 7.8 kilometres per second sideways. But it also loses speed fighting gravity on the way up and pushing through air, so in total it needs to make about 9 to 10 kilometres per second of speed change. With exhaust moving at about 3 kilometres per second, the rocket equation says the full rocket must weigh more than 20 times as much as the empty one. No one can build a single tank-and-engine that light and still strong enough. That is the fuel problem, and for many years people thought it made spaceflight impossible."]},{"heading":"Dropping Dead Weight","paragraphs":["The answer is staging, an idea described by the Polish-Lithuanian artillery expert Kazimierz Siemienowicz in 1650 and worked out for spaceflight by Tsiolkovsky with his \"rocket trains\". Instead of one huge rocket, you stack several rockets on top of each other. When the bottom one runs out of fuel, you throw it away, empty tanks, heavy engines and all, and light the next one. Each new stage only has to push what is left above it, so it starts its job much lighter. It is like a team of runners in a relay race, except that each runner is also carrying the next runner on their back.","The Saturn V shows how it works. Its first stage, the S-IC, held about 2,000 tonnes of kerosene and liquid oxygen. Its five F-1 engines burned all of it in only about two and a half minutes, more than 12 tonnes every second, lifting the rocket to about 66 kilometres high and nearly 10,000 kilometres per hour. Then small explosive charges cut it loose, and little rockets pushed it away. The empty stage, as tall as a 14-storey building, fell into the Atlantic Ocean.","Next, the second stage, the S-II, lit its five J-2 hydrogen engines and burned for about six minutes. By the time it was dropped, the rocket was well above the atmosphere and almost at orbit speed. Then the third stage, the S-IVB, with its single J-2, fired for about two and a half minutes to reach orbit. It stayed attached, and later its engine was restarted for the big burn that sent the astronauts towards the Moon. After that, it too was cast off.","By the time an Apollo spacecraft reached the Moon, the 2,900-tonne monster that sat on the launch pad had shrunk to about 45 tonnes: the command module, service module and lunar module. The lunar module itself had two stages: the descent stage stayed on the Moon as a launch pad while the lighter ascent stage blasted off. And of all of it, only the command module, a cone about 3.9 metres wide, came back to Earth.","Staging is still used on almost every rocket that reaches orbit. Rockets like the Falcon 9 have two stages; others strap extra boosters to their sides that fall away first, as the Space Shuttle's solid boosters did. Throwing away stages works, but it is wasteful, a bit like flying across the world in a jumbo jet and then throwing the plane away after landing."]},{"heading":"Ride Along: Ten Minutes in the Life of a Rocket","paragraphs":["Let's put all of these pieces together and imagine riding a big liquid-fuel rocket from the launch pad, second by second. A few hours before launch, the tanks are filled with super-cold liquid oxygen and fuel. Vapour streams off the sides like steam from a kettle. The astronauts climb in and strap themselves into couches shaped to their bodies, lying on their backs so that the push of launch presses them into their seats rather than draining blood from their heads.","About eight or nine seconds before liftoff, the turbopumps spin up and the engines ignite. Computers check that every engine is running properly; if not, they shut everything down before the clamps let go. At zero, the rocket rises. At first it climbs slowly, because its thrust is only a little greater than its weight. But every second it burns tonnes of propellant and gets lighter, while the engines keep pushing just as hard, so it speeds up faster and faster.","About a minute or so after launch, the rocket passes through a moment engineers call \"Max Q\", short for maximum dynamic pressure. The rocket is now moving fast through air that is still fairly thick, so the air presses harder on its body than at any other time. Some rockets even throttle their engines down briefly to ease the strain. Higher up, the air thins out quickly and the stress drops.","Meanwhile, the guidance computer is slowly tipping the rocket over, from pointing straight up to pointing more and more sideways. This is called the gravity turn. Remember that orbit is mostly about sideways speed, about 7.8 kilometres per second. Going straight up wastes fuel fighting gravity, so the rocket climbs out of the thick lower air first and then spends most of its effort speeding up along the horizon.","Just before the first stage runs dry, the astronauts are pushed back hardest of all, because the nearly empty rocket is so light that the same thrust speeds it up much more quickly. On Apollo this reached about four times normal gravity. Then the engines cut off, the stage separates, and for a moment the crew lurches forward before the next stage lights. On some rockets the nose fairing that protected the cargo also falls away now, since there is no longer enough air to harm it. A few more minutes later, the last stage shuts down, everything goes quiet, and pencils, checklists and dust begin to float. The crew is in orbit, falling around the Earth."]},{"heading":"Keeping It Pointed the Right Way","paragraphs":["A rocket is tall, thin and top-heavy, and it is being pushed from the bottom. Try balancing a broomstick upright on your hand: that is the steering problem rockets face. Without constant small corrections, a rocket would tip over and tumble. Engineers have invented several ways to keep it on course.","Fins are the oldest method. Like the feathers on an arrow, they keep a rocket pointing into the airflow. William Hale's rockets in the 1800s were made to spin instead, which kept them steady like a spinning top or a well-thrown football. The Saturn V had four fins at its base too. But fins only work in thick air, and they cannot actively steer at low speed or in space.","The German V-2 used small heat-proof vanes made of graphite that stuck into the exhaust stream, deflecting the gas to turn the rocket. Most modern rockets use a smarter method called gimballing: the whole engine is mounted on a pivot, like a ball joint, and powerful hydraulic arms tilt it a few degrees. Pointing the thrust slightly off-centre swings the rocket's nose the other way. On the Saturn V's first stage, the four outer F-1 engines could gimbal while the centre one was fixed.","But how does a rocket know which way it is pointing? Robert Goddard experimented with gyroscopes in the 1930s. A gyroscope is a fast-spinning wheel that resists being tilted, so it acts like a steady reference even as the rocket shakes and turns. Accelerometers measure how the rocket speeds up in each direction. Together, they form an inertial guidance system, which works without seeing the stars or getting signals from the ground.","On the Saturn V, these instruments sat in a ring about one metre tall called the Instrument Unit, between the third stage and the spacecraft. Inside was a guidance computer that checked the rocket's position many times a second and sent commands to gimbal the engines. Modern rockets also use GPS, and the Falcon 9's first stage uses grid fins, folding lattice paddles, to steer itself back to a landing pad. In space, where fins are useless, small thrusters puff gas to turn a spacecraft, a system called reaction control."]},{"heading":"Coming Home Through Fire","paragraphs":["Getting up is only half the story. A spacecraft coming home is moving incredibly fast. A capsule returning from low Earth orbit hits the top of the atmosphere at about 7.8 kilometres per second. One returning from the Moon, like Apollo, arrived at up to about 11 kilometres per second, roughly 40,000 kilometres per hour, fast enough to cross the United States in about seven minutes. All that speed has to be lost before splashdown, and it turns into heat.","Many people think re-entry heat comes mainly from friction, the way your hands get warm when you rub them together. In fact, most of it comes from compression. The capsule is moving so fast that the air in front of it cannot get out of the way. It piles up and gets squashed into a thin layer just ahead of the spacecraft, called a shock layer. When you squeeze gas very hard and very fast, it gets very hot; you may have felt a bicycle pump warm up while pumping a tyre. In the shock layer the air can reach several thousand degrees Celsius, and it glows as a blazing plasma.","In the early 1950s, two American engineers at NACA, NASA's predecessor, H. Julian Allen and Alfred Eggers, discovered something surprising. A pointed, streamlined shape was the worst choice, because it kept the shock wave pressed tight against the vehicle. A blunt, rounded shape pushed the shock wave forward, leaving a cushion of hot gas that carried most of the heat away into the air. That is why space capsules, from Mercury to Apollo to Orion and Soyuz, come in base-first with their broad, rounded bottoms facing forward.","The bottom is covered with a heat shield. Apollo used an ablative shield, a material designed to char, melt and flake away slowly. The command module's shield was made from a resin called Avcoat packed by hand into a honeycomb of hundreds of thousands of tiny cells. As its surface burned away, it carried the heat off with it, a bit like how sweat cools you as it evaporates. The astronauts inside stayed at a comfortable temperature, even though the shield's outer surface reached around 2,700 degrees Celsius. Today's Orion capsule uses an updated version of the same material. The Space Shuttle used a different idea: reusable tiles and panels that could survive the heat many times without burning away.","The angle of re-entry also has to be just right. Come in too steeply and the heating and slowing down would be deadly; come in too shallowly and the capsule could skip off the atmosphere like a flat stone on a pond. Apollo's safe \"corridor\" was only a couple of degrees wide. As it slowed down, the crew felt several times their normal weight. For a few minutes, the glowing plasma around the capsule blocked all radio signals, a nervous silence called blackout.","The final step is the parachutes. After the air has slowed the capsule to a few hundred kilometres per hour, small drogue parachutes pop out to steady it, then the main parachutes open. Apollo used three main parachutes, each about 25 metres across, and was designed to land safely even if one failed, which is exactly what happened on Apollo 15. The capsule splashed into the ocean at about 35 kilometres per hour, and the crew were collected by ship. Russian Soyuz capsules land on the ground instead; just before touchdown, small rockets fire for a fraction of a second to soften the bump.","So every Apollo flight followed a pattern: a 110-metre rocket, almost all fuel, burned and threw away its stages one after another, and in the end only a small, scorched cone came home. It worked brilliantly, but it was enormously expensive. Every launch threw away an entire Saturn V. Engineers began to ask: could we build a spaceship that flies to orbit, comes back and flies again, like an aeroplane?"]}],"deepDive":"The rocket equation, published by Tsiolkovsky in 1903, is usually written as delta-v = ve x ln(m0/mf), where delta-v is the change in speed, ve the effective exhaust velocity, m0 the starting mass and mf the final mass. Engineers often quote engine efficiency as specific impulse, measured in seconds, which is the exhaust velocity divided by standard gravity (9.81 m/s2). The F-1 burning RP-1 and liquid oxygen managed about 263 seconds at sea level, while the hydrogen-burning J-2 reached about 420 seconds in vacuum. Hydrogen wins on efficiency because its exhaust molecules are very light, but liquid hydrogen is roughly one-eleventh as dense as kerosene, so its tanks and stages are bulky and the structure weighs more; this is why many rockets use dense kerosene in the first stage, where raw thrust matters, and hydrogen higher up. Reaching low Earth orbit needs about 9.3 to 10 km/s of delta-v once gravity losses and air drag are added to the 7.8 km/s orbital speed. With an exhaust velocity of 3 km/s, that implies a mass ratio above about 20, which is beyond realistic single-stage structures with useful payloads, the reason staging dominates. The nozzle is a converging-diverging de Laval design: below the speed of sound, narrowing a pipe speeds up the flow, but once the flow is supersonic, widening it accelerates the gas further while its pressure and temperature fall. A nozzle performs best when its exit pressure matches the outside pressure, so sea-level engines use smaller expansion ratios than vacuum engines. On re-entry, H. Julian Allen and Alfred Eggers' blunt-body insight at NACA Ames (1951 to 1953) showed that a detached bow shock dumps most of the energy into the air rather than the vehicle. At lunar-return speeds, radiation from the hot shock layer becomes a significant part of the heating, not just convection. Ablative shields like Apollo's Avcoat absorb heat by pyrolysis, as the resin decomposes into gases that thicken the boundary layer and block some incoming heat, leaving a protective char. On Artemis I in 2022, Orion's Avcoat shield lost unexpected chunks of char during its skip entry, which NASA traced to gases trapped inside the material; engineers changed the entry path for later flights.","funFact":"Each of the Saturn V's five F-1 engines pumped about 2.5 tonnes of kerosene and liquid oxygen into its combustion chamber every second.","check":{"q":"What mainly heats a spacecraft as it comes back into the atmosphere?","a":"Air being squeezed (compressed) in front of it","wrong":["Friction from rubbing against the air","Sunlight shining on the capsule","The capsule's engines firing"]},"sources":[{"title":"Rockets and rocket launches, explained","publisher":"National Geographic","url":"https://www.nationalgeographic.com/science/article/rockets-and-rocket-launches-explained"},{"title":"Most powerful single-chamber liquid-fuelled rocket engine","publisher":"Guinness World Records","url":"https://www.guinnessworldrecords.com/world-records/113427-most-powerful-single-chamber-liquid-fuelled-rocket-engine"},{"title":"Man in Space: Saturn V Launch Vehicle (National Historic Landmark theme study)","publisher":"US National Park Service (via NPS History)","url":"https://www.npshistory.com/publications/nhl/theme-studies/man-in-space/space12.htm"},{"title":"Command Module, Apollo 11","publisher":"Smithsonian National Air and Space Museum","url":"https://airandspace.si.edu/collection-objects/command-module-apollo-11/nasm_A19700102000"},{"title":"Why NASA's crew capsule had heat shield issues during Artemis I","publisher":"Popular Science","url":"https://www.popsci.com/science/why-nasas-crew-capsule-had-heat-shield-issues-during-artemis-i/"},{"title":"Rocketdyne F-1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Rocketdyne_F-1"},{"title":"Saturn V","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Saturn_V"},{"title":"Apollo command and service module","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Apollo_command_and_service_module"}],"photos":[{"src":"img/deep/rockets/14-1.jpg","alt":"A Rocketdyne F-1 engine, the kind that powered the Saturn V first stage, on display at the Air Zoo museum.","file":"F1 Engine.jpg","url":"https://commons.wikimedia.org/wiki/File:F1_Engine.jpg","author":"Varnav","license":"Public domain"},{"src":"img/deep/rockets/14-2.jpg","alt":"Apollo 11 seen from a tracking plane as the spent first stage (S-IC) falls away and the second stage fires.","file":"ALOTS image of Apollo 11 S-IC separation.jpg","url":"https://commons.wikimedia.org/wiki/File:ALOTS_image_of_Apollo_11_S-IC_separation.jpg","author":"NASA","license":"Public domain"},{"src":"img/deep/rockets/14-3.jpg","alt":"A burned piece of the Apollo 10 command module heat shield, scorched during re-entry, in a museum display.","file":"Stafford Air & Space Museum, Weatherford, OK, US (16).jpg","url":"https://commons.wikimedia.org/wiki/File:Stafford_Air_%26_Space_Museum,_Weatherford,_OK,_US_(16).jpg","author":"Bubba73","license":"CC BY-SA 3.0"}],"words":3805},{"n":15,"title":"Space Stations and the Space Shuttle","when":"1971 – 2011","summary":"After the Moon, people wanted to LIVE in space, so they built houses in orbit called space stations. Then America built the Space Shuttle, a spaceship with wings that landed on a runway like a giant glider and flew again and again. It launched telescopes, carried the first American women and Black astronauts to space, and taught us hard lessons about safety.","sections":[{"heading":"A House in the Sky: Salyut 1","paragraphs":["Landing on the Moon was like a sprint: a few days there, a few days back, splashdown, parade. But scientists knew that if humans were ever going to explore the solar system properly, they needed to learn something much harder. They needed to learn how to live in space for weeks and months. How do you sleep, eat, wash, work and stay healthy when everything floats? The only way to find out was to build a home in orbit. That home is called a space station: a spacecraft big enough to live in, which stays in orbit for years while crews come and go.","The Soviet Union got there first. On 19 April 1971 a powerful Proton rocket roared away from the Baikonur Cosmodrome in Kazakhstan carrying Salyut 1, the world's first space station. Salyut means 'salute' or 'fireworks' in Russian. The launch had been planned for 12 April, exactly ten years after Yuri Gagarin's flight, but technical problems delayed it by a week. Salyut 1 was a metal tube about 16 metres long, longer than a city bus, weighing around 18 tonnes. It had solar panels sticking out like wings, a docking port at one end, and inside there was room for a small crew, scientific instruments and even a telescope.","The first crew to try to move in had bad luck. In April 1971 the Soyuz 10 spacecraft reached the station and touched its docking port, but the latches would not lock tightly. The cosmonauts could not open the hatch, so after a few hours they had to fly home without ever going inside. Engineers worked fast, and in June the next crew set off on Soyuz 11: Georgy Dobrovolsky, the commander, Vladislav Volkov and Viktor Patsayev. On 7 June 1971 they docked successfully, opened the hatch, and floated into the first house in space.","Then came the tragedy. Late on 29 June 1971 the three men climbed back into their Soyuz, undocked and began the trip home. As the spacecraft separated into its parts before re-entry, a small valve that was supposed to stay shut until much later was jolted open. Air rushed out of the cabin into the vacuum of space in less than a minute. The cosmonauts were not wearing spacesuits, because the cabin was too small to fit three people in suits, and there was no way to close the valve in time. When the capsule landed gently on its parachute in Kazakhstan and the recovery team opened the hatch, they found that all three men had died. They are still the only people known to have died above the Kármán line, in space itself.","Afterwards, Soviet engineers made a firm rule: cosmonauts must wear pressure suits during launch and landing. Salyut 1 itself was steered into the Pacific Ocean on 11 October 1971, after about 175 days in orbit, and more Salyut stations followed."]},{"heading":"Skylab: A Workshop Made from a Moon Rocket","paragraphs":["America's first space station had a clever origin. When the last Apollo Moon missions were cancelled, NASA had spare Saturn V rockets. Engineers took the empty third stage of one of them, the giant fuel tank called the S-IVB, and turned it into a home. Instead of filling it with liquid hydrogen, they filled it with sleeping cabins, a kitchen table, a shower, an exercise bike, cupboards of food and a whole observatory for studying the Sun. They called it Skylab.","Skylab was launched on 14 May 1973 on the very last Saturn V ever to fly. It was huge for its time, about 25 metres long and weighing around 77 tonnes, with roughly as much living space as a small house. But the launch went badly wrong. About a minute after liftoff, a thin metal shield designed to protect the station from tiny space rocks and the heat of the Sun was torn away by the rushing air. It ripped off one of the two big solar panel wings and jammed the other one shut. Once in orbit, Skylab had very little electrical power, and without its shield the inside started to bake in the sunlight, with temperatures reportedly climbing above 50 degrees Celsius.","The first crew, Pete Conrad, Joseph Kerwin and Paul Weitz, launched on 25 May 1973 with a new job: rescue the station. They had brought a folding sunshade that worked like a giant umbrella. They pushed it out through a small airlock in the side of Skylab and opened it over the hot outer wall. Slowly, the temperature inside fell to a comfortable level. Then, on a daring spacewalk, Conrad and Kerwin used cutting tools and a long pole to free the jammed solar wing. When it finally swung open, power flowed into the station again. It was the first time astronauts had repaired a crippled spacecraft in orbit, and it showed how valuable human hands and brains could be in space.","Over the next nine months three crews lived aboard Skylab. The second crew stayed 59 and a half days and the third crew, from 16 November 1973 to 8 February 1974, stayed 84 days, a record that would last for years. Skylab's crews took tens of thousands of photographs of the Sun with the station's special telescopes, capturing huge solar flares and loops of glowing gas. They photographed Earth's forests, crops and storms, and studied what long stays in weightlessness do to the heart, muscles and bones.","After the last crew left, NASA hoped that a Space Shuttle might one day boost Skylab higher. But the Shuttle was not ready in time, and the thin upper air slowly dragged the station down. On 11 July 1979 Skylab re-entered the atmosphere. Most of it burned up, but some pieces fell into the Indian Ocean and scattered across a remote, thinly populated part of Western Australia. Nobody was hurt, and some fragments ended up in museums."]},{"heading":"From a Handshake to Mir","paragraphs":["For almost twenty years the space race had been a contest between rivals. But in the early 1970s the leaders of the United States and the Soviet Union agreed to try a joint mission, the Apollo–Soyuz Test Project. There was a practical problem: the two spacecraft had different docking systems and even different air inside. Apollo used pure oxygen at low pressure, while Soyuz used an Earth-like air mix, and switching too fast could give astronauts the 'bends', the painful illness divers get when pressure changes quickly. So the Americans built a special docking module, a short tube that worked as an adapter and an airlock at the same time.","On 15 July 1975 both spacecraft launched on the same day, Soyuz 19 from Baikonur and, about seven and a half hours later, the last Apollo spacecraft ever flown from Florida. The Soviet crew was Alexei Leonov, the cosmonaut who had made the first spacewalk, and engineer Valery Kubasov. The American crew was Thomas Stafford, Vance Brand and Deke Slayton, one of the original Mercury Seven astronauts who had finally made it to space after years grounded by a heart problem.","On 17 July 1975 the two ships docked. A few hours later Stafford and Leonov reached through the open hatch and shook hands, while television viewers around the world watched. The crews visited each other's spacecraft, shared meals, swapped gifts, and practised each other's languages: the Americans spoke Russian and the Soviets spoke English, which made for some funny moments. They stayed linked together for about two days before going their separate ways.","Meanwhile the Soviets kept improving their Salyut stations. Salyut 6, launched in 1977, and Salyut 7, launched in 1982, had two docking ports instead of one. That meant robot cargo ships called Progress, first flown in 1978, could deliver food, water, air, fuel and mail while a crew stayed aboard, so crews could now live in orbit for half a year or more. Visitors came too, including Vladimír Remek of Czechoslovakia in 1978, the first person in space from a country other than the USSR or the USA, and in 1984 Rakesh Sharma, the first Indian in space.","On 20 February 1986 the Soviet Union launched the core of a new kind of space station. It was called Mir, a Russian word that can mean both 'peace' and 'world'. The core module looked a lot like a Salyut, but with one big difference: at its front end was a ball-shaped docking hub with several ports. Mir was designed to grow. Over the next ten years, new modules were launched one by one and attached to the hub, like rooms being added to a house. A small docking module was carried up by an American Space Shuttle in 1995. Mir became the first truly modular space station, with seven pressurised modules, and it weighed about 130 tonnes when it was complete.","Mir was also the place where people pushed the limits of the human body. The doctor-cosmonaut Valeri Polyakov lived aboard for 437 days in a row in 1994 and 1995, carefully studying what happened to his own heart, muscles and mind. It is still the longest single spaceflight by any human. When he came back to Earth, he insisted on walking the few steps from the capsule to a chair by himself, to show that people could survive a trip as long as a journey to Mars.","Between 1994 and 1998 the United States and Russia ran the Shuttle–Mir program. American Space Shuttles flew eleven missions linked to Mir, docking with it nine times, and seven American astronauts lived aboard for months, side by side with Russian crewmates. The first docking, by the Shuttle Atlantis in June 1995, joined two of the biggest spacecraft ever built into a single giant ship. These flights let both countries learn to work together in orbit before building something much bigger.","By 2000 Mir was old, and Russia needed its money and attention for the new International Space Station. On 23 March 2001, after 15 years in orbit, mission controllers fired the engines of a docked Progress ship to slow Mir down. The great station broke apart and burned in the sky over the South Pacific, with the surviving pieces splashing harmlessly into the ocean far from land."]},{"heading":"A Spaceship with Wings","paragraphs":["While the Soviets built stations, NASA wanted a spaceship that could fly to orbit, land on a runway and fly again a few weeks later, instead of throwing away a whole rocket every time. It was called the Space Shuttle.","The Shuttle had three main parts, and you could recognise them from far away. The first was the orbiter, the white winged spaceship with a black belly that looked like a stubby aeroplane. It was about 37 metres long, with a wingspan of about 24 metres, and it carried the crew, usually seven people, plus a cargo hold called the payload bay, 18 metres long and 4.6 metres wide, big enough to carry a bus. At its tail were three main engines that burned liquid hydrogen and liquid oxygen.","Those engines did not carry their own fuel. It came from the second part, the huge orange external tank, about 47 metres tall, which the orbiter rode on like a rider on a horse. Inside were two separate tanks, a big one for liquid hydrogen and a smaller one for liquid oxygen, kept at hundreds of degrees below zero. The third part was a pair of tall, thin solid rocket boosters strapped to the sides of the tank. Each was about 45 metres tall. Like giant fireworks, they burned a rubbery solid propellant and provided most of the push at liftoff, well over two-thirds of the thrust.","A launch went like this. The main engines lit a few seconds before liftoff, then the boosters ignited and the whole stack leapt off the pad. About two minutes later, the empty boosters dropped away and floated down to the Atlantic Ocean on parachutes, where ships picked them up so they could be cleaned and refilled. About eight and a half minutes after liftoff, the main engines shut down and the external tank was dropped. It was the only part not reused; it fell back and broke up over a remote part of the ocean.","Coming home was the most unusual part. The orbiter fired small engines to slow down, then dropped into the atmosphere belly-first. About 24,000 heat-resistant tiles, made mostly of a light silica foam, protected the underside. The nose and the front edges of the wings, the hottest parts, were covered with a tough grey material called reinforced carbon-carbon. After re-entry, the orbiter had no working engines at all. It was a glider, a very heavy one, and the commander had exactly one chance to line up with the runway. It touched down at more than 300 kilometres per hour and used a parachute to help it stop.","The first Shuttle flight launched on 12 April 1981, exactly 20 years after Yuri Gagarin's flight. The orbiter was Columbia, and the crew was just two people: commander John Young, a veteran who had walked on the Moon on Apollo 16, and pilot Robert Crippen. It was the first time NASA had ever put people aboard a new kind of rocket on its very first flight, with no uncrewed test first. After 37 orbits in just over two days, Columbia glided down onto a dry lake bed at Edwards Air Force Base in California on 14 April. Thousands of people cheered as the spaceship rolled to a stop.","Five orbiters flew in space: Columbia, Challenger, Discovery, Atlantis and Endeavour, which was built later to replace Challenger. A test orbiter called Enterprise, named after the starship in Star Trek after fans wrote in, never reached space but made gliding tests in 1977."]},{"heading":"New Faces in Space","paragraphs":["In 1978 NASA chose a new group of astronauts that, for the first time, included women and people of colour. One of them was Sally Ride, a physicist from California who had also been a talented tennis player. On 18 June 1983 she launched aboard Challenger on mission STS-7 and became the first American woman in space. She was 32, and she operated the Shuttle's robotic arm, a long jointed arm built in Canada and nicknamed Canadarm, to release a satellite and grab it again.","Just two months later, on 30 August 1983, Challenger launched again on STS-8, this time at night, the first night launch of the Shuttle program. Aboard was Guion Bluford, an engineer and air force fighter pilot from Philadelphia who had flown 144 combat missions. He became the first African American in space. Bluford went on to fly four Shuttle missions in total.","On 12 September 1992, the orbiter Endeavour lifted off with Mae Jemison aboard. Jemison was a doctor, an engineer and a dancer who had worked as a medical officer in the Peace Corps in West Africa. She became the first African American woman in space. On her mission she studied, among other things, how frogs' eggs developed in weightlessness, and, as a big Star Trek fan, she opened her work shifts with the famous line 'Hailing frequencies open'. The same flight carried Mamoru Mohri, the first Japanese astronaut to fly on a Shuttle."]},{"heading":"Fixing Hubble's Blurry Eye","paragraphs":["Above the air, starlight is not blurred by the wobbling atmosphere that makes stars twinkle. That is why astronomers had dreamed for decades of a big telescope in orbit. On 24 April 1990 the Shuttle Discovery carried the Hubble Space Telescope into space, and the next day astronauts released it from the robotic arm. Hubble is about the size of a school bus, roughly 13 metres long, and its main mirror is 2.4 metres across. It is named after Edwin Hubble, the astronomer who showed in the 1920s that the universe is full of galaxies and is expanding.","But when the first pictures came back, astronomers' hearts sank. The images were fuzzy. Engineers discovered that the main mirror had been ground to slightly the wrong shape. The mistake was tiny, about 2 micrometres at the edges, about one fiftieth of the thickness of a human hair, but for a precision telescope it was enough to smear the light. This kind of flaw is called spherical aberration.","Here the Shuttle showed what it could do that no throwaway rocket could. Hubble had been designed so that astronauts could visit and swap its parts. In December 1993 the Shuttle Endeavour flew the first servicing mission, STS-61. Over five spacewalks lasting more than 35 hours in total, astronauts installed a new camera called the Wide Field and Planetary Camera 2, whose optics contained a correction for the mirror's flaw, rather like a prescription for glasses. They also added a box of small corrective mirrors called COSTAR to fix the light going to the other instruments, and they replaced the solar panels and gyroscopes.","In January 1994 the first new images arrived, and they were sharp and stunning. Hubble went on to become one of the most productive scientific instruments in history. It helped measure how fast the universe is expanding, photographed galaxies more than ten billion light-years away, and watched comet Shoemaker–Levy 9 crash into Jupiter in 1994. Shuttle crews visited Hubble five times in all, the last in 2009, each time leaving it better than before. Hubble is still working today, more than 35 years after launch."]},{"heading":"Two Sad Days","paragraphs":["The first was 28 January 1986. Challenger was ready to launch on mission STS-51-L from Florida. Aboard were commander Dick Scobee, pilot Michael Smith, mission specialists Ronald McNair, Ellison Onizuka and Judith Resnik, engineer Gregory Jarvis, and Christa McAuliffe, a high school teacher from New Hampshire. McAuliffe had been chosen from more than 11,000 applicants to be the first teacher in space, and she planned to teach lessons to schoolchildren from orbit. Because of her, millions of students were watching on television in their classrooms.","The morning was unusually cold for Florida, about 2 degrees Celsius, and icicles hung from the launch tower. Each solid rocket booster was built in segments, and the joints between them were sealed with rubber rings called O-rings. Engineers from the company that made the boosters had worried that cold rubber becomes stiff and might not seal properly. They had argued the night before that the launch should wait for warmer weather, but managers decided to go ahead.","At 11:38 in the morning Challenger lifted off. Hidden from view, hot gas began leaking through a joint on the right booster, like a blowtorch. About 73 seconds into the flight, the flame weakened the external tank and the structure holding it, the tank came apart, and the orbiter was torn apart by the enormous forces of the air rushing past at nearly twice the speed of sound. A huge cloud appeared in the sky. All seven astronauts were lost.","A special group called the Rogers Commission investigated. One of its members, the famous physicist Richard Feynman, showed the problem in the simplest possible way on live television: he squeezed a piece of O-ring rubber in a clamp, dipped it in a glass of ice-cold water, and showed that it did not spring back. The commission also found that NASA's decision-making had not listened properly to the engineers' warnings. The Shuttle was grounded for almost three years while the boosters were redesigned, and it returned to flight with Discovery in September 1988.","The second sad day was 1 February 2003. Columbia, the first orbiter ever to fly, was coming home from a 16-day science mission, STS-107, with more than 80 experiments aboard. Its crew was commander Rick Husband, pilot William McCool, Michael Anderson, David Brown, Laurel Clark, Kalpana Chawla and Ilan Ramon. Chawla had been born in Karnal, India, and was the first woman of Indian birth to fly in space. Ramon was the first astronaut from Israel. Just over 81 seconds after launch, on 16 January, a briefcase-sized piece of hard foam insulation had broken off the external tank and struck the front edge of Columbia's left wing. Nobody on the ground realised how badly it had damaged the wing's protective carbon panels.","When Columbia re-entered the atmosphere, superheated air poured in through the hole in the wing and slowly melted the structure inside. Over Texas, only about 16 minutes before landing, the orbiter broke apart. All seven astronauts were lost. Investigators found that foam had hit the Shuttle on earlier flights too, and that it had come to be treated as a normal nuisance instead of a serious danger.","After Columbia, every Shuttle carried a long boom with cameras and lasers so astronauts could inspect the heat shield in orbit, and the crews practised repair techniques. The 14 astronauts lost on Challenger and Columbia are remembered with memorials, schools, craters on the Moon and even asteroids named after them. Their loss changed how NASA thinks about safety, especially the importance of listening when engineers say something is wrong."]},{"heading":"Buran, the Last Landing and What Came Next","paragraphs":["The Soviet Union worried that the American Shuttle might give the United States a military advantage, so it built its own. It was called Buran, which means 'snowstorm', and from the outside it looked so much like the American orbiter that people sometimes mixed up photographs. But there were important differences. Buran had no big main engines of its own. Instead, it rode on the side of a gigantic rocket called Energia, whose own engines and strap-on boosters did all the work of reaching orbit. That meant Energia could also launch other heavy cargo without an orbiter at all.","On 15 November 1988 Buran launched from Baikonur with nobody aboard. It circled Earth twice, re-entered and then, completely under computer control, glided down and landed on a runway at Baikonur, close to its target, in strong crosswinds. It was the first spaceplane ever to fly to orbit and land fully automatically. It was an impressive success. But it was also Buran's only flight. The Soviet Union was running out of money, and after the country broke apart in 1991 there were no funds to continue. The program was cancelled in 1993. Sadly, in 2002 the roof of the hangar where the flown Buran was stored at Baikonur collapsed, destroying it.","The American Shuttle kept flying for another two decades. In its last years, its most important job was building the International Space Station, carrying up big modules, solar panels and trusses in its payload bay and using its robotic arm to fit them together. But after the loss of Columbia, the United States decided the Shuttle had become too old, too expensive and too risky. In 2004 it was announced that the Shuttle would retire once the space station was finished.","The last mission, STS-135, launched on 8 July 2011 with a crew of four: Chris Ferguson, Doug Hurley, Sandra Magnus and Rex Walheim. Atlantis delivered supplies to the space station and, on 21 July 2011, glided down to the runway at the Kennedy Space Center in Florida for the final time.","Altogether the Shuttle flew 135 missions over 30 years. It carried hundreds of astronauts, launched dozens of satellites and space probes, repaired Hubble, and helped build a space station. Today the surviving orbiters are museum pieces: Discovery is at the Smithsonian's Steven F. Udvar-Hazy Center near Washington, D.C., Atlantis is at the Kennedy Space Center in Florida, Endeavour is at the California Science Center in Los Angeles, and Enterprise is aboard the Intrepid Museum in New York. You can stand under them and look up at the scorched tiles on their bellies.","But the most important thing the Shuttle helped create is still flying right now, above your head. Former rivals who had once raced each other to the Moon had shaken hands in orbit, shared Mir, and learned to trust one another. Now they were ready to build together the biggest, most complicated and most expensive thing humans have ever put in space: a station that would never be empty."]}],"deepDive":"Why did the Shuttle, designed to make spaceflight cheap and routine, end up so costly? Historians usually point to compromises made in the early 1970s. NASA first sketched a fully reusable two-stage vehicle: a winged booster with a pilot that would fly back to the launch site, carrying a winged orbiter. Budgets were cut, and the Air Force, whose support NASA needed, demanded a large payload bay and the ability to glide sideways a long way during re-entry. The result was a partly reusable design: an orbiter with expensive, high-performance hydrogen engines, recoverable solid boosters that had to be fished out of the sea and rebuilt, and a throwaway tank. Early plans spoke of around 50 flights a year. In reality the busiest year, 1985, saw nine flights, and the program averaged about 4 to 5 a year. Each orbiter needed months of work on its roughly 24,000 tiles and its three main engines between flights. Counting all development and operations, the program cost on the order of 200 billion US dollars in today's money, which works out to well over a billion dollars per flight. Safety was the other hard lesson. The Shuttle had no launch escape system for most of its climb, and because the orbiter sat beside the tank instead of on top, falling debris such as foam could strike it. Both investigations, the Rogers Commission in 1986 and the Columbia Accident Investigation Board in 2003, concluded that the technical causes were made worse by organisational ones: schedule pressure and a habit of treating repeated small problems as acceptable. The sociologist Diane Vaughan called this the 'normalization of deviance'. Yet the Shuttle also did things no other vehicle could. It could carry about 27 tonnes into low orbit, brought satellites back down for repair, served as a laboratory, and lifted most of the large pieces of the International Space Station. Stations taught a complementary lesson: long-duration flights by Salyut, Skylab and Mir showed that bones and muscles weaken and fluids shift towards the head in weightlessness, but that exercise and careful medicine let people stay healthy for a year or more.","funFact":"Valeri Polyakov's 437 days aboard Mir in 1994 and 1995 is still the longest single trip any human has made in space.","check":{"q":"What caused the Challenger accident in January 1986?","a":"A rubber O-ring seal in a solid rocket booster failed in cold weather, letting hot gas escape","wrong":["A piece of foam hit the wing","The main engines ran out of fuel","A meteoroid hit the cabin"]},"sources":[{"title":"Space Shuttle","publisher":"NASA","url":"https://www.nasa.gov/space-shuttle/"},{"title":"Skylab","publisher":"NASA","url":"https://www.nasa.gov/mission/skylab/"},{"title":"STS-107","publisher":"NASA","url":"https://www.nasa.gov/mission/sts-107/"},{"title":"Servicing Mission 1","publisher":"NASA Science","url":"https://science.nasa.gov/mission/hubble/observatory/missions-to-hubble/servicing-mission-1/"},{"title":"Sally Ride, First American Woman in Space","publisher":"NASA","url":"https://www.nasa.gov/history/sally-ride-first-american-woman-in-space/"},{"title":"Salyut 1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Salyut_1"},{"title":"Mir","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Mir"},{"title":"Space Shuttle Challenger disaster","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Space_Shuttle_Challenger_disaster"}],"photos":[{"src":"img/deep/rockets/15-1.jpg","alt":"Space Shuttle Columbia lifts off from Pad 39A on STS-1, the first Shuttle mission, 12 April 1981.","file":"Space Shuttle Columbia launching.jpg","url":"https://commons.wikimedia.org/wiki/File:Space_Shuttle_Columbia_launching.jpg","author":"NASA","license":"Public domain"},{"src":"img/deep/rockets/15-2.jpg","alt":"The Mir space station above Earth, showing its modules and solar panels, photographed from Shuttle Discovery in 1998.","file":"Mir on 12 June 1998edit1.jpg","url":"https://commons.wikimedia.org/wiki/File:Mir_on_12_June_1998edit1.jpg","author":"Original image: NASA/Crew of STS-91Retouched image: Thegreenj","license":"Public domain"},{"src":"img/deep/rockets/15-3.jpg","alt":"Astronauts Story Musgrave and Jeffrey Hoffman work on the Hubble Space Telescope during the first servicing mission, December 1993.","file":"Astronauts Musgrave and Hoffman during First STS-61 Extravehicular Activity (28051107481).jpg","url":"https://commons.wikimedia.org/wiki/File:Astronauts_Musgrave_and_Hoffman_during_First_STS-61_Extravehicular_Activity_(28051107481).jpg","author":"NASA Hubble Space Telescope","license":"Public domain"}],"words":4323},{"n":16,"title":"The International Space Station","when":"1998 – today","summary":"Countries that once raced each other teamed up to build the biggest thing ever put in space: the International Space Station. It is as long as a football field, zooms around the whole Earth every hour and a half, and people have lived on it every single day for more than 25 years. Up there, astronauts sleep on the walls, drink recycled water, grow lettuce and do science you cannot do on Earth.","sections":[{"heading":"From Rivals to Partners","paragraphs":["Imagine trying to build a house where every room is made in a different country, nobody can test whether the rooms fit together until they meet, and the building site is flying around the planet at about 28,000 kilometres per hour. That is roughly what it took to build the International Space Station, or ISS.","In the 1980s the United States planned a big station of its own called Freedom, with help from Europe, Japan and Canada. Meanwhile Russia was running Mir and had decades of experience living in orbit. After the Cold War ended in 1991, it made sense to join forces. Russia brought its long-stay knowledge, its reliable Soyuz spacecraft and its Progress cargo ships; the Americans brought the Space Shuttle and a huge budget; Europe, Japan and Canada brought laboratories, robots and skilled astronauts. The Shuttle–Mir flights of the 1990s, described in the last part, were a kind of rehearsal.","The deal was written down in an international treaty called the Intergovernmental Agreement, signed on 29 January 1998. Five space agencies run the station together: NASA for the United States, Roscosmos for Russia, the European Space Agency (ESA), which speaks for many European countries, the Japan Aerospace Exploration Agency (JAXA), and the Canadian Space Agency (CSA). Altogether about 15 countries are partners. Each partner owns and runs its own pieces, and they share out crew time, electricity and supplies by agreement. It is a bit like a block of flats where every family owns its own apartment but everyone shares the lift, the water and the heating.","Building began on 20 November 1998, when a Russian Proton rocket launched the first module from Baikonur in Kazakhstan. It was called Zarya, meaning 'sunrise'. Zarya was built in Russia but paid for by the United States, and in the early days it supplied electricity, steering and storage. Just two weeks later, on 4 December 1998, the Space Shuttle Endeavour carried up Unity, an American connecting module called a node. Using the Shuttle's robotic arm, the crew grabbed Zarya and joined the two together. On 7 December, astronauts Jerry Ross and James Newman made the station's first spacewalk to connect power and data cables between them. Those two modules, one Russian and one American, bolted together in orbit, were the first seed of the station.","In July 2000 the Russian service module Zvezda, meaning 'star', arrived. It contained living quarters, toilets, life-support machines and engines to keep the station in its orbit. Now people could move in.","Over the next eleven years dozens of pieces followed. The American laboratory Destiny arrived in February 2001. Europe's laboratory Columbus, built in Italy and Germany, came in February 2008. Japan's laboratory Kibo, the largest single module on the station, arrived in stages in 2008 and 2009; it has a small 'porch' outside where experiments can sit directly in space. Long metal beams called trusses, carrying gigantic solar panels and radiators, were added piece by piece. In 2010 a dome-shaped window module called the Cupola was installed, with seven windows that give astronauts the best view of Earth ever built into a spacecraft. Building the station took more than 40 launches, including 36 Space Shuttle assembly flights, plus well over a hundred spacewalks. The newest Russian modules, the Nauka laboratory and the Prichal docking hub, arrived in 2021. Nobody knows the exact total cost, but it is often estimated at well over 100 billion US dollars, making the ISS one of the most expensive objects humans have ever built."]},{"heading":"Never Empty Since 2000","paragraphs":["On 31 October 2000 a Soyuz rocket lifted off from Baikonur carrying three men: the American commander Bill Shepherd and two Russian cosmonauts, Yuri Gidzenko and Sergei Krikalev. You might remember Krikalev as the cosmonaut who was aboard Mir when the Soviet Union broke apart. On 2 November 2000 they docked, opened the hatch and floated in. They were Expedition 1, the first crew to live on the International Space Station.","Here is a remarkable thing. Since that day, there has never been a moment when the station was empty. Crew after crew has arrived and handed over to the next, with no gap at all. That means that since 2 November 2000, there have always been humans living in space. If you are reading this and you were born after that date, you have never lived a single second when every human being was on the ground. Somebody was always up there, sleeping, working or looking down at your town.","Each crew stays for an 'expedition', usually about six months, and the expeditions are numbered. By the mid-2020s the numbers had passed 70. Some astronauts have stayed much longer. In 2015 and 2016 the American Scott Kelly and the Russian Mikhail Kornienko spent nearly a year aboard, about 340 days. In 2022 and 2023 the American Frank Rubio stayed 371 days, the longest single flight by an American, after his planned six months were extended when his Soyuz spacecraft sprang a coolant leak and a replacement had to be sent. The record for the longest single stay ever still belongs to Valeri Polyakov, from his 437 days on Mir.","Today the station usually has a crew of about seven. Many different spacecraft take people and supplies up and down. The Russian Soyuz has carried crews since the very beginning. After the Space Shuttle retired in 2011, Soyuz was for nine years the only way for anyone to reach the station, and American astronauts bought seats on it. Robot cargo ships also visit: Russia's Progress, and over the years Europe's Automated Transfer Vehicle, Japan's HTV, nicknamed Kounotori or 'white stork', and American commercial ships. The story of the private companies whose spacecraft now fly crews from Florida comes later in this Deep Dive.","Hundreds of people from about 26 countries have visited the ISS. They include scientists, doctors, engineers, pilots and a few paying private visitors. Some countries sent their first astronauts there, such as Hazzaa AlMansouri of the United Arab Emirates in 2019. In June 2025 Shubhanshu Shukla, an Indian Air Force pilot flying on a private Axiom mission, became the first Indian to visit the station, and only the second Indian ever to fly in space, 41 years after Rakesh Sharma."]},{"heading":"A Football Field Flying Around the World","paragraphs":["The ISS is huge. From one end to the other it measures about 109 metres, almost exactly the length of an American football field including the end zones, and much longer than the giant Airbus A380 airliner. Most of that width is the main truss, a long backbone of metal beams holding eight enormous solar wings. The station weighs about 420 tonnes, about as much as 300 cars. Its pressurised modules, the parts where people can live and breathe without spacesuits, have about as much space inside as a six-bedroom house, or the inside of a Boeing 747 jumbo jet.","Those solar panels produce up to about 75 to 90 kilowatts of electricity, enough to run dozens of homes. Since 2021, new rolled-out solar arrays have been added on top of the old ones to boost the power as the original panels wear out. Big white panels called radiators get rid of extra heat into space, because in a vacuum there is no air to carry heat away, so a spacecraft has to shed it as invisible infrared light.","The station orbits about 400 kilometres above the ground, roughly the distance from London to Paris, but straight up. It travels at about 7.7 kilometres every second, around 28,000 kilometres per hour. That is fast enough to cross the whole of the United States in about ten minutes. It goes once around the Earth about every 90 minutes, which means astronauts see about 16 sunrises and 16 sunsets every 24 hours. If they looked out of the Cupola at every one, they would never get any sleep.","Remember from Part 10 that the station is not floating in 'no gravity'. At 400 kilometres up, Earth's gravity is still about 90 percent as strong as on the ground. The station and everyone inside it are falling around the Earth together, endlessly, missing the ground because they are moving sideways so fast. That is why the astronauts float.","The station is not perfectly safe from the air, either. Even at 400 kilometres there is a tiny trace of atmosphere, which slowly drags on the station and makes it sink a little lower every day. Every so often, engines on Zvezda or on a docked cargo ship fire to push it back up. The station can also dodge: if a piece of space junk is predicted to pass too close, controllers fire the engines to shift it out of the way. Its walls are lined with special shields, made of layers of metal and fabric spaced apart, that can shatter small specks before they reach the living areas.","You can see the ISS yourself without a telescope. On many clear nights, shortly after sunset or before sunrise, it appears as a very bright, steady star sliding silently across the sky in a few minutes, brighter than any real star. It shines because sunlight reflects off its solar panels while the ground below is already dark. NASA's 'Spot the Station' website and many phone apps tell you exactly when it will pass over where you live. It is a strange and wonderful feeling to wave at it and know that people are waving back, even if they cannot see you."]},{"heading":"A Day in the Life, Upside Down","paragraphs":["What is it actually like to live up there? The station runs on Greenwich Mean Time, the time zone of London, as a compromise between the control centres in Houston, Moscow, Germany, Japan and Canada. A typical weekday starts at about six in the morning, when the crew wakes up, washes, has breakfast and joins a planning call with the ground. Then they work through a detailed timeline of experiments, repairs and exercise, set by mission controllers, until the evening. Weekends are lighter, with time for cleaning, calling family and looking out of the window.","Sleeping is easy in one way: you never need a mattress. Each astronaut has a tiny private cabin about the size of a phone box, with a sleeping bag fastened to the wall, a laptop, a reading light and a few family photographs. Because there is no up or down, it does not matter whether the bag is on a wall, the floor or the ceiling. Astronauts zip themselves in loosely so they do not drift around and bump into things in the night, and some say their arms float up in front of them like a sleepwalker's while they doze. Fans must blow air through every cabin, because in weightlessness warm air does not rise. Without a breeze, the carbon dioxide you breathe out would collect in a bubble around your face.","Food comes from Earth, packed in pouches and cans. Some is dried and needs hot water squirted in; some is heated in a small food warmer; some, like nuts and biscuits, is eaten just as it is. Crews from different countries often swap treats: Russian soups, Japanese curry, European cheeses. Bread is a problem because crumbs float away and can get into equipment or people's eyes, so astronauts eat tortillas instead. Salt and pepper come as liquids, the salt dissolved in water and the pepper in oil, so the grains do not drift around. Fresh fruit arrives on cargo ships and disappears quickly. Many astronauts say food tastes blander in space, probably because fluids shift towards the head and make it feel like having a blocked nose.","Then there is the toilet, the question every child asks. Without gravity, nothing falls downwards, so space toilets use moving air instead, like a gentle vacuum cleaner. Each astronaut has a personal funnel attached to a hose for urine, and a small seat for solid waste, which is sucked into bags and packed into containers that are later loaded into a cargo ship and burned up in the atmosphere. Astronauts train carefully on Earth to use it, with a camera mock-up to check their aim.","The urine does not go to waste. Water is heavy and expensive to launch, so the station's Water Recovery System collects urine, sweat and even the moisture breathed into the air, filters it, boils it and cleans it into drinking water. Astronauts like to joke that 'yesterday's coffee becomes tomorrow's coffee'. For years the system recycled more than 90 percent of the water, and in 2023 NASA announced that new equipment had pushed it to about 98 percent. That kind of recycling will be essential on a trip to Mars, where there will be no resupply ships.","There are no showers. Astronauts wash with wet towels and special no-rinse soap and shampoo, and squeeze water onto their skin, where it clings as a wobbly layer. Brushing teeth means swallowing the toothpaste or spitting it into a towel. Haircuts are done with clippers attached to a vacuum hose, so the hair does not float away. Even crying is different: tears do not roll down your cheeks but collect in a blob around your eyes.","Oxygen to breathe comes mostly from splitting water into hydrogen and oxygen with electricity, and machines scrub carbon dioxide out of the air. Fire is one of the biggest dangers on any spacecraft, so the crew practises emergency drills, and every module has extinguishers and masks."]},{"heading":"Staying Strong Without Gravity","paragraphs":["On Earth, every step you take, every stair you climb and even just standing up works your bones and muscles against gravity. In orbit, that load disappears. The body is clever and lazy at the same time: if a bone or muscle is not being used, it slowly gets rid of it. Before modern exercise machines, astronauts on long missions lost about 1 to 2 percent of the mineral in some of their bones, such as the hips and spine, every month. Their leg and back muscles shrank too, and their hearts got a little weaker because pumping blood around a weightless body is easier.","That is why ISS astronauts exercise for about two hours every day. They have three main machines. The first is a treadmill. To stop themselves floating off it, runners wear a harness attached to elastic bungee cords that pull them down onto the moving belt. The second is an exercise bike called CEVIS, which has no seat: astronauts clip their shoes into the pedals and hold the handlebars. The third and most important is the Advanced Resistive Exercise Device, or ARED. Since there is no gravity to make weights heavy, ARED uses vacuum cylinders, like giant syringes, to create a pulling force of up to a few hundred kilograms. Astronauts can do squats, deadlifts and other weightlifting exercises on it just as they would in a gym.","It works. Since ARED arrived in 2008, crews coming home after six months have kept much more of their bone strength and muscle than earlier space travellers. Some even return with stronger arms than before. Even so, when astronauts land after a long stay, they often feel dizzy and heavy at first and need days or weeks of physical therapy to walk normally again. Some say even holding up their own head feels like hard work for the first day.","Weightlessness changes the body in other ways too. Fluids that gravity normally pulls into your legs float upwards, so astronauts get puffy faces and thin legs, which they call 'puffy face, bird legs'. Their spines stretch out a little, so most astronauts grow by a few centimetres in space and shrink back on Earth. Some develop changes in the shape of their eyes that can blur their vision, a problem doctors are still studying. The inner ear, which senses balance, gets confused at first, and many new astronauts feel a bit sick for their first few days.","One famous experiment used identical twins. In 2015 and 2016 Scott Kelly spent nearly a year aboard the ISS, while his identical twin brother Mark, also an astronaut, stayed on the ground. Because they share the same genes, scientists could compare them to see which changes were caused by space. They found changes in how some of Scott's genes were switched on and off, in his immune system and in his eyes. Most of the changes went back to normal within months of his return, which was encouraging news for anyone planning a long trip to Mars.","Space is also stressful for the mind. Astronauts live in a small space with the same few people for months, far from family, with a busy schedule. To help, they have regular video calls home, private talks with doctors and psychologists, films, music, books and care packages of favourite foods. Many say that looking down at Earth, with its thin glowing blue atmosphere and no borders visible from above, is the best medicine of all. Some astronauts describe a deep change of feeling called the 'overview effect': a sense of how fragile and precious our planet is."]},{"heading":"A Laboratory Like No Other","paragraphs":["The main reason the ISS exists is science. It is a laboratory where gravity is almost switched off, something you cannot do on Earth for more than a few seconds at a time. Over its lifetime, thousands of experiments from more than 100 countries and areas have been run aboard, many of them designed by school students.","Plants are one favourite subject. In a small growth chamber called Veggie, lit by pink and blue LED lights, astronauts have grown lettuce, cabbage, kale and even flowers such as zinnias. On 10 August 2015 the crew ate the first lettuce grown on the American side of the station, a red romaine variety, after cleaning it with sanitising wipes. Later crews grew chili peppers and radishes. Learning how plants find their way without gravity, using light and water instead, helps scientists plan for growing food on long missions, and helps farmers on Earth too.","Fire and fluids behave in fascinating ways in orbit. A candle flame in space is not tall and pointed but round and blue, because hot air does not rise. Experiments discovered so-called cool flames, which burn at much lower temperatures than normal flames and can keep going for minutes in microgravity. Water forms floating spheres that wobble like jelly. Studying these things helps engineers design better engines, fire safety and medical devices.","Medicine benefits as well. Protein crystals, the tiny regular structures scientists use to work out the shape of molecules, often grow larger and more perfect in weightlessness, which helps researchers design new medicines. Studies of astronauts' bones have helped doctors understand osteoporosis, a disease that makes elderly people's bones fragile. In 2016 the astronaut Kate Rubins became the first person to read the DNA of living things in space, using a pocket-sized sequencer, showing that crews could one day identify germs aboard without sending samples home.","Physicists have used the station to do very strange things. In 2018 an instrument called the Cold Atom Lab cooled a cloud of atoms to a tiny fraction of a degree above absolute zero, the coldest possible temperature, and made a Bose–Einstein condensate, sometimes called the fifth state of matter, in orbit for the first time. Outside, a big detector called the Alpha Magnetic Spectrometer has recorded more than 100 billion cosmic-ray particles since 2011, hunting for clues about dark matter. Cameras and sensors on the outside watch Earth's forests, storms, fires and lightning.","Much of the work outside the station is done by robots. The most famous is Canadarm2, Canada's robotic arm, installed in April 2001. It is about 17.6 metres long when fully stretched, with joints like a shoulder, elbow and wrist, and it can move objects weighing up to about 116 tonnes, including whole spacecraft, because in orbit nothing is heavy, although large things still need to be moved slowly and carefully. Canadarm2 has a clever trick: it has a grabbing 'hand' at both ends, so it can let go with one end and grab a new fixture with the other, flipping end over end along the station like an inchworm. Astronauts operating it from inside use it to catch visiting cargo ships out of the sky and berth them to the station, to move spacewalking astronauts around like a cherry-picker crane, and to install new equipment. In 2008 it was joined by Dextre, a two-armed robot 'hand' that can do delicate jobs such as changing batteries, so that astronauts do not have to go outside as often."]},{"heading":"New Stations, New Nations","paragraphs":["The ISS is not the only story in orbit. On 15 October 2003 a Long March 2F rocket lifted off from the Jiuquan launch centre in the Gobi Desert carrying Yang Liwei, a former fighter pilot, aboard the spacecraft Shenzhou 5. He circled Earth 14 times in about 21 hours before landing safely in Inner Mongolia. China became only the third country, after the Soviet Union and the United States, to launch a person into space on its own rocket. Chinese astronauts are often called taikonauts, from the Chinese word for space.","China then built up its skills step by step. In 2008 a Chinese astronaut made the country's first spacewalk. Two small test laboratories, Tiangong-1 in 2011 and Tiangong-2 in 2016, let crews practise docking and living in orbit; in 2012 Liu Yang became the first Chinese woman in space. Then, on 29 April 2021, a Long March 5B rocket launched Tianhe, meaning 'harmony of the heavens', the core module of a permanent station called Tiangong, which means 'heavenly palace'. Two laboratory modules, Wentian and Mengtian, joined it in 2022, completing the T-shaped station. Tiangong weighs about 100 tonnes, roughly a quarter of the ISS, and orbits at a similar height. Crews of three now live aboard in rotation, and in 2021 Wang Yaping became the first Chinese woman to walk in space.","India is building its own human spaceflight program, called Gaganyaan, which means 'sky vehicle'. Its plan is to launch Indian astronauts on an Indian rocket from Sriharikota, starting with uncrewed test flights, and Indian scientists have also talked about building an Indian space station in the future. Like all future spaceflight plans, the dates may change. The training of Indian astronauts got a boost when Shubhanshu Shukla flew to the ISS in 2025.","Many other countries now send astronauts or build parts of spacecraft. Europe's astronauts have commanded the ISS; Japan's astronauts have lived aboard many times; the United Arab Emirates sent Sultan AlNeyadi for a six-month stay in 2023, and he became the first Arab astronaut to make a spacewalk. Private companies are designing commercial space stations of their own, which they hope will one day rent out space to scientists, companies and visitors.","The ISS will not last forever. Its oldest modules have been in space for more than 25 years, and metal parts slowly wear out, crack and leak. The partners currently plan to keep using it until about 2030. After that, NASA plans to use a special spacecraft, the US Deorbit Vehicle, to push the station down into a remote part of the Pacific Ocean, the same area where Mir ended its life. As with every plan in spaceflight, the exact dates may change. By then, it is hoped, new stations will be ready to take over, so that the chain of humans living in space does not have to be broken.","The ISS may be the greatest example of cooperation in human history: former enemies sharing air, water and meals in a fragile tin can far above the Earth, year after year. But astronauts aboard it never go further than about 400 kilometres from home. Meanwhile, machines without any people inside were travelling millions and even billions of kilometres, to the hot clouds of Venus, the dusty red plains of Mars and beyond the edge of the solar system. It is time to follow the robots."]}],"deepDive":"How do you keep about 420 tonnes of hardware, built by five agencies over more than a decade, working in orbit for over 25 years? Engineers point to three big ideas. The first is modularity. Every module was designed to fit inside the Shuttle's payload bay or on top of a Proton or other rocket, so no piece is much wider than about 4.5 metres. Standard connecting ports, power and data plugs, and robot-friendly grapple fixtures meant pieces made in Russia, the United States, Italy, Germany, Japan and Canada could be joined in orbit without ever having been assembled together on Earth. The second is redundancy: the station has two partly independent segments, Russian and American, each with its own life support, so if one oxygen generator or carbon dioxide scrubber fails, the crew can rely on another. The third is maintainability. Thousands of parts are designed as 'orbital replacement units' that astronauts or Dextre can swap out. Running the station is not cheap. NASA spends roughly 3 to 4 billion US dollars a year on ISS operations, and the total cost to all partners is usually estimated at well over 100 billion dollars, though numbers vary because each country counts differently. Critics argue that the same money could have funded many robotic missions or telescopes, and debates about the station's scientific value have continued since the 1990s. Supporters reply that it has taught us how to keep humans healthy for a year in space, that results such as better water recycling and bone-loss treatments matter on Earth, and that the partnership itself kept Russia and the West cooperating even through difficult political times. The station also faces ageing problems: since 2019 a slow air leak in a small tunnel in the Russian segment has needed repeated patching. The orbit itself has a famous number, 51.6 degrees. That is the angle between the station's path and the equator, chosen so that Soyuz rockets launched from Baikonur in Kazakhstan can reach it. It also means the ISS passes over places where about 90 percent of the world's population lives.","funFact":"Because the ISS circles Earth about every 90 minutes, astronauts aboard see roughly 16 sunrises and 16 sunsets every single day.","check":{"q":"Why do astronauts on the ISS exercise about two hours every day?","a":"To stop their bones and muscles from weakening in weightlessness","wrong":["To keep warm because the station is freezing","To make electricity for the station","Because there is no room to sit down"]},"sources":[{"title":"Space Station Facts and Figures","publisher":"NASA","url":"https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"},{"title":"International Space Station","publisher":"NASA","url":"https://www.nasa.gov/reference/international-space-station/"},{"title":"20 Breakthroughs from 20 Years of Science aboard the International Space Station","publisher":"NASA","url":"https://www.nasa.gov/humans-in-space/20-breakthroughs-from-20-years-of-science-aboard-the-international-space-station/"},{"title":"International Space Station legal framework","publisher":"ESA","url":"https://www.esa.int/Science_Exploration/Human_and_Robotic_Exploration/International_Space_Station/International_Space_Station_legal_framework"},{"title":"Building the International Space Station","publisher":"ESA","url":"https://www.esa.int/Science_Exploration/Human_and_Robotic_Exploration/International_Space_Station/Building_the_International_Space_Station3"},{"title":"Tiangong space station","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Tiangong_space_station"},{"title":"Shenzhou 5","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Shenzhou_5"},{"title":"NASA Achieves Water Recovery Milestone on International Space Station","publisher":"NASA","url":"https://www.nasa.gov/missions/station/iss-research/nasa-achieves-water-recovery-milestone-on-international-space-station/"}],"photos":[{"src":"img/deep/rockets/16-1.jpg","alt":"The International Space Station in 2021, its long truss and huge solar wings photographed from a departing Crew Dragon","file":"The station pictured from the SpaceX Crew Dragon 5.jpg","url":"https://commons.wikimedia.org/wiki/File:The_station_pictured_from_the_SpaceX_Crew_Dragon_5.jpg","author":"NASA","license":"Public domain"},{"src":"img/deep/rockets/16-2.jpg","alt":"Japanese astronaut Koichi Wakata works out on the ARED weightlifting machine aboard the space station, 2013","file":"ISS-38 Koichi Wakata exercises aboard station.jpg","url":"https://commons.wikimedia.org/wiki/File:ISS-38_Koichi_Wakata_exercises_aboard_station.jpg","author":"NASA","license":"Public domain"},{"src":"img/deep/rockets/16-3.jpg","alt":"The station's Canadarm2 robotic arm grabs a SpaceX Dragon cargo ship high above northern Africa, 2015","file":"ISS-43 Canadarm2 grapples CRS-6 Dragon over northern Africa (ISS043-E-124641).jpg","url":"https://commons.wikimedia.org/wiki/File:ISS-43_Canadarm2_grapples_CRS-6_Dragon_over_northern_Africa_(ISS043-E-124641).jpg","author":"NASA","license":"Public domain"}],"words":4328},{"n":17,"title":"Robot Explorers and the Road to Mars","when":"1962 – today","summary":"Robots went where people could not: past scorching Venus, out beyond the giant planets and even out of the solar system. On Mars, six-wheeled rovers drove for years, and a tiny helicopter made the first flight on another planet.","sections":[{"heading":"Sending Robots Instead of People","paragraphs":["While astronauts were learning to orbit the Earth and walk on the Moon, a quieter kind of explorer was setting off on much longer journeys. These explorers had no lungs, no stomachs and no families waiting at home. They were robots: boxes of electronics, cameras and radios, folded up on top of rockets and flung toward other planets. Scientists call them space probes, and over the past sixty years they have visited every planet in our solar system.","Why send robots? The answer is mostly about distance and danger. The Moon is about three days away by spacecraft. Mars, at its closest, is more than a hundred times farther than the Moon, and a trip there takes many months. Venus is covered in clouds of acid. Jupiter is wrapped in radiation strong enough to fry a human in a short time. A robot does not need food, water, air or a way home. It can be built small and light, which means a smaller, cheaper rocket can launch it. And if something goes wrong, nobody dies.","Most of the early planetary probes were built by NASA's Jet Propulsion Laboratory, usually called JPL, in Pasadena, California, and by Soviet design bureaus such as the Lavochkin company near Moscow. Both sides were racing, just as they were racing to put people in orbit. Both suffered painful failures. In the early 1960s, more probes to Mars and Venus broke down, missed their targets or never left Earth orbit than succeeded. Building a machine that could survive a long trip through cold, empty space, then do its job perfectly at the right moment, turned out to be fiendishly hard."]},{"heading":"Venus: Hotter Than an Oven","paragraphs":["NASA launched Mariner 1 toward Venus in July 1962, but it veered off course just after liftoff because of a guidance problem, and the range safety officer had to destroy it. Its twin, Mariner 2, launched on 27 August 1962. It was a small craft, about 200 kilograms, with solar panels spread like wings. After a journey of almost four months it swept past Venus on 14 December 1962, passing roughly 35,000 kilometres from the planet. It became the first successful mission to another planet.","Mariner 2 had no camera. Instead it carried instruments that measured invisible microwave and infrared light coming from Venus. Its readings showed that Venus was not a tropical paradise at all. The surface was blazing hot, hundreds of degrees Celsius, far hotter than a kitchen oven. On the way, Mariner 2 also made the first direct measurements of the solar wind, the steady stream of charged particles that flows outward from the Sun. Scientists had predicted it, and now they had proof.","The Soviet Union wanted to go further and land. Its Venera ('Venus' in Russian) probes were built tough, like diving bells, because the air of Venus turned out to be far thicker and hotter than anyone had guessed. After several earlier probes were crushed or failed, Venera 7 reached the surface on 15 December 1970. Its signal was very weak, perhaps because it tipped over or bounced as it landed, and at first controllers thought it had failed. But when scientists studied the recordings carefully, they found it had kept sending faint data from the ground for about twenty minutes. Venera 7 had become the first spacecraft to land on another planet and send information back. It reported a temperature of around 475 degrees Celsius.","Later Venera landers went further. In October 1975, Venera 9 sent back the first pictures ever taken on the surface of another planet: a grey, rocky landscape under a dim orange sky. In 1982, Venera 13 took colour pictures and survived for about two hours before the heat and crushing pressure destroyed it. On the surface of Venus, the air presses down about 90 times harder than air does on Earth, like being nearly a kilometre deep in the ocean. The clouds are made of sulfuric acid, and a thick blanket of carbon dioxide traps heat in a runaway greenhouse effect. Venus taught scientists a sobering lesson about how hot a planet can become."]},{"heading":"Mariner 4's Grainy Pictures of Mars","paragraphs":["If Venus was hidden behind clouds, Mars seemed to be teasing. Through telescopes it showed red deserts, dark patches that changed with the seasons and white polar caps that grew and shrank. In the late 1800s, the Italian astronomer Giovanni Schiaparelli described 'canali' on Mars, an Italian word meaning channels, and the American astronomer Percival Lowell became convinced they were canals built by intelligent Martians. Science-fiction writers filled Mars with civilisations. Most astronomers were doubtful, but nobody could be sure until a spacecraft went close.","That spacecraft was Mariner 4. It launched from Cape Kennedy (now Cape Canaveral) in Florida on 28 November 1964, and its sister, Mariner 3, had failed just weeks earlier when the protective cover over the spacecraft did not come off. Mariner 4 spent more than seven months travelling to Mars. On 14 and 15 July 1965, it flew past the planet, coming within about 10,000 kilometres of the surface, and took the first close-up photographs of another planet from space.","Today your phone can send a photo across the world in a second. Mariner 4 was very different. Its camera stored the pictures on a tape recorder, and the spacecraft then radioed them home at about 8 bits per second. That is so slow that each small black-and-white picture took many hours to arrive, and the whole set of about 21 pictures, plus part of a 22nd, took more than a week.","Engineers at JPL were too excited to wait for the computers to turn the first numbers into an image. So they printed out the brightness numbers on strips of paper, pinned them to a board and coloured them in by hand with pastel crayons, like a giant paint-by-numbers. That hand-coloured first picture of Mars was framed and given to JPL's director, William Pickering, and it is still a wonderful reminder of how eager people were to see.","The pictures were a shock. Instead of canals and green fields, they showed a dusty, cratered landscape that looked more like the Moon. Mariner 4 also measured the air by watching how its radio signal changed as the spacecraft passed behind the planet. The atmosphere turned out to be extremely thin, less than one percent as thick as Earth's. Mars was colder, drier and emptier than the dreamers had hoped. Mariner 4 kept working long after its flyby, travelling around the Sun for about three more years and studying the solar wind."]},{"heading":"Voyager's Grand Tour and the Planet Slingshot","paragraphs":["In the 1960s, a young mathematician named Michael Minovitch, working at JPL as a summer student, and other scientists studied a clever trick that would change space exploration: the gravity assist. NASA engineers then noticed something rare coming up in the late 1970s. Jupiter, Saturn, Uranus and Neptune would be lined up on the same side of the Sun in a way that happens only about once every 175 years. A spacecraft launched at the right time could visit all four, using each planet to fling it on to the next.","Here is how a gravity assist works, explained simply. Imagine a tennis ball thrown at the front of a moving train. The ball bounces off the train much faster than it was thrown, because it picks up some of the train's speed. A spacecraft does something similar with a planet, except it never touches the planet. Gravity does the bouncing. The spacecraft sails close behind the planet as the planet moves along its orbit around the Sun. The planet's gravity swings the craft around and sends it off in a new direction, carrying away a little of the planet's orbital energy. The planet slows down by an amount far too tiny to ever measure, but the small spacecraft gains a huge boost.","Twin spacecraft were built for the journey: Voyager 1 and Voyager 2. Each was about the size of a small car, with a big white dish antenna 3.7 metres across. They were too far from the Sun to use solar panels, so each carried three generators powered by the heat of decaying plutonium. Voyager 2 actually launched first, on 20 August 1977. Voyager 1 followed on 5 September 1977 on a faster path, overtaking its twin and reaching Jupiter first.","The Voyagers' pictures amazed the world. Voyager 1 passed Jupiter in March 1979 and discovered active volcanoes on its moon Io, the first erupting volcanoes ever seen anywhere beyond Earth. It found thin rings around Jupiter, too. It reached Saturn in November 1980, and swung close to Saturn's giant moon Titan, which turned out to have a thick, hazy atmosphere mostly made of nitrogen. That close look at Titan bent Voyager 1's path up and out of the plane of the planets, so it could not visit any more worlds.","Voyager 2 carried on with the grand tour. After Jupiter (1979) and Saturn (1981), it became the first, and so far the only, spacecraft to visit Uranus (January 1986) and Neptune (August 1989). It found new moons and rings and showed Neptune's dark storms and its icy moon Triton, where geysers seemed to spray dark material into the thin air. Everything we have seen up close of those two distant blue worlds comes from that one spacecraft.","On 14 February 1990, Voyager 1 turned its camera back toward home and took a family portrait of the planets. In one frame, Earth is a tiny speck less than a single pixel wide, floating in a beam of scattered sunlight. Carl Sagan called it the 'Pale Blue Dot'.","In August 2012, Voyager 1 crossed the heliopause, the edge of the bubble of solar wind that surrounds our solar system, and entered interstellar space: the space between the stars. Voyager 2 followed in November 2018. They are the most distant human-made objects ever. Voyager 1 is so far away that its radio signals, travelling at the speed of light, take almost a whole day to reach us, and NASA expects it to pass one full light-day from Earth around November 2026. Their power is slowly running down, and engineers have been switching off instruments one by one to keep them talking a little longer."]},{"heading":"Touching Down on Mars: Mars 3, Viking and Sojourner","paragraphs":["Flying past a planet is hard. Landing on Mars is much harder. Mars has enough air to make a spacecraft glow red-hot as it plunges in, but far too little air for parachutes to slow it down fully. Engineers have to combine a heat shield, a parachute and then something else, such as rockets or airbags, to finish the job. Everything must happen automatically, because radio signals take minutes to cross the gap and there is no time for anyone on Earth to steer.","The Soviet Union tried first. In late 1971, two Soviet spacecraft, Mars 2 and Mars 3, arrived just as a huge dust storm was raging across the whole planet. The Mars 2 lander crashed on 27 November 1971, becoming the first human-made object to reach the surface of Mars, though not in one piece. On 2 December 1971, the Mars 3 lander came down safely, becoming the first spacecraft to make a soft landing on Mars. It began to transmit, but after only about 20 seconds the signal stopped and never returned. It was a real first, but a heartbreaking one.","NASA's turn came with the Viking program. Two Vikings were launched in 1975, each made of an orbiter and a lander. The orbiters circled the planet and scouted for safe landing places. On 20 July 1976, exactly seven years after Apollo 11's Eagle touched down on the Moon, the Viking 1 lander settled onto a plain called Chryse Planitia, slowed by a heat shield, a parachute and finally three small rocket engines. Within minutes it began sending the first picture ever taken from the surface of Mars: a view of one of its own footpads resting in the dusty, rocky soil.","After Viking, more than twenty years passed before anything else landed successfully on Mars. Then, on 4 July 1997, NASA's Mars Pathfinder arrived in a startling new way. Instead of a gentle rocket landing, it was wrapped in giant airbags, like a bundle of beach balls. After the parachute and rockets slowed it, Pathfinder dropped to the ground and bounced across the surface many times before rolling to a stop. Then the airbags deflated, the lander opened its petals like a flower, and out rolled the first rover ever to drive on Mars.","That rover was called Sojourner, named after Sojourner Truth, the American campaigner against slavery and for women's rights. It was tiny: about the size of a microwave oven and weighing only about 11 kilograms. Sojourner was designed to work for a week but kept going for nearly three months, inching around the landing site, studying rocks that the team gave friendly names such as Barnacle Bill and Yogi."]},{"heading":"Spirit and Opportunity: Rovers That Would Not Quit","paragraphs":["Sojourner proved that a rover could work on Mars. The next step was to build real robot geologists that could drive far and study rocks like a scientist would. NASA built twin rovers, each about the size of a golf cart, with six wheels, a mast topped with stereo cameras like eyes, and a robotic arm carrying a microscope, spectrometers and a tool that could grind into rocks. They were named Spirit and Opportunity by a third-grade girl, Sofi Collis, who won a naming contest. She had once lived in an orphanage in Russia before being adopted and wrote that America gave her the opportunity to make her dreams come true.","Both rovers landed using Pathfinder-style airbags. Spirit came down in Gusev Crater on 4 January 2004. Three weeks later, on the other side of the planet, Opportunity bounced and rolled straight into a small crater on the flat plain of Meridiani Planum. Scientists joked it was a 'hole in one', because the walls of that little crater showed layers of rock right in front of the rover's cameras.","Each rover was designed for a mission of 90 Martian days, called sols (a sol is about 40 minutes longer than an Earth day). Engineers expected dust to slowly cover their solar panels until they ran out of power. But something lucky happened: Martian winds and small whirlwinds called dust devils sometimes swept across the rovers and blew their panels clean. Again and again, the rovers' power came back.","Spirit explored the hills of Gusev Crater for more than five years. When one of its front wheels stopped working in 2006, the team drove it backwards, dragging the broken wheel. That accident turned out to be useful: the dragging wheel scraped up bright soil that was almost pure silica, a material that on Earth often forms around hot springs. It was a strong clue that hot water had once flowed there. In 2009 Spirit got stuck in soft sand and could not escape. It kept working as a stationary science station until it fell silent in March 2010, and NASA officially ended its mission in May 2011.","Opportunity kept rolling. Soon after landing, it found small round grains of a mineral called hematite, nicknamed 'blueberries', and layers of rock that could only have formed in water. This was some of the strongest evidence yet that liquid water had once soaked the surface of Mars. Later, the rover drove for years to reach the rim of Endeavour Crater, about 22 kilometres across, where it found signs of ancient water that was not too acidic, the kind of water that living things might have been able to use.","Then, in June 2018, a dust storm swelled until it wrapped the entire planet. The sky above Opportunity grew so dark that its solar panels could no longer make enough electricity. Its last message arrived on 10 June 2018. For eight months the team sent more than a thousand commands, hoping the wind would clean its panels once more. On 13 February 2019, NASA announced the mission was over. A rover meant to last 90 days had worked for almost 15 years."]},{"heading":"Sky Cranes, Perseverance and a Helicopter on Mars","paragraphs":["NASA's next rover, Curiosity, was too big for airbags. It is about the size of a small car and weighs about 900 kilograms, roughly five times as much as Spirit or Opportunity. Instead of solar panels, it runs on a nuclear generator that turns the heat of decaying plutonium into electricity, so dust storms and winter do not stop it. But how do you gently set down a one-tonne robot on a planet with hardly any air?","JPL engineers invented a daring answer: the sky crane. After the heat shield and an enormous parachute had slowed the spacecraft, a rocket-powered descent stage dropped free and hovered above the ground like a jet-pack. Then it lowered Curiosity on nylon cables several metres long, until the rover's wheels touched the ground. The cables were cut, and the descent stage flew off to crash safely some distance away. The whole sequence, from hitting the top of the atmosphere to standing on the ground, took about seven minutes, all carried out by the spacecraft's computers on their own. Engineers called it the 'seven minutes of terror'.","It worked perfectly. Curiosity landed in Gale Crater on 6 August 2012 (the evening of 5 August in California), and the control room at JPL erupted in cheers and hugs. Not long afterwards, the rover found that Gale Crater once held a lake of fresh water, with the chemical ingredients that microbes on Earth would need. Later it detected organic molecules, carbon-based chemicals that are building blocks for life (although they can also form without life), and seasonal changes in a gas called methane. Curiosity is still climbing the slopes of Mount Sharp, a mountain of layered rock in the middle of the crater, reading the history of Mars layer by layer like the pages of a book.","Its bigger cousin, Perseverance, launched on 30 July 2020 and landed on 18 February 2021 using the same sky crane, plus a new trick: a camera system that compared pictures of the ground with a map and steered toward a safe spot. Perseverance landed in Jezero Crater, which billions of years ago held a lake fed by a river. The river left behind a fan-shaped delta of mud and sand, just the kind of place where signs of ancient life might be preserved.","Tucked under Perseverance's belly was the most charming passenger of all: a small helicopter named Ingenuity. It weighed only about 1.8 kilograms on Earth and had two rotors, each about 1.2 metres across, spinning in opposite directions very fast, roughly 2,400 times a minute, because the thin Martian air gives so little to push against. Flying on Mars is like flying on Earth at nearly 30 kilometres high, far above where any normal helicopter can go.","On 19 April 2021, Ingenuity lifted off, rose about 3 metres, hovered, turned and landed again. The flight lasted about 39 seconds, but it was the first powered, controlled flight of an aircraft on another planet. The helicopter carried a postage-stamp-sized piece of fabric from the Wright brothers' 1903 Flyer, linking the first flight on Earth with the first flight on Mars, and the team named the take-off spot Wright Brothers Field.","Ingenuity was built as a quick experiment of up to five flights in about a month. Instead it flew 72 times between 2021 and 2024, travelling roughly 17 kilometres in total and spending more than two hours in the air. It became a scout, flying ahead to show the rover's drivers the best routes. On its 72nd flight, on 18 January 2024, it came down hard and damaged its rotor blades, possibly because the smooth, featureless sand confused its navigation camera. NASA ended its mission that month. Its success means future Mars missions will probably carry flying scouts of their own."]},{"heading":"New Flags at Mars, and Why Mars Is So Hard","paragraphs":["India's Mars Orbiter Mission, nicknamed Mangalyaan ('Mars craft' in Hindi), launched on 5 November 2013 from Sriharikota on India's PSLV rocket. On 24 September 2014, after a journey of about 300 days and roughly 670 million kilometres, it fired its engine and slipped into orbit around Mars. India became the first country to reach Mars orbit on its very first try. The mission cost about 74 million US dollars, famously less than the budget of some Hollywood space films. Mangalyaan kept working for about eight years.","In July 2020, three missions set off for Mars in the same few weeks, because that was when the planets were in the right positions. The United Arab Emirates launched its Hope orbiter on a Japanese H-IIA rocket from Tanegashima, Japan, on 20 July 2020. Hope reached Mars orbit on 9 February 2021, making it the first interplanetary mission from an Arab country. Its special orbit lets it watch Martian weather at every time of day, like a weather satellite for another planet.","China's Tianwen-1 ('Questions to Heaven') arrived in Mars orbit the next day, on 10 February 2021. Its mission carried an orbiter, a lander and a rover all at once, something no country had done on its first Mars trip. In May 2021, the lander touched down on Utopia Planitia, the same broad plain where Viking 2 had landed 45 years before, and the rover Zhurong, named after a fire god in Chinese mythology, rolled onto the surface. China became the second country, after the United States, to drive a rover on Mars. Zhurong was designed for 90 sols and worked for about a year, studying the ground with radar, before it went into hibernation for the harsh Martian winter in May 2022 and did not wake up.","Why is Mars so difficult? First, timing. Earth and Mars both circle the Sun, Earth on the inside track moving faster. The most fuel-saving path from one to the other is a long curving arc that takes about seven months, and it only lines up roughly every 26 months. Miss that launch window and you wait more than two years for the next one. That is why so many Mars missions launch together in bursts, such as the three in July 2020.","Second, distance and delay. The distance between Earth and Mars changes from about 55 million kilometres at the closest to around 400 million kilometres when they are on opposite sides of the Sun. Radio waves travel at the speed of light, but even so a message takes from about 3 minutes to more than 20 minutes to cross, one way. You cannot drive a Mars rover with a joystick like a video game. Engineers send a whole day's instructions at once and wait to see what happened, and landings must be completely automatic.","Third, the air. Mars's atmosphere is less than one percent as thick as Earth's at the surface. It is thick enough to cause dangerous heating during entry, but too thin for parachutes alone to slow a heavy spacecraft. Landing larger and larger loads, such as one day a ship carrying people, is one of the biggest unsolved engineering problems in spaceflight.","Fourth, radiation and cold. Mars has no global magnetic field and only a thin atmosphere, so far more harmful radiation from the Sun and from deep space reaches the surface than on Earth. Nights are colder than Antarctica. Machines must be built to survive it, and future astronauts would need shelter.","It is no wonder that, by 2014, only around 21 of 51 missions sent toward Mars had succeeded, as India's prime minister pointed out when Mangalyaan arrived. Every success was built on lessons learned from failures. And all of these brave robot explorers had one thing in common: the rockets that launched them were used once and then thrown away, falling into the ocean or burning up in the sky. Every mission meant building a whole new rocket from scratch, which is a little like throwing away an airliner after one flight. Then a young company decided to do something that many experts thought was impossible: land its rockets and fly them again."]}],"deepDive":"Getting to Mars is less about raw speed than about clever timing. The most fuel-efficient route between two planets is called a Hohmann transfer orbit: a half-ellipse around the Sun that just touches Earth's orbit at one end and Mars's orbit at the other. For Mars that trip takes roughly 7 to 9 months. The launch must be timed so that Mars arrives at the far end of the ellipse at the same moment as the spacecraft. Because Earth laps Mars about once every 780 days (the synodic period, about 26 months), that alignment repeats only that often. Missions can take faster, more curved paths, but every extra bit of speed costs fuel, and fuel costs mass, which, as the rocket equation shows, grows very quickly. Gravity assists are the other big money-saver of planetary travel. Relative to the planet, a spacecraft leaves a flyby with the same speed it arrived with; only its direction changes. But measured relative to the Sun, that change in direction can add or remove several kilometres per second, borrowed from the planet's orbital motion. Voyager 2 more than doubled its speed through flybys of Jupiter, Saturn and Uranus. Without such slingshots, reaching the outer planets in a reasonable time would need far bigger rockets than exist. Landing is the third great challenge. Engineers call it EDL: entry, descent and landing. Mars's thin atmosphere removes most of a probe's speed during entry, but the supersonic parachutes used since Viking become less useful as payloads grow heavier, and Curiosity and Perseverance, at around one tonne, are close to the practical limit of today's methods. Landing the tens of tonnes that a human expedition would need may require new ideas such as inflatable heat shields or rocket engines fired against the oncoming supersonic air. There is also a long-running scientific debate about life. Viking's Labeled Release experiment gave results that looked biological to its designer, Gilbert Levin, but most researchers attribute them to reactive chemicals such as perchlorates, which the Phoenix lander found in Martian soil in 2008. Perseverance's sealed samples were collected partly to settle questions like this in Earth laboratories, if a return mission is ever flown.","funFact":"When NASA's Mariner 4 sent the first close-up pictures of Mars in 1965, engineers were so impatient that they coloured in the first image by hand with pastel crayons, using the numbers printed on strips of paper, before the computers could finish it.","check":{"q":"What was special about the Ingenuity helicopter's flight on 19 April 2021?","a":"It was the first powered, controlled flight of an aircraft on another planet","wrong":["It was the first spacecraft to land on Venus","It carried the first astronaut to Mars","It was the first object to leave the solar system"]},"sources":[{"title":"Mariner 2","publisher":"NASA Jet Propulsion Laboratory","url":"https://www.jpl.nasa.gov/missions/mariner-2"},{"title":"Mariner 4","publisher":"NASA Jet Propulsion Laboratory","url":"https://www.jpl.nasa.gov/missions/mariner-4"},{"title":"Voyager 1","publisher":"NASA Science","url":"https://science.nasa.gov/mission/voyager/voyager-1/"},{"title":"Basics of Space Flight: Interplanetary Trajectories (gravity assist)","publisher":"NASA Science","url":"https://science.nasa.gov/learn/basics-of-space-flight/chapter4-1/"},{"title":"Viking 1 and 2","publisher":"NASA Science","url":"https://science.nasa.gov/mission/viking/"},{"title":"NASA's Opportunity Rover Mission on Mars Comes to End","publisher":"NASA Jet Propulsion Laboratory","url":"https://www.jpl.nasa.gov/news/nasas-opportunity-rover-mission-on-mars-comes-to-end/"},{"title":"Ingenuity Mars Helicopter","publisher":"NASA Jet Propulsion Laboratory","url":"https://www.jpl.nasa.gov/missions/ingenuity"},{"title":"India's Mangalyaan satellite successfully in orbit around Mars","publisher":"Physics World","url":"https://physicsworld.com/a/indias-mangalyaan-satellite-successfully-in-orbit-around-mars/"}],"photos":[{"src":"img/deep/rockets/17-1.jpg","alt":"Too excited to wait, JPL engineers coloured Mariner 4's first Mars picture by hand from printed numbers, 1965","file":"First Image from Mariner 4 - GPN-2003-00060.jpg","url":"https://commons.wikimedia.org/wiki/File:First_Image_from_Mariner_4_-_GPN-2003-00060.jpg","author":"NASA/JPL/Dan Goods","license":"Public domain"},{"src":"img/deep/rockets/17-2.jpg","alt":"The gold cover of Voyager's Golden Record, engraved with pictures explaining how to play it and where Earth is","file":"The Sounds of Earth Record Cover - GPN-2000-001978.jpg","url":"https://commons.wikimedia.org/wiki/File:The_Sounds_of_Earth_Record_Cover_-_GPN-2000-001978.jpg","author":"NASA/JPL","license":"Public domain"},{"src":"img/deep/rockets/17-3.jpg","alt":"The Ingenuity helicopter standing on the dusty ground of Mars, photographed by the Perseverance rover in 2021","file":"Mastcam-Z Gives Ingenuity a Close-up.jpg","url":"https://commons.wikimedia.org/wiki/File:Mastcam-Z_Gives_Ingenuity_a_Close-up.jpg","author":"NASA/JPL-Caltech/ASU/MSSS","license":"Public domain"}],"words":4365},{"n":18,"title":"Rockets That Land: The New Space Age","when":"2000 – today","summary":"For fifty years, rockets were used once and thrown away. Then new companies taught rockets to fly back, flip around and land standing up, and even to be caught in mid-air by a giant tower. Now launches cost much less, and more people than ever can go to space.","sections":[{"heading":"The Most Expensive Way to Travel","paragraphs":["Imagine flying from London to New York, and when the plane lands, everyone gets off and the airliner is pushed into the sea. Every single flight would need a brand-new plane. Tickets would cost millions. That sounds silly, but for almost all of space history, that is exactly how rockets worked. A Saturn V, an R-7 or an Atlas was used once. Its stages fell into the ocean, crashed in empty deserts or burned up in the sky. Only small capsules, and later the Space Shuttle, came home.","The Shuttle was supposed to fix this. Its orbiter landed like a glider and flew again, and its two big solid boosters were fished out of the ocean and refilled. But after every flight, thousands of heat-shield tiles had to be checked, the boosters had to be taken apart and rebuilt, and the giant orange fuel tank was thrown away. Getting the Shuttle ready again took months of work by thousands of people. In the end, each Shuttle launch cost far more than its designers had hoped. Reuse that needs that much repair does not save much money.","Around the year 2000, a few wealthy people who had grown up watching Apollo began to wonder whether a business could do better. They believed that space travel was expensive not because of the laws of physics, but because rockets were built like handmade jewellery and then thrown away. If you could build them more like cars or aeroplanes, and land them to fly again, the cost of reaching space might drop enormously.","In 2000, Jeff Bezos, who had founded the online shop Amazon, quietly started a company called Blue Origin near Seattle, in Washington state. Its motto is a Latin phrase, 'Gradatim Ferociter', meaning 'step by step, ferociously'. In 2002, Elon Musk, who had made a fortune from internet companies including PayPal, founded Space Exploration Technologies, known as SpaceX, in California. He later said his long-term dream was to help people live on Mars, and he started SpaceX after finding that buying a rocket was shockingly expensive.","On the other side of the world, a New Zealand engineer named Peter Beck, who had built rocket-powered bicycles and backpacks as a young man, founded Rocket Lab in 2006. His plan was different: to build small, cheap rockets that could carry little satellites, some no bigger than a shoebox, whenever their owners needed. Rocket Lab's Electron rocket, about 18 metres tall, uses engines with 3D-printed parts and fuel pumps driven by electric motors and batteries, an unusual idea in rocketry. On 21 January 2018, Electron reached orbit from the Mahia Peninsula in New Zealand on a flight cheekily named 'Still Testing'.","These new companies are part of what people call the 'New Space' age. Old space companies mostly built rockets to order for governments. The new ones wanted to sell rides to anyone who could pay, and they were willing to take big risks, blow things up during testing, and learn fast from their mistakes. Many experts doubted they would succeed."]},{"heading":"Three Failures and a Fourth Try","paragraphs":["SpaceX's first rocket was small: Falcon 1, about 21 metres tall, with one engine called Merlin in its first stage, burning kerosene and liquid oxygen. Its launch site was a tiny tropical island called Omelek, part of the Kwajalein Atoll in the middle of the Pacific Ocean, thousands of kilometres from almost anywhere. The team lived and worked in a few simple buildings, shipping everything in by boat and plane.","The first launch, on 24 March 2006, lasted less than a minute. A fuel leak started a fire on the engine, and the rocket fell back onto the reef near the launch pad. The second launch, in March 2007, did much better and reached space, but the second stage began to wobble because its fuel sloshed around in the tank, and its engine shut down early. It did not reach orbit.","The third launch, on 3 August 2008, was the most painful. After the first stage finished burning, it was supposed to separate cleanly. But the engine was still giving a tiny bit of thrust from leftover propellant, and the first stage bumped into the second stage just as it tried to ignite. The rocket and its satellites were lost.","SpaceX was running out of money. Musk later said the company had only enough left for about one more try, and his other company, the electric-car maker Tesla, was in trouble at the same time. The team found the fix for the separation problem, a slightly longer pause before the stages parted, and rushed to put together the next Falcon 1 in just a few weeks.","On 28 September 2008, the fourth Falcon 1 roared off Omelek Island. This time the first stage separated cleanly, the second stage ignited and carried a dummy payload of about 165 kilograms into orbit. In the SpaceX factory in California, hundreds of employees watching the video feed screamed and cheered. Falcon 1 became the first privately developed liquid-fuelled rocket to reach orbit around the Earth. Musk called it 'a great day for SpaceX'.","The success came just in time. A few months later, in December 2008, NASA gave SpaceX a contract worth about 1.6 billion US dollars to fly cargo to the International Space Station. The lesson of Falcon 1 was simple but powerful: failure is not the end if you learn from it and keep going. Three failures had taught the team more than an easy success might have."]},{"heading":"Dragon Delivers to the Space Station","paragraphs":["When NASA decided to retire the Space Shuttle, it had a problem. Who would carry food, water, experiments and spare parts to the International Space Station? NASA's answer was to pay private companies to do it, like hiring a delivery service instead of owning its own lorries. The companies would design and build their own rockets and spacecraft, and NASA would pay for each successful delivery.","SpaceX built a much bigger rocket, Falcon 9, named for its nine Merlin engines in the first stage. On top went Dragon, a capsule shaped a bit like a gumdrop. Falcon 9 first flew on 4 June 2010. In December 2010, Dragon orbited the Earth and splashed down safely in the Pacific, making SpaceX the first private company to bring a spacecraft back from orbit.","The big test came in May 2012. Falcon 9 launched Dragon on 22 May. Over the next three days the capsule carefully approached the station, testing its sensors and thrusters, then stopped and floated just a few metres away. On 25 May 2012, astronauts Don Pettit of NASA and Andre Kuipers of the European Space Agency reached out with the station's long robotic arm, Canadarm2, and grabbed it. They then attached it to the station. Dragon had become the first commercially built spacecraft to visit the International Space Station.","Dragon carried about 460 kilograms of supplies, and unlike most other cargo ships at the time, it could also bring things home: finished experiments, broken equipment and samples, which came back in the capsule when it splashed into the ocean. Regular cargo flights began in October 2012. Another American company, Orbital Sciences (later part of Northrop Grumman), began delivering cargo with its Cygnus spacecraft too.","Meanwhile, a bigger gap had opened. After the last Shuttle landed in July 2011, the United States had no way to launch its own astronauts. For nearly nine years, every American astronaut going to the space station had to ride a Russian Soyuz from Kazakhstan, and NASA paid Russia for every seat, eventually more than 80 million US dollars each. In 2014, NASA picked two companies, Boeing and SpaceX, to build new spacecraft that could carry crews. SpaceX began turning Dragon into Crew Dragon, with seats, life support, touch-screen controls and powerful escape engines built into its sides."]},{"heading":"How to Land a Rocket Backwards","paragraphs":["Landing a rocket is a little like balancing a broomstick on your finger, except the broomstick is as tall as a building, falling from the edge of space, and moving faster than a bullet. Many engineers believed it would never be worth the trouble. Two companies decided to try anyway.","Blue Origin got there first with a smaller, suborbital rocket called New Shepard, named after Alan Shepard, the first American in space. On 23 November 2015, in the desert of West Texas, New Shepard launched an empty capsule to about 100.5 kilometres, just past the Kármán line that many people use as the edge of space. The capsule floated back on parachutes. Then the booster fell back toward the ground, relit its engine, slowed down to about 7 kilometres per hour and settled gently onto a concrete pad on its landing legs. It was the first time a rocket had flown to space and then landed upright on Earth. A couple of months later, the same booster flew again.","Less than a month later, SpaceX did something even harder. A suborbital hop goes mostly straight up and down. An orbital rocket's first stage, by contrast, is heading sideways at several thousand kilometres per hour when it separates, far out over the ocean. On the night of 21 December 2015, a Falcon 9 lifted off from Cape Canaveral in Florida carrying 11 small communications satellites for a company called Orbcomm. A few minutes later, while the second stage carried on to orbit, the first stage turned around and flew back. About ten minutes after liftoff, it touched down upright at a landing zone near the coast, not far from where it had launched. It was the first time the first stage of a rocket that reached orbit had landed back on Earth.","Here is how a Falcon 9 booster does it. After about two and a half minutes, the first stage shuts down its engines and separates. Small jets of compressed gas on its top flip it around so its engines point the way it is travelling. If it is returning to land, it fires three engines in a 'boostback burn' to cancel its sideways speed and head home. As it falls, four lattice-shaped 'grid fins' near the top fold out and steer it like the feathers on a dart. Just before it hits the thicker air, it fires its engines again in an 'entry burn' to slow down so it does not overheat. Finally, in the last moments, one engine fires for the 'landing burn', four legs swing down, and the booster touches down.","There is a tricky detail. Even one Merlin engine at its lowest setting is too powerful to let the nearly empty booster hover. So the computer must time the burn so that the rocket's speed reaches zero at exactly the moment it touches the ground. Too early and it would start going back up; too late and it would crash. Engineers sometimes call this a 'hoverslam'.","When a mission needs more of the rocket's fuel for the payload, there is not enough left to fly all the way back. So SpaceX lands those boosters on 'drone ships': large, flat robotic barges stationed hundreds of kilometres out at sea. The ships have playful names taken from science-fiction novels by Iain M. Banks, such as 'Of Course I Still Love You' and 'Just Read the Instructions'. Several early attempts ended in fiery crashes on the deck before the first successful drone-ship landing in April 2016.","Landing a booster is only half the point; it must also fly again. In March 2017, SpaceX launched a satellite on a Falcon 9 booster that had already flown once. Since then, reflown boosters have become normal, and some individual boosters have now flown more than 25 times each. SpaceX also catches and reuses the nose cone halves, called fairings, that protect satellites during launch. Reuse is the main reason launches have become much cheaper per kilogram than in the Shuttle era."]},{"heading":"Astronauts Ride a Company Spaceship","paragraphs":["On 30 May 2020, at 3:22 in the afternoon Florida time, a Falcon 9 rocket stood on Launch Complex 39A at NASA's Kennedy Space Center, the same pad from which Apollo 11 had left for the Moon and the very first Space Shuttle had launched. On top sat a gleaming white Crew Dragon. Inside were two NASA astronauts, Bob Behnken and Doug Hurley. Both were Space Shuttle veterans, and Hurley had been the pilot of the very last Shuttle mission in 2011.","The world was in the middle of the COVID-19 pandemic, and many people were stuck at home, so millions watched online. The countdown reached zero, the nine engines lit, and the rocket climbed into a clear sky. It was the first time astronauts had launched to orbit from the United States since 2011, and the first time ever that NASA astronauts had flown on a spacecraft built and run by a private company. The mission was called Demo-2, because it was the final test before Crew Dragon could carry regular crews.","Crew Dragon is very different inside from older spacecraft. Instead of hundreds of switches, the astronauts used large touchscreens. The spacecraft is designed to fly itself and dock with the station automatically, though Hurley tested flying it by hand for a short while. On 31 May, Dragon docked at the International Space Station. The astronauts named their capsule Endeavour, after the Space Shuttle Endeavour on which both had made their first spaceflights.","Behnken and Hurley spent about two months on the station. Then, on 2 August 2020, Endeavour came home. It plunged into the atmosphere at about 28,000 kilometres per hour, its heat shield glowing at temperatures of roughly 1,900 degrees Celsius, before two small drogue parachutes and then four big main parachutes opened. It splashed down in the Gulf of Mexico, the first American crew splashdown since 1975. Soon afterwards, Crew Dragon began flying regular crews of four to the space station, including astronauts from Europe, Japan and other countries."]},{"heading":"Starship and the Chopsticks","paragraphs":["Falcon 9 lands its first stage, but its second stage is still thrown away. SpaceX's next idea was much bolder: a giant rocket that would be completely reusable, both stages, to carry huge loads to orbit, to the Moon and one day to Mars. It is called Starship.","Starship has two parts. The bottom stage, called Super Heavy, is about 70 metres tall and has 33 Raptor engines burning liquid methane and liquid oxygen. On top sits the upper stage, also called Starship, which is a spacecraft and rocket in one, with six more engines. Stacked together, they stand about 120 metres tall, taller than the Saturn V and taller than the Statue of Liberty with its pedestal. It is made of stainless steel rather than the aluminium used for most rockets, partly because steel is cheap and handles both the extreme cold of the fuel and the heat of re-entry well. At liftoff it produces roughly twice the thrust of the Saturn V, making it the largest and most powerful rocket ever flown.","SpaceX tests Starship in a way that surprises many people: it builds rockets quickly, flies them, and accepts that some will explode. The first full test flight, on 20 April 2023, launched from SpaceX's site called Starbase, near Boca Chica on the southern tip of Texas. Several engines failed, the two stages never separated, and the rocket was destroyed about four minutes after liftoff. The launch pad itself was badly damaged, and the ground shook for kilometres around. SpaceX rebuilt, changed its design and flew again. Each test flight went further than the one before, although later ones also included failures and explosions as engineers pushed the design.","Starship's boosters are not meant to land on legs. Instead, the plan is for the launch tower to catch them in mid-air. The tower, nicknamed 'Mechazilla', has two huge mechanical arms, nicknamed the 'chopsticks'. Leaving off the landing legs saves weight, and catching the booster right at the launch pad means it could, in theory, be checked, refuelled and launched again quickly.","On 13 October 2024, during Starship's fifth test flight, the 70-metre Super Heavy booster separated from the ship, turned around and flew back toward the tower. About seven minutes after liftoff, it slowed to a hover beside the tower, fire spurting around its engines, and the chopsticks closed around it, holding it in the air. Engineers and onlookers cheered wildly. Many space fans described it as one of the most astonishing things they had ever seen a rocket do. Meanwhile, the ship flew about halfway around the world and made a controlled splashdown in the Indian Ocean.","Starship still has a long way to go. NASA has chosen a version of it to be the lander that will carry astronauts down to the Moon's surface in its Artemis program, and for that it must be refuelled in orbit by other Starships, moving huge amounts of super-cold propellant from one ship to another, something never done on that scale before. Plans and dates for these missions may change. But Starship shows how far rocket reuse has come in just a few years."]},{"heading":"Tourists, Private Astronauts and a Crowded Sky","paragraphs":["Cheaper, reusable rockets have opened space to people who are not government astronauts. The very first space tourist, the American businessman Dennis Tito, paid about 20 million US dollars to fly to the International Space Station on a Russian Soyuz in April 2001. For many years only a handful of very rich people followed him.","In July 2021, two companies started flying passengers on short suborbital trips. On 11 July, Richard Branson flew on his company Virgin Galactic's rocket plane, which was carried up under a jet aircraft and then fired its own rocket. Nine days later, on 20 July 2021, the 52nd anniversary of the Apollo 11 Moon landing, Jeff Bezos flew on Blue Origin's New Shepard. With him were his brother Mark, 82-year-old Wally Funk, who had trained as a pilot and passed astronaut-style tests in the early 1960s but was never allowed to fly to space, and 18-year-old Oliver Daemen. At that moment Funk became the oldest person ever to fly to space, and Daemen the youngest. A few months later, the Star Trek actor William Shatner flew on New Shepard at the age of 90.","Private orbital flights followed. In September 2021, a Crew Dragon carried Inspiration4, the first orbital flight with no professional astronauts on board, for three days. Its four crew members raised money for a children's hospital. Since then, private crews have visited the International Space Station, and in September 2024 the Polaris Dawn mission made the first spacewalk by private, non-government astronauts.","Other countries are part of the New Space age too. In China, private companies have built their own rockets; in July 2023 a Chinese company called LandSpace launched Zhuque-2, the first rocket burning methane and liquid oxygen to reach orbit. Blue Origin's big orbital rocket, New Glenn, reached orbit on its first flight in January 2025, and on its second flight, in November 2025, its booster landed on a ship at sea. Rocket Lab is developing a larger, reusable rocket of its own. Reuse, once thought to be a fantasy, is becoming the normal way to build a rocket.","But there is a downside to cheap launches. Because reaching orbit is now so much cheaper, companies are launching thousands of small satellites into huge groups called megaconstellations, mostly to beam internet to the ground. SpaceX began launching its Starlink satellites in 2019, often 20 or more on a single rocket, and now has many thousands in orbit, more than all other companies and countries put together. Other companies and countries are planning constellations of their own.","According to the European Space Agency, by its 2025 report about 40,000 objects in orbit were being tracked, about 11,000 of them working satellites, and there were more than a million pieces of debris bigger than a centimetre, too small to track but still dangerous at orbital speeds. Satellites now have to swerve out of each other's way more and more often. Astronomers have also complained that bright satellites leave streaks across their telescope pictures.","Rockets that land have made space cheaper, busier and more open to more people than ever before. That is exciting, but it also raises big questions. Who should be allowed to fill the sky with satellites? What happens to all the old ones? Is rocket exhaust harming the air? And has the human race really learned to keep its explorers safe? In other words, does all this rocket power come with costs, for people, for the planet and for space itself?"]}],"deepDive":"Why did reusable rockets take so long, and why do they save money? The rocket equation explains the cost of reuse. To land, a booster must keep back some of its propellant for the boostback, entry and landing burns, and it must carry legs and grid fins all the way up. That extra mass is paid for directly in payload: a Falcon 9 that lands its booster can carry noticeably less to low Earth orbit than one that is thrown away, very roughly a quarter less. For a long time many engineers assumed this penalty, plus the cost of inspecting and repairing a used rocket, would cancel out any savings. The Space Shuttle seemed to prove them right, because its refurbishment was so slow and labour-intensive. SpaceX's bet was different in two ways. First, it made the booster rugged enough to need only light checks between flights. Second, it builds most parts in its own factories, so the most expensive piece of the rocket, the first stage with its nine engines, no longer has to be built new each time. The savings are real, though exact figures are debated, because companies set prices for business reasons rather than simply passing on costs. One widely cited 2018 analysis by NASA engineer Harry Jones estimated that launching a kilogram to low orbit cost about 54,500 US dollars on the Space Shuttle, but only about 2,700 dollars on a Falcon 9, a drop of roughly twenty times. Starship aims to lower the cost much further by making both stages reusable and refuelling in orbit, but whether it reaches those goals is still unknown. There is also a debate about competition. Critics worry that one company launching most of the world's rockets and most of its working satellites gives it too much power over access to space. Supporters argue that cheap launches have opened space to universities, small countries and start-ups that could never afford it before. Astronomers and debris experts add another concern: cheaper access means far more objects in orbit, and the European Space Agency warns that in some popular orbits the amount of dangerous debris is now of the same order as the number of active satellites.","funFact":"SpaceX's robot landing ships are named after spaceships in Iain M. Banks's science-fiction novels, so a rocket booster can land on a ship called 'Of Course I Still Love You'.","check":{"q":"On what date did a Falcon 9 first stage first land back on Earth after an orbital launch?","a":"21 December 2015","wrong":["20 July 1969","12 April 1981","4 October 1957"]},"sources":[{"title":"SpaceX rocket reaches orbit after fourth attempt","publisher":"Physics Today (American Institute of Physics)","url":"https://physicstoday.aip.org/news/spacex-rocket-reaches-orbit-after-fourth-attempt"},{"title":"Capturing SpaceX's Dragon","publisher":"NASA","url":"https://www.nasa.gov/image-article/capturing-spacexs-dragon/"},{"title":"NASA Astronauts Launch from America in Historic Test Flight of SpaceX Crew Dragon","publisher":"NASA","url":"https://www.nasa.gov/news-release/nasa-astronauts-launch-from-america-in-historic-test-flight-of-spacex-crew-dragon/"},{"title":"Top 10 Things to Know for NASA's SpaceX Demo-2 Return","publisher":"NASA","url":"https://www.nasa.gov/humans-in-space/top-10-things-to-know-for-nasas-spacex-demo-2-return/"},{"title":"SpaceX's Starship plucked from the air by giant chopsticks, but why did they do it?","publisher":"BBC Sky at Night Magazine","url":"https://skyatnightmagazine.com/news/spacex-starship-test-5-chopsticks"},{"title":"ESA Space Environment Report 2025","publisher":"European Space Agency","url":"https://www.esa.int/Space_Safety/Space_Debris/ESA_Space_Environment_Report_2025"},{"title":"Falcon 1","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Falcon_1"},{"title":"New Glenn","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/New_Glenn"}],"photos":[{"src":"img/deep/rockets/18-1.jpg","alt":"The first Falcon 9 booster ever to land, standing on Landing Zone 1 at Cape Canaveral after the December 2015 Orbcomm launch","file":"Falcon 9 first stage at LZ-1(two).jpg","url":"https://commons.wikimedia.org/wiki/File:Falcon_9_first_stage_at_LZ-1(two).jpg","author":"SpaceX Photos","license":"CC0"},{"src":"img/deep/rockets/18-2.jpg","alt":"Falcon 9 lifts Crew Dragon off Launch Complex 39A on the Demo-2 mission, 30 May 2020","file":"SpaceX Falcon 9 rocket and Crew Dragon spacecraft lifts off from Launch Complex 39A.jpg","url":"https://commons.wikimedia.org/wiki/File:SpaceX_Falcon_9_rocket_and_Crew_Dragon_spacecraft_lifts_off_from_Launch_Complex_39A.jpg","author":"NASA/Tony Gray and Tim Powers","license":"Public domain"},{"src":"img/deep/rockets/18-3.jpg","alt":"A scorched, flight-worn Blue Origin New Shepard booster on show at the 2017 Oshkosh air show","file":"New Shepard booster at Oshkosh Airventure 2017 01 (35975649982).jpg","url":"https://commons.wikimedia.org/wiki/File:New_Shepard_booster_at_Oshkosh_Airventure_2017_01_(35975649982).jpg","author":"LunchboxLarry","license":"CC BY 2.0"}],"words":3771},{"n":19,"title":"The Dangers and the Debates","when":"1940s – today","summary":"Rockets are amazing, but they can also be dangerous. Brave astronauts have been lost, rockets have been used as weapons, and old bits of satellites now zoom around Earth like a swarm of tiny bullets. In this part we look at the hard questions: how do we keep people safe, keep space clean, and make sure space is fair for everyone?","sections":[{"heading":"The Price of Reaching Up","paragraphs":["Every story about rockets has a quiet side. When you read about countdowns, fire and cheering crowds, it is easy to forget that a rocket is really a controlled explosion with people sitting on top of it. Space does not care how brave or clever you are, and one small mistake can be enough. Over the decades, some of the bravest people of their time paid for that lesson with their lives. Remembering them is part of telling the story honestly.","The first big loss of the American program did not even happen in space. On 27 January 1967, the Apollo 1 crew, Gus Grissom, Ed White and Roger Chaffee, were strapped into their capsule on Launch Complex 34 in Florida for a practice countdown. The cabin was filled with pure oxygen at slightly more than normal air pressure, which makes almost anything burn fiercely. A spark, probably from damaged wiring, started a fire that spread in seconds. The hatch opened inwards and was held shut by the pressure inside, so the crew could not escape in time. All three died.","NASA was shaken, and the whole Apollo spacecraft was redesigned. The new hatch could swing outward in a few seconds. Flammable materials were replaced. On the launch pad, the cabin air became a mix of nitrogen and oxygen instead of pure oxygen. Many astronauts later said that Apollo would never have reached the Moon safely without the hard changes made after the fire.","Only three months later, on 24 April 1967, the Soviet cosmonaut Vladimir Komarov was coming home in Soyuz 1, a brand-new spacecraft that had many problems from the moment it reached orbit. During the descent, the main parachute did not come out of its container, and the reserve parachute tangled. The capsule hit the ground at high speed and Komarov was killed. He was the first person to die during a space mission.","In June 1971 came an even stranger tragedy. Georgy Dobrovolsky, Vladislav Volkov and Viktor Patsayev had just spent more than three weeks aboard Salyut 1, the world's first space station. As their Soyuz 11 capsule separated from the rest of the spacecraft on the way home, a small valve was jolted open. The cabin air leaked away into space in a short time. The three men were not wearing pressure suits, because the cramped capsule had been designed without room for them. When the recovery team opened the hatch after landing, the crew was gone. Because their deaths happened above the Kármán line, these three cosmonauts are the only people known to have died in space itself. After Soyuz 11, every Soviet and Russian crew wore pressure suits during launch and landing, and they still do.","The American Space Shuttle program had two disasters. On 28 January 1986, on a very cold Florida morning, Challenger lifted off. A rubber seal called an O-ring, in a joint of the right solid rocket booster, had stiffened in the cold and did not seal properly. Hot gas escaped through the joint, and about 73 seconds after launch the external tank came apart and Challenger broke up in the sky. The seven people aboard died, including Christa McAuliffe, a schoolteacher who had planned to teach lessons from orbit. During the investigation, the physicist Richard Feynman dropped a piece of O-ring material into a glass of ice water at a public hearing to show how it lost its springiness in the cold. It was a simple, unforgettable experiment.","On 1 February 2003, Columbia was returning from a 16-day science mission. During its launch, a piece of foam insulation about the size of a small suitcase had broken off the external tank and smashed into the front edge of the left wing, making a hole in the heat protection. Nobody realised how serious the damage was. As Columbia plunged back into the atmosphere, superhot gas entered the wing, and the orbiter broke apart over Texas, only about 16 minutes before it was due to land. Its seven crew members died, including Kalpana Chawla and Ilan Ramon.","Counting the people aboard Soyuz 1, Soyuz 11, Challenger and Columbia, 18 people have died during spaceflight missions. Others died in training. In March 1961, a young cosmonaut trainee named Valentin Bondarenko died after a fire in a pressure chamber filled with oxygen, an accident the Soviet Union kept secret for many years; the full story only came out in the 1980s. In 2014, the test pilot Michael Alsbury was killed when Virgin Galactic's rocket plane VSS Enterprise broke apart during a test flight over California's Mojave Desert, while his fellow pilot Peter Siebold survived. Every one of these losses led to investigations, new rules and safer machines. That is how the people who were lost still protect astronauts today."]},{"heading":"Disasters on the Ground","paragraphs":["Some of the worst rocket accidents never left the launch pad. The deadliest is known as the Nedelin catastrophe. On 24 October 1960, at the secret Soviet launch base now called Baikonur, in what is today Kazakhstan, engineers were rushing to prepare the first test of a new missile called the R-16. It was meant to be an intercontinental ballistic missile, a rocket weapon that could carry a nuclear bomb across the world. Its fuels were toxic chemicals that burst into flame the instant they touched each other, which made them convenient for a weapon but dangerous for the people working around it.","There was great pressure to launch quickly, before an important national holiday in November. A fault in the electrical system made the second-stage engine fire while the rocket was still standing on the pad, full of fuel and surrounded by people. The rocket exploded into a huge fireball. The commander of the Soviet missile forces, Chief Marshal Mitrofan Nedelin, was among those killed. The exact number of deaths is still uncertain: an official investigation in the 1990s counted 78, while other estimates range from about 50 to more than 120. The chief designer of the missile, Mikhail Yangel, survived only because he had stepped away behind a protective bunker moments before.","The Soviet government hid the disaster. The public was told that Nedelin had died in a plane crash, and families were told to say the same. The truth was not officially admitted until 1989, almost 30 years later. Secrecy like this was common on both sides of the Cold War, and it meant that hard lessons were sometimes learned slowly.","Today, launch sites are built very differently. Workers watch launches from blast-proof control rooms far away. Before liftoff, the area is cleared for kilometres around. Many rockets carry a range safety system, which can destroy a rocket that flies off course before it threatens a town. Rockets that carry people often have a launch escape system, a small, very powerful rocket that can yank the crew capsule away from a failing booster. This has already saved lives. In September 1983, a fire broke out at the base of a Soyuz rocket on the pad, and the escape tower pulled cosmonauts Vladimir Titov and Gennady Strekalov to safety seconds before the rocket exploded. In October 2018, a booster failed during the launch of Soyuz MS-10, and the capsule carrying Alexey Ovchinin and NASA's Nick Hague separated automatically and landed safely in Kazakhstan. Both men flew to space again a few months later."]},{"heading":"From Weapons to Treaties","paragraphs":["Throughout this Deep Dive, rockets have had two faces. The same push that lifts a spacecraft can carry a bomb. From the fire arrows of China to Tipu Sultan's iron rockets and the V-2, rockets were weapons long before they were spaceships. Even the rocket that launched Sputnik, the R-7, was first built to carry a nuclear warhead to the other side of the world.","During the Cold War, the United States and the Soviet Union built thousands of intercontinental ballistic missiles, or ICBMs. An ICBM goes up into space and comes back down on a target thousands of kilometres away, about 30 minutes after launch. In October 1962, during the Cuban Missile Crisis, the world came frighteningly close to nuclear war over Soviet missiles placed in Cuba. People everywhere realised that rocket technology had made the whole planet vulnerable.","Then came the most important space law ever written. The Outer Space Treaty was opened for signing on 27 January 1967 and came into force in October that year. Today more than 100 countries have joined it, including every country that launches people into space. Its main rules are simple and remarkable. No country may place nuclear weapons or other weapons of mass destruction in orbit, on the Moon or anywhere else in space. The Moon and other worlds may be used only for peaceful purposes, with no military bases or weapons tests there. No country can claim the Moon, a planet or any part of them as its own territory. Countries are responsible for whatever their companies and citizens do in space, and they must pay if their spacecraft cause damage. Astronauts are called envoys of all humankind, and any country must help them if they are in trouble.","The treaty did not answer every question. A later agreement, the Moon Agreement of 1979, tried to say that the Moon's resources belong to everyone, but only a small number of countries joined it, and none of the biggest space powers did. Since 2020, many countries have signed the Artemis Accords, a set of principles led by the United States about peaceful exploration, sharing scientific data and using resources such as lunar ice. By late 2026, more than 75 countries had signed. China and Russia have not, and are planning their own lunar research station together. People still argue about whether mining the Moon or asteroids is fair, and who should decide. These are not just questions for lawyers: whoever grows up to explore the Moon may have to live by the answers."]},{"heading":"A Junkyard in the Sky","paragraphs":["Look up on a clear night and the sky seems empty and calm. In fact, the space just above our atmosphere is getting crowded. Besides thousands of working satellites, there are dead satellites, empty rocket stages, lost tools, flakes of paint and countless fragments from explosions and crashes. All of this is called space debris, or space junk.","Space agencies keep careful track of it. NASA says the US Space Surveillance Network routinely follows objects larger than about 10 cm, about the size of a softball, and that there are tens of thousands of these large, trackable objects. Below that size, the numbers explode. Scientists estimate there are around a million pieces between 1 and 10 cm across, and about 100 million pieces around a millimetre in size, far too small to track one by one.","Why worry about a speck the size of a grain of sand? Because of speed. In low Earth orbit, debris travels at about 7 to 8 km per second, many times faster than a bullet. When two objects meet, they can hit each other at an average of about 10 km per second. At that speed, even a tiny piece carries a startling amount of energy. In 1983, a fleck of paint smaller than a millimetre left a little crater in a window of the Space Shuttle Challenger, and over the Shuttle program dozens of windows had to be replaced because of such hits. The International Space Station has thick bumper shields on its outside, and it has fired its engines dozens of times since 1999 to dodge larger pieces of junk. Sometimes, when a warning comes too late, the crew climbs into their spacecraft, ready to leave quickly if the station is hit.","The first accidental crash between two whole satellites happened on 10 February 2009, about 790 km above Siberia. Iridium 33, a working American communications satellite, and Cosmos 2251, a dead Russian military satellite that had been switched off for years, slammed into each other at about 11.7 km per second. Both were smashed to pieces, creating about 2,000 trackable fragments and many more smaller ones. Many of those pieces are still circling Earth today.","Some debris was made on purpose. On 11 January 2007, China tested an anti-satellite weapon by launching a missile that smashed into one of its own old weather satellites, Fengyun-1C, about 865 km up. It created more than 3,000 trackable pieces, the largest single debris-making event ever recorded, and because that orbit is so high, much of the debris will stay there for decades or longer. The United States, Russia and India have also destroyed satellites in tests. On 15 November 2021, a Russian missile destroyed an old satellite called Kosmos 1408, creating about 1,500 tracked pieces, and the crew of the space station had to shelter in their spacecraft for safety.","The scariest idea about space junk has a name. In 1978, two NASA scientists, Donald Kessler and Burton Cour-Palais, published a paper warning that if enough objects crowd into one region of orbit, collisions will create fragments, those fragments will cause more collisions, and those will create even more fragments, like a chain reaction. This is now called the Kessler syndrome. In the worst case, some orbits could become so cluttered that they would be too risky to use for a very long time. Scientists disagree about how close we are to that point, but nearly all agree that we must stop making the problem worse.","Some solutions are already in place. Many countries now ask satellite operators to bring old satellites down so they burn up in the atmosphere, instead of leaving them in orbit. In 2022, the US Federal Communications Commission set a rule that US-licensed satellites in low orbit should come down within five years of the end of their mission. Rocket stages are designed to vent leftover fuel so they do not explode later. Engineers are also testing ways to clean up junk: in 2024, a Japanese spacecraft called ADRAS-J, built by the company Astroscale, flew close to an old rocket stage and photographed it, practising the first step toward one day grabbing it and pulling it down."]},{"heading":"Rockets and the Planet","paragraphs":["Compared with cars, planes and power stations, rockets burn only a small amount of fuel in total, and their share of the world's greenhouse gas emissions is tiny. So why do scientists study their effect on the environment? Because rockets release their exhaust in places nothing else reaches, and because the number of launches is growing quickly.","Different fuels make different exhaust. Engines that burn hydrogen and oxygen produce mostly water vapour, though making the hydrogen on Earth uses a lot of energy. Kerosene engines, like those on the Saturn V and many modern rockets, also release soot, tiny black particles of carbon. Solid rocket boosters release chlorine compounds and fine particles of aluminium oxide. Down near the ground this exhaust is soon washed away. But high up in the stratosphere, more than 10 km above us, there is no rain to clean the air. Particles injected there can float for years. Scientists are studying whether, if launches keep multiplying, soot could warm the stratosphere and chemicals could thin the ozone layer, the shield that protects us from the Sun's ultraviolet light. Right now the effects are small, but researchers want to understand them before they grow.","Launch sites have neighbours too. NASA's Kennedy Space Center in Florida shares its land with the Merritt Island National Wildlife Refuge, home to sea turtles, manatees, alligators and hundreds of kinds of birds. Rocket noise, lights and occasional fires all have to be managed carefully. When the first Starship test flight lifted off from south Texas in April 2023, its engines blasted apart the concrete under the launch mount and scattered chunks and dust across the surrounding area, which included protected wildlife habitat. Some rockets, especially older Russian and Chinese ones, burn toxic fuels, and their empty first stages fall onto land rather than into the ocean, sometimes near farms and villages.","There is also a newer problem, and it shows up on astronomers' photos. Since 2019, companies have launched thousands of small satellites to beam internet service around the world. These huge groups are called megaconstellations. Soon after launch, the satellites can be bright enough to see with the naked eye, sometimes looking like a string of pearls crossing the night. For telescopes that take long-exposure pictures of the sky, each passing satellite can leave a bright streak across the image. Radio telescopes, which listen for faint signals from space, can also be disturbed by satellite radio signals.","Astronomers and satellite companies have started working together. SpaceX tested darker coatings and sunshades to make its satellites dimmer, and astronomers are writing software to spot and remove streaks. In 2022, the International Astronomical Union set up a centre to protect dark and quiet skies. The debate is about balance: satellite internet can connect remote schools, ships and disaster zones, but the night sky is also a treasure that belongs to everyone, and it has inspired people for as long as there have been people."]},{"heading":"Is Space Worth the Money?","paragraphs":["Spaceflight is expensive. The Apollo program cost about 25.8 billion US dollars at the time, which is roughly 250 billion dollars or more in today's money. In 1966, at the height of the Moon race, NASA's budget was more than 4% of all the money the US federal government spent. Today it is much smaller, about four-tenths of one percent, though it is still many billions of dollars a year. Other countries also spend large sums on rockets, satellites and astronauts. So a fair question has been asked again and again: should this money be spent on problems here on Earth instead?","People were already asking that while Apollo 11 stood on the pad. On 15 July 1969, the day before launch, the civil rights leader Ralph Abernathy led a group of poor families, some with mule-drawn wagons, to the gates of the Kennedy Space Center. He said the money for the Moon could help hungry people in America. NASA's leader Thomas Paine went out to meet him. Paine said that if not pushing the launch button tomorrow would solve the problems Abernathy was talking about, they would not push it, but that space technology was far easier than solving poverty. He invited the group to watch the launch, and Abernathy said he would pray for the astronauts' safety. The two men disagreed, but they treated each other with respect.","What has space work actually given us? Some benefits are huge. The first weather satellite, TIROS-1, sent back pictures of clouds from orbit in April 1960, and today weather satellites give warnings of hurricanes and storms days in advance, saving countless lives. Communication satellites carry television, phone calls and internet. In July 1962, Telstar 1 relayed the first live television pictures across the Atlantic. The Global Positioning System, or GPS, was built by the US military, with the first satellite launched in 1978, and now guides cars, ships, planes and phones everywhere. Its clocks must even be corrected for Einstein's theory of relativity, or positions would drift by kilometres every day.","Smaller inventions came out of space research too. NASA has published a magazine called Spinoff every year since 1976 describing more than 2,000 technologies that started in space work and became products. A tough coating developed at NASA's Ames Research Center was licensed in the 1980s to make scratch-resistant sunglasses and spectacle lenses. Systems developed to keep drinking water clean on spacecraft helped improve water filters. Memory foam came from a 1960s NASA project to make safer aircraft seats. The tiny camera chips in most mobile phones grew out of work at NASA's Jet Propulsion Laboratory in the 1990s.","But beware of myths. NASA did not invent Velcro, which was invented by the Swiss engineer George de Mestral in the 1940s. It did not invent Tang, the orange drink powder made by General Foods in the 1950s, or Teflon, discovered by accident at the chemical company DuPont in 1938. Astronauts used them, which made them famous. And the story that NASA spent millions on a space pen while Russian cosmonauts just used pencils is not true: the Fisher Space Pen was developed with private money, and both the American and Soviet programs bought it."]},{"heading":"Hidden Figures and Who Gets to Go","paragraphs":["Who gets the credit for a rocket? For a long time, history books told the story through a few famous astronauts and engineers. But every launch depends on thousands of people, and some of them were left out of the story for decades because of their sex, their skin colour or the secrecy of their work.","At the Langley laboratory in Hampton, Virginia, starting in the 1940s, teams of women worked as human computers, doing long, careful calculations by hand for aircraft and, later, spacecraft. Because Virginia's laws enforced racial segregation, the Black women mathematicians worked in a separate group called the West Area Computers, and they had to use separate dining areas and bathrooms. Dorothy Vaughan became the group's leader in 1949, the first Black supervisor at the laboratory, and later taught herself and her team the computer language FORTRAN when electronic computers arrived. Mary Jackson became NASA's first Black woman engineer in 1958.","Katherine Johnson calculated flight paths for the Mercury flights and for Apollo. Before John Glenn's orbital flight in 1962, he asked that she personally check the numbers produced by the new electronic computer; he trusted her more than the machine. For years, few people outside NASA knew her name. In 2015, at the age of 97, she received the Presidential Medal of Freedom, and the 2016 book and film Hidden Figures finally told the story of these women to millions of people.","Women who wanted to be astronauts faced closed doors too. In 1960 and 1961, a doctor named William Randolph Lovelace II privately put a group of women pilots, including Jerrie Cobb, through some of the same medical tests given to the Mercury men. Several did very well. But the testing was stopped, and NASA at the time only chose military jet test pilots, a job women were not allowed to do. The group later became known as the Mercury 13. None of them flew in space for NASA. The first American woman in space, Sally Ride, did not fly until 1983, twenty years after the Soviet Union's Valentina Tereshkova. In 2021, one of the Mercury 13, Wally Funk, finally reached space at the age of 82 aboard Blue Origin's New Shepard.","Other hidden workers did not choose their role at all. As Part 7 of this story told, thousands of prisoners were forced to build V-2 rockets in the underground Mittelwerk factory, and many of them died. Their story was barely mentioned for decades while some of the engineers who used their labour became celebrated in America. Today, a memorial at the site of the Mittelbau-Dora camp in Germany helps make sure they are remembered.","There are also questions about who gets to go now. Fewer than a thousand people have ever been to space, and for most of history they were chosen from just a few countries. That is slowly changing: astronauts now come from dozens of nations, and crews include more women and people from many backgrounds. Private spaceflight has opened another door, but it is very expensive. In 2001, the American businessman Dennis Tito paid about 20 million dollars to visit the International Space Station, and tickets for private trips to orbit still cost tens of millions. Some people worry that space could become a playground only for the very rich. Others hope prices will keep falling, just as flying in an aeroplane went from a luxury to something millions of families do.","There are no easy answers to these debates. But the people asking hard questions, from Ralph Abernathy at the gates of the space centre to astronomers counting satellite streaks, have often made spaceflight better, safer and fairer. And despite all the dangers, people around the world are now getting ready to go back to the Moon, and to travel even further than anyone has gone before."]}],"deepDive":"How bad is the space debris problem, really? The physics is what makes it alarming. Kinetic energy grows with the square of speed, so an object hitting at 10 km/s carries about 100 times more energy per kilogram than one hitting at 1 km/s. A 1 cm aluminium fragment at orbital collision speeds can release energy comparable to a small car crash, concentrated on a spot the size of a fingertip. Spacecraft protect themselves with Whipple shields, named after astronomer Fred Whipple, who proposed them in the 1940s: a thin outer bumper sits some distance in front of the main wall, so a fragment that hits the bumper shatters and spreads into a cloud of smaller, slower bits that the inner wall can stop. The space station's critical parts can survive hits from debris up to about 1 cm; for larger tracked pieces, it moves out of the way. Whether we are already in a Kessler cascade is debated. Kessler and Cour-Palais argued in 1978 that above a critical density, collisions would eventually produce debris faster than atmospheric drag removes it. Atmospheric drag is the key: below about 400 to 500 km, debris usually falls back within a few years, especially when the Sun is active and the upper atmosphere swells. Above about 800 km, objects can stay up for centuries, which is why the 2007 Fengyun-1C test and the 2009 Iridium-Cosmos crash were so harmful: both happened in that long-lasting region. Many models suggest that some crowded bands near 800 to 1,000 km are already close to, or past, the point where collisions among existing objects alone would keep the debris growing, even if nobody launched anything new. That is why experts emphasise removing a handful of large dead objects, such as old rocket bodies, which are the most likely to create future swarms of fragments. Megaconstellations change the picture: they put many thousands of satellites at lower altitudes, where failures clear more quickly, but they also require constant automated collision avoidance, with each operator performing thousands of manoeuvres. Some researchers argue that the true limit of orbit is not space but coordination: without shared tracking data and agreed rules, the risk rises faster than the number of satellites.","funFact":"When pieces of the Skylab space station fell on Western Australia in 1979, the town of Esperance issued NASA a 400 Australian dollar fine for littering, which an American radio host finally paid off in 2009.","check":{"q":"Which two satellites were involved in the first accidental collision between two whole satellites, in February 2009?","a":"Iridium 33 and Cosmos 2251","wrong":["Sputnik 1 and Explorer 1","Hubble and Skylab","Telstar 1 and Fengyun-1C"]},"sources":[{"title":"Frequently Asked Questions","publisher":"NASA Orbital Debris Program Office","url":"https://orbitaldebris.jsc.nasa.gov/faq/"},{"title":"Nedelin catastrophe","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Nedelin_catastrophe"},{"title":"Kessler syndrome","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Kessler_syndrome"},{"title":"NASA Spinoff","publisher":"NASA","url":"https://spinoff.nasa.gov/"},{"title":"Outer Space Treaty","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Outer_Space_Treaty"},{"title":"2009 satellite collision","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/2009_satellite_collision"},{"title":"Soyuz 11","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Soyuz_11"},{"title":"Artemis Accords","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Artemis_Accords"}],"photos":[{"src":"img/deep/rockets/19-1.jpg","alt":"NASA computer image of tracked objects around Earth; most dots are space junk, not working satellites (dots not to scale)","file":"Debris-LEO1280.jpg","url":"https://commons.wikimedia.org/wiki/File:Debris-LEO1280.jpg","author":"NASA employee","license":"Public domain"},{"src":"img/deep/rockets/19-2.jpg","alt":"Mathematician Katherine Johnson at her desk at NASA Langley Research Center, 1966","file":"Katherine Johnson At Her Desk at NASA Langley Research Center (LRC-1966-B701 P-06717).tiff","url":"https://commons.wikimedia.org/wiki/File:Katherine_Johnson_At_Her_Desk_at_NASA_Langley_Research_Center_(LRC-1966-B701_P-06717).tiff","author":"NASA Langley Research Center / NASA , Bob Nye","license":"Public domain"},{"src":"img/deep/rockets/19-3.jpg","alt":"Signing the Outer Space Treaty at the White House in 1967, with the USSR, UK and USA at the table","file":"Signing Outer Space Treaty.jpg","url":"https://commons.wikimedia.org/wiki/File:Signing_Outer_Space_Treaty.jpg","author":"ITU","license":"CC BY 2.0"}],"words":4378},{"n":20,"title":"Back to the Moon, On to Mars","when":"Today – the future","summary":"In April 2026, four astronauts flew all the way around the Moon, farther from Earth than any people ever before. Robots from China, India, Japan and private companies are landing on the Moon too, hunting for ice hidden in dark craters. Next comes a Moon base, and one day maybe Mars, and the first people to walk there could be kids reading this right now.","sections":[{"heading":"Artemis, Twin Sister of Apollo","paragraphs":["In Greek myth, Apollo had a twin sister: Artemis, goddess of the Moon. So when NASA planned a new program to send people back to the Moon, more than fifty years after Apollo, it chose her name. The program's goal is not just to plant flags and footprints, as in 1969, but to learn how to stay: to build a long-lasting human presence on and around the Moon, and to use it as practice for going to Mars.","Artemis has two main pieces of hardware built by NASA. The first is the Space Launch System, or SLS, a giant rocket about 98 m tall, a little shorter than the Saturn V but more powerful at liftoff. Its orange core stage burns liquid hydrogen and liquid oxygen in four RS-25 engines, the same type that once powered the Space Shuttle, and some of these very engines actually flew on Shuttle missions. Two white solid rocket boosters, also descended from the Shuttle's boosters, provide most of the push in the first two minutes. The second piece is Orion, a cone-shaped crew capsule a bit like a much bigger Apollo command module, with room for four astronauts. Orion's service module, which supplies power, air, water and the main engine, is built in Europe for the European Space Agency.","Artemis I was the test with no crew aboard. It lifted off from Kennedy Space Center in Florida in the early hours of 16 November 2022, lighting up the night sky. Orion flew out to the Moon, swung within about 130 km of the lunar surface, and then went into a wide, looping orbit far beyond it. At its farthest point, it was about 432,000 km from Earth, farther than any spacecraft built to carry humans had ever gone. Instead of astronauts, the seats held mannequins fitted with sensors to measure vibration and radiation, and a plush Snoopy toy floated in the cabin as a zero-gravity indicator, showing when the capsule was in free fall.","After about 25 days, Orion splashed down in the Pacific Ocean on 11 December 2022, exactly fifty years after Apollo 17 landed on the Moon. The mission was a success, but engineers found something surprising when they inspected the capsule: pieces of the outer layer of its heat shield had cracked and broken away in an unexpected way during the fiery return. Months of tests followed. NASA decided to keep the shield for the next mission but to change Orion's path back into the atmosphere, so the capsule would spend less time in the conditions that caused the damage."]},{"heading":"Artemis II: Four People Around the Moon","paragraphs":["On 1 April 2026, after several delays caused by the heat shield studies and by leaks of liquid hydrogen during fuelling tests, the SLS rocket roared off Launch Complex 39B at Kennedy Space Center, the same pad used by Apollo 10 and many Space Shuttles. Inside the Orion capsule, which the crew had named Integrity, were four astronauts. Reid Wiseman, from NASA, was the commander. Victor Glover, from NASA, was the pilot. Christina Koch, from NASA, and Jeremy Hansen, from the Canadian Space Agency, were mission specialists. Koch became the first woman to travel to the Moon, Glover the first Black astronaut to do so, and Hansen the first person from outside the United States to fly beyond low Earth orbit.","Artemis II did not land on the Moon, and it did not go into orbit around it. It followed what is called a free-return trajectory: a path shaped like a stretched figure eight, where the Moon's gravity bends the spacecraft around and flings it back toward Earth even without a big engine burn. Apollo 13's crew used a path like this to get home safely in 1970. For Artemis II, it was chosen as a safety measure for the first crewed test. First, though, the crew spent about a day circling Earth, checking that Orion's life support, controls and communications worked, before firing toward the Moon.","On 6 April 2026, Orion swept around the far side of the Moon. The crew looked down on parts of the far side that no human eyes had ever seen directly and took hundreds of photographs. They also saw a total solar eclipse from space, as the Moon passed in front of the Sun from their point of view; Glover said afterwards that it had amazed all of them. During the flyby, the crew reached a distance of about 406,771 km (252,756 miles) from Earth, the farthest any humans have ever travelled. The record they broke had stood since Apollo 13 in April 1970.","Then came the long fall home. Orion hit the top of the atmosphere at about 11 km per second, more than 39,000 km per hour, the fastest any crew had re-entered since the Apollo era. After a fiery few minutes and a planned radio blackout, its parachutes opened, and on 10 April 2026 Integrity splashed down in the Pacific Ocean off the coast of San Diego, California, where the US Navy ship USS John P. Murtha was waiting. The whole mission lasted 9 days, 1 hour and 32 minutes. It was not perfectly smooth: the crew dealt with some valve problems and even a misbehaving toilet. But all four astronauts came home safely, and humans had travelled to the Moon for the first time in more than half a century.","What comes next? Space plans change often, and Artemis is no exception. In early 2026, NASA announced a big reshuffle. Under the new plan, Artemis III, which had been meant to be the first landing, would instead become a test mission in Earth orbit, aimed for 2027, where astronauts in Orion would practise meeting up with the new commercial Moon landers being built by SpaceX and Blue Origin. The first attempts to land astronauts near the Moon's south pole were moved to later missions, aimed for around 2028. These are targets, not promises. Each lander still has to be tested, and huge new systems almost always take longer than planned. Meanwhile, China has announced its own goal of landing astronauts on the Moon by around 2030, with a new rocket, a new crew spacecraft and a lander. Whichever mission comes first, a new chapter of Moon exploration has clearly begun."]},{"heading":"A Crowd on the Moon","paragraphs":["Between 1976 and 2013, no spacecraft made a soft landing on the Moon at all. Today the Moon is busy again, and much of the action comes from countries other than the United States and Russia.","China has carried out a remarkable step-by-step program named after Chang'e, the Moon goddess in Chinese legend. Chang'e 3 landed in 2013 with a small rover called Yutu, meaning Jade Rabbit, the goddess's companion. Then, on 3 January 2019, Chang'e 4 did something nobody had done before: it made a soft landing on the far side of the Moon, in Von Kármán crater. Because the Moon blocks radio signals from the far side, China first placed a relay satellite called Queqiao, meaning Magpie Bridge, far beyond the Moon, so the lander could talk to Earth through it. Its rover, Yutu-2, kept driving for years, far longer than planned.","In December 2020, Chang'e 5 landed on the near side, scooped and drilled about 1.7 kg of soil and rock, launched it back into lunar orbit, and returned it to Earth, the first lunar samples brought home since the Soviet Luna 24 in 1976. The samples turned out to include some of the youngest volcanic rocks ever collected from the Moon. In 2024, Chang'e 6 went one step further. It launched on 3 May, landed on 1 June inside the Apollo basin on the far side, and on 25 June its capsule landed in Inner Mongolia carrying about 1.9 kg of material, the first samples ever collected from the Moon's far side.","India's turn came after a disappointment. In 2019, the lander of Chandrayaan-2 crashed during its final descent. The Indian Space Research Organisation, ISRO, studied what went wrong, strengthened the lander's legs, widened its landing zone and improved its software. Chandrayaan-3 launched on 14 July 2023, and on 23 August 2023 its lander, Vikram, touched down gently at about 69 degrees south, far closer to the south pole than any earlier landing. India became the fourth country to make a soft landing on the Moon, after the Soviet Union, the United States and China. The small rover, Pragyan, rolled down a ramp and drove about 100 m, and its instruments confirmed sulfur in the lunar soil. Only days earlier, Russia's Luna 25, also heading for the south polar region, had crashed after an engine problem.","More landers followed. Japan's SLIM spacecraft landed in January 2024 within about 100 m of its target, a remarkable feat of precision, although it ended up tipped on its nose; it still worked and sent back pictures. In February 2024, a lander called Odysseus, built by the American company Intuitive Machines, became the first privately built spacecraft to land on the Moon, though it also tipped over. In March 2025, Firefly Aerospace's Blue Ghost lander touched down upright and carried out its planned mission successfully, the first fully successful landing by a private company. Landing on the Moon is still hard, and several private landers have crashed. But each attempt, successful or not, teaches engineers something new, just as in the early days of the space race."]},{"heading":"Treasure in the Dark","paragraphs":["Why are so many missions heading for the Moon's south pole? The answer is a substance you drank today: water.","Earth's axis is tilted, which gives us seasons. The Moon's axis is tilted only about 1.5 degrees, so at its poles the Sun always hangs low on the horizon, like a sunset that never ends. The floors of some deep craters near the poles have not seen sunlight for perhaps billions of years. Measurements from NASA's Lunar Reconnaissance Orbiter show that some of these permanently shadowed craters are colder than minus 200 degrees Celsius, among the coldest places ever measured in the solar system. Any water molecules that drift into such a cold trap, perhaps delivered by comets or created by the solar wind, freeze and stay there.","For years scientists suspected ice was there. Then, on 9 October 2009, NASA deliberately crashed the spent upper stage of a rocket into a shadowed crater called Cabeus, near the south pole. A small spacecraft named LCROSS flew through the cloud of debris thrown up by the impact and detected water in it, before crashing in turn. Instruments on India's Chandrayaan-1 orbiter, including one built by NASA, had also found signs of water on the lunar surface, and in 2018 scientists reported direct evidence of surface ice inside shadowed craters at both poles.","Water on the Moon would be worth far more than gold, because it is so heavy and expensive to launch from Earth. Astronauts could melt and clean it for drinking and for growing plants. Using electricity, water can be split into hydrogen and oxygen. The oxygen could fill astronauts' air tanks. And hydrogen and oxygen, chilled into liquids, are exactly the propellants used by many powerful rocket engines. A Moon base that could make its own fuel could become a kind of filling station in space.","The south pole has another advantage: some high crater rims, such as parts of the rim of Shackleton crater, are lit by the Sun most of the time, which would be useful for solar power. Being next to both near-constant sunlight and frozen water makes these places some of the most valuable real estate in the solar system, which is exactly why the questions in Part 19 about who may use lunar resources matter so much. Scientists still do not know how much ice there is, how pure it is or how hard it will be to dig out of soil so cold. Finding out is one of the main jobs of the coming missions."]},{"heading":"The Long Road to Mars","paragraphs":["The Moon is about three days away. Mars is a completely different challenge. Depending on where the two planets are in their orbits, Mars is between about 55 million and 400 million km from Earth. With today's rockets, the trip takes around seven months each way, and launch windows open only about every 26 months, when the planets line up well. A crew might have to wait on Mars for more than a year before the next good window home. A full round trip could last two to three years.","Radiation is one of the biggest dangers. On Earth, our magnetic field and thick atmosphere shield us from energetic particles from the Sun and from exploding stars far away. In deep space, there is no such shield. During its trip to Mars in 2011 and 2012, the Curiosity rover carried an instrument that measured radiation inside its spacecraft. Scientists calculated that astronauts on a typical round trip would receive a radiation dose of about 0.66 sieverts from the journey alone, more than many space agencies' career limits for astronauts. Engineers are studying better shielding, using water tanks or food supplies as walls, and storm shelters where a crew could hide during a solar storm.","The human body also changes in weightlessness. As Part 16 explained, astronauts lose bone and muscle, which is why they exercise every day on the space station. Some also have changes in their eyesight. After seven months of floating, Mars astronauts would have to step out onto a planet with about 38% of Earth's gravity and immediately start working. Their minds matter too. Between 2010 and 2011, six men lived for 520 days in a sealed mock spaceship in Moscow in an experiment called Mars-500, to learn how a crew copes with isolation, boredom and a delay in talking to home. Real astronauts on Mars would wait up to about 20 minutes for a message to reach Earth, and as long again for the reply, so they would have to solve emergencies on their own.","They would also need food, water and air for years. Astronauts on the space station have already grown and eaten fresh food: in August 2015, a crew tasted red romaine lettuce grown in a small plant chamber called Veggie. On Mars itself, a small experiment called MOXIE aboard the Perseverance rover proved that oxygen can be made from the planet's thin carbon dioxide air. Over 16 runs between 2021 and 2023, it produced 122 grams of oxygen, about as much as a small dog breathes in ten hours. That is tiny, but it showed the idea works. A full-sized version could make oxygen for breathing and for the fuel of the rocket home.","Then there is the landing. Mars has an atmosphere only about one percent as thick as Earth's, too thin for parachutes alone to slow down a heavy ship, but thick enough to create dangerous heat on the way in. The heaviest thing ever landed on Mars so far is Perseverance, which weighs about one tonne. A ship carrying people, supplies and a rocket to return home might weigh dozens of tonnes. It would probably have to fire powerful engines downward while still flying faster than sound, a technique the reusable rockets of Part 18 have practised in Earth's atmosphere. SpaceX hopes its giant Starship could one day carry crews and cargo to Mars, and NASA and other agencies are studying their own designs. No one can yet give a reliable date for the first human landing on Mars; it is a goal, not a schedule."]},{"heading":"New Engines for Long Journeys","paragraphs":["Chemical rockets, which burn fuel with an oxidizer, have carried every human into space. They push hard, but they use up their propellant very quickly. For long journeys, engineers are testing other kinds of engines.","One is the ion engine. Instead of burning anything, it uses electricity, often from solar panels, to strip electrons off atoms of a gas such as xenon. The atoms become electrically charged ions, and a strong electric field flings them out of the back at about 30 to 40 km per second, roughly ten times faster than the exhaust of a chemical rocket. The push is incredibly gentle: the ion engines on NASA's Dawn spacecraft pushed about as hard as the weight of a single sheet of paper resting on your hand. But they can run for months or years without stopping, and in the emptiness of space that tiny push adds up.","Dawn launched on 27 September 2007. Using its ion engines for a total of more than five years of thrusting, it became the first spacecraft to orbit two different worlds beyond Earth and the Moon: first the giant asteroid Vesta in 2011 and 2012, then the dwarf planet Ceres from 2015 to 2018, where it discovered bright patches of salt. Its ion engines changed its speed by about 11 km per second in total, more than any spacecraft had achieved with its own engines before. Earlier, in 1998, NASA's Deep Space 1 had been the first deep-space mission to rely on ion propulsion, and ion thrusters now help keep many communications satellites in place.","Ion engines are too gentle to carry a heavy crewed ship quickly to Mars on their own, so engineers are also looking at nuclear power. In a nuclear thermal rocket, a small reactor would heat hydrogen to extremely high temperatures and blast it out of a nozzle, about twice as efficiently as the best chemical engines. The United States built and ground-tested such engines in the 1960s in a program called NERVA, but none ever flew. A faster trip would mean less time exposed to radiation and weightlessness, which is why the idea keeps coming back. Nuclear power is not new in space: Voyager, Curiosity and Perseverance all get their electricity from the heat of decaying plutonium. In 2018, NASA also successfully tested a small fission reactor called Kilopower in Nevada, designed to one day power a base on the Moon or Mars.","Some ideas use no fuel at all. In 2010, Japan's IKAROS spacecraft unfurled a solar sail, a thin sheet thinner than a human hair, and was pushed along by the gentle pressure of sunlight itself, on its way past Venus. Engineers are also studying ways to make propellant on other worlds, so ships do not have to carry everything from Earth. The rockets of the future may look very different from the fire arrows of the past, but they will still obey the same rule Newton wrote down in 1687: push something one way, and you go the other."]},{"heading":"One Long Relay Race","paragraphs":["Step back and look at the whole story you have just read. It is not the tale of one genius or one country. It is more like a relay race lasting a thousand years, where each runner carried the baton a little further and then passed it on.","It began with Chinese alchemists who stumbled on gunpowder while searching for medicines, and soldiers who discovered that a tube of burning powder could push an arrow by itself. Rockets spread to the Mongols, the Islamic world and Europe. In India, Tipu Sultan's iron-cased rockets impressed the British so much that William Congreve copied and improved them, and their red glare entered a national anthem. Isaac Newton explained why any of it worked: every action has an equal and opposite reaction.","Then came the dreamers. Jules Verne imagined a journey to the Moon. Konstantin Tsiolkovsky, a deaf schoolteacher in a small Russian town, worked out the mathematics of rockets and imagined space stations and multi-stage rocket trains. Robert Goddard, alone in a snowy field in Massachusetts in 1926, launched the first liquid-fuel rocket. Hermann Oberth's books inspired rocket clubs full of young enthusiasts.","The darkest chapter came next, when rockets became weapons of war, built by forced labourers, and the V-2 became the first human-made object to reach space. After the war, Sergei Korolev in the Soviet Union and Wernher von Braun in the United States led rival teams. Korolev's R-7 launched Sputnik and then Yuri Gagarin, the first human in space. Von Braun's Saturn V carried Neil Armstrong, Buzz Aldrin and ten other astronauts to walk on the Moon. Behind them stood hundreds of thousands of people: engineers, seamstresses who sewed the spacesuits, mathematicians such as Katherine Johnson, and programmers such as Margaret Hamilton's team.","Space stations taught humans to live in orbit, and the International Space Station turned old rivals into partners. Robot explorers visited every planet. Then companies learned to land rockets and fly them again, making launches far cheaper. And in April 2026, four astronauts from two countries looped around the Moon, carrying the baton further from Earth than anyone had ever been. Every step built on the steps before it, and people from China, India, the Middle East, Europe, Russia, America, Japan and many other places all ran a leg of the race."]},{"heading":"Your Countdown","paragraphs":["Now think about this. If people do reach Mars in the 2030s or 2040s, the astronauts who make that trip are probably not famous yet. Many of them are still in school. Some might be about your age. The engineers who design their ship, the doctors who keep them healthy, the scientists who decide where they will land and the programmers who write the software that steers them home may be sitting in classrooms right now, wondering what they will be when they grow up.","You do not have to be an astronaut to be part of space exploration. Remember that Tsiolkovsky taught himself from library books, that Goddard was laughed at by a newspaper, that Katherine Johnson's careful arithmetic helped bring astronauts home, and that Mars rovers are driven by teams of scientists who never leave Earth. Curiosity, patience and the courage to keep trying after failures have mattered as much as any rocket engine. Space needs builders, writers, artists, doctors, lawyers, farmers who can grow food in strange places, and people who ask hard questions about safety and fairness.","So imagine it. You are strapped into a seat, looking up through a small window at a deep blue sky. Beneath you, a rocket hums and creaks as icy propellant boils off. A calm voice in your headset begins to count.","Ten. Nine. Eight. Somewhere far below, a fire arrow from a thousand years ago whooshes into the air. Seven. Six. Newton writes down his third law by candlelight. Five. Four. A deaf schoolteacher in Kaluga fills a notebook with equations. Three. Two. A small rocket leaps from a cabbage field in Massachusetts, and Gagarin shouts that it is time to go. One. The engines roar, the whole ship shakes, and you are pressed back into your seat as the sky turns from blue to black.","Liftoff. The next chapter of this story is yours."]}],"deepDive":"Why go to the Moon to reach Mars, and why do engineers obsess over lunar ice? The answer is the rocket equation from Part 4. A rocket's total possible change in speed, called delta-v, depends on its exhaust speed multiplied by the natural logarithm of its fuelled mass divided by its empty mass. That logarithm is brutal: to double your delta-v you must square your mass ratio. Reaching low Earth orbit takes about 9.4 km/s of delta-v once gravity and air drag losses are included, which is why rockets launched from Earth are mostly propellant. Escaping the Moon's surface, by contrast, takes only about 2.4 km/s, because the Moon has about one-sixth of Earth's surface gravity and no air. So propellant made on the Moon would be far cheaper, in energy, to deliver into space than the same propellant lifted from Earth. Whether that advantage outweighs the cost of building mining and processing plants on the Moon is a major open question, and estimates vary widely. Artemis has its own debates. The SLS rocket is largely expendable: each one is thrown away after a single launch. In 2022, NASA's Office of Inspector General estimated that each of the first four Artemis launches would cost about 4.1 billion US dollars for the SLS, Orion and ground systems, a figure critics argue is too high to support frequent missions. Supporters reply that SLS was the only system available to send Orion and its crew directly toward the Moon. The landers chosen by NASA, SpaceX's Starship-based lander and Blue Origin's Blue Moon, both depend on refuelling in orbit, transferring very cold propellant between spacecraft in weightlessness, something never yet done at that scale. Starship's lunar lander is expected to need many tanker launches to fill up, which is one reason schedules are uncertain. For Mars, the main competition is between chemical propulsion with refuelling and nuclear propulsion. A nuclear thermal rocket with an exhaust speed of about 9 km/s, double that of the best hydrogen-oxygen engines, could shorten trips and reduce radiation dose, but it raises questions about safety, testing and cost. Nobody yet knows which approach will carry the first crew to Mars.","funFact":"On their April 2026 flight around the Moon, the Artemis II astronauts travelled 406,771 km from Earth, breaking a distance record set by the Apollo 13 crew in 1970.","check":{"q":"Which mission made the first soft landing on the far side of the Moon, on 3 January 2019?","a":"China's Chang'e 4","wrong":["Apollo 17","India's Chandrayaan-3","Artemis II"]},"sources":[{"title":"Artemis II","publisher":"NASA","url":"https://www.nasa.gov/mission/artemis-ii/"},{"title":"Artemis II astronauts return from moon with a splashdown to close out a record-breaking lunar voyage","publisher":"Associated Press via Boston.com","url":"https://www.boston.com/news/world-news/2026/04/10/artemis-ii-astronauts-return-from-moon-with-a-splashdown/"},{"title":"Chang'e-6, China's lunar far side sample return mission","publisher":"The Planetary Society","url":"https://www.planetary.org/space-missions/change-6"},{"title":"Chandrayaan-3 Details","publisher":"ISRO","url":"https://www.isro.gov.in/Chandrayaan3_Details.html"},{"title":"Dawn","publisher":"NASA Science","url":"https://science.nasa.gov/mission/dawn/"},{"title":"Artemis II","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Artemis_II"},{"title":"Artemis III","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Artemis_III"},{"title":"Dawn (spacecraft)","publisher":"Wikipedia","url":"https://en.wikipedia.org/wiki/Dawn_(spacecraft)"}],"photos":[{"src":"img/deep/rockets/20-1.jpg","alt":"NASA's SLS rocket with the Orion capsule launches Artemis I from Launch Complex 39B at night, 16 November 2022","file":"Artemis I Launch (NHQ202211160017).jpg","url":"https://commons.wikimedia.org/wiki/File:Artemis_I_Launch_(NHQ202211160017).jpg","author":"Joel Kowsky","license":"Public domain"},{"src":"img/deep/rockets/20-2.jpg","alt":"The Artemis II crew: Christina Koch, Victor Glover, Jeremy Hansen and (front) Reid Wiseman","file":"Artemis 2 Crew Portrait.jpg","url":"https://commons.wikimedia.org/wiki/File:Artemis_2_Crew_Portrait.jpg","author":"Josh Valcarcel","license":"Public domain"},{"src":"img/deep/rockets/20-3.jpg","alt":"India's Vikram lander on the Moon, photographed by the Pragyan rover in 2023 (shown as stereo image pairs)","file":"Chandrayaan 3 Vikram lander stereo (53167467822).png","url":"https://commons.wikimedia.org/wiki/File:Chandrayaan_3_Vikram_lander_stereo_(53167467822).png","author":"semeion.photo","license":"CC BY 2.0"}],"words":4143}],"words":82157};
